UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен еркін жүру». Бөпе енді бір қолынан ұстасаңыз, аяқтарын кезектестіріп, әр басқышқа бір аяғын қойып, баспалдақпен көтерілуге тырысады. Бұл — жалпы моториканың дамуындағы елеулі жетістік. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз, бірақ өздігінен қадам басуына сенім беріңіз.') WHERE id = 'e1b72aca-8d9f-4f33-aedd-ed905b733dbf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Кеңістікті білдіретін сөздер». Бөпе «үстінде», «астында», «артында» сияқты ұғымдарды қимылдарымен көрсете алады. Оған «Допты орындықтың астына қой» деп, шағын ойын ойнаңыз. Мұндай тапсырмалар оның тілді түсінуін де, кеңістікті бағдарлау дағдысын да жылдам дамытады.') WHERE id = '455a2119-ac1e-44e4-8b8c-20b0405c50d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Бұрап ашу және айналдыру шеберлігі». Бөпе бөтелке қақпақтары мен ойыншық бұрандаларын сенімді түрде бұрап ашып-жаба алады. Бұл — білек бұлшықеттерінің икемділігін дамытуға арналған тамаша жаттығу. Оған өлшемдері әртүрлі қауіпсіз ыдыстар беріп, осындай «механикалық» зерттеуге деген қызығушылығын қолдаңыз.') WHERE id = '61305052-b44e-493c-a6f8-ffe876e0e01e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз 23-айдың соңына таяп қалды. Енді ол өзіне жай ғана «мен» деп емес, атымен де айтылатынын толық түсінеді. Онымен сөйлескенде: «Мұны сен істедің бе?» деп сұрасаңыз, мақтанышпен «Иә» деп жауап беруі — оның өзін жеке тұлға ретінде сезінуі дамып келе жатқанының белгісі. Жетістіктерін атын атап мақтаңыз: «Жарайсың, (баланың аты), сенің қолыңнан келді!».') WHERE id = '9459dc0c-afe8-45b3-b94d-dd65b48126f2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Еркін жүгіру және тоқтау». Балаңыз енді жүгіріп келе жатып, құламай кенет тоқтай алады. Бұл оның тежеуші бақылау жүйесі мен бұлшықеттерінің қаншалықты дамығанын көрсетеді. Онымен саябақта «Жүгір де, тоқта!» ойынын ойнаңыз. Бұл әрі көңілді, әрі қимыл үйлесімділігін дамытуға пайдалы.') WHERE id = 'ecf7ae38-688c-4cbe-90a0-7112da130536';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Сұрақ қою кезеңі». Балаңыз көп нәрсенің атауын білетіндіктен, енді олардың не үшін қажет екенін сұрауға бейім болады. Ол бір затты көрсетіп: «Бұл не?» дегенде, оның атауын ғана емес, не үшін қолданылатынын да түсіндіріңіз: «Бұл — қолшатыр, ол жаңбырдан қорғану үшін қажет». Сіздің толық жауаптарыңыз оның дүниетанымын жылдам кеңейтеді.') WHERE id = 'cb8ab97b-604a-4728-ac40-ae0675a2ce85';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Тік және көлденең сызықтар». Балаңыз енді қарындашты сенімдірек ұстап, қағаз бетіне мақсатты түрде түзу сызықтар сыза алады. Оған түрлі түсті қарындаштар мен үлкен қағаздар беріп, «суретшілік» қабілетін қолдаңыз. Бұл — болашақта жазу дағдысын қалыптастырудың маңызды негізі.') WHERE id = 'b5be883e-3ec9-4583-905f-d5eaa6d996f3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше таңдау» кезеңі шарықтау шегіне жетті. Балаңыз енді не жейтінін, қандай ойыншықпен ойнайтынын, тіпті қай жолмен жүретінін өзі шешкісі келеді. Оған шектеулі таңдау ұсыныңыз: «Бүгін алма жейсің бе, әлде банан ба?». Бұл оның шешім қабылдау қабілетін арттырып қана қоймай, өзін біреу басқаратын емес, өз әрекетін өзі басқаратын тұлға ретінде сезінуіне көмектеседі.') WHERE id = 'd071c76a-b155-43af-a2a1-de9194ca4c11';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Символдық еліктеу». Балаңыз енді Сіздің үйдегі әрекеттеріңізге еліктейді: «тамақ пісіреді», «телефонмен сөйлеседі», «үй жинайды». Мұндай еліктеу — оның қоршаған ортаны танып-білу тәсілі. Оған кішкентай ойыншық сыпырғыш немесе ыдыстар беріп, Сіздің «көмекшіңіз» болуына мүмкіндік жасаңыз.') WHERE id = 'ee398ccc-6f29-41df-b0a4-1bb95b88b1a5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Бөлшектерден бүтін құрастыру». Бала енді 3-4 бөліктен тұратын қарапайым пазлдарды суретіне қарап құрастыра алады. Бұл зейінін шоғырландыруға және мәселені шешу дағдысын дамытуға көмектеседі. Қолынан келмей жатса, оған сабырлы үнмен көмектесіңіз: «Қарашы, бұл иттің құйрығы, ол қай жерде болуы мүмкін?». Осындай кішкентай жеңістер оның танымдық қабілетін нығайтады.') WHERE id = '6ae9f735-9ae2-46e6-8771-fa1ead2cea34';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Доп тебу және жүгіру». Бала енді жүгіріп бара жатып, тепе-теңдігін жоғалтпай, алдындағы допты тебе алады. Бұл қозғалыс жылдамдығы мен динамикалық тепе-теңдікті бір мезгілде басқару қабілетін көрсетеді. Онымен аулада немесе саябақта «футбол» ойнап, қимыл дәлдігін жетілдіріңіз. Сізбен бірге қимылдау — ол үшін ең үлкен қызық.') WHERE id = '17868f49-652d-4efe-940b-fac27063768e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Естелікті жеткізу». Бала кеше көрген немесе басынан өткен оқиғаны есіне түсіріп (мысалы, «Саябақта құс көрдім»), Сізге айтып бере алады. Оның әңгімелерін мұқият тыңдап, «Құс не істеп жүрді?» деп диалогті жалғастырыңыз. Бұл оның есте сақтау қабілеті мен ойын жеткізу дағдысын айтарлықтай нығайтады.') WHERE id = 'd99ef035-085a-4da0-b18e-ddf8dda326d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 700 күнді артқа тастадық! 2 жасқа небәрі бір ай (30 күн) қалды. Балаңыз бөпелік кезеңнен толық өтіп, өз мінезі, қалауы мен қабілеттері бар кішкентай «адамға» айналды. Бүгін онымен ең сүйікті ойынын ойнап, осы үлкен белесті атап өтіңіз. Сіз керемет жолдан өттіңіз, Ана!') WHERE id = '0e3a52c6-9f66-42e2-994a-692b5b642618';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '24-ші айға, яғни балаңыздың 2 жасқа толуына қарай соңғы қадамдарды бастаймыз! Бала енді өз заттары мен киімдерін өте жақсы таниды. Оған «Киім шкафынан өз көйлегіңді алып кел» дегенде, өтінішіңізді орындаса, бұл оның есте сақтау қабілеті мен өзіне тиесілі заттарды ажырату сезімі нығайғанын көрсетеді. Осындай шағын тапсырмалар оның өзіне деген сенімін арттырады.') WHERE id = 'f1337afd-8cd4-4800-85b9-83874ec33ec8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Жиекта тепе-теңдік сақтау». Бала енді қолынан ұстаған кезде аласа жиектаспен жүруге қызығушылық танытады. Бұл оның күрделі тепе-теңдік сақтау қабілетін дамытады. Қауіпсіз жерлерде осы қызығушылығын қолдаңыз, өйткені бұл болашақта күрделірек дене қимылдарын меңгеруге негіз болады.') WHERE id = '48e8258d-7e1b-417f-861b-84e4a830fb92';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қорытынды жасау». Бала енді кейбір оқиғалардың нәтижесін алдын ала болжай алады. Мысалы, Сіз аяқ киіміңізді қолыңызға алғанда, ол: «Далаға шығамыз ба?» деп сұрайды. Бұл оның логикалық байланыстарды жақсы құра алатынын көрсетеді. Оның мұндай сұрақтарын мақұлдап, қосымша ақпарат беріңіз: «Иә, барып құстарға нан береміз».') WHERE id = '0aaeb1eb-0155-44f3-b404-be39c9061780';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дайындық: 2 жасқа толуына небәрі 20 күн қалды! Бала енді өз сезімдерін анық білдіріп, Сізге деген сүйіспеншілігін «Мен Сізді жақсы көремін» деген сөздермен (немесе өз тілінде соған ұқсас мағынадағы ишаралармен) көрсетеді. Осы күндері онымен бірге өткізген әрбір сәтіңіз оның эмоциялық әлемінде өшпес із қалдырады. Сіз — керемет ана әрі бағыт берушісіз!') WHERE id = 'f640772a-39c6-4d33-9c3f-64bd16ad5ed0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала қазір «Өзім киінемін» кезеңінің ең табанды сатысында. Шалбарын өзі киюге немесе аяқ киімін (қиын болса да) аяғына сұғып көруге ұмтылуы — оның дербестікке талпынысы. Әрекет жасап көруі үшін оған бірнеше минут артық уақыт беріңіз. Сіздің бұл сабырыңыз — оның болашақтағы өзіне деген сеніміне салынған ең құнды инвестиция.') WHERE id = 'e264db36-ff8b-4ffc-8d0c-2a9a86b8e80e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Бір орында айналу». Бала енді өз орнында айналып, одан пайда болатын «бас айналу» сезімін қызығушылықпен қабылдайды. Бұл — оның вестибулярлық (тепе-теңдік) жүйесінің дамуы. Қауіпсіз әрі жұмсақ жерде онымен бірге билеп, осы жаңа сезімді зерттеуіне мүмкіндік беріңіз.') WHERE id = 'c1b5ac77-3624-4a68-8f84-6255305e6a71';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Көп сөзден құралған сөйлемдер». Бала енді 3-4 сөзді байланыстырып, күрделі ойын жеткізе алады: «Анашым, мен үлкен мәшине қалаймын». Оның сөйлемдерін түзетпеңіз, тек дұрыс нұсқасын қайталап жауап беріңіз: «Иә, сен анау үлкен қызыл мәшинемен ойнағың келе ме?». Бұл оған тіл құрылымын біртіндеп меңгеруге көмектеседі.') WHERE id = '4ada0942-f71a-4215-a9a2-e770a9dcbe42';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Шығармашылық». Бала енді қарындашты сенімдірек ұстап, қағазға дөңгелек сызықтар салуға тырысады. Бұл — болашақта жазу үшін қажет бұлшықет үйлесімділігінің негізі. Оған түрлі түсті бояулар мен үлкен қағаздар беріп, қиялына ерік беріңіз.') WHERE id = 'c206267a-2d42-4d2c-8a75-f79f89a1455a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Есімдіктерді дұрыс қолдану». Бала енді «Мен», «Сен», «Ол» сияқты есімдіктерді сөйлемде дұрыс қолдана бастайды. Мысалы: «Менің қарным ашты» немесе «Сен кел». Оның осы дағдысын қолдау үшін Сіз де сөйлеген кезде есімдіктерге екпін түсіріңіз. Бұл оның әлеуметтік қарым-қатынас жасау қабілетін жылдам жетілдіреді.') WHERE id = '6c0e87a6-05f9-4b6b-826c-adb939561dc2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Құрастыру шеберлігі». Бала енді тек текшелерді бірінің үстіне бірін қойып қана қоймай, олардан «үй», «пойыз» немесе «қоршау» сияқты пішіндер құрастырады. Бұл оның көру-кеңістіктік ойлауы жаңа кезеңге өткенін көрсетеді. Оның «құрылыстарына» қызығушылық танытып, «Мұнда кім келеді?» деген сияқты сұрақтар қойыңыз.') WHERE id = 'd0a7b08b-aa7f-465e-8cfb-7b1cbe914d24';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Рөлдік ойындардың күрделенуі». Бала енді бірнеше бірізді әрекеттен тұратын ойындар ойнайды: мысалы, ойыншық қонжығын «жуындырады», «сүртеді», содан кейін «ұйықтатады». Бұл оның жадында сақталған күнделікті өмір көріністерін қалай жүйелі түрде біріктіретінін көрсетеді.') WHERE id = '290cdbcc-b930-4c04-ac8f-c9e9a99f2bd8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өздігінен тамақтану шеберлігі». Бала енді тамақты шанышқымен түйреп алып, аузына апаруды жақсы меңгерген. Оған өздігінен тамақтануға көбірек мүмкіндік беріңіз. Үстелдің аздап былғануы — оның ұсақ моторикасы мен өзіне-өзі қызмет ету жауапкершілігін дамыту үшін төленетін шағын ғана баға.') WHERE id = 'a907e23d-d22f-4f12-8eba-ed2e00af2852';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Үлкен-Кіші-Орташа». Бала енді екі ғана емес, үш түрлі өлшемді ажырата бастауы мүмкін. Оған бір ойыншықтың үш түрлі өлшемін беріп, «Маған ең үлкенін берші» деп тексеріп көріңіз. Бұл — оның математикалық салыстыру дағдысының негізі. Дұрыс тапқан сайын оны мақтап, жігерлендіріңіз.') WHERE id = '228f5557-8af1-45e0-8eea-dab6d6ab319d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Екі аяқпен алға секіру». Бала енді бір орында ғана емес, сәл алға қарай да секіре алады. Бұл аяқ бұлшықеттерінің серпінді күшін және дене қимылдарының үйлесімділігін қажет етеді. Онымен саябақта «Қояндар көгалда секіреді» ойынын ойнаңыз. Бұл әрі көңілді, әрі жалпы моториканы дамытуға арналған тамаша жаттығу.') WHERE id = 'fed4cb8e-d23c-4ef3-9fb0-62697ac89488';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісу және шекаралар». Бала кейбір заттардың өзіне, ал кейбірінің өзгелерге тиесілі екенін енді түсінеді. Дегенмен оған ойыншығымен бөлісу әлі де қиын болуы мүмкін. Оған «Бұл қазір сенікі, біраздан кейін досың ойнайды» деп, кезек ұғымын үйретіңіз. Бұл — әлеуметтік бейімделудегі ең маңызды қадамдардың бірі.') WHERE id = '0337bbc8-021f-48c3-b2d6-9d07615b2eb6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен көмектесемін». Бала Сізге үй шаруасында көмектескенді қатты ұнатады. Киімдерді себетке салу немесе дастарқанға нан қою сияқты шағын тапсырмалар оған өзін отбасының «маңызды мүшесі» ретінде сезінуге көмектеседі. Оның бұл ынтасын мақтап қойыңыз: «Сен болмағанда, мен мұны кешірек бітірер едім!».') WHERE id = '176cc57c-d49b-4d93-9ce5-5829f43afd94';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Түстердің атауы». Бала енді түстерді жай ғана ажыратып қоймай, олардың көбінің атауын дұрыс айтады. Саябақта серуендеп жүргенде «Жасыл жапырақ қайда?» немесе «Маған сары гүлді көрсетші» деп, білімін іс жүзінде қолдануға мүмкіндік беріңіз. Бұл оның көру және сөздік жадын өзара байланыстырады.') WHERE id = 'b1599687-8b9b-4b36-972d-e646da9ca057';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты иықтан асыра лақтыру». Бала енді допты жай ғана жерге тастамай, оны мақсатты түрде алға немесе Сізге қарай лақтыруға тырысады. Бұл қол бұлшықеттері мен нысананы бағдарлау қабілетінің дамуын көрсетеді. Онымен «Допты себетке кім түсіре алады?» ойынын ойнап, дәлдігін арттырыңыз.') WHERE id = 'a5dba3a5-d849-43ef-ab12-3acff84027fc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өтініш және әдептілік». Бала енді бір нәрсе сұрағанда саусағымен жай ғана көрсетпей, «Берші» немесе «Өтінемін» деп айтуға тырысады, тіпті оны өз тілімен айтса да. Сіздің сыпайы қарым-қатынасыңыз оның тілдесу мәнерін қалыптастырады. Сіз «Рақмет» деген сайын, ол да бұл әдепті табиғи түрде бойына сіңіреді.') WHERE id = 'd8b07d2d-d5ae-44e4-8e83-13117a3ef758';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дайындық: 2 жасқа толуына небәрі 10 күн қалды! Бала енді өз сезімдерін (қуаныш, ашу, ұялу) өте анық білдіреді. Оның эмоцияларын сабырмен қабылдап, атап беріңіз: «Сен қазір қуанып тұрсың, өйткені біз саябаққа барамыз». Сезімдерді атау балаға өзінің ішкі жан дүниесін түсінуге және болашақта өзін-өзі басқару қабілетін дамытуға көмектеседі.') WHERE id = '5b177d90-0a27-4e2b-8501-6cbcb2351fef';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '2 жасқа толуына соңғы 10 күн қалды! Бөпе енді өзін жеке тұлға ретінде толық түсінеді. Айнаға қарап, өз атын айтады немесе «Бұл менмін!» деген ишара білдіреді. Өзіндік «менін» осылай сезінуі — оның болашақтағы өзіне деген сенімінің негізі. Онымен бірге айна алдына тұрып, қаншалықты өскенін және нені үйренгенін атап өтіңіз.') WHERE id = '391d8114-3346-495b-b8f3-45861173d919';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Күрделі жүгіру». Бөпе енді жүгіріп келе жатып, алдындағы кедергілерден епті қимылмен өте алады. Бұл — дене күші мен жылдам шешім қабылдаудың үйлесімі. Үйде немесе аулада оған арнап шағын «кедергілер жолағын» жасап, ептілігін сынап көруіне мүмкіндік беріңіз.') WHERE id = '23f145d6-39f1-4e1e-84f1-49d36b707443';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Әңгімеші» кезеңі. Бөпе енді күн ішінде болған қарапайым оқиғаны (мысалы, «Құс ұшып кетті», «Балмұздақ жедім») есіне түсіріп, Сізге айтып бере алады. Оның осы шағын әңгімелерін мұқият тыңдап, сұрақтар арқылы толықтыруға көмектесіңіз. Бұл оның есте сақтау қабілетін де, оқиғалар арасында логикалық реттілік құру дағдысын да нығайтады.') WHERE id = 'c8794b59-4f44-4d01-9dfd-9f86547c80bb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Кітапқа сүйіспеншілік». Бөпе енді жұқа қағаз беттерін жыртпай, бір-бірден аудара алады. Ол сүйікті ертегі кітабын әкеліп, оқып беруіңіз үшін тізеңізге қояды. Бұл әдет оның тілінің дамуы мен Сізбен арасындағы эмоциялық байланыс үшін аса маңызды. Оқып отырғанда суреттер туралы сұрақтар қойыңыз.') WHERE id = '25aab72e-4248-42bb-9009-a3467dd34bf8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Алғашқы достық». Бөпе енді басқа балалармен жай ғана қатар ойнамайды, оларға ойыншық ұсынады немесе бірге жүгіреді. Бұл — әлеуметтік ынтымақтастықтың алғашқы нақты қадамдары. Оның осындай жағымды қарым-қатынасын қолдап, бөлісуге дайын болғаны үшін мақтаңыз.') WHERE id = 'fbc5e912-7941-46bd-9137-7aea112e7d13';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Гигиенаны өз бетінше сақтау». Бөпе енді қолын сабынмен жуып, сүлгімен құрғатуға талпынады. Өзіне-өзі қызмет көрсетудің бұл дағдылары оның дербестік сезімін нығайтады. Осы гигиеналық әдеттер күнделікті өмірінің табиғи бөлігіне айналуы үшін бойына сай қолайлы жағдай жасаңыз.') WHERE id = 'e689f8a3-742e-457c-849e-63c06d7af7c0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сөздік қордың күрт өсуі». Бала енді күн сайын бірнеше жаңа сөз үйреніп, 3-4 сөзден тұратын мағыналы сөйлемдер құрайды. Мысалы: «Мен саябаққа барғым келеді». Онымен сөйлескенде: «Саябақта не істегің келеді?» деген сияқты ашық сұрақтар қойыңыз. Бұл оның қиялын да, өз ойын жеткізу қабілетін де дамытады.') WHERE id = 'c49d7f6c-cef1-458f-99cb-da68585b7ac5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Шеңбер салу». Бала енді қарындашты сенімдірек ұстап, қағазға шеңберге ұқсас пішіндер салуға тырысады. Бұл — оның қол мен көз үйлесімінің жаңа деңгейі. Оған түрлі түсті қарындаштар мен үлкен қағаз беріп, «алғашқы суреттерін» салуына мүмкіндік жасаңыз.') WHERE id = '448009d5-07ef-4006-89f4-993bbe989179';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дербестік: «Мен өзім киінемін». Бала енді шұлығын шешіп қана қоймай, оны өзі киюге немесе киюге ыңғайлы шалбарын жоғары тартуға тырысады. Бұл үдеріс ұзаққа созылса да, оны асықтырмаңыз. Бір нәрсені өз бетінше істей алуы — ол үшін ең үлкен «марапат». Сіздің сабырлылығыңыз оның өзіне деген сенімін нығайтады.') WHERE id = 'ae5217ae-ff5f-4178-a4dd-001e8d391224';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Кезек ұғымы». Бала енді әткеншекке немесе сырғанаққа міну үшін кезек күту керегін түсінеді. «Қазір сенің кезегің, содан кейін досыңның кезегі» деген сөйлем оған анағұрлым түсінікті бола бастайды. Бұл — әлеуметтік ортаға бейімделу мен шыдамдылықты үйренудің маңызды кезеңдерінің бірі.') WHERE id = 'fd888eb3-7169-4c50-bc0d-f0696ed103ff';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Түстерді топтастыру». Бала енді 4-5 түрлі түсті бір-бірінен толық ажыратып, олардың көбінің атауын біледі. Оған «Барлық көк ойыншықтарды маған берші» деп, шағын тапсырма ұсынып көріңіз. Мұндай ойындар оның көріп талдау қабілеті мен есте сақтауын жақсартады.') WHERE id = '6aeca11f-b490-4362-b41c-539703e28816';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарының үйлесімі: «Доп тебу». Бала енді жүгіріп келе жатып, тепе-теңдігін жоғалтпай, алдындағы допты нысанаға қарай тебе алады. Бұл қимыл-қозғалыс пен зейінді бір нүктеге шоғырландыруды қатар қажет етеді. Онымен аулада шағын «футбол» жарысын өткізіп, ептілігін арттырыңыз.') WHERE id = 'da17a594-1250-4f85-98b1-50f0b6588294';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Реттеу және логика». Бала енді 4-5 затты көлеміне қарай (үлкенінен кішісіне дейін) реттей алады. Бұл — математикалық ойлаудың ең алғашқы негізі. Оған көлемі әртүрлі текшелер немесе ыдыстар беріп, осы реттеу дағдысын жаттықтырыңыз. Әр сәтті құрастырған қатары оның миында жаңа нейрондық байланыстар қалыптастырады.') WHERE id = 'd3ed6715-8284-423a-bbce-cfe0156fda68';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Екі аяқпен алға секіру». Бала енді бір орында ғана емес, алға қарай бірнеше сантиметрге секіре алады. Бұл аяқ бұлшықеттерінің шапшаң күшін және тепе-теңдікті жақсы сақтауды қажет етеді. Саябақта онымен бірге «Шұңқырдан секіру» ойынын ойнаңыз. Бұл әрі көңілді, әрі денесін басқаруды үйрететін жаттығу.') WHERE id = '710d761b-996a-4661-a9e2-1515ed31c7a0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Мен кіммін?». Бала енді өз есімін, жасын (саусақтарымен көрсетсе де) және жынысын айта алады. Бұл — оның өзін жеке тұлға ретінде сезінуінің маңызды шыңы. Онымен ертеңгі үлкен күн туралы сөйлесіңіз: «Ертең сен 2 жасқа толған үлкен бала боласың!».') WHERE id = 'ee27a56e-6e80-46b6-8a93-8ee183712978';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз! Бүгін балаңыз тура 2 жасқа толды! Сіз 730 күн бойы ғажайып шыдамдылық, сүйіспеншілік пен еңбек көрсеттіңіз. Балаңыз енді бөпелік кезеңнен өтіп, әлемді танып-білуге дайын кішкентай тұлғаға айналды. Осы ерекше күнді онымен бірге сүйікті ойындарын ойнап атап өтіңіз. Жарайсыз, Ана!') WHERE id = '493d8af7-6247-4790-9dba-5fe6ecd538f7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өмірінің үшінші жылының алғашқы күніне қош келдіңіз! Бала 2 жасқа толып, өзін «үлкен» сезінеді. Осы кезеңде ол өз заттары мен ойыншықтарына көбірек иелік ете бастайды. Оған өз бөлмесінде немесе ойын бұрышында шағын ережелер орнатуға мүмкіндік беріңіз. Бұл оның жауапкершілік сезімін қалыптастырады.') WHERE id = 'e1193c8b-9caf-42cc-b0d1-380bfd68848e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен еркін жүру». Бала енді баспалдақпен әр басқышта аяғын алмастырып, тек бір қолынан ұстаған кезде көтеріле алады. Бұл оның сан бұлшықеттері мен тепе-теңдік сақтау қабілетінің қаншалықты нығайғанын көрсетеді. Қауіпсіздік ережелерін еске салып, оған сенімділік беріңіз.') WHERE id = '23cbdeb8-6ec7-49eb-b8f0-c4ae1a3cb46c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде "Неге?" сұрағының пайда болуы. Бала айналасындағы барлық нәрсенің себебіне қызыға бастайды. "Неліктен бұлай?" деген сұраққа қарапайым әрі шынайы жауап беріңіз. Сіздің түсіндірулеріңіз оның санасында әлемнің қисынды картасын қалыптастырады. Оның қызығушылығын ешқашан жауапсыз қалдырмаңыз, бұл оның білім алуға деген ынтасын арттырады.') WHERE id = 'f3d92e61-3d30-4ede-90d4-27478dd2115f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық даму: "Дербестік және шекаралар". Бала кейде бәрін өзі жасағысы келіп, қолынан келмей қалғанда қатты ашулануы мүмкін. Мұндай сәттерде сабыр сақтап, "Түсінемін, сен мұны өзің жасағың келіп тұр" деп оның сезімін атап айтыңыз. Сіздің түсіністік танытуыңыз оның эмоцияларын реттеу қабілетін қалыптастырады.') WHERE id = '1f37d9cd-995a-4d88-97e4-8b7fdb37e3d8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді "Мен" есімдігінің мағынасын толық түсініп қолданады. "Мен келдім", "Мен тамақ жедім" деген сияқты сөйлемдер оның өзін айналасындағы адамдардан бөлек жеке тұлға ретінде сезінетінін көрсетеді. Оның осындай дербес ойларын қолдап, диалогті жалғастырыңыз: "Иә, сен дәмді тамағыңды жедің, жарайсың!".') WHERE id = 'bf78ea68-2a1f-4194-9ef3-62146ea4799d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында "Екі аяқпен алға секіру" дағдысы қалыптасады. Бала енді бір орында ғана емес, сәл алға қарай да секіре алады. Бұл — дене үйлесімділігінің жоғары деңгейі. Онымен саябақта "Қояндар көгалда секіреді" ойынын ойнаңыз. Бұл ірі моториканы дамытуға арналған тамаша жаттығу.') WHERE id = 'ce99df1c-1b81-4d41-b95d-9180c49c6d9f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Себеп-салдар" байланыстары. Бала енді оқиғалар арасындағы байланысты түсінеді: "Жаңбыр жауып тұр, мен су болдым" немесе "Тамақ ыстық, үрлеу керек". Оның осындай қисынды пайымдарын мақтаңыз. Бұл оның тілдік және абстрактілі ойлау қабілеттерінің қаншалықты дамығанын көрсетеді.') WHERE id = 'bcee9d16-cb48-4f63-9295-23b44110e7d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада "Бұрау және айналдыру шеберлігі". Бала бөтелке қақпақтары мен ойыншық бұрандаларын сенімді түрде ашып-жаба алады. Бұл — білек бұлшықеттерінің икемділігін арттыратын тамаша жаттығу. Оған өлшемдері әртүрлі қауіпсіз ыдыстар беріп, зерттеуге деген қызығушылығын қолдаңыз.') WHERE id = 'bff29c40-0fa8-45dd-982c-f35a2f18ac52';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Рөлдік ойындардың күрделенуі". Бала енді бірнеше рет-ретімен орындалатын әрекеттен тұратын ойындар құра алады: мысалы, ойыншық қонжығын "жуындырады", "сүртеді", содан кейін "ұйықтатады". Бұл оның жадындағы күнделікті өмір көріністерін жүйелі түрде қалай байланыстыратынын көрсетеді.') WHERE id = 'd343f65f-f46a-44dd-a5fc-a51c1510c094';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өздігінен тамақтану". Бала шанышқы мен қасықты ештеңе төгіп-шашпайтындай дерлік шебер қолдана алады. Оған тамақты өздігінен жеуіне толық мүмкіндік беріңіз. Бұл оның тойғанын сезінуі және өзіне деген сенімділігі үшін өте маңызды.') WHERE id = '61ba4f1e-aa7b-426a-97ad-a9a4240347af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Бөлшектерден бүтін құрастыру". Бала енді 4-6 бөліктен тұратын қарапайым пазлдарды (басқатырғыштарды) көріп отырып құрастыра алады. Бұл зейінін шоғырландыруды да, мәселені шешу қабілетін де дамытады. Қолынан келмей жатса, оған сабырлы үнмен көмектесіңіз: "Қарашы, бұл иттің құйрығы, ол қай жерде болуы мүмкін?".') WHERE id = 'd008eb87-e4b7-4791-98e4-80774b7e5fc4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты иықтан асыра лақтыру". Бала енді допты жай ғана жерге тастамай, оны иықтан асыра (overhand) алға лақтыруға тырысады. Бұл қимыл бүкіл дененің үйлесімді жұмысын қажет етеді. Онымен саябақта "Допты кім алысырақ лақтырады?" ойынын ойнаңыз.') WHERE id = '018d47a4-b94c-4bab-a923-24c091f9e302';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Өтініш пен әдептілік". Бала енді бір нәрсе сұрағанда саусағымен жай ғана көрсетпей, "Берші" немесе "Өтінемін" (тіпті өз тілінде болса да) деп айтуға тырысады. Сіздің сыпайы қарым-қатынасыңыз оның сөйлесу мәнерін қалыптастырады. Сіз әр жолы "рақмет" дегенде, ол да осы әдепті табиғи түрде бойына сіңіреді.') WHERE id = '11cb7320-ce82-47a0-a231-8d9923b30f4a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық дайындық: "Қорқыныш пен қиял". Бұл жаста балалар кейде қараңғыдан немесе белгілі бір дыбыстардан қорқа бастауы мүмкін. Бұл — қиялдың дамып келе жатқанының белгісі. Оның қорқынышын күлкіге айналдырмаңыз, тек жанында болып, құшақтаңыз және қауіпсіз жерде екенін сездіріңіз. Сіздің қолдауыңыз оның эмоциялық тұрақтылығын арттырады.') WHERE id = '4edde2f0-76ee-4d3a-a2af-2d7d71d87764';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді жай ғана танып қоймай, оларды сәйкестендіруді де жақсы меңгеріп келеді. Оған «Қызыл шұлығыңның сыңарын тап» дегенде дұрыс тапса, бұл оның көрнекі ойлау қабілетінің дамып келе жатқанын көрсетеді. Күнделікті киіну кезінде түстерге жиі назар аударыңыз: «Бүгін жасыл жейдеңді киеміз бе?». Бұл оның сөздік қорындағы сын есімдерді бекітуге көмектеседі.') WHERE id = 'f4611a68-9983-4caf-808b-4616cf4c60d5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Бір аяқпен тепе-теңдік сақтау». Бала енді бірнеше секунд болса да, бір аяғын жерден көтеріп, тепе-теңдігін сақтауға тырысады. Бұл — дененің ауырлық орталығын басқаруды қажет ететін күрделі үйлесімді қимыл. Онымен «Ләйлек» ойынын ойнаңыз. Бұл әрі көңілді, әрі дене дамуына өте пайдалы.') WHERE id = 'c7634c82-b4b5-450c-9811-7e5cbdc218af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт ұғымының алғашқы белгілері». Бала «қазір», «кейін» сияқты сөздердің айырмашылығын түсіне бастайды. Оған «Алдымен тамақ ішеміз, содан кейін саябаққа барамыз» дегенде күте алса, бұл — үлкен жетістік. Шыдамдылық дағдысы қалыптасуы үшін іс-әрекеттеріңіз арқылы уақыт ретін түсіндіруді жалғастырыңыз.') WHERE id = '2c927604-0f3e-4615-94c5-86dc48b7896a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәл құрастыру». Бала енді конструктордың ұсақ бөлшектерін немесе текшелерді бір-біріне ұқыптырақ жалғайды. Бұл зейінді шоғырландыруды да, саусақ ұштарының дәлдігін де қажет етеді. Оның «инженерлік» талпыныстарын қолдап, «Бұл ненің үйі?» деп сұраңыз.') WHERE id = '92d8aec4-818c-4b3a-abd3-dd724c129df5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше су ішу». Бала енді ашық стақаннан суды төкпей дерлік, сенімді түрде ішеді. Бұл оның ерін және жақ бұлшықеттерінің сөйлеуге қаншалықты дайын екенін көрсетеді. Осы дағдыны толық меңгеруі үшін оған балаға арналған, ұстауға ыңғайлы стақандар беруді жалғастырыңыз.') WHERE id = '659e2094-8141-4a5a-bed6-c6f715c75799';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әзіл және қалжың». Бала әдейі бір нәрсені «дұрыс емес» жасап (мысалы, бас киімін қолына киіп), Сізге қарап күлуі мүмкін. Бұл оның әзілді түсіне бастағанын және айналасындағылардың реакциясын байқау қабілеті қалыптасып келе жатқанын көрсетеді. Оның бұл «ойынына» қуана қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты одан әрі нығайтады.') WHERE id = 'c1045492-8f8e-491f-a86f-8a5ceb126f15';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Себебін іздеу». Бала әлі «Неге?» деп толық айта алмаса да, іс-әрекеттері арқылы оқиғалардың себебін білуге тырысады. Оған: «Күртешені киеміз, өйткені далада жел соғып тұр», — деп түсіндіріңіз. Оқиғалар арасындағы логикалық байланысты көрсету — оның болашақта логикалық ой қорытуына қаланатын ең маңызды негіз.') WHERE id = 'f63d183c-6b97-43da-8c82-1a87c629cc0d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Бұрап ашу және айналдыру шеберлігі». Бала бөтелкелердің қақпақтарын немесе ойыншық бұрандаларын сенімді түрде ашып-жаба алады. Бұл қимыл білек бұлшықеттерінің икемділігін дамытуға арналған тамаша жаттығу. Оған өлшемдері әртүрлі қауіпсіз ыдыстар беріп, механизмдерді зерттеуге деген қызығушылығын қолдаңыз.') WHERE id = '583cd090-6bc1-4438-afd7-8703fd352e08';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Дербес таңдау» және ерік-жігер. Бала не киетіні немесе қай ыдыстан тамақ ішетіні туралы өз қалауын анық білдіре алады. Оған «Бүгін көк жейдені киесің бе, әлде жасылын ба?» деген сияқты таңдау ұсыну өзін жеке тұлға ретінде сезінуіне көмектеседі және қырсығу ұстамаларын барынша азайтады.') WHERE id = '5377658a-72e7-437d-b697-abdb7c76bfcd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Ынтымақтастық». Бала Сізге көмектесуден үлкен қуаныш алады. «Кел, азық-түлік салынған сөмкеден нанды шығарайық», — дегенде Сізге қосылуы оның отбасындағы өз рөлін түсіне бастағанын көрсетеді. Бұл жауапкершілік сезімін қалыптастырып қана қоймай, араларыңыздағы байланысты да нығайтады.') WHERE id = '57201085-ec92-4795-8598-90d9a04fb33a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Санаттар». Бала бір түрге жататын заттарды (мысалы, барлық жануарды бір жерге, барлық мәшинені басқа жерге) топтастыра алады. Оған «Мұнда қай ойыншық өзгеше?» деген сияқты сұрақтар қойып, көрнекі логикасын тексеріңіз. Санаттар бойынша ойлау оның танымдық қабілетін жаңа деңгейге көтереді.') WHERE id = 'ffdc805c-2aad-4971-afc7-9cb3c0053b5c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Қос аяқпен секіру шеберлігі». Бала бір орында биігірек немесе сәл алға қарай сенімді секіре алады. Бұл аяқ бұлшықеттерінің нығайып келе жатқанын білдіреді. Онымен «Көгалдағы қояндар» ойынын ойнаңыз: бұл әрі көңілді, әрі ірі моториканы дамытуға пайдалы.') WHERE id = 'dcd7700f-4c1a-40e7-9469-0739827e396d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Биіктік пен қашықтық». Бала енді баспалдақтан немесе диваннан түскенде қашықтықты жақсырақ бағалай алады. Оған әрдайым абай болуды және қауіпсіз түсу жолдарын (артпен түсуді) еске салып отырыңыз. Бұл — оның дене қауіпсіздігі ережелерін меңгеруіндегі маңызды кезең.') WHERE id = 'c7630ee3-1695-4062-9e13-7540975aa465';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Артқа жүру шеберлігі». Бала енді артына қарамай, бірнеше қадам артқа жүре алады. Бұл оның өз денесінің кеңістіктегі орнын сезінуі (проприоцептивті сезім) үшін маңызды. Оған «Шаян сияқты жүрейік» деп, бұл қимылды ойынға айналдырыңыз. Сізбен бірге қимылдау — ол үшін әлемдегі ең қызықты ойын.') WHERE id = 'e1577858-a1db-40b1-bd39-0ce8d678ff7a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Есім мен есімдіктің байланысы». Бала енді өзін атымен атаудан «Мен» деуге толықтай көшеді. Сіз одан бір нәрсе сұрағанда «Мен» немесе «Менікі» десе, бұл оның өзін жеке тұлға ретінде сезінуі толық қалыптасқанын көрсетеді. Онымен осы тақырыпта диалог құрыңыз: «Бұл кімнің добы? Менікі!».') WHERE id = 'a37651fe-7cc3-4f59-bbce-f7763c1637a8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Бала енді «Болмайды» деген сөзге жауап береді, бірақ кейде Сіздің реакцияңызды тексеру үшін ережені әдейі бұзуы мүмкін. Сабырлы, бірақ табанды болу — ең маңызды шарт. Егер бір нәрсеге «жоқ» десеңіз, әр жолы сол ұстанымыңыздан айнымаңыз. Ережелердің тұрақтылығы баланың бойында ішкі тәртіп пен қауіпсіздік сезімін қалыптастырады.') WHERE id = '8f5c35ba-05d9-40e2-a687-7bfe8146f1ee';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '26-айға қадам бастық! Бала енді екі түрлі тапсырманы бірінен соң бірін шебер орындай алады. Мысалы: «Ойыншықты ал да, сөреге қой». Бұл оның есте сақтау қабілеті мен тілді түсінуі жаңа деңгейге жеткенін көрсетеді. Күні бойы осындай шағын «міндеттер» беріп, өзін пайдалы сезінуіне мүмкіндік жасаңыз.') WHERE id = '86c6ccb4-326d-41d5-81c5-ea4c8d0faf13';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Жылдам маневр». Бала енді жүгіріп келе жатып бағытын кенет өзгерте алады немесе кедергілерді ептілікпен айналып өте алады. Бұл оның бұлшықет күші мен жылдам шешім қабылдау қабілетінің дамығанын көрсетеді. Саябақта онымен «қуаласпақ» ойнап, денесін басқару қабілетін жетілдіріңіз.') WHERE id = 'eb8969ec-bb8d-48c5-8dfb-f818249bf8e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сәтсіздікті жеңе білу». Бөпеңіз енді текшелері құлап қалса, бірден жыламай, «Қайтадан құрастырамын» деп айта алады. Оның осындай табандылығын қолдаңыз. 1030 күн артта қалды – балаңыз енді кішкентай қаһарман!') WHERE id = '1293c75f-beda-4513-88cc-b7951ec10777';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Үш дөңгелекті велосипедті еркін тебу». Балаңыз енді рөлді басқара отырып, бір мезгілде педальдарды да ырғақты айналдыра алады. Бұл — дененің төменгі және жоғарғы бөліктері қимылдарының тамаша үйлесімі. Саябақтағы серуендерді белсендірек өткізетін уақыт келді.') WHERE id = 'e81ab935-f108-46cd-a88f-e53e09ed924f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісудің мәні». Бала енді басқа баланың қолындағы ойыншықты бірден тартып алмай, «бер» деп айтып, күтуге тырысады. Бұл — өзін-өзі реттеу (self-regulation) дағдысының нығайып келе жатқанының белгісі. Оның осындай сабырлы әрекетін байқағанда, міндетті түрде: «Кезегіңді күткеніңе көп рақмет», — деп мақтаңыз.') WHERE id = '71a96327-cfe2-4ab5-bb79-d332a1ff5de4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық жетілу: «Кешір» сөзінің мағынасы. Бала енді біреуді әдейі немесе байқамай ренжіткенде «Кешір» деудің әлеуметтік маңызын түсінеді. Оған әрдайым үлгі болыңыз; қателескен кезде одан кешірім сұраңыз, сонда ол да мұндай әрекетті әлсіздік емес, күштің белгісі деп қабылдайды.') WHERE id = 'f7b6ee04-7015-4382-abaa-03462e452408';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды бір уақытта екі белгісіне қарай (мысалы, түсі мен пішініне қарай) ажырата алады. Сіз оған «Маған кішкентай қызыл мәшинелердің бәрін берші» дегенде орындай алса, бұл — оның когнитивті дамуының жаңа деңгейге көтерілгенінің белгісі. Күнделікті үй шаруасында оған осындай шағын «таңдау» тапсырмаларын беріп көріңіз.') WHERE id = 'fa3d103a-9bc8-44ef-b8d5-cab5337e7b60';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігіндегі «Нысанаға секіру». Бала енді жерге сызылған шеңбердің немесе түрлі түсті нысананың ортасына секіруге тырысады. Бұл тепе-теңдікті сақтауды да, кеңістіктегі қашықтықты есептеу қабілетін де жетілдіреді. Саябақта онымен «тастан тасқа секіру» ойынын ойнаңыз.') WHERE id = '4bbc0ebb-e4d4-4fb1-9a60-923e8fae76b3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу тіліндегі «Қарама-қарсы мағыналы сөздер қорын кеңейту». Бала енді «тез-баяу», «қараңғы-жарық», «бос-толық» сияқты дерексіз қарама-қарсылықтарды түсінеді. Оған бос және су толы стақанды көрсетіп, айырмашылығын сұраңыз. Бұл оның қоршаған ортаны салыстырып талдау қабілетін нығайтады.') WHERE id = 'a89f9de3-ed84-4cfa-95a8-cf4c5d345de7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пазл құрастыру шеберлігі». Бала енді күрделі 10-12 бөліктен тұратын пазлдарды суреттің шеттері мен ортасын ажырата отырып құрастыра алады. Бұл көру арқылы есте сақтау қабілетін де, саусақтарының дәл қимылдау шеберлігін де дамытады. Қолынан келмей жатса, оған сабырлы үнмен бағыт беріңіз.') WHERE id = '81c4bfcb-e5df-4929-b621-91e622f18ac6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше жинау және көмектесу». Бала енді дастарқанды жинағанда өз тәрелкесін апару, қиқымдарды сүрту сияқты істерге үлкен қызығушылық танытады. Оған бойына сай келетін тазалық құралдарын беріңіз. Бұл оның отбасындағы жауапкершілік пен ортақ іске қатыстылық сезімін нығайтады. Өз еңбегінің нәтижесін көру оны ерекше қуантады.') WHERE id = '9ef3f34d-a63f-4f49-9005-c854d4303909';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Ережелер мен шекаралар». Бала енді «жоқ» деген сөздің себебін біршама жақсырақ түсінеді, бірақ әлі де шекараны сынағанды ұнатады. Сіздің сабырлы әрі бірізді болуыңыз оған қауіпсіздік сезімін береді. Ережелерді әрдайым бірдей ұстануға тырысыңыз.') WHERE id = 'c4d24c3e-4601-4235-8cdc-f39b3aa35149';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Реттік сандар». Бала енді «бірінші», «екінші», «соңғы» ұғымдарын түсінеді. Ойыншық көліктерді бір қатарға тізіп, «Қай көлік бірінші тұр?» деп сұраңыз. Бұл оның реттілік туралы түсінігі мен математикалық ойлауын дамытады. Жарыс кезінде «Сіз бірінші келдіңіз!» деу оған үлкен жігер береді.') WHERE id = 'b0d3eed0-e639-4528-9c81-8601b70e54bd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Артқа және жанымен жүру». Бала енді әртүрлі бағытта епті қозғала алады. Онымен «Айна ойынын» ойнаңыз: Сіз бір қадам жанға жасаңыз, ал ол қимылыңызды қайталасын. Бұл әрі көңілді, әрі дене қимылдарын үйлестіру қабілетін жаңа деңгейге көтереді.') WHERE id = 'da0e2216-17ef-49f2-83ad-1599f6a6e332';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді "алдымен" және "содан кейін" деген реттілікті тереңірек түсінеді. "Киіміңді ки, содан кейін далаға шығамыз" дегенде, ол екінші әрекеттің марапат екенін ұғынады. Бұл — баланың бойында шыдамдылық пен жоспарлау дағдыларының алғашқы қалыптасу кезеңі. Күнделікті әдеттер кезінде осы реттілікті оған жиі еске салып отырыңыз.') WHERE id = '2add65f7-d33c-4b48-a1e7-f388a5549421';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы "Өрмелеу шеберлігі". Бала енді саябақтағы баспалдақтарға немесе үйдегі қауіпсіз биіктіктерге сенімдірек көтеріледі. Бұл кезде қол мен аяқ бұлшықеттері үйлесімді жұмыс істейді. Әрдайым жанында болыңыз, бірақ оған өз күшін сынап көруге мүмкіндік беріңіз.') WHERE id = '25d5eedf-59a2-4e4e-8131-39a811d36fe6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Логикалық байланыстар". Бала енді екі оқиғаны бір сөйлемде байланыстырады: "Күн суық, күртеңді ки". Бұл оның жай ғана қайталамай, ойлана да алатынын көрсетеді. Өз ойын білдіруге ынтасы арта түсуі үшін оның осындай логикалық пайымдарын "Иә, дұрыс айтасың" деп қолдаңыз.') WHERE id = '90469c76-8fc0-41db-a7e9-3862f12f4d6b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Қағазбен жұмыс істеу". Бала енді қағазды бүктеуге немесе оны қарапайым түрде қиюға (балаларға арналған үлкен қайшымен және ересектің бақылауымен) қызығушылық танытуы мүмкін. Бұл әрекеттер саусақ бұлшықеттерін басқару қабілетін жаңа деңгейге көтереді. Оған түрлі түсті қағаздармен жұмыс істеуге жағдай жасаңыз.') WHERE id = '8f149cc4-a06e-4928-a8cb-2b953480c3af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Рөлдік ойындардың күрделенуі". Бала енді "дәрігер", "аспаз" немесе "жүргізуші" рөліне енеді. Осындай ойындар арқылы ол айналасындағы адамдардың міндеттерін түсініп, жанашырлық танытуды үйренеді. Оның ойындарына қосылып, Сізге берген "рөлге" сай әрекет етіңіз.') WHERE id = 'c9bd395e-c3c2-46e2-abf3-1f924d619000';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше тазалық сақтау" дағдысы. Бала енді қолын жуған кезде сабындап, шаюды дерлік өз бетінше орындай алады. Осы жаста гигиеналық дағдыларды бекіту өте маңызды. Бұл үдерісті ұнатуы үшін оған бойына сай шағын басқыш (step stool) дайындап қойыңыз.') WHERE id = 'dd1b7d3a-2552-45df-81c5-cf8e1914b882';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше киіну: Киімнің өңі мен терісін ажырату". Бала енді жейде мен шалбардың өңі мен терісін, аяқкиімнің оң және сол сыңарын (кейде қателессе де) ажыратуға тырысады. Оған шағын кеңестер беріңіз: "Қарашы, суреті бар жағы алдына қарауы керек". Бұл оның ұсақ-түйекке назар аударуын және өзіне-өзі қызмет көрсету дағдыларын жетілдіреді.') WHERE id = 'a1a89564-b6bb-483a-bd10-bb44b24484a4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Командалық рух". Бала енді басқа балалармен бірге ортақ мақсатқа жету үшін (мысалы, үлкен қамал тұрғызу үшін) ойнай алады. Бұл — "Қатар ойнаудан" "Бірлесіп ойнауға" өту кезеңі. Оның басқа балалармен қалай тіл табысатынын бақылаңыз және күрделі сәттерде араларында әлеуметтік "көпір" орнатуға көмектесіңіз.') WHERE id = '999ddf88-03eb-4dd0-856d-79ce3e7385df';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Сан мен мөлшердің сәйкестігі". Бала 1-ден 5-ке дейін санай алады, енді "3" санын көргенде 3 ойыншықты бөліп қоя алады. Бұл — математикалық ойлау дамуының ең маңызды кезеңдерінің бірі. Күнделікті өмірде "Маған 2 қасық берші" сияқты тапсырмалар арқылы осы байланысты нығайтыңыз.') WHERE id = '8193ed91-5f04-4955-a4b1-522d5a941870';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Жоғарыдан лақтырылған допты қағып алу". Бала енді өзіне қарай баяу лақтырылған үлкен допты екі қолымен қағып алуға тырысады. Бұл қимыл қол-көз үйлесімін де, реакция жылдамдығын да қажет етеді. Онымен жақын қашықтықтан допты бір-біріңізге лақтырып, қағып алу ойынын ойнаңыз.') WHERE id = '575cf871-23de-446e-8398-4dd4c0ff6773';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы "Абстрактілі сұрақтардың шарықтау шегі". Бала енді "Жел неге соғады?", "Күн ұйықтауға қайда кетеді?" деген сияқты тіршілік пен табиғат құбылыстары туралы сұрақтар қояды. Жауап бергенде қиялды да қосыңыз: "Күн шаршады, ертең бізді қайта ояту үшін демалуға кетіп барады". Бұл оның дүниетанымы мен білімге деген құштарлығын арттырады.') WHERE id = 'fdfb7732-94cf-4e6c-8519-4e6877b4ad89';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық жетілу: "Басқа адамның эмоциясын қабылдау". Бала енді Сіздің шаршағаныңызды немесе басқа баланың ренжігенін көргенде "Не болды?" деп сұрап, жұбатуға тырысады. Бұл оның жанашыр тұлға болып қалыптасып келе жатқанын көрсетеді. Сіз керемет анасыз!') WHERE id = '9721a15c-607b-4236-9999-231bdd0b4e99';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі сұрақтардың тереңдеуі». Бала «Бұлттар қайда кетеді?», «Жұлдыздар неге түнде шығады?» деген сұрақтарымен Сізді таңғалдыруы мүмкін. Жауап бергенде оның қиялын да іске қосыңыз: «Сеніңше, жұлдыздар қазір не істеп жатыр?». Бұл оның шығармашылық ойлауын дамытады.') WHERE id = '1f153d5c-5da7-4c69-b731-2dc34e06cb4f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Бөлісудің қуанышы». Бала өз еркімен ойыншығын немесе тәттісін бөліскенде, Сіздің қуанғаныңызды байқап, мұны қайта жасағысы келеді. Оның жомарттығын «Досыңды қуантқаның үшін көп рақмет» деп ерекше атап өтіңіз. 1040 күнді сәтті аяқтадық – Сіз керемет анасыз!') WHERE id = '3c9e08eb-1969-4283-90ec-97d2de26fd19';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '35-ші айға қадам басамыз! Бала енді «екі кезеңді» ойлаудан «үш кезеңді» тапсырмаларға көшеді. «Ойыншықты ал, қорапқа сал да, қақпағын жап» дегенде ретін бұзбай орындаса, бұл оның жұмыс жадының (working memory) үлкен жетістігі. Күні бойы оған шағын әрі бір-бірімен логикалық байланысқан тапсырмалар беріп, осы дағдысын жетілдіріңіз.') WHERE id = 'b4ed41fc-fc60-439e-82df-81e0242123d3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Жылдам жүгіру және маневр жасау». Бала енді жүгіріп келе жатып алдындағы кедергіні көрсе, жылдамдығын бәсеңдетпей-ақ оны айналып өте алады. Бұл оның денені сезіну қабілетінің (proprioception) толық қалыптасқанын көрсетеді. Саябақта «кедергілермен жүгіру» жарыстарын өткізіп, оның күш-қуатын пайдалы арнаға бағыттаңыз.') WHERE id = '140764ec-2a00-4bc6-b514-5e093357430f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Салыстыру шырайлары». Бала енді «үлкенірек», «ең кішкентай», «өте дәмді» сияқты тіркестерді орынды қолданады. Заттарды салыстыра отырып, онымен сөйлесіңіз: «Мына алма тәттірек пе, әлде анау ма?». Сын есімнің шырайларын меңгеру оның сипаттап сөйлеуін байытып, ойын нақты жеткізуіне көмектеседі.') WHERE id = '5868f762-ea68-431f-855d-54c5a04efe50';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Мүсіндеу». Бала енді ермексазбен немесе кинетикалық құммен ойнағанда оларды жай ғана қыспай, «доп», «жылан» немесе «нан» тәрізді тан recognizable пішіндер жасайды. Бұл шығармашылық ойлауды дамытуға да, саусақ ұшындағы ұсақ бұлшықеттерді нығайтуға да арналған тамаша жаттығу.') WHERE id = '060a9ae6-7e66-446f-800a-a74eb2d502d9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Артығын тап» ойыны. Бала енді заттар тобының ішінен өзгеше затты (мысалы, көліктердің арасындағы алманы) көзбен ажырата алады. Бұл оның талдау қабілетін шыңдайды. Үйде оған қарапайым «Не артық?» ойындарын ұйымдастырыңыз. Бұл болашақтағы математикалық және логикалық тапсырмаларға тамаша дайындық.') WHERE id = 'f8163db2-8f81-44fa-bc05-1057d8b42f15';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Бір аяқпен тұруға талпыныс». Бала бірнеше секунд болса да, бір аяғын жерден көтеріп, тепе-теңдігін сақтауға тырысады. Бұл денесінің ауырлық орталығын сезінуі үшін маңызды. Онымен «Ләйлек» ойынын ойнап, кімнің бір аяқпен ұзағырақ тұра алатынын байқап көріңіз.') WHERE id = '0dbea1ae-3808-4d99-b129-68ed1447a173';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сезімдерді білдіру». Бала енді мұңайғанын, қуанғанын немесе қорыққанын сөзбен айта алады: «Мен қорықтым» немесе «Мен қуаныштымын». Сезімдерді атай білу — баланың эмоциялық интеллектінің негізі. Ол сезімін айтқанда, мұқият тыңдап, «Иә, мен сені түсінемін» деп оның сезімін мойындаңыз.') WHERE id = '384f5938-24c1-4dc2-8691-403780565471';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың күші: «Символдық ойлау». Бала таяқты «ат» деп елестетіп, оны мініп шауып жүргендей ойнай алады. Бұл — бір заттың басқа нәрсені бейнелейтінін түсіну қабілеті. Бұл дағды болашақта оқу мен математиканы меңгеру (таңбаларды түсіну) үшін өте маңызды. Сіз керемет бағыт-бағдар беріп жүрсіз!') WHERE id = '94697180-1105-4fe0-9d68-ffdaab53705e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «мен», «сен» және «біз» есімдіктерін орынды қолданады. «Біз қазір тамақ ішеміз бе?» деп, өзін отбасының белсенді мүшесі ретінде сезінеді. Онымен сөйлескенде, оны да жоспарларыңызға қосыңыз: «Кел, дастарқанды бірге жаяйық». Бұл оның отбасыға тиесілі екенін сезінуін және жауапкершілігін нығайтады.') WHERE id = '38010093-f42b-4818-a3db-81219f590eee';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен еркін көтерілу». Бала енді әр басқышқа бір аяғын кезек-кезек қойып, бір қолынан ғана ұстаған кезде баспалдақпен сенімді көтеріледі. Бұл оның жалпы моторикасының жақсы жетілгенін көрсетеді. Сіз тек жанында болып, оған рухани қолдау көрсетіңіз.') WHERE id = '8503d4e9-2c78-4879-9d8c-ef7c6d2a467c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме құрастыру». Бала енді суреттерге қарап, қарапайым әңгімелер ойлап табады. «Мысық келді, сүт ішті де, ұйықтап қалды» деген сияқты бірізді сөйлемдер оның жады мен қиялының үйлесімін көрсетеді. Оған қызықты суреттері бар кітаптар беріп, «Мұнда не болып жатыр?» деп сұраңыз. Бұл оның шығармашылық ойлауын дамытады.') WHERE id = 'ebe63eb5-d3b9-410d-8ddc-267b97751075';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәл орналастыру». Бала енді кішкентай ойыншық мүсіндерді орналастыруды немесе моншақтарды жіпке тізуді азырақ қателесіп орындай алады. Бұл кезеңде саусақ ұштарының сезімталдығы артады. Оған түрлі құрылымы бар ұсақ заттармен ойнауды ұсыныңыз (міндетті түрде бақылауыңызбен).') WHERE id = '9acc3fd3-37ec-4b80-9709-ac31444a2801';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше киінуге» деген табандылық. Бала енді түймесіз жейделерін немесе шалбарын өзі киюге тырысады. «Өзім!» деген сәттерде оған уақыт беріңіз. Өз бетінше әрекет етуге деген мұндай талпыныстар — болашақтағы өзіне деген сенімділік пен жеке жауапкершіліктің берік негізі. Кішкентай жетістіктерін «Қарашы, өзің-ақ істей алдың!» деп атап өтіңіз.') WHERE id = '48d41fa6-6f48-4a84-a2b6-f82cae4ce209';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әдептілік ережелері». Бала енді «Өтінемін», «Көп рақмет», «Рұқсат болса» сияқты сөздерді жай ғана қайталамай, орынды қолданады. Сіздің сыпайы қарым-қатынасыңыз — ол үшін ең жақсы үлгі. Осындай әрекеттерін мақтап, оның қарым-қатынас мәдениетін нығайтыңыз.') WHERE id = 'fe3ec85d-8b47-408d-a0ad-870b3b58db94';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мезгіл үстеулері». Бала «кейін», «сәлден соң», «қазір» сөздерін орынды қолдана бастайды. Сіз «Сәлден соң келемін» дегенде, ол біраз уақыт өтуі керектігін түсінеді. Бұл баланың күте білу және өзін-өзі реттеу дағдыларын арттырады. Күнделікті әдеттеріңізде осы сөздерді жиі қолданыңыз.') WHERE id = 'df8b2f32-9f00-4805-8e4c-c754c399be31';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Доп тебу және нысанаға бағыттау». Бала енді допты жай ғана теппей, оны белгілі бір бағытқа, мысалы, екі ойыншықтың арасынан өткізуге тырысады. Бұл — қол-көз және аяқ-көз үйлесімінің қатар жұмыс істеуі. Онымен үйде «шағын футбол» турнирін өткізіңіз.') WHERE id = '852439ac-fd00-4ba1-aa13-d519b9407d5f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Дербес шешімдер". Бала енді қай ойыншықпен ойнайтынын немесе қай кітапты оқитынын нақты таңдайды. Оған бұл таңдауды өз бетінше жасауға мүмкіндік беріңіз. Өз таңдауына құрметпен қарайтынын сезіну баланың өзіне деген сенімін арттырып, ішкі дүниесінің баюына көмектеседі.') WHERE id = '064446a8-f711-4f01-89fb-101964123929';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Кезек күту". Бала енді бәрі бір уақытта әткеншек тебе алмайтынын түсінеді. Оның "Қазір ол тебеді, содан кейін мен" деп айта алуы — әлеуметтік зерденің дамуындағы үлкен қадам. Бұл әрекет әдетке айналуы үшін оның сабырлылығын міндетті түрде мақтаңыз.') WHERE id = '9280edaf-2356-4dce-a273-2cd4a5d6fd57';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Сұрыптау және санаттарға бөлу". Бала енді заттарды тек түсіне қарай емес, қолданылуына қарай да топтастырады: "Бұлар — тағамдар, ал бұлар — ойыншықтар". Оған аралас заттарды беріп, "Асүйге қатысты заттарды тап" деп айтыңыз. Бұл оның миындағы ақпаратты жүйелеуге көмектеседі.') WHERE id = '55b33de4-6e1b-4815-985d-641594c12f05';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты иықтан асыра лақтыру". Бала енді допты тек төменнен емес, иық деңгейінен алға қарай лақтыра алады. Бұл қол мен иық бұлшықеттерінің нығайғанын және оның қимыл траекториясын жоспарлай алатынын көрсетеді. Онымен саябақта "нысанаға лақтыру" сияқты шағын ойындар ойнаңыз.') WHERE id = 'eb04363a-ab4d-4a94-888d-e7e2e5211e9c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Есімдіктерді дұрыс қолдану". Бала енді "мен", "сен", "ол", "біз" есімдіктерін іс жүзінде шатастырмайды. Бұл оның әлеуметтік ортадағы өз орнын және басқалармен қарым-қатынасын толық түсінетінін білдіреді. Онымен сөйлескенде күрделі сөйлемдерді қолданудан тартынбаңыз.') WHERE id = '4705908e-12af-4329-ab11-ab69b76d1be9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: "Қателіктерден үйрену". Баланың бір ісі ойдағыдай шықпаса, ол бірден жыламай, Сізге қарап: "Болмады, қайтадан жасап көрейін бе?" деп сұрауы мүмкін. Бұл оның эмоциялық төзімділігінің артып келе жатқанын көрсетеді. Оған "Әркім қателесуі мүмкін, ең бастысы — қайтадан байқап көру" деп жігер беріңіз. Сіз керемет жол көрсетушісіз!') WHERE id = 'cb464c9f-f6c4-48c0-ab1a-62c435d01c32';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі сұрақтар». Бала «Бұлт қайдан келеді?», «Ай қайда кетті?» деген сұрақтар қоюы мүмкін. Жауап бергенде қиял мен шынайы ақпаратты үйлестіріңіз: «Бұлттар алыстан келіп, бізге жаңбыр әкеледі». Осындай әңгімелер оның дүниетанымы мен білімге деген құштарлығын айтарлықтай кеңейтеді.') WHERE id = 'fe4cb6a5-1e61-4aaa-9066-7165c1ab72dd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: бала сәтсіздікке бұрынғыдан сабырлырақ қарайды. Текшелері құлап қалғанда бірден жыламай, «Қайтадан құрастырамын» деп айта алады. Оның осы табандылығын қолдаңыз. 1070 күн артта қалды, 3 жасқа толуына аз ғана уақыт қалды! Сіз бұл жолда әрі ұстаз, әрі ең жақын доссыз!') WHERE id = '39f0d5e2-0187-4785-9bb9-453ef9250d3e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала өзін басқа балалармен салыстыра бастайды: «Мен одан жылдам жүгіремін». Бұл бәсекелестік сезімінің емес, өз мүмкіндіктерін түсіне бастауының бір көрінісі. Оған әр адамның қабілеті әртүрлі болатынын қарапайым тілмен түсіндіріңіз. Бұл оның өзін құрметтеуіне және өзгелерге төзімділікпен қарауына көмектеседі.') WHERE id = 'b9b4b281-d07d-4b24-8be3-a13d61d2de12';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Жылдам тоқтау». Бала жүгіріп бара жатқанда Сіздің «Тоқта!» деген пәрменіңізді естіп, бірден тоқтай алады. Бұл оның бұлшықеттерін басқара алатынын және миындағы импульстерді тежеу қабілетінің (inhibitory control) дамығанын көрсетеді. Саябақта «Қызыл шам, жасыл шам» ойынын ойнауға таптырмас уақыт.') WHERE id = '36d86d2b-43c1-4460-afbb-45a783701a53';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Күрделі диалогтер». Бала енді бір оқиғаны Сізге ретімен айтып бере алады. «Алдымен саябаққа бардық, содан кейін балмұздақ жедік, кейін мысық көрдік». Оның әңгіме құра білуі — жады мен сөйлеу қабілетінің үйлесімді дамуының белгісі. «Содан кейін не болды?» деп сұрап, оқиғаны жалғастырып айтуға ынталандырыңыз.') WHERE id = '62cbc2dc-4d91-48c4-8b87-f71ac5555a0a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Геометриялық пішіндерді көшіру». Бала енді Сіз салған дөңгелекті немесе айқыш белгісін қайталап сала алады. Бұл оның көзімен көрген пішінді қолымен қайталау қабілетінің (көру-қимыл үйлесімі) дамып келе жатқанын көрсетеді. Оған түрлі түсті қарындаштармен пішіндер салуды үйретіңіз.') WHERE id = 'c219d541-0794-4388-b19c-1b3296bc6f1a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді өзін жай ғана «мен» деп емес, белгілі бір қабілеттері бар тұлға ретінде қабылдайды. Ол «Мен жылдам жүгірушімін» немесе «Мен сурет бояғанды ұнатамын» деп өзін сипаттай бастайды. Оның өзі туралы осындай жағымды түсінігін қолдаңыз. Өзін қалай сипаттайтынына назар аударыңыз: бұл — оның болашақтағы өзіне деген сенімінің үні.') WHERE id = '24b05457-5c55-4e7e-93bd-e8e2e24e7b8c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене батылдығындағы «Биіктіктен қорқуды жеңу» кезеңі. Бала енді саябақтағы биігірек сырғанақтар мен сатыларды байқап көргісі келеді. Оның дене мүмкіндіктері санасындағы «Менің қолымнан келеді» деген оймен толық үйлесе бастады. Сіз тек жанында тұрып, «көзге көрінбейтін қауіпсіздік кепілі» болыңыз.') WHERE id = 'a48cb007-600a-438e-b8fd-ac64a32480ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Неге?» сұрағының философиясы. Енді ол «неге?» деп тек жауап алу үшін емес, Сізбен әңгімені жалғастыру үшін де сұрайды. Жауап беріп болған соң ол тағы да «неге?» десе, сұрақты өзіне бұрыңыз: «Ал сен қалай ойлайсың?». Оның қиялға толы түсіндірмелері Сізді әрі күлдіріп, әрі таңғалдырады.') WHERE id = 'a7f2070c-4631-4744-b176-d7bba5b19ea6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Символдардың пайда болуы» кезеңі. Бала енді қағазға «тұйық пішіндер» сала бастайды. Ол салған бір шеңбер әрі күнді, әрі допты, әрі ананы білдіруі мүмкін. Бұл — абстрактілі ойлаудың жоғары деңгейі: бір символ кез келген нәрсені бейнелей алады. Оның осы алғашқы «өнер туындыларын» міндетті түрде күнін жазып сақтап қойыңыз.') WHERE id = '8291f627-bff8-4ae0-9fda-966d1f2e80ac';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Шекараны сынаушы». Бала Сіз жасауға болмайды деген әрекетті әдейі жасап, реакцияңызды бақылауы мүмкін. Бұл оның «жаман» екенін білдірмейді. Осылайша ол Сіздің эмоциялық шекараларыңыз бен ережелердің өзгермейтінін тексереді. Сіздің сабырлы әрі нық болуыңыз оған ең маңызды қауіпсіздік белгісін береді: «Әлем әлі де тұрақты әрі қауіпсіз».') WHERE id = 'a9bf7bd3-b390-48c2-b220-67d40659de03';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік зияттағы «Ойын ережелері» кезеңі. Бала енді ойын жалғасуы үшін ережелерді сақтау керектігін түсінеді. Мысалы, «жасырынбақ» ойнағанда көзін жұму маңызды екенін біледі. Бұл — оның қоғамдағы алғашқы «әлеуметтік келісімдері». Онымен бірге ережелері қарапайым үстел ойындарын ойнай бастаңыз.') WHERE id = '6de77e4c-02d9-4646-a638-e1f9881237a4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдағы «Уақыт рәсімдері». Бала «кеше», «бүгін» және «ертең» ұғымдарын әлі толық ажырата алмаса да, күнделікті рәсімдерді біледі. «Тамақтан кейін — саябақ» немесе «Ұйықтар алдында — ертегі». Осындай реттілік оның санасында уақыт желісін қалыптастырады. Оған оқиғаларды ретімен айтып беріп, көмектесіңіз.') WHERE id = '3677e8d8-da75-4da9-b002-0343f54de7f8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестірудегі «Епті қимылдар». Бала енді сұйықтық толтырылған стақанды көп төкпей алып жүре алады немесе жіңішке соқпақпен жүре алады. Бұл оның көру-қимыл үйлесімінің қаншалықты жетілгенін көрсетеді. Үйде оған «кішкентай даяшы» рөлін беріңіз.') WHERE id = '24b745fb-d8d2-4191-b523-51bef737292f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сезімдер сөздігі». Бала енді жай ғана «жаманмын» немесе «жақсымын» демейді. «Ашуландым», «сағындым», «қуаныштымын» сияқты сөздерді орынды қолданады. Оның сезімдерін қабылдап, растаңыз: «Сағынғандықтан жылауың қалыпты». Бұл — оның эмоциялық саулығының ең мықты кепілі.') WHERE id = 'e9c2314b-a8e3-4e87-93f6-fa6cd95e6e36';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '3 жастың (1095 күннің) табалдырығында. Бала «бөпелік» жағалауынан алыстап, «балалық шақ» мұхитына бет алды. Ол енді Сіздің іс-әрекеттеріңізді ғана емес, эмоциялық күйіңізді де қайталайды. Сіз — ол үшін ең үлкен айнасыз. Өзіңізді мақтан тұтыңыз: 1090 күн бойы ғажайып адамды өсіріп келесіз!') WHERE id = '6d3a16a2-1643-4f5c-be11-40251b29e16d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '3 жасқа толуына (1095 күнге) небәрі 5 күн қалды! Бала «Мен» ұғымын толық меңгеріп, өз шекарасын табандылықпен қорғап жүр. Осы күндері жиі еститін «жоқ» сөзі оның Сізге қарсы екенін білдірмейді, бұл — оның өз болмысын таныту тәсілі. Оған таңдау мүмкіндігін беру арқылы осы өтпелі кезеңді жеңілдетіңіз.') WHERE id = '1dacdad0-c90b-4399-810b-283d367d437c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Толық еркіндік». Бала енді екі аяғымен бір мезгілде жоғары секіре алады, баспалдақпен тіреусіз түсіп-шығады және үш дөңгелекті велосипедті басқара алады. Оның дене қуаты енді үйлесімді қимылдарға айналды.') WHERE id = '0788e284-3cae-46fe-a730-5b0adb5d2052';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Абстрактілі ойлау". Бала енді көз алдында жоқ заттар немесе өткен оқиғалар туралы ұзақ әңгімелей алады. "Есіңде ме, біз ол жерге барған едік қой?" деген сияқты сөйлемдер — оның ұзақ мерзімді жады мен сөйлеу қабілетінің тамаша үйлесімі. Онымен бұрынғы естеліктеріңізді жиі бөлісіңіз.') WHERE id = 'f3f07ee7-1804-4733-8e04-f58c824d1ef9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Жазуға дайындық дағдылары". Бала енді қарындашты алақанымен емес, саусақтарымен ұстап, тұйық шеңберлер, айқыштар және тіпті кейбір әріптерге ұқсайтын сызықтар салады. Бұл — оның болашақта жазуды меңгеруі үшін аса маңызды физикалық даму кезеңі.') WHERE id = '1e35d34e-147e-430a-a51b-7c615ecdd852';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'ТУҒАН КҮНІҢ ҚҰТТЫ БОЛСЫН! Тұп-тура 3 жыл, яғни 1095 күн! Бала енді ресми түрде "бөпелік" кезеңімен қоштасты. Ол қазір сөйлейтін, ойлайтын, әзілдейтін және өзіндік әлемі бар кішкентай тұлға. Осы 1095 күн ішінде Сіз оның санасында мызғымас сенім мен сүйіспеншіліктің негізін қаладыңыз. Жарайсыз, Ана!') WHERE id = '94af9664-3a01-40cf-b485-6d92b46dd312';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '4-ші жастың алғашқы күні! Балада "Жауапкершілік" сезімі оянады. Енді ол ойыншықтарын жинау да ойынның бір бөлігі екенін түсіне алады. Оған үйдегі шағын тапсырмаларды тапсырыңыз (мысалы, дастарқанға майлық қою). Бұл оның отбасының пайдалы мүшесі екенін сезінуіне көмектеседі.') WHERE id = '8a58846e-740c-494e-b055-cca0e1dee700';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Эмпатияның дамуы". Бала енді тек өзінің сезімдерін ғана емес, басқа адамдардың да мұңаюы мүмкін екенін түсінеді. "Ол бала неге жылап жатыр?" деген сұрақ — оның әлемге өзгенің көзімен қарай бастағанының дәлелі.') WHERE id = '3be5dfbf-e6fa-4586-9735-23266743fb18';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдағы "Логикалық реттілік". Бала енді 3-4 бөліктен тұратын оқиғаларды дұрыс ретпен айта алады: "Алдымен қолымды жудым, содан кейін нан жедім, сосын ойнадым". Оған күндеріңізді бірге жоспарлауды ұсыныңыз. Бұл оның санасындағы "ретсіздікті" жүйелі "уақыт желісіне" айналдырады.') WHERE id = 'cce49adb-3f97-4be9-9435-40b81895ee05';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала түстер мен пішіндерді үйлестіре отырып, әлемді сипаттай бастайды. Егер ол: «Маған анау сары шаршы текшені берші», — десе, бұл оның миы бір уақытта бірнеше белгіні өңдеп жатқанын көрсетеді. Бұл дағдысын күнделікті өмірде шағын тапсырмалар беру арқылы (мысалы, «көк шұлығыңды тап») қолдаңыз.') WHERE id = 'd8ae8173-4cc7-42b0-8737-2bedce267dcb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Динамикалық тепе-теңдік». Бала енді бір аяғымен 5 секундқа дейін тұра алады. Бұл вестибулярлық жүйесі мен аяқ бұлшықеттерінің нығайып келе жатқанын көрсетеді. Онымен «Ләйлек» ойынын ойнап, кімнің бір аяғымен ұзағырақ тұра алатынын байқап көріңіз.') WHERE id = '071b03c5-b7b5-42d1-a970-a44e8e806595';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Себеп-салдар байланыстары». Бала енді «Егер... онда...» түріндегі сөйлемдерді түсіне бастайды. «Егер ойыншықтарыңды жинасаң, мультфильм көре аламыз» дегенде, ол шартты түсінеді. Бұл логикалық ойлау мен ішкі тәртіптің қалыптасуындағы маңызды қадам.') WHERE id = 'a7ceb34f-04f4-4303-a5f6-fca236e067db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Қайшымен алғашқы тәжірибелер». Бала енді қағазды (қауіпсіз қайшымен) түзу сызық бойымен қиюға қызығушылық танытады. Бұл әрекет қол-көз үйлесімін жақсартып, саусақтардың ұсақ моторикасын дамытады. Оны қараусыз қалдырмаңыз, бірақ дербестігіне кедергі жасамаңыз.') WHERE id = '42cc6ea9-d4af-4873-a31f-be87ca7ae22d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қиялдағы ойын серіктері». Бала енді жалғыз ойнағанда да дауыстап сөйлеп, ойыншықтарына рөлдер береді. Бұл оған өз әрекеттерін сөз арқылы реттеуге көмектеседі. Оның осы «монологтарын» тыңдау арқылы ішкі әлемінде не болып жатқанын түсіне аласыз.') WHERE id = 'b9a0516e-a5fd-46ab-abb8-4e16e305575b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Дербес таңдау: Шешім қабылдау». Бала енді не жегісі келетінін немесе қандай ойын ойнағысы келетінін нақты біледі. Оған күн сайын екі нұсқа ұсыныңыз: «Алма қалайсың ба, әлде банан ба?». Бұл оған өз өмірін басқара алатынын сезінуге көмектесіп, өзіне деген сенімін арттырады.') WHERE id = 'd2594413-54bc-4a0b-857c-1959a2b007b2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше киіну: сыдырма мен түйме". Бала енді үлкен түймелерді ағытуға немесе сыдырманы (Сіз бастап бергеннен кейін) жоғары қарай тартуға ерекше қызығушылық танытады. Оған "Кәне, өзің жасап көр" деп, шыдамдылықпен күтіңіз. Өздігінен киіне алуы баланың бойындағы "менің қолымнан келеді" деген сезім мен өзіне деген сенімді айтарлықтай арттырады.') WHERE id = '9a464aa6-3d95-421a-948d-be4bbc442bbe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Бөлісуді түсіну". Бала енді ойыншығын досына беру одан біржола айырылып қалу емес, жай ғана "кезектесіп ойнау" екенін түсіне бастайды. Бұл — эмпатияның алғашқы дәндері. Оның бұл әрекетін міндетті түрде "Досыңмен бөліскеніңе рақмет" деп қолдап, бекіте түсіңіз.') WHERE id = '7f75fc5d-eb6e-4e7a-abdd-f9659116f406';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Сан мен мөлшердің байланысы". Бала 1-ден 10-ға дейін жатқа санаумен қатар, заттарды саусағымен көрсетіп, "бір, екі, үш" деп нақты санын санай бастайды. Оған "Дастарқанға 3 қасық қояйық" сияқты тапсырмалар беріңіз. Бұл — абстрактілі сандардың нақты өмірмен алғаш рет маңызды байланыс орнататын кезеңі.') WHERE id = '6bc8719d-b139-4ea0-af7e-596754bfb254';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Артқа қарай жүру". Бала енді артына қарамай-ақ, артқа қарай бірнеше қадамды сенімді жасай алады. Бұл қимыл оның өз денесін сезінуін (проприоцепция) және кеңістікте бағдарлану қабілетін нығайтады. Онымен "Шаяндар жарысы" ойынын ойнап, бірге көңіл көтеріңіз әрі бұлшықеттерін жаттықтырыңыз.') WHERE id = '2fce926c-604e-40c3-aff1-959bf3574903';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Абстрактілі сұрақтар". Бала енді "Неге?", "Қалай?" деген сұрақтар арқылы әлемді танып-біледі. "Бұлт қайда барады?", "Құмырсқа қайда жүгіріп барады?" сияқты сұрақтар оның қызығушылығын да, қоршаған ортамен құратын логикалық байланыстарын да көрсетеді. Жауаптарыңыздың қарапайым әрі балаға түсінікті тілде болуы маңызды.') WHERE id = '5eb5c186-69a6-483f-9ba1-b6f471501a76';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: "Шыдамдылық сынағы". Бала енді қалаған нәрсесін алу үшін бірнеше минут күту керектігін түсінеді. "Қазір емес, сәлден кейін" дегенде бірден жыламаса, бұл оның эмоцияларын реттеу қабілетінің дамып келе жатқанын көрсетеді. Оның шыдамдылығын байқағанда, "Күткеніңе рақмет" деп жігерлендіріңіз.') WHERE id = '6751f01f-eb8d-4bf5-bdeb-fec3d11483e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдағы «Күрделі рөлдік ойындар». Енді ойындар егжей-тегжейлі бола түседі. Бала тек «дәрігер» болып қана қоймай, Сізге «рецепт жазып», «екпе салады». Мұндай ойындар балаға күйзелісті жеңуге және қоғамды түсінуге көмектеседі. Оның ойын әлеміне құрметпен қосылыңыз.') WHERE id = '63c35556-85c7-4de4-956c-b06072fe14e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1100 күндік жолдың соңғы аялдамасы. Бала енді өзін «үлкенмін» деп сезінеді. Оның даралығы, талғамы мен мінезі толық қалыптасып үлгерді. Сіз бұл жолдан сабырмен, біліммен және ең бастысы, шексіз сүйіспеншілікпен өттіңіз. «Anacan» қолданбасы әрдайым Сіздің және кішкентай қаһарманыңыздың жанында!') WHERE id = 'b3b1d154-d59c-44d1-8bf7-a6ef75357962';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '3 жастың алғашқы онкүндігіне қош келдіңіз! Бұл кезеңде баланың сөздік қоры шамамен 1000 сөзге жетеді. Енді ол тек қажеттіліктерін ғана емес, армандарын да бөліседі. Онымен сөйлескенде «Сеніңше, неге?» деген сұрақты жиі қойып, логикалық ойлауын ынталандырыңыз.') WHERE id = 'a79f70f3-f350-4b22-984a-7f58dfd4b7fb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Нысанаға дәл секіру». Бала енді тұрған орнынан жоғары қарай да, белгілі бір нысанаға қарай да (мысалы, едендегі түрлі түсті кілемшенің үстіне) секіре алады. Бұл оның тепе-теңдікті сақтау және кеңістіктегі қашықтықты бағалау қабілетін көрсетеді. Саябақтағы «тастан тасқа секіру» ойыны ол үшін тамаша жаттығу болады.') WHERE id = '05ceca15-09f0-41f4-a54b-99db2b828cc8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Есімдіктер мен жақ категориялары». Бала енді «мен», «сен», «ол» есімдіктерін дұрыс қолданады. Егер ол әлі де кейде өзін үшінші жақта өз атымен атаса (мысалы, «Әли су ішкісі келеді»), оны жайлап түзетіңіз: «Иә, СЕН су ішкің келіп тұр».') WHERE id = '03d396dd-e487-41b7-9885-73235271ea53';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пазлдар мен құрастыру». Бала енді 8-12 бөліктен тұратын пазлдарды өз бетінше жинап, текшелерден күрделі мұнаралар мен көпірлер құра алады. Бұл көру арқылы талдау қабілетін де, саусақтардың ұсақ әрі дәл қимылдарын да дамытады. Қолынан келмей жатса, дайын шешімді бермей, тек бағыт көрсетіңіз.') WHERE id = 'ca591a5d-4734-459d-be9b-3eaadeddb81b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Көлем мен мөлшердің сақталуы». Бала әлі де биік әрі жіңішке ыдыстағы су кең ыдыстағы судан көп деп ойлауы мүмкін. Бұл осы жас үшін қалыпты жағдай. Онымен су ойындарын ойнап, суды әртүрлі ыдыстарға құйыңыз. Бұл тәжірибе арқылы логикалық түсінігінің қалыптасуын жылдамдатады.') WHERE id = 'c2c7f4f2-7e4e-4f22-9785-bdddbd705503';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Екі аяқпен алға секіру». Бала енді кедергілерден (мысалы, жерде жатқан арқаннан) екі аяғымен бір мезгілде секіріп өте алады. Бұл бүкіл дене қимылдарының үйлесімділігін қажет етеді. Оған қауіпсіз жерлерде шағын кедергілер жолағын жасап беріңіз.') WHERE id = '3c4e0869-e516-493c-90a9-df3b2f2e738b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі уақыт ұғымы». Бала енді «Таң», «Түс» және «Кеш» арасындағы айырмашылықты күнделікті дағдылар арқылы түсінеді. «Кешке әкең келгенде...» дегеніңізде, ол күннің осы мезгілін ойша елестетеді. Күн тәртібін сақтауыңыз оның уақыт туралы түсінігін қауіпсіздік сезімімен байланыстырады.') WHERE id = 'd719015d-011e-40f6-8ffa-5cdcb4302e71';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық жетілу: «Кешір» сөзінің мағынасы. Бала енді біреуді әдейі немесе байқамай ренжіткенде «Кешір» деудің әлеуметтік маңызын түсінеді. Оған әрдайым үлгі болыңыз: қателескен кезде одан кешірім сұраңыз. Сонда ол да мұндай әрекетті мықты мінездің белгісі ретінде қабылдайды.') WHERE id = 'c8c25e23-7ba2-4ee9-a363-3be20d076417';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді суреттерге қарап, қарапайым оқиғалар құрастырады. «Аю орманға барды, қарны ашты да, бал жеді» деген сияқты бірізді сөйлемдер оның логикалық реттілікті түсінетінін көрсетеді. Оған қызықты суреттері бар кітаптар беріп, «Сіздіңше, бұдан кейін не болады?» деп сұраңыз. Бұл оның шығармашылық қиялын барынша дамытады.') WHERE id = 'd67be23e-c203-4809-a7a3-cbfd66266b55';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен өз бетінше жүру». Бала енді баспалдақпен әр басқышқа бір аяғын кезек-кезек қойып, тек бір қолынан ұстағанда (немесе мүлде ұстамай-ақ) сенімді түрде түседі. Бұл оның жалпы моторикасының толық жетілгенін көрсетеді. Сіз тек қасында болып, оған рухани қолдау көрсетіңіз.') WHERE id = '7b344d73-ef09-40bc-8962-14de04d0a9d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап тізбегі». Бала енді Сіздің сұрақтарыңызға жай ғана «иә/жоқ» деп емес, толық сөйлемдермен жауап береді. «Бүгін саябақта кіммен ойнадың?» деген сұраққа егжей-тегжейлі жауап бере алады. Онымен сөйлескенде «Оның түсі қандай болды?», «Не істедіңдер?» сияқты қосымша сұрақтар қойып, сөйлеу қабілетін дамытыңыз.') WHERE id = '728c62de-e9bd-4825-a015-839c4ef09ac4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәлірек бояу». Бала енді кішкентай пішіндердің де шекарасын байқап, бояу кезінде жиектен көп шығып кетпеуге тырысады. Бұл — қол бұлшықеттерін басқарудағы үлкен ілгерілеу. Оған жуандығы әртүрлі қарындаштар беріп, тәжірибе жасауына мүмкіндік беріңіз.') WHERE id = '1e2db868-b348-4ed1-a7d7-4e1b235065d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше киіну: сыдырма мен түйме». Бала енді үлкен түймелерді ағытып, сыдырманы (Сіз бастап бергеннен кейін) жоғары қарай тарта алады. Оған «Кәне, өзің жасап көр» деп, асықтырмай күтіңіз. Өздігінен киіне алуы баланың бойындағы «менің қолымнан келеді» деген сезім мен өзіне деген сенімділікті айтарлықтай арттырады.') WHERE id = 'd0289832-2e1f-4c80-bf6f-025f04fde8c3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісудің мәні». Бала енді басқа баланың қолындағы ойыншықты бірден тартып алмай, «берші» деп күтуге тырысады. Бұл — өзін-өзі реттеу (self-regulation) дағдысының нығаюы. Осындай сабырлы әрекетін байқағанда, міндетті түрде «Кезегіңді күткеніңе көп рақмет» деп мақтаңыз.') WHERE id = '8b0e05af-2727-418a-b763-3601d197e7d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Жалпы және жалқы». Бала енді алма, алмұрт және бананның барлығы «жеміс» екенін түсінеді. Оған әртүрлі заттарды көрсетіп, «Бұлардың барлығын бір сөзбен қалай атаймыз?» деп сұраңыз. Санаттар бойынша ойлау оның миындағы ақпаратты сақтау жүйесін ретке келтіреді.') WHERE id = 'cfa7be75-1286-4575-9a59-47547f98434d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты иықтан асыра лақтыру». Бала енді допты жай ғана жерге тастамай, оны иықтан асыра алға қарай, белгілі бір нысанаға бағыттап лақтыра алады. Бұл бүкіл дене қимылдарының үйлесімділігін қажет етеді. Онымен саябақта «нысанаға лақтыру» ойындарын ойнаңыз.') WHERE id = '7ccd147e-b878-45ff-a8c8-f2d12fac2b06';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Кеңістік пен бағыт» ұғымдары. Бала «оң» және «сол» ұғымдарын әлі толық ажырата алмаса да, «алға», «артқа», «жоғары» және «төмен» нұсқауларын дәл орындайды. Онымен «Робот» ойынын ойнаңыз: «Екі қадам алға, бір қадам артқа!». Бұл әрі көңілді, әрі кеңістікте бағдарлау қабілетін дамытады.') WHERE id = 'd6a03598-2471-4b13-a839-fb2c51010318';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сәтсіздікті еңсеру». Баланың текшелері құлап қалса, ол енді бірден жыламай, «Қайтадан құрастырамын» деп айта алады. Оның табандылығын қолдаңыз. 1130 күнді артқа тастадық – Сіздің балаңыз енді кішкентай қаһарман!') WHERE id = 'b7ab015d-a4e4-4c1d-a9a5-7f26c5798a69';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды бір уақытта екі белгісі бойынша (мысалы, түсі мен пішініне қарай) ажырата алады. «Маған кішкентай қызыл көліктердің бәрін берші» дегеніңізді орындай алса, бұл – оның танымдық дамуының жаңа деңгейі. Күнделікті үй шаруасында оған осындай шағын «іріктеу» тапсырмаларын беріңіз.') WHERE id = 'ff1dcdb3-fd81-4345-80ce-058e6b7a0d6b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігіндегі «Нысанаға секіру». Бала енді жерге сызылған шеңбердің немесе түрлі түсті нысананың ортасына секіруге тырысады. Бұл тепе-теңдікті сақтауды да, кеңістіктегі қашықтықты есептеу қабілетін де жетілдіреді. Саябақта онымен «тастан тасқа секіру» ойынын ойнаңыз.') WHERE id = '5d8b4009-8971-48b6-aa55-75a96a823d2d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қарама-қарсы мағыналы сөздер қорын кеңейту». Бала енді «ерте-кеш», «қараңғы-жарық», «бос-толық» сияқты абстрактілі қарама-қарсылықтарды түсінеді. Оған бос және толы стақанды көрсетіп, айырмашылығын сұраңыз. Бұл оның қоршаған ортаны салыстырып талдау қабілетін дамытады.') WHERE id = '18232b0a-482a-40e1-90c7-8a04a56dc3b9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пазл құрастыру шеберлігі». Бала енді 10-12 бөліктен тұратын күрделі пазлдарды (суреттің шеттері мен ортасын ажырата отырып) толық құрастыра алады. Бұл көру арқылы есте сақтау қабілетін де, саусақтардың дәл қимылдау икемін де дамытады. Қолынан келмей жатса, оған сабырлы үнмен бағыт-бағдар беріңіз.') WHERE id = '3045e148-b927-4872-8354-b9edb5116d18';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше жинау және көмектесу". Бала дастарқанды жинаған кезде өз тәрелкесін апаруға, қиқымдарды сүртуге ықылас танытады. Оған бойына сай келетін тазалық құралдарын беріңіз. Бұл оның отбасындағы жауапкершілік пен ортақ іске қатыстылық сезімін нығайтады. Өз еңбегінің нәтижесін көру оған үлкен қуаныш сыйлайды.') WHERE id = '5fed215f-7140-471a-887f-855f666792ab';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Ережелер мен шекаралар". Бала енді "жоқ" деген сөздің себебін жақсырақ түсінеді, бірақ әлі де шекараларды тексергенді ұнатады. Сіздің сабырлылығыңыз бен бірізділігіңіз оған қауіпсіздік сезімін береді. Ережелерді әрдайым бірдей қолдануға тырысыңыз.') WHERE id = 'ad322e7c-2c29-48c7-ba0d-376889e0bc86';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Реттік сандар". Бала енді "бірінші", "екінші", "соңғы" ұғымдарын түсінеді. Көліктерді бірінен кейін бірін тізіп, "Қай көлік бірінші тұр?" деп сұраңыз. Бұл оның реттілік туралы түсінігі мен математикалық ойлауын дамытады. Жарыс кезінде "Сен бірінші келдің!" деу оған үлкен жігер береді.') WHERE id = 'ccdeb036-ba4e-49c8-960c-f4271e0fc740';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Артқа және жанымен жүру". Бала енді әртүрлі бағытта епті қозғала алады. Онымен "Айна ойынын" ойнаңыз: Сіз бір қадам жанға басыңыз, ал ол қимылыңызды қайталасын. Бұл әрі көңілді, әрі дене қимылын үйлестіру қабілетін жаңа деңгейге көтереді.') WHERE id = '53f08fbe-8240-4c06-91f5-3a6645fa77af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы "Абстрактілі сұрақтардың күрделенуі". Бала "Бұлттар қайда барады?", "Жұлдыздар неге түнде шығады?" деген сұрақтарымен Сізді таңғалдыруы мүмкін. Жауап бергенде оның қиялын да іске қосыңыз: "Сеніңше, жұлдыздар қазір не істеп жатыр?". Бұл оның шығармашылық ойлауын дамытады.') WHERE id = 'ca368c4f-966b-4846-b9ca-ff68822b1eca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: "Бөлісудің қуанышы". Бала ойыншығын немесе тәттісін өз еркімен бөліскенде, Сіздің қуанғаныңызды көріп, мұны қайта жасағысы келеді. Оның жомарттығын "Досыңды қуантқаның үшін көп рақмет" деп ерекше атап өтіңіз. 1140 күнді сәтті аяқтадық – Сіз керемет анасыз!') WHERE id = '706c863b-0328-4280-9ae2-b61f0dddff18';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '39-айға қадам бастық! Бала енді «екі кезеңді» ойлаудан «үш кезеңді» тапсырмаларды орындауға көшеді. «Ойыншықты ал, қорапқа сал да, қақпағын жап» дегенде ретін бұзбай орындаса, бұл — оның жұмыс жадының (working memory) үлкен жетістігі. Күні бойы оған шағын әрі бір-бірімен логикалық байланысқан тапсырмалар беріп, осы дағдысын жетілдіріңіз.') WHERE id = '0f30e0b2-fa18-4fe2-8164-072ae2911569';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Жылдам жүгіру және маневр жасау». Бала енді жүгіріп келе жатып алдындағы кедергіні көргенде, жылдамдығын бәсеңдетпей-ақ оны айналып өте алады. Бұл оның өз денесін сезіну қабілетінің (проприоцепция) толық қалыптасқанын көрсетеді. Саябақта «кедергілермен жүгіру» жарыстарын өткізіп, энергиясын пайдалы арнаға бағыттаңыз.') WHERE id = 'c69b10fa-3ecf-43fd-9d25-d70589994cb8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Салыстыру шырайлары». Бала енді «үлкенірек», «ең кішкентай», «өте дәмді» сияқты тіркестерді орынды қолданады. Заттарды салыстыра отырып, онымен әңгімелесіңіз: «Мына алма тәттірек пе, әлде анау ма?». Сын есімнің осы шырайларын меңгеру оның сипаттап сөйлеуін байытып, ойын дәлірек жеткізуіне көмектеседі.') WHERE id = '10874a8b-618a-44ed-9a23-9c2c3bcf6530';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Мүсіндеу». Бала енді ермексазбен немесе кинетикалық құммен ойнағанда оларды жай ғана қысып қоймай, «доп», «жылан» немесе «нан» сияқты танылатын пішіндер жасайды. Бұл — шығармашылық ойлауды дамытып, саусақ ұштарындағы ұсақ бұлшықеттерді нығайтатын тамаша жаттығу.') WHERE id = '8ef81138-3a54-4c5e-ab33-5ab135be888d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше киіну: киімнің оң-терісін ажырату». Бала енді жейде немесе шалбардың оң-терісін, аяқкиімнің оң-солын (кейде қателессе де) ажыратуға тырысады. Оған шағын ишаралар беріңіз: «Қарашы, суреті бар жағы алдына келеді». Бұл оның ұсақ-түйекке назар аударуын және өзіне-өзі қызмет көрсету дағдыларын жетілдіреді.') WHERE id = '0d252040-b7cf-42d1-8e5c-b4a1ea436608';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Командалық рух». Бала енді басқа балалармен бірге ортақ мақсатқа жету үшін (мысалы, үлкен қамал тұрғызу үшін) ойнай алады. Бұл — «Қатар ойнаудан» «Бірлесіп ойнауға» көшу кезеңі. Оның басқа балалармен қалай тіл табысатынын бақылап, қиын сәттерде әлеуметтік «көпір» құруына көмектесіңіз.') WHERE id = 'b59f81d2-048d-48f5-8c51-231cd1498118';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Келер шақты нақтылау». Бала енді жай ғана «барамыз» демей, «Ертең әжемнің үйіне барып, мысықпен ойнаймыз» деген сияқты бірізді жоспарлар құрады. Күннің соңында онымен ертеңгі жоспарларды талқылаңыз. Бұл оның оқиғаларды алдын ала елестету және жоспарлау (атқарушы функция) қабілетін дамытады.') WHERE id = 'e7723585-78f9-489b-95f6-9d306c6417b7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Күрделірек пішіндер». Бала қарындашты енді шебер ұстап (үш саусақпен ұстау), қағазға үшбұрыш салуға немесе қиылысатын сызықтар жүргізуге тырысады. Бұл оның қол бұлшықеттері жазуға дайын деуге болатынын көрсетеді. Оған «Кәне, нүктелерді қосайық» ойынын ұсыныңыз.') WHERE id = '23c81011-ddf7-4cf3-aec3-f115d29c3f5e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Жеке бас гигиенасы: Тіс тазалау». Бала тіс тазалау ретін енді біледі. Соңында әлі де «тексеріп» қоюыңыз қажет болса да, оған бұл істі өз бетінше орындауға мүмкіндік беріңіз. Бұл әдет оның өз денесіне күтім жасау жауапкершілігін арттырады.') WHERE id = '94615e85-6da2-44c7-a201-6901c2a92ddf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қиял-ғажайып оқиғалар мен өтірік». Бала кейде шындыққа жанаспайтын нәрселерді айтуы мүмкін (мысалы, «Мен аспанда ұштым»). Бұл алдау емес, қиял мен сөйлеудің ұштасуы. Оған «Қандай қызық оқиға!» деп, қиялын қолдаңыз, бірақ шындық пен қиялдың арасындағы нәзік айырмашылықты да жұмсақ түсіндіріңіз.') WHERE id = 'd70b5fda-77b6-4fb1-bc69-d894fe21ca89';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Санаттарды тереңірек түсіну». Бала енді заттарды жай ғана «көлік» деп атамай, «жылдам көлік», «жүк көлігі» сияқты кіші топтарға бөледі. Оған «Қандай заттар суда қалқып жүреді, ал қайсысы батады?» деген тәжірибе ұсыныңыз. Бұл оның ғылыми бақылау дағдысының негізін қалайды.') WHERE id = '164e0d4f-5849-466c-88ec-e6961c6d0680';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты аяқпен басқару». Бала енді допты жай ғана теппей, оны аяғымен сәл алға итеріп, бағыттап қозғалтуға тырысады. Бұл динамикалық тепе-теңдікті дамытуға арналған тамаша жаттығу. Онымен бірге саябақта шағын «футбол жолын» жасаңыз.') WHERE id = 'c019ed6e-efde-47c2-b2ac-37c3fbd433b5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Цифр мен мөлшердің сәйкестігі». Бала 1-ден 5-ке дейін санай алады, енді «3» цифрын көргенде 3 ойыншықты бөліп қоя алады. Бұл — математикалық ойлауды дамытудың ең маңызды кезеңдерінің бірі. Күнделікті өмірде «Маған 2 қасық берші» сияқты тапсырмалар арқылы осы байланысты нығайтыңыз.') WHERE id = '5b8b658c-3ba9-46dd-b7e1-a329bde32c59';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарының үйлесімділігі: «Жоғарыдан лақтырылған допты қағып алу». Бала өзіне қарай баяу лақтырылған үлкен допты екі қолымен қағып алуға тырысады. Бұл қимыл қол мен көз үйлесімділігін де, реакция жылдамдығын да қажет етеді. Онымен жақын арақашықтықтан доп лақтырып, қағып алу ойынын ойнаңыз.') WHERE id = '9cbfafe8-e2d3-4b4c-a7dd-a7d50a0d73a4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Абстрактілі сұрақтардың шарықтау кезеңі». Бала енді «Жел неге соғады?», «Күн ұйықтауға қайда кетеді?» сияқты қоршаған әлем мен табиғат құбылыстары туралы сұрақтар қояды. Жауап бергенде қиялыңызды да қосыңыз: «Күн шаршады, ертең бізді қайта ояту үшін демалуға кетіп барады». Бұл оның дүниетанымын кеңейтіп, білімге деген құштарлығын арттырады.') WHERE id = 'be40f099-56c3-42b3-90d0-8aec32c8e2ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық жетілу: «Басқаның эмоциясын мойындау». Бала Сіздің шаршағаныңызды немесе басқа баланың ренжігенін байқаса, «Не болды?» деп сұрап, жұбатуға тырысады. Бұл оның жанашыр тұлға болып қалыптасып келе жатқанын көрсетеді. Сіз керемет анасыз!') WHERE id = '28850826-f8da-4cde-a0f3-c10d2981e7f4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «мен» және «менікі» ұғымдарын әлеуметтік қарым-қатынаста сынап көреді. Ойыншығын бөліскісі келмеуі өзімшілдіктен гөрі, жеке шекарасын белгілеуге деген талпыныс. Оған «Бұл сенің ойыншығың, дайын болғанда оны досыңа бере аласың» деп, оның меншік сезімін құрметтейтініңізді көрсетіңіз. Бұл болашақта басқа адамдардың да шекарасын құрметтеу қабілетін қалыптастырады.') WHERE id = '3d0a961f-8311-4c15-82e4-3b93885267b5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Биіктен секіру». Бала енді аласа басқыштан немесе төсеніштің үстінен екі аяғымен бір мезетте жерге секіріп түскенді ұнатады. Бұл қимыл оның вестибулярлық жүйесінің дамуы үшін маңызды. Жерге жұмсақ төсеніш төсеп, оның батылдығын қауіпсіз түрде қолдаңыз.') WHERE id = '0680b361-8e77-46ad-a0ea-0e96e9759bdc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді өз сезімдерін күрделірек түрде білдіреді: «Ойыншығым сынып қалғандықтан, көңілім түсіп тұр». Бұл — эмоциялық интеллект дамуындағы үлкен серпіліс. Оның сезімдерін қабылдап қана қоймай, шешім ұсынуына да мүмкіндік беріңіз: «Қалай ойлайсың, оны қалай жөндей аламыз?». Бұл оның қиындықтарға төзімділігін (resilience) де қалыптастырады.') WHERE id = '72c6a670-175e-4e59-a40a-08a5b3924e43';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында «Бүйірге секіру» дағдысы пайда болады. Бала енді тек алға емес, бүйірге де секіре алады. Бұл сан мен аяқ бұлшықеттерінің әртүрлі бағытта үйлесімді жұмыс істеуін талап етеді. Онымен бірге жерге сызылған сызықтардың үстінен «бүйірлей секіру» жарысын өткізіңіз.') WHERE id = '7ad7a096-5914-4eed-80cb-8089f672c249';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде «Есімдіктерді толық меңгеру» кезеңі. Бала енді «менікі», «сенікі», «оныкі» ұғымдарын шатастырмайды. «Бұл — менің ойыншығым, ал анау — сенікі» деп, затқа иелік етудің әлеуметтік шекараларын айқындайды. Бұл кезеңде оған ортақ заттар (мысалы, отбасылық кітап) мен жеке заттардың айырмашылығын түсіндіруге өте қолайлы уақыт.') WHERE id = '2b8c7b62-f908-41ef-8972-07466c4a7bd0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада «Симметрия жасау талпыныстары» байқалады. Бала қағазды бүктеуге немесе салған суретіндегі бөлшектерді симметриялы орналастыруға тырысады. Мысалы, салған адамның екі жағына да құлақ немесе қол қосады. Бұл — мидың екі жартышарының үйлесімді дамуының көрсеткіші.') WHERE id = 'bd356611-73c3-4619-9883-1f920ac53fa9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Дастарқан басындағы дербестік мәдениеті». Бала енді шанышқыны шебер қолданады және пышақпен (қауіпсіз балалар пышағымен) жұмсақ тағамдарды (мысалы, банан немесе омлет) кесуге тырысады. Оған осындай дербестік беріңіз. Өзіне-өзі қызмет ету сезімі оның өзіне деген сенімін іштей нығайтады.') WHERE id = 'a07fbd02-0c2f-49de-ba5e-43f31c0bcc20';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта «Ережесі бар ойындар» кезеңі. Бала енді «Жасырынбақ» немесе «Қуаласпақ» сияқты қарапайым ережелері бар ойындарды шарттарын бұзбай ойнауға қызығушылық танытады. Бұл — әлеуметтік бейімделудің маңызды кезеңі. Ережелерді сақтаған кезде оны міндетті түрде: «Әділ ойнағаның үшін жарайсың», — деп мақтаңыз.') WHERE id = 'e172dbdc-63ea-4b2b-afac-30588be411eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сын есімдердің молаюы». Бала заттарды сипаттағанда «жұмсақ», «тікенекті», «тегіс», «жылтыр» сияқты сөздерді қолдана бастайды. Онымен «Ұстап көр де, тап» ойынын ойнаңыз: көзін жұмып, затты ұстағанда қандай сезім тудыратынын айтып беруін сұраңыз.') WHERE id = '0b5835ed-17d3-46e9-b2cd-eb9c92154c53';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Басқаға көмектесу». Бала Сіздің бір істі орындауда қиналып жатқаныңызды немесе бір нәрсе іздеп жүргеніңізді байқап, көмек ұсына алады. Бұл оның эгоцентризм кезеңінен өтіп, нағыз «әлеуметтік серіктеске» айналып келе жатқанын көрсетеді. Оның көмегін «Сен болмағанда, мен мұны таба алмас едім» деп ерекше атап өтіңіз.') WHERE id = '95ef23e6-3a1e-4eb7-bed7-103fc452a1e2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «салдарға» бағытталып ойлай бастайды. Мысалы, Сіздің еске салуыңызбен «Егер тәтті жесем, тісім ауыруы мүмкін» деген сияқты себеп-салдар байланыстарын түсінуге тырысады. Осы кезеңде оған ережелердің не үшін қажет екенін түсіндіру өте маңызды. Бұл балада соқыр бағынуды емес, ішкі қисынға негізделген тәртіпті қалыптастырады.') WHERE id = '602eea29-96df-4d75-b3f3-a89b088efbe3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Динамикалық тепе-теңдік». Бала енді жерге сызылған түзу сызықтың немесе керілген арқанның бойымен тепе-теңдігін жоғалтпай, «арқан үстіндегі әртіс» сияқты жүре алады. Бұл вестибулярлық жүйенің толық жетілгенін көрсетеді. Саябақта онымен бірге жиектастардың үстімен (қолынан ұстап) жүру бұл дағдысын одан әрі жетілдіреді.') WHERE id = '5465b5ac-4749-433f-99e1-222fda8c10bf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Оқиғаны егжей-тегжейлі баяндау». Бала енді күні бойы басынан өткен бір оқиғаны 4-5 сабақтас сөйлеммен айтып бере алады. «Бүгін саябаққа бардық, Елжанды көрдім, біз құммен ойнадық». Оның әңгімелерін мұқият тыңдап, «Содан кейін не болды?» деп диалогті кеңейтіңіз. Бұл оның сөздік жадын және сөйлеу мәнерінің еркіндігін арттырады.') WHERE id = '7607f78f-a199-4155-af72-552bbd09b140';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Шеңберден символдарға». Бала енді тұйық шеңберлер салып, оларды «адам» (таяқша адам) бейнесіне айналдыру үшін астына сызықтар қосады. Бұл — визуалды символизмнің бастауы. Оған түрлі түсті қарындаштар беріп, «Бүгін кімнің суретін салып жатырсың?» деп сұрау арқылы қиялын ынталандырыңыз.') WHERE id = 'ead2dac9-db7b-47ae-9b92-23aa29cddd39';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше киіну: Түйме мен сыдырма". Бала енді ірі түймелерді өзі салып, сыдырмасын өз бетінше жабуға талпынады. Бұл саусақтардың ұсақ бұлшықеттерінің үйлесімді жұмысын талап етеді. Таңертең киінгенде, осы әрекеттерді өзі аяқтауы үшін оған қосымша 5 минут уақыт беріңіз. Өз қолынан келгенде сезінетін мақтаныштың орны бөлек.') WHERE id = '24f54158-6d74-423e-b96c-5270e549d121';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Кезек күту және Сабыр сақтау". Бала енді әткеншек тебу үшін басқа баланың түсуін күту керектігін түсінеді. "Кезек сенікі" және "Кезек менікі" деген ұғымдар ортадағы келіспеушіліктерді азайтады. Оның сабырлылығын міндетті түрде "Кезегіңді күткенің үшін көп рақмет" деп мақтаңыз.') WHERE id = '97f18e0c-30d0-42a5-aa90-ac6015233d99';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Мөлшерді түсіну". Бала 1-ден 10-ға дейін санай алумен қатар, енді 3 немесе 4 заттың санын санамай-ақ, бір қарағанда анықтай алады (subitizing). Одан "Мұнда неше алма бар?" деп сұрап, саусағымен көрсетіп санауын өтініңіз. Бұл — болашақ математикалық ойлаудың негізі.') WHERE id = '6e61f63b-18f2-4f84-b98e-0d07b524e3e9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты екі қолмен қағып алу". Бала енді өзіне қарай баяу лақтырылған допты қолдарын бүгіп, кеуде тұсында біріктіріп қағып ала бастайды. Бұл реакция жылдамдығы мен қол-көз үйлесімінің дамуын көрсетеді. Үйде онымен жұмсақ допты бір-біріңізге лақтырып, қағып алу ойындарын ойнаңыз.') WHERE id = 'eb5816aa-f53e-4699-abf2-d1ff0b98f5f9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Абстрактілі ұғымдар: Уақыт". Бала әлі "сағат неше болды?" деген сұрақты түсінбесе де, "ертең", "кеше", "кейін" сияқты сөздерді орнымен қолдануға тырысады. Оған уақытты күнделікті дағдылы әрекеттер арқылы түсіндіріңіз: "Ұйқыдан оянғанда, ертең болады". Бұл оған әлемді реттелген әрі болжамды деп қабылдауға көмектеседі.') WHERE id = '6c159ac6-63d6-41de-9c9e-e48fdddeeaef';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: "Сәтсіздіктен қорықпау". Бала енді бір нәрсе қолынан келмей қалса (мысалы, текшелерден мұнара тұрғызу), бірден жыламай, Сізге қарап: "Қайта жасап көрейін бе?" деп сұрай алады. Нәтижесін емес, талпынысын мақтаңыз: "Сен көп тырыстың және қайтадан жасап көрдің, жарайсың!". Сіз — керемет жолсеріксіз!') WHERE id = '487ce40e-d1a5-42bb-ab35-fd94c37e1b74';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Мақсатты сұрақтар». Бөпе енді жай ғана «бұл не?» деп емес, «бұл қалай жұмыс істейді?» деп сұрайды. Ол заттардың ішкі механизміне қызығушылық танытады. Жауап бергенде тым күрделендірмеңіз, бірақ логикалық реттілікті сақтаңыз. Бұл сұрақтар — болашақ ғылыми ойлаудың алғашқы ұшқындары.') WHERE id = 'fda8c637-494b-4891-b635-d2a91f4dbd7b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пішіндер комбинациясы». Бала енді жай ғана шеңбер сызбайды, шеңберлерді біріктіріп, «жұлдызқұрт» немесе «аққала» жасайды. Бұл оның көрнекі белгілерді біріктіріп, жаңа мағына қалыптастыра алатынын көрсетеді.') WHERE id = 'c2392a7c-85eb-4d9e-aff3-15371b541a80';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Саяси» келіссөздер. Бала енді Сізбен «саудаласады»: «Ойыншықтарымды жинасам, маған тағы бір ертегі оқып бересіз бе?». Бұл оның әлеуметтік ықпал ету тетіктерін үйреніп жатқанын көрсетеді. Мұндай «келіссөздерде» әділ болыңыз, бірақ негізгі ережелеріңізден айнымаңыз.') WHERE id = '1c3607b2-8132-49bc-b9ba-d3f310a2378b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қиялдағы сценарийлер». Енді ойындар күрделене түседі: «Мен аспазбын, ал Сіз тұтынушысыз, маған ақша төлеуіңіз керек». Мұндай ойындарда бала қоғамдағы рөлдер мен экономикалық қарым-қатынастарды байқап көреді. Оның сценарийіне ілесіп, осы шығармашылық үдерісті ынталандырыңыз.') WHERE id = '74c3e2b6-b59d-47f7-ac39-b3a6571a3f4e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Заттардың қызметі». Бала енді заттарды тек сыртқы көрінісіне қарай емес, атқаратын қызметіне қарай да топтастырады. «Бұлар — кесетін құралдар (қайшы, пышақ)», «Ал бұлар — жазатын құралдар». Бұл оның миындағы ақпарат қорының жүйеленіп, қызметіне қарай реттеле бастағанын көрсетеді.') WHERE id = '78693b6d-347d-4486-94dc-37e920221a4d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Баспалдақпен өздігінен жүру». Бала енді баспалдақпен әр басқышқа кезек-кезек бір аяғын қойып, еш жерден дерлік ұстамай, сенімді көтеріледі. Бұл тепе-теңдікті сақтау қабілеті мен аяқ бұлшықеттері күшінің жоғары деңгейге жеткенін көрсетеді.') WHERE id = 'cc0be0ea-ed32-4ad7-a00e-446a9d717d47';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өйткені» кезеңі. Бөпе өз әрекеттерінің себебін түсіндіруге тырысады: «Мен мұны кимеймін, өйткені бұл денеме батады». Оның осындай «өйткені» деп айтатын түсіндірмелерін тыңдаңыз. Бұл өз қажеттіліктері мен мазасыздықтарын қисынды түрде жеткізу қабілетін нығайтады.') WHERE id = '1172f061-c7e1-4517-8b34-e51a76cdf51e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Басқаның жетістігіне қуану». Бала енді Сіздің немесе досының жетістігін көргенде (мысалы, ойында жеңіске жеткенін) «Жарайсың!» деп айта алады. Бұл — эгоцентризмнің (тек өзін ойлаудың) азайып, өзгенің қуанышына ортақтаса білудің басталғанын білдіреді. Сіз керемет тұлға тәрбиелеп жатырсыз!') WHERE id = 'e58983bd-cd78-4d0a-8590-e07b73fa9e05';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «Неліктен?» деген сұрақтарды жай ғана жауап алу үшін емес, себеп-салдар байланысын түсіну үшін қояды. «Жапырақтар неліктен жерге түседі?» деген сияқты табиғат құбылыстарына қызығушылығы арта түседі. Оған қарапайым әрі ғылыми деректерге негізделген жауаптар беріңіз. Бұл оның қоршаған әлемге талдамалы көзқарасын қалыптастырады.') WHERE id = '8335f345-0d57-482d-b821-779e730295ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Шебер тепе-теңдік». Бала енді жіңішке соқпақпен немесе жерге төселген арқанның үстімен тепе-теңдігін сақтап, сенімді жүре алады. Бұл — вестибулярлық жүйе дамуының жоғары деңгейі. Үйде онымен «Арқанның үстімен жүруші» ойынын ойнап, қимыл дәлдігін жетілдіріңіз.') WHERE id = '00cce1f4-ca47-462d-b84a-6205502d4f13';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өткен шақ пен келер шақтың үйлесімі». Бала «Кеше мен саябаққа бардым, ал ертең әжемнің үйіне барамын» деген сияқты сөйлемдерде уақыт айырмашылықтарын дұрыс қолданады. Уақыт туралы түсінігін нығайту үшін күнделікті істерін «алдымен, қазір, кейін» ретімен еске түсіруді жалғастырыңыз.') WHERE id = '10538e9b-c203-4dd2-8b24-d807c72fa3fb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Адамды егжей-тегжейлі бейнелеу». Бала енді «таяқша адамды» салғанда оған саусақ, шаш немесе көз сияқты көбірек бөлшек қосады. Бұл оның көру арқылы бақылау қабілеті мен қол-ми үйлесімінің қаншалықты жетілгенін көрсетеді.') WHERE id = 'e534e280-1b5b-4f3e-b1db-79a0cf64e3af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Биіктік пен ұзындықты салыстыру». Бала енді заттарды биіктігіне қарай ретімен орналастыра алады. Оған өлшемдері әртүрлі 3-4 ойыншық беріп: «Ең биігінен ең аласаға қарай орналастыр», — деңіз. Бұл оның көру арқылы қабылдауын және логикалық реттеу дағдысын жетілдіреді.') WHERE id = '3281647e-af83-48c8-9e0e-9deebd826a8f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Үш дөңгелекті велосипедпен маневр жасау». Бала енді велосипед теуіп келе жатып, алдындағы кедергіні көргенде рөлді бұрып, оны айналып өте алады. Бұл педаль айналдыру (дене қимылы) және жолды бақылау (көру) дағдыларының үйлесімін көрсетеді. Саябақта оған қауіпсіз «веложол» жасап, осы дағдысын қолдаңыз.') WHERE id = 'cccc4e73-bd8f-49ce-ac37-8b06ba255913';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт пен реттілік». Бала енді «Ертең әжемдікіне барамыз, содан кейін мен саябаққа барамын» деген сияқты болашаққа жоспар құра алады. Бұл оның оқиғаларды алдын ала көз алдына елестету қабілетінің дамығанын көрсетеді. Күннің соңында онымен ертеңгі жоспарларды «ертегі» секілді әңгімелесіп, ұйқыға жатыңыз.') WHERE id = '533647bf-c77f-434e-8420-bd22239f3086';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сабыр сақтау және күту». Бала енді кезекте бірнеше минут күту «соңы» емес, тек уақытша жағдай екенін түсінеді. Бұл оның өзін-өзі басқару (атқарушы функциялар) дағдысының дамығанын көрсетеді. 1180 күн – балаңыз енді әлемді түсініп, оған бейімделіп келе жатқан кішкентай тұлға. Сіз керемет жолсеріксіз!') WHERE id = 'fe96ce06-9654-4a3f-8b50-d93363f0cbca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді өзін дене ерекшеліктері арқылы сипаттайды: «Мен тез жүгіремін» немесе «Менің бойым ұзын». Бұл — өзін-өзі танудың жаңа деңгейі. Оның өзі туралы жағымды көзқарасын қолдаңыз. Өзін қалай қабылдайтыны туралы сұрақтар қойыңыз: «Сенің ойыңша, тағы нені жақсы істей аласың?».') WHERE id = '4f2b9702-c295-43cf-9776-2d9fd4b98c79';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Динамикалық секіру». Бала енді жүгіріп келе жатып, алдынан шыққан шағын кедергіден (мысалы, жерде жатқан арқаннан) жылдамдығын бәсеңдетпей секіріп өте алады. Бұл мидағы қозғалысты алдын ала жоспарлау дағдысының дамығанын көрсетеді.') WHERE id = '63d363dc-9356-4fa8-bbd3-57a0c8ed1083';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Шекараны қорғау". Бала енді "Менің бөлмем", "Менің үстелім" деп өзінің жеке кеңістігін белгілей бастайды. Оның жеке кеңістік сезіміне құрметпен қараңыз. "Бөлмеңе кіруге бола ма?" деп сұрау арқылы Сіз оған жеке шекараны құрметтеуді және болашақта басқа адамдардың да шекарасын мойындауды үйретесіз.') WHERE id = '19704700-4f78-4a2f-8063-e34e01705522';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Әділет сезімі". Бала енді ойын кезінде ереженің бұзылуына: "Ол кезекті бұзды!" деп жауап береді. Бұл оның әлеуметтік әділет пен ережелер туралы түсінігінің дамып келе жатқанын көрсетеді. Ережелердің не үшін маңызды екенін (мысалы, ойын қызықты болуы үшін) түсіндіру арқылы оның әлеуметтік әдеп негіздерін қалыптастырыңыз.') WHERE id = 'bb50baca-3306-43e8-84f0-8ecfe4ce2ed7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Мөлшер мен санды байланыстыру". Бала 10-ға дейін санай алады, ал енді сандарды мөлшермен байланыстыра бастайды. Сіз "Мұнда 5 жаңғақ қойдым" дегенде, ол мөлшерді көзбен бағалай алады. Күнделікті істер кезінде оған "Маған 4 қасық берші" деген сияқты тапсырмалар беріңіз.') WHERE id = '3b180a00-84f2-4ef7-b180-bb007866d4c3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Үш дөңгелекті велосипедпен жылдам жүру". Бала енді велосипедті жылдамырақ жүргізіп, кедергілерді айналып өте алады. Бұл аяқ пен дененің төменгі бөлігінің күшін және көру-қимыл үйлесімін жоғары деңгейде меңгергенін көрсетеді. Жылдамдығын байқап көруі үшін саябақта оған қауіпсіз "жүру жолдарын" белгілеңіз.') WHERE id = 'cf35973e-cf99-454b-b4d7-5058e5466945';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Әзіл мен юмор". Бала енді сөздермен ойнап, "оғаш" сөйлемдер құрау арқылы Сізді күлдіруге тырысады. Мысалы, "Ит мияу деді" деп өзі күлуі мүмкін. Бұл оның тіл ережелерін білетінін және әзіл тудыру үшін оларды әдейі бұзатынын көрсетеді. Онымен бірге күліп, әзіл сезімін дамытыңыз.') WHERE id = '7856919f-0f1f-4c55-9554-5d9226e933f6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1200 күндік үлкен сапар! Бала 40 айды артта қалдырды. Енді ол – өз ойы, әзілі мен армандары бар кішкентай тұлға. Осы 1200 күн бойы Сіз оның әлемінің сәулетшісі болдыңыз. Оның өзіне сенімді жанарында Сіздің махаббатыңыздың қолтаңбасы бар. Сіз керемет анасыз!') WHERE id = '1104a81e-20a0-469a-b38d-bffb8442b875';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '41-айға қош келдіңіз! Бұл кезеңде балада "ниет" ұғымы қалыптасады. Ол енді оқиғаның кездейсоқ немесе әдейі болғанын ажырата бастайды. Мысалы, біреу оған тиіп кетсе, "Мұны әдейі істедің бе?" деп сұрауы мүмкін. Бұл — әлеуметтік қарым-қатынаста адалдық пен ниетті түсінуге бастайтын маңызды қадам.') WHERE id = 'be82050e-9ad6-486e-9d98-a2c2c31a243e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында — "Бір аяқпен секіру". Бала енді бір аяғымен қатарынан бірнеше рет секіруге талпынады. Бұл күшті де, тепе-теңдікті жақсы сақтауды да қажет етеді. Саябақта онымен "бір аяқпен секіру жарысын" ойнап, осы дағдысын қолдаңыз.') WHERE id = '59f9bda8-ddf4-49be-ad49-7ae815287273';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде — "Логикалық жалғаулықтар". Бала енді "бірақ", "себебі", "егер" жалғаулықтарын сөйлемдерінде шебер қолданады. "Мен саябаққа барғым келеді, бірақ жаңбыр жауып тұр". Бұл оның санасындағы қарама-қайшы ойларды байланыстыра алу қабілетін көрсетеді. Онымен сөйлескенде осы жалғаулықтарды қолданып, диалогті ұзартыңыз.') WHERE id = 'b5dc9cdd-e5bc-4c21-ba9e-2e9fe7dbdaee';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада — "Қағаз қию". Бала енді қауіпсіз қайшымен қағаздағы түзу сызықтың бойымен қия алады. Бұл қол мен көз үйлесімінің жоғары деңгейге жеткенін көрсетеді. Оған қиып-жапсыру (аппликация) жұмыстарын жасау үшін түрлі түсті қағаздар мен үлгілер беріңіз.') WHERE id = '93689350-75d1-4dc3-befa-2516fff9cb92';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзін-өзі реттеу (Self-regulation)". Бала енді ашуланғанда немесе көңілі түскенде өзін тыныштандыру үшін Сіз ұсынған тәсілдерді (мысалы, терең тыныс алу немесе ойыншығын құшақтау) қолдана алады. Бұл — эмоциялық интеллектінің өмірдегі ең маңызды дағдыларының бірі.') WHERE id = 'cad2a6f6-14d3-4ac8-a455-240edf668e56';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта — "Ережесі бар командалық ойындар". Бала енді топ ішінде ортақ ережелер бойынша ойнауға қызығушылық танытады. "Енді бәріміз қоян сияқты секіреміз" дегенде, ол командаға бейімделеді. Бұл — мектеп ортасында маңызды болатын "топпен бірге әрекет ету" дағдысының негізі.') WHERE id = '6f7c2344-f4ee-4701-9810-594e0c930fc0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әдептілік пен реңктер». Бала енді дауыс ырғағы мен сөздерін кіммен сөйлесіп тұрғанына қарай бейімдей бастайды (мысалы, бөпемен жұмсақтау, ал ересектермен байыптырақ сөйлеседі). Бұл — әлеуметтік лингвистиканың бастауы. Сіздің сөйлеу мәдениетіңіз ол үшін ең негізгі әрі мінсіз үлгі.') WHERE id = '3eaa8096-e288-4159-9aa2-8223399dd023';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Өзін-өзі мақтау». Бала бір істі орындағанда: «Қарашы, мен мұны қандай әдемі жасадым!» — деп, Сізден мақұлдау күтеді. Оның ішкі мақтаныш сезімін: «Иә, сен көп күш салдың», — деп қолдаңыз. Сіздің қолдауыңыз оның болашақтағы өзіне деген сенімінің негізін қалайды!') WHERE id = '97ef6f09-4fed-4fcd-abbe-7756d8045e1e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды бір уақытта бірнеше белгісіне қарай топтастыра алады: «әрі үлкен, әрі көк ойыншықтар». Бұл — когнитивтік икемділіктің (cognitive flexibility) көрсеткіші. Оған: «Кел, жұмсақ әрі қызыл заттардың бәрін табайық», — деген сияқты қызықты іздеу тапсырмаларын беріңіз.') WHERE id = '0d946fb4-d148-46c8-80fc-f0a7b324c07f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Еркін жүгіру және тоқтау». Бала енді бар жылдамдығымен жүгіріп келе жатып, Сіздің «Тоқта!» деген нұсқауыңыздан кейін тепе-теңдігін жоғалтпай, бірден тоқтай алады. Бұл оның жүйке-бұлшықет бақылауының қаншалықты дамығанын көрсетеді. Саябақта «Қызыл шам, жасыл шам» ойынын ойнау — әрі көңілді, әрі пайдалы жаттығу.') WHERE id = '824aa9f8-040c-4665-a6d8-64a894fd7261';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қарама-қарсы мағыналы сөздер». Бала енді «ыстық-суық», «биік-аласа», «ауыр-жеңіл» сияқты қарама-қарсылықтарды түсініп қана қоймай, оларды әңгімесінде де қолданады. Оған қарама-қарсылықтарға байланысты жұмбақ сұрақтар қойыңыз: «Піл үлкен, ал тышқан қандай?». Бұл оның сөздік қорын молайтып, салыстыра ойлау қабілетін жетілдіреді.') WHERE id = '56f799be-0231-4113-94ee-9fbaa18f177f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Адам бейнесінің бөлшектері». Бала енді салған адамына қол, аяқ, тіпті саусақтар да қосуға тырысады. Бұл суреттер оның өз денесін және айналасындағы адамдарды қалай қабылдайтынын көрсетеді. Оның әрбір «туындысын» кішкентай бір оқиғадай тыңдаңыз.') WHERE id = '0006f22d-7d35-4a7c-abab-057194f6402c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Уақытты визуализациялау". Бала енді "Кеше не істедік?" деген сұраққа ретімен жауап бере алады. Оған күн ішіндегі оқиғаларды суреттермен көрсететін "күндік жоспар" дайындаңыз. Бұл оның уақыт туралы абстрактілі түсінігін нақтылауға көмектеседі.') WHERE id = 'ecad2493-1c0b-4ab4-b089-7a992488d7c5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты нысанаға лақтыру". Бала енді допты жай ғана лақтырмай, оны белгілі бір қорапқа немесе нысанаға дәл түсіруге тырысады. Бұл кеңістіктегі қашықтықты бағалау және күшті реттеу (кеңістікті бағалау) дағдысын дамытады.') WHERE id = '6f552613-227f-4085-940c-f293c42bd5f1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сұрақтардың тереңдеуі". Бала "Өлім деген не?", "Біз қайдан келдік?" сияқты болмысқа қатысты күрделі сұрақтар қоюы мүмкін. Жауап бергенде әрдайым шындықты айтыңыз, бірақ оның жасына сай қарапайым әрі көңілін тыныштандыратын түсіндірмелерді таңдаңыз. Бұл сұрақтар — оның қоршаған әлемді түсінуге деген талпынысы.') WHERE id = '5eb1ed63-47a4-4170-b1fc-b58d4507160b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: "Шығармашылық арқылы өзін білдіру". Баланың көңіл күйі болмағанда, ол сурет салып немесе ойыншықтарымен "сырласып", өзін жұбата алады. Оның салған суреттеріне назар аударыңыз; түстер мен пішіндер — оның ішкі дүниесінің айнасы. Сіз — оның ең сенімді панасыз, ал Сізге деген сенімі — оның ең үлкен күші.') WHERE id = '48efdb3a-063c-40d5-837a-9373492693c6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді айналасындағы жазуларға қызығушылық таныта бастайды. Дүкен атауларынан немесе кітап мұқабаларынан өзі білетін әріптерді (мысалы, есімінің бас әрпін) көріп, қуануы мүмкін. Бұл — "бастапқы сауаттылық" кезеңі. Оған әріптерді мәжбүрлеп үйретпеңіз, тек қызығушылығын қолдаңыз.') WHERE id = '4c700caf-0287-4ea7-8bd0-73ca97292800';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы "Аяқты кезектестіріп түсу". Бала енді баспалдақтан түскенде әр басқышқа бір аяғын қойып, аяқтарын кезектестіре бастайды. Бұл жоғары көтерілуден қиынырақ және жақсы тепе-теңдікті қажет етеді. Сіз тек жанында тұрып, оған қауіпсіздік сезімін сыйлаңыз.') WHERE id = '970cfec9-666d-4324-ad8a-2d2689753b64';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Қиялдағы ойын серігі". Кейбір балалар осы кезеңде қиялдан дос ойлап табуы мүмкін. Бұл баланың шығармашылығы мен эмоциялық әлемінің бай екенін көрсетеді. Оны сөкпеңіз және "бұл өтірік" демеңіз. Бала осы досы арқылы өз қорқыныштарын немесе тілектерін зерттейді. Сабырмен әрі қызығушылықпен бақылаңыз.') WHERE id = '9ce75a82-fd02-47a8-adbb-96eadd2b8653';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Көшбасшылық және бағыну". Бала енді ойын кезінде кейде ережелерді өзі белгілесе, кейде басқалардың ережелеріне бейімделеді. Бұл — әлеуметтік икемділіктің негізі. Үйде онымен рөлдеріңізді ауыстырып ойнаңыз: "Енді сен мұғалім бол, ал мен оқушы болайын".') WHERE id = 'd0b4ac9e-9bd0-4b78-83ac-e932a23bb3ff';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Себеп-салдар тізбегі". Бала енді "Егер жаңбыр жауса, біз саябаққа бара алмаймыз" деген сияқты қисынды ой қорыта алады. Онымен оқиғалардың салдары туралы сөйлесіңіз. Бұл баланың болашақта өз әрекеттерінің жауапкершілігін түсіну қабілетін (логикалық салдарларды) қалыптастырады.') WHERE id = '44001e8a-e9dc-4edd-96dc-e3baba2b5ba4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Үш дөңгелекті велосипедті өз бетінше тебу". Бала енді рөлді басқара отырып, педальдарды бірқалыпты айналдырып, қажет кезде тежегішті де қолдана алады. Бұл — дененің төменгі және жоғарғы бөліктері қимылының үйлесімді жұмыс істеуі. Саябақта шағын "велосипед жолын" белгілеп беріңіз.') WHERE id = 'ec14848a-2298-473c-80f2-13859ca28476';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сыпайы өтініштер". Бала енді қалағанын алу үшін "бола ма?", "өтінемін" сияқты сөздерді мақсатты түрде қолданады. Сіздің сыпайы қарым-қатынасыңыз — ол үшін ең жақсы үлгі. Бала сыпайы өтініш айтқан кезде, мұны міндетті түрде атап өтіңіз: "Осындай әдемі өтініш айтқаның үшін саған көмектесуге қуаныштымын".') WHERE id = 'c89c5c28-c3bd-46e0-93e1-c16bc60a714b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: "Өзін-өзі реттеу". Баланың бір ісі сәтсіз болғанда (мысалы, ойыншығы бөлшектеніп қалса), ол бірден жыламай, Сізге қарап көмек сұрайды немесе қайтадан жасап көреді. Бұл — эмоциялық жетілудегі үлкен қадам. Сіз — оның ең сенімді қолдаушысысыз!') WHERE id = 'a0873db2-259d-4791-a8af-c5e115589858';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды тек түсіне қарай емес, атқаратын қызметіне қарай да топтастырады. «Бұлар тамақ ішуге арналған», «Бұлар киюге арналған». Онымен үйде «Қайсысы артық?» ойынын ойнаңыз (мысалы, 3 жеміс пен 1 ойыншық қойыңыз). Бұл оның логикалық ойлау қабілетін дамытады.') WHERE id = 'c4b0066e-1d1d-4a2d-b280-39f147e134fe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Жылдам маневр». Бала енді бар жылдамдығымен жүгіріп келе жатып, алдындағы кедергіні көріп, құламай айналып өте алады. Бұл — мидағы «қимылды жоспарлау» қабілетінің жоғары деңгейге жеткенінің белгісі. Саябақта оған арнап шағын кедергілер жолағын құрыңыз. Бұл денесін басқару қабілеті мен ептілігін арттырады.') WHERE id = 'b1971b1f-63a0-40cf-bb46-3ba6bb8689b2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өткен оқиғаның егжей-тегжейі». Бала енді «Кеше әжеміздікіне барғанда, біз балмұздақ жедік» деген сияқты күрделі естеліктерімен бөліседі. Онымен өткен күн туралы әңгімелесу эпизодтық жадын нығайтады. «Тағы не есіңде?» деп сұрап, әңгімесін кеңейтіңіз.') WHERE id = 'f5184b0f-58ef-4b72-af3f-546cec7ec971';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Суретті көшіру». Бала енді Сіз салған айқышты (+), шеңберді (O) немесе кейбір әріптерді қайталап салуға тырысады. Бұл — көз бен қолдың үйлесімді жұмысы (визуалды-моторлық интеграция). Оған түрлі түсті қарындаштар беріп, әртүрлі геометриялық пішіндерді салуға ынталандырыңыз.') WHERE id = '5ee5e247-d8bd-4375-9669-ceda6b1b0a73';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Әділдік пен ережелер». Бала енді ойын кезінде ереже бұзылса, оған бірден назар аударады: «Ол кезекті бұзды!». Бұл — әлеуметтік «Менінің» дамуы. Ережелердің барлығына бірдей екенін түсіндіру арқылы оның ішкі әділдік сезімі мен әлеуметтік тәртібін нығайтасыз.') WHERE id = 'd1358d5f-b48d-4121-a736-887203ecfc67';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Көшбасшы болуға талпыныс». Бала енді ойынның желісін өзі құрғысы келеді: «Мен дәрігер боламын, ал сен науқас боласың». Осындай рөлдік ойындар арқылы ол әлемді танып, шешім қабылдауды үйренеді. Кейде оның сценарийіне бағыныңыз; бұл оның бойында көшбасшылық пен жауапкершілік сезімін қалыптастырады.') WHERE id = 'd27742a4-8533-4759-aff4-185d7dbf081f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуындағы «Сөз ойындары мен ұйқас». Бала дыбысталуы ұқсас сөздерді табуды ұнатады: «доп-көп», «бала-қала». Бұл — фонематикалық қабылдаудың (дыбыстарды ажырата білудің) дамуы. Онымен бірге ұйқасы бар шағын өлеңдер оқыңыз немесе сөз ойындарын ойнаңыз. Бұл болашақта оқуды меңгеруіне берік негіз қалайды.') WHERE id = '2fa13e97-2173-4c5c-afa8-90f8eaedaa8a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Түйін мен ілмек». Бала аяқкиімнің бауына немесе жіптерге қызығушылық танытып, оларды бір-біріне орап, байлауға тырысады. Оған тесіктері үлкен моншақтар немесе арнайы «бау өткізу ойыншықтарын» беріңіз. Бұл саусақтардың ұсақ бұлшықеттерін жазуға және күрделірек әрекеттерге дайындайды.') WHERE id = '5b2e2766-e73a-4ec2-b386-7bdc27e2bf73';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Қиялдан туындайтын қорқыныштар». Бұл кезеңде баланың қиялы өте күшті болғандықтан, ол қараңғылықтан немесе ойдан шығарылған «құбыжықтардан» қорқуы мүмкін. Оның қорқынышын күлкі етпеңіз және «бұл өтірік» демеңіз. Оның орнына: «Мен қасыңдамын, сені қорғаймын», — деп, оған эмоциялық тірек болыңыз. Бұл оның Сізге деген сенімін нығайта түседі.') WHERE id = 'b420b26f-d658-40bc-93d9-fcbe9a159330';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Дипломатиялық әрекеттер». Бала енді келіспеушіліктерді «Сен маған мынаны бер, мен саған ананы беремін» деген сияқты ұсыныстармен шешуге тырысады. Бұл — әлеуметтік зерденің айқын көрсеткіштерінің бірі. Оның осы «келіссөз жүргізуші» қырын мадақтап, әділ шешімдер табуына қолдау көрсетіңіз.') WHERE id = '4ee1a693-af27-4c8f-b294-06b8239d80b9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мөлшердің сақталуын түсіну тәжірибелері». Бірдей мөлшердегі суды пішіні әртүрлі ыдыстарға құйсаңыз, бала әлі де биік ыдыста су көбірек деп ойлауы мүмкін. Онымен су немесе құм ойындарын ойнап, мөлшердің ыдыс пішініне байланысты өзгермейтінін тәжірибе арқылы түсінуіне мүмкіндік беріңіз.') WHERE id = '13a54bb2-22dc-4956-ad40-80e7f13eda7c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Жылдам тоқтау және бұрылу». Бала жүгіріп бара жатқанда Сіздің «Тоқта!» деген нұсқауыңыз бойынша бірден тоқтай немесе бағытын күрт өзгерте алады. Бұл — бұлшықеттер мен жүйке жүйесінің үйлесімді жұмысының нәтижесі. Онымен саябақта «Қызыл жарық, жасыл жарық» ойынын ойнаңыз; бұл оның өзін-өзі тежеу (inhibitory control) қабілетін дамытады.') WHERE id = '29ee5396-69c9-428e-9152-0052da7ababd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Сан мен мөлшердің сәйкестігі». Бала 5-ке дейін санап қана қоймай, енді «3» санын көргенде 3 ойыншықты бөлек қоя алады. Бұл — болашақ математикалық сауаттылықтың негізі. Күнделікті істер кезінде «маған 4 алма берші» деген сияқты тапсырмалар беріңіз.') WHERE id = '0f53eb59-1dad-4d39-84e5-43e97150561c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Екі аяқпен секіру». Бала енді кедергілерден екі аяғымен бір мезгілде еркін секіріп өте алады. Бұл аяқ пен дененің төменгі бөлігінің күшін әрі қимылдарды үйлестіруді талап етеді. Үйде еденге арқан қойып, оның үстінен секіріп өтетін «Өзеннен өту» ойынын бірге ойнаңыз.') WHERE id = '080c3ee9-a0ea-4062-9f79-5fba44d2d0e4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әзіл мен юмор». Бала енді сөздерді әдейі қате айтып немесе күлкілі дыбыстар шығарып, сізді күлдіруге тырысады. Бұл — тілдік нормаларды түсінудің бір көрінісі. Оның әзілдеріне күліп, юмор сезімін бірге дамытыңыз.') WHERE id = '9fb34927-219f-4b2d-bb9f-dda7da92c634';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Қателігін мойындау». Бала енді бір нәрсені сындырып немесе шашып алғанда, оны бірден жасыруға тырыспай, «мұны мен істедім» деп айта алады. Осындай адалдық танытқан сәтте оны жазаламаңыз; оның орнына бірге жинауды ұсыныңыз. Сіз ол үшін қауіпсіз панасыз!') WHERE id = 'c4b6f5da-e09e-4e7a-8e0a-9a60747fa087';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды бір мезгілде түсіне де, пішініне де қарай топтастыра алады. «Бұл әрі қызыл, әрі дөңгелек» деп, бірнеше белгіні біріктіреді. Бұл — когнитивтік икемділіктің маңызды көрсеткіші. Оған әртүрлі геометриялық пішіндер қолданылатын ойындарды ұсыныңыз.') WHERE id = '2b4289d9-5b1f-4994-a054-e4727135705c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Динамикалық секіру». Бала енді жүгіріп келе жатып, алдынан шыққан шағын кедергіден жылдамдығын бәсеңдетпей секіріп өте алады. Бұл — мида қимылды алдын ала жоспарлау (моторлық жоспарлау) қабілетінің дамуы. Саябақта оған арнап шағын кедергілер құра аласыз.') WHERE id = 'ae389307-05d6-4296-90e1-0a21e776e282';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Мақсатты сұрақтар». Ол енді жай ғана «бұл не?» деп емес, «бұл қалай жұмыс істейді?» деп сұрайды. Заттардың ішкі механизміне, сағаттарға, ойыншықтардың дөңгелектеріне қызығушылық танытады. Жауап бергенде логикалық реттілікті сақтаңыз; бұл сұрақтар — болашақ ғылыми ойлаудың алғашқы ұшқындары.') WHERE id = 'd2e255d4-c4cb-4992-b207-917bc8c7e987';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Симметрияға талпыныстар». Бала қағазды бүктеуге немесе салған суретіндегі бөлшектерді (мысалы, адамның екі көзі мен екі қолын) симметриялырақ орналастыруға тырысады. Бұл оның көру-кеңістіктік қабылдауының қаншалықты жетілгенін көрсетеді.') WHERE id = 'b4315b1b-9d62-41cc-a063-b3b09c4c589a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Саяси» келіссөздер. Бала енді Сізбен «саудаласады»: «Егер мен көкөніс жесем, содан кейін саябақта ұзағырақ қала аламыз ба?». Бұл оның әлеуметтік ықпал ету тетіктерін үйреніп жатқанын көрсетеді. Мұндай «келіссөздерде» адал әрі бірізді болыңыз; ол осылайша шекараларды түсініп үйренеді.') WHERE id = '431cd610-a165-475a-8f4f-464196e237c1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қиялдағы сценарийлер». Енді ойындар күрделірек: «Мен сатушымын, ал сен менен нан сатып алуға кел». Мұндай ойындарда ол қоғамдағы рөлдерді байқап көреді. Оның сценарийлеріне ілесіп, осы шығармашылық үдерісті ынталандырыңыз.') WHERE id = '81128f46-ecb8-47f0-aa0b-337c398b3230';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Уақыт рәсімдері». Бала «кеше», «бүгін» және «ертең» ұғымдарын әлі толық ажырата алмаса да, күнделікті рәсімдерді біледі. «Тамақтан кейін — саябақ» немесе «Ұйықтар алдында — ертегі». Осындай реттілік оның санасында уақыт бағытын қалыптастырады.') WHERE id = '5cb6d50d-147c-44f7-91b0-1d67f401019b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестірудегі «Нәзік әрекеттер». Бала енді сұйықтық құйылған стақанды көп төкпей алып жүре алады немесе жіңішке соқпақпен жүре алады. Бұл оның көру-қимыл үйлесімінің қаншалықты жетілгенін көрсетеді. Үйде оған «кішкентай көмекші» рөлін беріп, осы зейінін нығайтыңыз.') WHERE id = 'efc83589-a712-4c32-9e12-c9ee0f9cee01';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «алдымен, қазір, содан кейін» реттілігін күрделі әрекеттерге қолдана алады. «Алдымен қолымды жуамын, содан кейін тамақ ішемін, ең соңында ойнаймын». Бұл — оның миындағы әрекеттерді жоспарлау қабілетінің (атқарушы функцияның) дамуы. Оған күні бойы орындайтын шағын жоспарлар құруды тапсырыңыз. Бұл оның бойындағы тәртіп сезімін нығайтады.') WHERE id = 'c4e864cd-f8ff-486c-994b-11d240e723ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында — «Үш дөңгелекті велосипедпен маневр жасау». Бала енді велосипед теуіп келе жатқанда алдынан шыққан кедергілерді байқап, рөлді дер кезінде бұра алады. Бұл — педаль айналдыру (дене қимылы) мен жолды бақылау (көру) дағдыларының үйлесімді ұштасуы.') WHERE id = '63226ba2-0699-459a-be66-a4c9af97d876';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде — «Себеп-салдар диалогтары». Ол енді Сіздің шешімдеріңізге қатысты сұрақ қояды: «Мен неге ұйықтауым керек?». Жауап бергенде қисынды түрде түсіндіріңіз: «Өйткені ертең қайтадан күш-қуатпен ойнауың үшін денең демалуы керек». Мұндай тәсіл баланың бойында соқыр бағынуды емес, саналы тәртіпті қалыптастырады.') WHERE id = 'aba02008-e74d-4081-9df9-4e23bad078b6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада — «Қағаз қию». Бала енді қауіпсіз қайшымен қағазды түзу сызық бойымен (немесе қарапайым шеңберді) қиюға тырысады. Бұл — қол мен көз үйлесімін сынайтын ең маңызды әрекеттердің бірі. Оған түрлі түсті қағаздар мен қиюға арналған үлгілер беріп, қол бұлшықеттерін жаттықтырыңыз.') WHERE id = 'd337c2b8-8f8a-4037-8a7a-e030f9920b04';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Шекаралар және бөлісу». Бала енді кейбір заттардың барлығына ортақ екенін (мысалы, саябақтағы әткеншек), ал кейбірінің тек өзіне тиесілі екенін түсінеді. Оған «Бұл — сенің ойыншығың, бөлісу-бөліспеуді өзің шешесің» деп, оның меншік сезімін құрметтеңіз. Өз меншігіне құрмет көрсетілген бала өзгенің заттарына да оңайырақ құрметпен қарайды.') WHERE id = '9f384019-50a1-4540-baab-8643e931568a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта — «Күрделі рөлдік ойындар». Енді ойындарда оқиға желісі бар: «Сен науқассың, мен дәрігермін, мен саған ине саламын». Осындай ойындар арқылы ол шынайы өмірдегі қорқыныштарын (мысалы, дәрігерден қорқуын) жеңуге үйренеді. Оның ойын сценарийіне белсенді қатысыңыз.') WHERE id = '9206ce15-0a76-4431-b07b-049bdcbed6b0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Қиялдан туған қорқыныштар". Бұл кезеңде баланың қиялы соншалықты күшті болғандықтан, ол қараңғылықтан немесе қиялындағы "құбыжықтардан" қорқуы мүмкін. Оның қорқынышына күлмеңіз, "бұл өтірік" деп айтпаңыз. Оның орнына: "Мен осындамын, сені қорғаймын", — деп, оған эмоциялық тірек болыңыз. Бұл оның Сізге деген сенімін мызғымас етеді.') WHERE id = '09cee55c-899d-468c-bef9-66eb86e868c6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Дипломатиялық талпыныстар". Бала енді келіспеушіліктерді "Сен маған мынаны бер, мен де саған ананы беремін" деген сияқты ұсыныстармен шешуге тырысады. Бұл — әлеуметтік зерденің ең айқын көрсеткіштерінің бірі. Оның бойындағы осы "келіссөз жүргізуші" қырын мадақтап, әділ шешімдерді қолдаңыз.') WHERE id = '1f6c2927-0b20-482c-b17f-a447f8fef25d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Мөлшердің сақталуын зерттеу". Бірдей мөлшердегі суды пішіні әртүрлі ыдыстарға құйсаңыз, бала әлі де биік ыдыста су көбірек деп ойлауы мүмкін. Онымен су немесе құм ойындарын ойнап, ыдыстың пішіні өзгергенімен, мөлшердің өзгермейтінін тәжірибе арқылы түсінуіне мүмкіндік беріңіз.') WHERE id = '73557d3a-6c9c-4c6a-a67f-c5d4bc801f0d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Жылдам тоқтау және бұрылу". Бала енді жүгіріп бара жатқанда Сіздің "Тоқта!" деген пәрменіңізді ести сала тоқтай немесе кілт бұрыла алады. Бұл — бұлшықеттер мен жүйке жүйесінің үйлесімді жұмысының нәтижесі. Онымен саябақта "Қызыл жарық, Жасыл жарық" ойынын ойнаңыз; бұл оның өзін-өзі басқару қабілетін дамытады.') WHERE id = '2c94b5e7-3f3c-4f5a-97ae-e15891e8c592';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Әдептілік пен реңктер". Бала енді дауыс ырғағы мен сөздерін кіммен сөйлесіп тұрғанына қарай бейімдей бастайды (мысалы, бөпемен жұмсақтау, ересектермен байыптырақ сөйлеседі). Бұл — әлеуметтік лингвистиканың бастауы. Сіздің сөйлеу мәдениетіңіз — ол үшін ең негізгі әрі мінсіз үлгі.') WHERE id = '708f00c5-3974-4a48-b57b-7ac187203dd5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: "Өзін-өзі мақтау". Бала бір істі орындап шыққанда, "Қарашы, мен мұны қандай әдемі жасадым!" деп, Сізден мақұлдау күтеді. Оның бойындағы осы мақтаныш сезіміне "Иә, сен көп күш жұмсадың" деп жауап беріңіз. Сіздің қолдауыңыз — оның болашақтағы өзіне деген сенімінің іргетасы!') WHERE id = '1eae35d0-6f20-4979-87f2-c88eacf3b104';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сезімдер сөздігі». Бала енді жай ғана «көңіл-күйім нашар» немесе «жақсымын» демейді. «Ашуландым», «сағындым», «қуаныштымын» сияқты сөздерді орынды қолданады. Оның сезімдерін мойындап, қабылдаңыз: «Сағынғандықтан жылауың қалыпты». Бұл — оның эмоциялық саулығының ең мықты кепілі.') WHERE id = 'e498f733-de85-4e45-8875-b886111a89f8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Үш жарым жастың нағыз шыңы! Бала бөпелік кезеңнен толық өтіп, ерте балалық шақтың ең белсенді кезеңіне аяқ басты. Қазір ол физикалық жағынан да, эмоциялық жағынан да дербес тұлға. Сіз осы 1250 күн ішінде оның дүниеге деген берік сенімінің негізін қаладыңыз. Өзіңізді мақтан тұтыңыз!') WHERE id = 'a45a87d4-253c-4fea-ac32-9cea3f5b1168';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала айналасындағы жазуларға қызығушылық таныта бастайды. Дүкен атауларынан немесе кітап мұқабаларынан өзі білетін әріптерді (мысалы, есімінің алғашқы әрпін) көріп, қуанып қалуы мүмкін. Бұл — «бастапқы сауаттылық» кезеңі. Оған әріптерді мәжбүрлеп үйретпеңіз, тек қызығушылығын қолдаңыз.') WHERE id = '0aedbd42-1452-4a3e-aa54-4adb1ad4a556';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Физикалық дамудағы «Баспалдақпен аяқты алма-кезек басып түсу». Бала енді баспалдақпен түскенде әр басқышқа аяғын кезек-кезек қойып түсе бастайды. Бұл жоғары көтерілуден қиынырақ әрі тепе-теңдікті жақсы сақтауды талап етеді. Сіз тек жанында тұрып, оған қауіпсіздік сезімін сыйлаңыз.') WHERE id = '4a1598de-455f-4bae-a8b3-0f5696c065c6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сөз ойыны мен ұйқас». Бала ұқсас естілетін сөздерді табуды ұнатады: «доп-көп», «алма-салма». Бұл — фонематикалық естудің (дыбыстарды ажырату қабілетінің) дамуы. Онымен бірге шағын ұйқасты өлеңдер оқыңыз немесе сөз ойындарын ойнаңыз. Бұл болашақта оқу дағдысының қалыптасуына берік негіз қалайды.') WHERE id = '3f6a6fa9-4e7a-4539-93e7-6da1070ea997';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Түйін мен ілмек». Бала аяқкиім бауына немесе жіптерге қызығып, оларды бір-біріне байлап көруге тырысады. Оған тесігі үлкен моншақтар немесе арнайы «бау өткізуге арналған ойыншықтар» беріңіз. Бұл саусақтардың ұсақ бұлшықеттерін жазуға және күрделірек әрекеттерді орындауға дайындайды.') WHERE id = 'cf6a8a3d-c742-40b0-a3c1-38fd2db89aec';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Сан мен мөлшердің сәйкестігі». Бала 5-ке дейін санауды біледі әрі «3» дегенде 3 затты көзбен ажырата алады. Оған «Маған 4 қасық берші» деген сияқты тапсырмалар беріңіз. Бұл — абстрактілі сандардың шынайы өмірмен алғаш рет нақты байланысатын кезеңі.') WHERE id = 'eaf2d09d-f792-4b9d-ab37-65dbbde32f39';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Екі аяқпен секіру». Бала енді кедергілерден (мысалы, жерге қойылған арқаннан) екі аяғымен бір уақытта еркін секіріп өте алады. Бұл аяқ пен төменгі дене күшін, сондай-ақ қимылдардың үйлесімділігін қажет етеді. Үйде онымен «Өзеннен өту» ойынын ойнап, белсенділігін арттырыңыз.') WHERE id = '9a61025f-abc9-4c98-bf07-819847137992';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әзіл және юмор». Бала сөздерді әдейі бұрмалап айтып немесе күлкілі дыбыстар шығарып, Сізді күлдіруге тырысады. Бұл оның тіл нормаларын білетінін және әзіл тудыру үшін оларды әдейі бұзатынын көрсетеді. Оның әзілдеріне күлу өзіне деген сенімділігі мен әлеуметтік зердесінің дамуына ықпал етеді.') WHERE id = 'b25c4c56-1f97-4223-b20b-689b5e94d1d3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сәтсіздікті еңсеру». Бала бір ісі (мысалы, текшелерден мұнара құрастыру) сәтсіз болғанда бірден жыламай, Сізге қарап: «Қайта жасап көрейін бе?» — деуі мүмкін. Оның нәтижесін емес, күш-жігерін мақтаңыз: «Сен көп тырыстың, жарайсың!». Сіз — оның ең үлкен мотивация көзісіз!') WHERE id = 'f9148bba-3642-4b13-ad48-62db8da7ed80';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды тек сыртқы көрінісіне қарай емес, материалына қарай да ажыратады: «Мынау пластик, ал мынау темір». Оған құрылымы әртүрлі заттарды беріп, олардың айырмашылығын сұраңыз. Бұл қоршаған ортаны егжей-тегжейлі талдауына және физикалық әлем туралы білімін жүйелеуіне көмектеседі.') WHERE id = '80e00e5a-2a93-4c1b-a710-db553822e4ae';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Бір аяқпен тепе-теңдікті сақтау». Бала енді бір аяғымен 5 секундтан артық тұра алады. Бұл мишық пен бұлшықет үйлесімінің жетілгенін көрсетеді. Онымен «Ләйлек» ойынын ойнап, кімнің ұзағырақ тұра алатынын байқап көріңіз.') WHERE id = '18ab2c20-2470-41d2-b5e5-3121b8d7e0c1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сын есімдер қорының молаюы». Бала заттарды сипаттағанда олардың түсін ғана айтып қоймай, «жұмсақ», «тікенекті», «тегіс» сияқты сөздерді де қолданады. Онымен «Ұста да тап» ойынын ойнаңыз: көзін жұмып, затты ұстағанда қандай сезім тудыратынын айтып беруін сұраңыз.') WHERE id = '6a7056fe-a7e8-4d7e-91b2-4d5b5277e537';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Таңбаларды танып-білу». Бала енді кейбір әріптерді (әсіресе өз есімінің бірінші әрпін) немесе сандарды көшіріп жазуға тырысады. Бұл оның көрнекі таңбалар мен дыбыс/мағына арасындағы байланысты түсінетінін көрсетеді. Оған құм бетіне немесе түрлі түсті қарындаштармен «жазу» жаттығуларын жасатыңыз.') WHERE id = 'b57332a7-c381-44a7-bdb8-aef8d6820036';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару және шыдамдылық». Бала енді қалаған нәрсесін алу үшін 5-10 минут күту керектігін (мысалы, тамақ дайын болғанша) сабырмен қабылдайды. Сіздің «сәл күте тұр» деуіңізді жаза ретінде емес, уақыт қажет болғандықтан айтылған өтініш деп түсінеді. Оның шыдамдылық танытқанын көргенде, міндетті түрде «Күткеніңе көп рақмет» деп жігерлендіріңіз.') WHERE id = '7374ce80-a74f-4d7f-bb0f-135ec7c6d431';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Жанашырлық пен жұбату». Бала енді Сіздің шаршағаныңызды немесе досының көңілі түскенін көрсе, оған ойыншығын әкеліп беруі немесе сипап жұбатуы мүмкін. Бұл оның ішкі дүниесінің қаншалықты байып, «мен» шеңберінен шығып, «бізге» бет бұра бастағанын көрсетеді.') WHERE id = '62ab0290-ec13-4b50-86f2-b4a69aba6dda';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Көлемді қабылдау». Енді ол үлкен қораптың ішіне қанша кішкентай ойыншық сыятынын болжауға тырысады. Оған әртүрлі көлемдегі ыдыстар беріп, «Қалай ойлайсың, мына су ана ыдысқа сия ма?» деп сұраңыз. Мұндай тәжірибелер болашақтағы математикалық және физикалық түсініктердің негізін қалайды.') WHERE id = 'd68476f5-47bc-4622-82c1-31e6c34eeecd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Артқа қарай жүру». Бала енді тепе-теңдігін жоғалтпай, артқа қарай сенімді түрде бірнеше қадам жасай алады. Бұл қимыл оның өз денесін сезіну қабілетін (проприоцепцияны) жақсартады. Онымен саябақта «шаяндар жарысы» ойынын ойнап, әрі көңіл көтеріңіз, әрі бұлшықеттерін жаттықтырыңыз.') WHERE id = 'ff4d4dbc-967a-48e5-b6f7-ae29e0a5390d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әдеп пен реңктер». Бала енді дауыс ырғағын кіммен сөйлесіп тұрғанына қарай бейімдей бастайды (мысалы, бөпемен жұмсақ, ал ересектермен байыптырақ сөйлейді). Бұл — әлеуметтік лингвистиканың бастауы. Сіздің сөйлеу мәдениетіңіз — ол үшін ең басты әрі мінсіз үлгі.') WHERE id = '3f691af2-a53f-4e9e-bda8-73c25f9784e5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1280 күндік үлкен даму! Бала қазір «ерте балалық шақтың» ең жемісті кезеңінде. Ол енді өз талғамы, қорқыныштары және шексіз сұрақтары бар толыққанды жеке тұлға. Сіз бұл жолдан білім мен сүйіспеншілікке сүйеніп өттіңіз. Anacan әрқашан сіздің жаныңызда!') WHERE id = 'cb9230b0-c04d-4749-92fd-37201aec8ecd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды бір ғана емес, екі белгісі бойынша топтастыра алады: «әрі қызыл, әрі кішкентай мәшинелер». Бұл — когнитивтік икемділіктің маңызды кезеңі. Оған әртүрлі ойыншықтар беріп, «Жұмсақ әрі көк түсті ойыншықтардың бәрін тап» деп, ойлау қабілетін жаттықтырыңыз.') WHERE id = '7f3f7af2-f05b-47b3-bb9a-bf661d551477';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Дәл секіру». Бала енді тұрған орнынан жоғары да, белгілі бір нысанаға қарай да (мысалы, жердегі шеңбердің ішіне) секіре алады. Бұл оның тепе-теңдік сақтау және кеңістіктегі қашықтықты есептеу қабілетін көрсетеді. Саябақтағы «тастан тасқа секіру» ойыны ол үшін тамаша жаттығу болады.') WHERE id = 'b66ed3bb-08b0-48a9-9270-0f8d21791b6b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт реттілігі». Ол енді «алдымен, қазір, содан кейін» ұғымдарын нақтырақ қолданады: «Алдымен қолымды жуамын, содан кейін тамақ жеймін». Онымен күн жоспарын талқылау тәртіп пен қауіпсіздік сезімін қалыптастырады. Оның «Енді не істейміз?» деген сұрақтарына әрдайым ретін сақтап жауап беріңіз.') WHERE id = '4a19271e-0252-465e-a5b6-220dfc833dfa';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Суретті көшіру: үшбұрыш пен айқыш». Бала енді түзу сызықтарды қиылыстырып, айқыш (+) сала алады және үшбұрышқа ұқсас пішіндер жасауға тырысады. Бұл — жазу дағдысының бастапқы негізі. Оған түрлі түсті қарындаштар мен таза қағаз беріп, осы «геометриялық жаңалықтарын» қолдаңыз.') WHERE id = '5e0bb7b8-fe4c-40a9-87b2-d5ec3dff9314';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзін-өзі реттеу және эмоциялар". Бала ашуланғанда немесе көңілі түскенде, кейде өзін тыныштандыру үшін Сіз ұсынған тәсілдерді (мысалы, терең тыныс алуды) қолдана алады. Бұл — эмоциялық интеллектінің өмірдегі ең маңызды дағдыларының бірі. Ол тынышталған кезде, бұл әрекетін міндетті түрде мақтаңыз.') WHERE id = 'cab1e84e-d4d4-48e6-a7cb-8122f2485764';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Командалық ойындар". Бала енді басқа баламен ортақ мақсатқа жету үшін (мысалы, үлкен құм қамалын салу үшін) бірлесіп әрекет ете алады. Бұл — "қатар ойнаудан" "әлеуметтік ойынға" толық өту кезеңі. Оның достарымен тіл табысуға талпынысын бақылап, қолдау көрсетіңіз.') WHERE id = '35da39d6-0c56-4410-8592-5e1cbd4b1e03';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Сан мен мөлшердің сәйкестігі". Бала 10-ға дейін санай алады, енді "3" санын көргенде 3 ойыншықты бөліп қоя алады. Бұл — математикалық ойлау дамуының ең маңызды кезеңдерінің бірі. Күнделікті өмірде "маған 2 қасық берші" сияқты тапсырмалар арқылы осы байланысты нығайтыңыз.') WHERE id = '4397b751-5eff-493f-b5d9-774c99d1ca07';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты екі қолмен ұстау". Бала енді өзіне қарай баяу лақтырылған үлкен допты екі қолымен (кейде кеудесіне қысып) ұстап алуға тырысады. Бұл қимыл қол мен көздің үйлесімділігін және реакция жылдамдығын қажет етеді. Онымен жақын қашықтықтан доп ойнаңыз.') WHERE id = '416872cb-a02b-4d4e-ac74-f040d4ce096b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сыпайы өтініштер". Бала енді қалағанын алу үшін "бола ма?", "өтінемін" сияқты сөз тіркестерін мақсатты түрде қолданады. Сіздің сыпайы қарым-қатынасыңыз — ол үшін ең жақсы үлгі. Ол сыпайы сөйлеген кезде, мұны міндетті түрде атап өтіңіз: "Осындай әдемі өтініш айтқаның үшін саған көмектесуге өте қуаныштымын".') WHERE id = 'eb838920-fe5c-415a-a9ba-0dabdeaffb4e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: "Қателігін мойындау". Бала енді бір нәрсені сындырып немесе шашып алғанда, оны бірден жасыруға тырыспай, "оны мен істедім" деп айта алады. Осындай адалдық танытқан сәтте оны жазаламаңыз; оның орнына бірге жинап-тазалауды ұсыныңыз. Бұл оның бойында жауапкершілік сезімін қалыптастырады. 1290 күндік жолдың әрбір сәті құнды!') WHERE id = 'fba8e58a-849a-4502-b3b8-829b5d503078';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Реттеу және логика". Балаңыз енді заттарды тек түсіне қарай емес, көлеміне қарай да (үлкен-кіші) ажырата бастайды. Оған әртүрлі көлемдегі ыдыстар беріп, оларды бірінің ішіне бірін салуын сұраңыз. Бұл — оның болашақ математикалық ойлауының негізі.') WHERE id = 'cd04a6bc-1fab-4d68-920a-3fa77ebf8503';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен өзім киінемін" кезеңі күрделене түседі. Балаңыз енді сыдырманы (Сіз бастап бергеннен кейін) тартуға немесе үлкен түймелерді ағытуға тырысады. Бұл кезде оған кедергі жасамаңыз және асықтырмаңыз. Бір нәрсені өз бетінше істей алғанын көру — оның өзіне деген сенімінің ең үлкен көзі. Кішкентай жетістіктері үшін оны міндетті түрде мадақтап, жігерлендіріңіз.') WHERE id = '701a4eec-68f9-49ca-9e96-f1cb4b81484e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта "Эмпатия" арта түседі. Балаңыз Сіздің немесе басқа баланың көңілсіз екенін көргенде, жаныңызға келіп, ойыншығын ұсынуы немесе құшақтауы мүмкін. Бұл — оның эмоциялық интеллектісінің (EQ) жақсы көрсеткіші. Оның осындай қамқорлығын "Маған қолдау көрсеткенің үшін көп рақмет" деп бағалаңыз.') WHERE id = 'db3deaea-d927-47d7-b65e-09bbf47b377f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Пішін мен көлем". Балаңыз енді бірдей пішіннің (мысалы, шеңбердің) үлкен және кіші нұсқаларын ажырата алады. Оған әртүрлі көлемдегі ыдыстарды бірінің ішіне бірін салуды көрсетіңіз. Бұл оның болашақ математикалық ойлауының негізі саналатын "реттеу" дағдысын дамытады.') WHERE id = '1317ee1d-1c19-4d58-ab70-d9a1fa691c6f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты тебу және нысанаға бағыттау". Балаңыз енді допты жай ғана теппей, оны белгілі бір бағытқа жіберуге тырысады. Бұл — көру зейіні мен қимыл үйлесімділігінің бірлескен жұмысы. Үйде немесе саябақта онымен бірге "кішкентай қақпа" жасап, допты соған тебу ойынын ойнаңыз. Бұл оның аяқ бұлшықеттерін нығайтып, қимыл дәлдігін арттырады.') WHERE id = 'c1e87167-2300-4b17-9def-ab985555b55e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Әңгіме айтуға талпыныстар". Балаңыз күні бойы көрген қызықты бір нәрсесін (мысалы, "Үлкен ит көрдім") Сізге айтып беруге асығады. Оның әңгімесін соңына дейін тыңдап, сұрақтар арқылы толықтырыңыз: "Ит не істеп жүрді?". Бұл оның есте сақтау қабілетін де, ойын жеткізу дағдысын да нығайтады.') WHERE id = '404203bc-920b-47d3-b584-2989b01e93ee';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Бала енді «Мен қаламаймын» деп, өз еркін табанды түрде білдіруі мүмкін. Мұндай сәттерде онымен қасарысудың орнына, таңдау мүмкіндігін ұсынып, назарын басқаға аударыңыз. Сіздің сабырлылығыңыз бен тұрақты ережелеріңіз баланың бойында қауіпсіздік сезімін қалыптастырады. Сіз керемет жұмыс атқарып жүрсіз!') WHERE id = '17f5e755-5dec-4458-9be1-0d08e0586eaf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «Мен» есімдігінің мағынасын толық түсініп, қолданады. «Мен келдім», «Мен жедім» деген сияқты сөйлемдер оның өзін айналасындағы адамдардан бөлек жеке тұлға ретінде қабылдайтынын көрсетеді. Оның осындай дербес сөйлеуін қолдап, диалогті кеңейтіңіз: «Иә, сен дәмді тамағыңды жедің, жарайсың!».') WHERE id = '12f036fb-3726-4e17-bff9-217ad09dba7b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында «Жиектас бойымен жүру» дағдысы қалыптасады. Бала енді қолынан ұстаған кезде аласа жиектастың үстімен жүруге қызығушылық танытады. Бұл оның күрделі тепе-теңдік сақтау қабілетін дамытады. Қауіпсіз жерлерде бұл қызығушылығын қолдаңыз, өйткені ол болашақта күрделірек дене қимылдарын меңгеруге негіз болады.') WHERE id = '292c2a9d-2b19-4e22-9095-add20bbbeaf5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде «Үш сөзден тұратын сөйлемдердің көбеюі» байқалады. Бала енді «Анашым, су бер», «Әке, саябаққа бар» сияқты күрделірек сөйлемдер құрайды. Ол өз қажеттіліктерін толық жеткізе алады. Оның сөйлемін мақұлдап, сәл кеңейтіп қайталаңыз: «Иә, қазір бірге су ішейік, содан кейін саябаққа барамыз». Бұл оның грамматиканы түсіну қабілетін жетілдіреді.') WHERE id = '7132fa94-7590-4b27-b006-e5936aaf0907';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада «Пазл құрастыру шеберлігі» артады. Бала енді 6-8 бөліктен тұратын қарапайым пазлдарды өз бетінше құрастыра алады. Бұл әрі көрнекі талдауды, әрі саусақ бұлшықеттерінің дәл қимылдауын қажет етеді. Суретті құрастырып болған сайын қуанышыңызды білдіріңіз, сонда оның күрделі тапсырмаларға қызығушылығы артады.') WHERE id = 'd4e00b50-79ce-485c-9a88-f514c156f1f6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім жинаймын». Ойыншықтарды орнына жинау енді ол үшін жай ғана тапсырма емес, жауапкершілікке айналады. Сіз «Кәне, көліктерді жататын орнына қояйық» дегенде ол көмектессе, бұл тәртіптіліктің негізі болып саналады. Бұл әдет болашақта оның жинақы әрі ұқыпты болуы үшін өте маңызды.') WHERE id = '03327c5a-8698-4e34-8b71-2d0914f0f88b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ерік-жігер және шекаралар: Бала «Болмайды» деген сөзге жауап береді, бірақ кейде сол әрекетті әдейі жасап, Сізге қарап тұрады. Осылайша ол Сіздің төзіміңіз бен ережелердің өзгермейтінін тексереді. Сабырлы, бірақ табанды болыңыз. Ережелердің тұрақтылығы балада қауіпсіздік пен тәртіп сезімін қалыптастырады.') WHERE id = '3e76b053-c97c-4476-b999-951be493bb64';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме айтуға талпыныстар». Бала күні бойы көрген қызықты нәрсесін (мысалы, «Саябақта үлкен ит көрдім») Сізге айтып беруге асығады. Оның әңгімесін соңына дейін тыңдап, «Ит не істеп жүрді?» деген сияқты сұрақтар қойып, толығырақ айтуына көмектесіңіз. Бұл оның есте сақтау қабілетін де, ойын жеткізу дағдысын да нығайтады.') WHERE id = 'e7fba00d-ba92-45d4-9c39-8a2e6decdc8c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық даму: «Өзін-өзі басқару». Бала ашуланғанда Сізге қарап, реакцияңызды күтуі мүмкін. Мұндай сәттерде сабыр сақтап: «Текшелер құлап қалғандықтан, сен қазір ашуланып тұрсың, мен сені түсінемін», — деп оның сезімін атап беріңіз. Сіздің сабырлылығыңыз — ол үшін эмоцияларын реттеудің ең жақсы үлгісі. Сіз керемет анасыз!') WHERE id = '4a2f0d04-3378-4296-a224-feb8d41e9254';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді ажыратып қана қоймай, олардың көбінің атауын дұрыс айта алады. «Көк машинаны алып кел» дегенде қателеспесе, бұл оның көру және сөздік жадысының үйлесімді дамып келе жатқанын көрсетеді. Күнделікті серуен кезінде «Жасыл жапырақ», «Сары күн» сияқты сипаттамаларды қолданып, оның әлемін түстермен байыта беріңіз.') WHERE id = '57505a63-7f8c-48f6-bce2-90daca2c8189';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Баспалдақпен еркін жүру». Бала енді бір қолынан ұстағанда, баспалдақтың әр сатысына аяғын кезекпен қойып көтерілуге талпынады. Бұл — ірі моториканың дамуындағы елеулі жетістік. Әрдайым жанында болып, қауіпсіздігін қамтамасыз етіңіз, бірақ өз бетінше қадам басуы үшін оған сенім білдіріңіз.') WHERE id = 'e9641593-3c91-4cf3-a6cc-b86c93ef50be';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Кеңістікті білдіретін сөздер». Бала «үстінде», «астында», «артында» сияқты ұғымдарды әрекеттерімен көрсете алады. Оған «Допты орындықтың астына қой» деп, шағын ойын ойнаңыз. Мұндай тапсырмалар оның тілді түсінуін де, кеңістікті бағдарлау қабілетін де жылдам дамытады.') WHERE id = '2ff11d89-9e65-4caa-b39f-98e5298d4503';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Кезек күту» дағдысы. Бала саябақта әткеншек тебу немесе ойыншықпен ойнау үшін біраз күту керегін енді түсінеді. «Қазір менің кезегім, содан кейін сенікі» деген ойындар арқылы оған шыдамдылықты үйретіңіз. Бұл дағды — оның болашақта балабақша мен мектеп ортасына бейімделуіне қажетті ең маңызды әлеуметтік негіздердің бірі.') WHERE id = '3ea5aca0-7734-4b06-864f-00aa21361675';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Бірдей және әртүрлі» ұғымдары. Бала енді бірдей санаттағы заттарды топтастыра алады (мысалы, барлық жануарды бір жерге, ал барлық көлікті басқа жерге жинайды). Оған «Мұнда қай ойыншық өзгеше?» деген сұрақтар қойып, көрнекі логикасын тексеріңіз. Санаттар бойынша ойлау оның танымдық қабілетін жаңа деңгейге көтереді.') WHERE id = '09d14134-1ab9-423c-86bd-46c0a52d2f86';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Доп тебу және жүгіру». Бала енді жүгіріп келе жатып, тепе-теңдігін жоғалтпай алдындағы допты тебе алады. Бұл әрі көңілді, әрі дене дамуына өте пайдалы. Онымен үйде немесе аулада жеңіл доппен ойнап, қимыл жылдамдығы мен дәлдігін дамытыңыз.') WHERE id = '39fb4064-3e7d-4aa6-b4d5-c75b564c92cc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Есте қалғанын жеткізу» дағдысы. Бала күні бойы болған қарапайым оқиғаны есіне түсіріп (мысалы, «Саябақта ит көрдім»), Сізге айтып бере алады. Оның әңгімелерін мұқият тыңдап, «Содан кейін не болды?» деп оқиғаны ретімен баяндауына көмектесіңіз. Бұл оның есте сақтау қабілетін де, ойын жеткізу дағдысын да нығайтады.') WHERE id = '109cbe57-dd82-4d85-b381-3ebd329772ab';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық даму: «Өзін-өзі басқаруға талпыныс». Бала ашуланған кезде Сізге қарап, реакцияңызды күтуі мүмкін. Мұндай сәттерде сабырлы болып, «Ойыншықты жөндей алмағандықтан, қазір ашуланып тұрсың» деп оның сезімін атап айтыңыз. Сіздің сабырлылығыңыз — ол үшін эмоцияларын реттеудің ең жақсы үлгісі. Сіз керемет анасыз!') WHERE id = 'cbb6c494-b75d-458c-b798-2ddf1bf9e334';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '27-айға қош келдіңіз! Бала енді «екі қадамды» есте сақтау дағдысын толық меңгереді. «Ойыншығыңды ал да, қорапқа сал» дегенде, екі әрекетті де ретімен орындайды. Бұл мидың префронталды қыртысының дамып жатқанын көрсетеді. Күні бойы оған шағын әрі түсінікті тапсырмалар беріп, осы дағдысын жетілдіріңіз.') WHERE id = '0b872b3f-49b7-446a-bc7c-dfae010fe461';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Өз бетінше тамақтану дағдысы енді қалыптасып қалуы керек. Иә, бөпеңіз әлі де қасықты теріс ұстап немесе тамақтың жартысын жерге төгіп алуы мүмкін, бірақ оның өзі тамақтануға талпынуы өзіне деген сенімі үшін бәрінен маңызды. Оған өзі қолдануға ыңғайлы терең ыдыс пен сабы резеңкеленген қасық беріңіз. Сабырлы болыңыз, көп ұзамай ол отбасы дастарқанының ең белсенді әрі "дербес" мүшесіне айналады.') WHERE id = 'd42878d7-1b6d-456a-b198-9e59777aacf0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Ажырасу мазасыздығы" (Separation anxiety) 1 жас шамасында қайтадан шарықтау шегіне жетуі мүмкін. Сіз бөлмеден шыққанда оның қатты жылауы — Сізге деген терең бауыр басуының және әлі де "анам кетсе, қайтып келмейді" деп қорқатынының белгісі. Оған әрдайым қайда бара жатқаныңызды және қашан қайтып келетініңізді айтыңыз (тіпті басқа бөлмеге ғана барсаңыз да). Сіздің шынайылығыңыз оның қауіпсіздік пен сенім сезімін қалпына келтіреді.') WHERE id = 'bf1abd20-6eb2-41e7-85ec-e1c3f46808a3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы жаңа жетістік: "Қақпақты ашу және жабу". Бөпеңіз енді қораптардың қақпағын ашу, бөтелкелердің қақпағын бұрап көру сияқты әрекеттерді ұнатады. Бұл білек пен саусақ бұлшықеттерінің үйлесімді жұмысының жоғары деңгейін көрсетеді. Оған өлшемдері әртүрлі пластик ыдыстар беріп, оларды бірінің ішіне бірін салып көруіне мүмкіндік беріңіз. Бұл оның математикалық және логикалық ойлауын дамытатын алғашқы жаттығу да болады.') WHERE id = '4e49e60c-de35-4a74-ac4f-e95ac56a3410';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік ережелерді үйрену: Бөпеңіз енді "сау бол" деп қол бұлғау, "ауада сүйіс жіберу" немесе "қол беру" сияқты ишараларды саналы түрде жасайды. Бұлар — оның қоғамға араласуына жол ашатын алғашқы "визалары". Осындай жағымды әрекеттерін әрдайым қуана қабылдаңыз. Сіздің реакцияңыз оған қандай мінез-құлықтың "жақсы" екенін түсінуге көмектеседі.') WHERE id = '21db9180-06af-489e-83b0-28bdcc1730d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ертең бөпеңіз тура 1 жасқа толады! Бүгін өткен 12 айдағы қызықты сәттерді еске алыңыз. Алғашқы жымиюы, алғашқы тісі, алғаш еңбектеуі... Қаншалықты қиын болса да, Сіз бәрін еңсердіңіз! Бөпеңіз енді біреудің көмегіне толық мұқтаж сәби емес, өз мінезі мен қалауы бар кішкентай тұлға. Бүгін түнде ұйықтар алдында өзіңізге де бір "жарайсың" деңіз. Сіз керемет анасыз!') WHERE id = '74f434ee-a5bf-498f-af06-34cc0939c106';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'ҚҰТТЫҚТАЙМЫЗ! АЛҒАШҚЫ ТУҒАН КҮНДЕРІҢІЗ ҚҰТТЫ БОЛСЫН! 🎂 Бөпеңіз ресми түрде 1 жасқа толды. Бұл жыл оның да, Сіздің де өміріңіздегі ең үлкен өзгерістер болған жыл еді. Ол енді жүруге, сөйлеуге және әлемді бағындыруға дайын "Toddler" (жүре бастаған бала). Бұл күнді еш уайымсыз, оның күлкісі мен Сіздің махаббатыңызға толы күйде атап өтіңіздер. Жолдарыңыз ашық, ғұмырларыңыз берекелі болсын!') WHERE id = '56917d9b-b358-4310-b651-30aecbaf8560';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Қағазбен жұмыс істеу». Бала енді қағазды бүктеуге немесе қарапайым түрде қиюға (үлкен балалар қайшысымен, ересектердің бақылауында) қызығушылық танытуы мүмкін. Бұл әрекеттер саусақ бұлшықеттерін басқаруды жаңа деңгейге көтереді. Оған түрлі түсті қағаздармен жұмыс істеуге жағдай жасаңыз.') WHERE id = '1867a29d-cdef-4c25-9fb4-31fe661ffbe5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Рөлдік ойындардың күрделенуі». Бала енді «дәрігер», «аспаз» немесе «жүргізуші» рөліне ене алады. Осы ойындар арқылы ол айналасындағы адамдардың міндеттерін түсініп, эмпатияны дамытады. Оның ойынына қосылып, Сізге берген «рөлге» сай әрекет етіңіз.') WHERE id = '09d954dd-f762-40e1-8030-11d38ef87b47';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тазалық сақтау» дағдысы. Бала енді қолын жуған кезде сабындап, шаюды толығымен дерлік өз бетімен орындай алады. Осы жаста гигиеналық дағдыларды бекіту өте маңызды. Бұл үдерістен ләззат алуы үшін оған бойына сай басқыш-тұғыр (step stool) дайындап қойыңыз.') WHERE id = '8f3c97e4-28e2-4575-994c-03b54f2a86ed';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Өзгеше затты тап». Бала енді заттар тобының ішінен өзгеше затты (мысалы, көліктердің арасындағы алманы) көзбен ажырата алады. Бұл оның талдау қабілетін жетілдіреді. Үйде оған қарапайым «Қай зат артық?» ойындарын ұйымдастырыңыз. Бұл болашақтағы математикалық және логикалық тапсырмаларға тамаша дайындық болады.') WHERE id = '0c2d9534-6a6b-4045-844a-9433e0a69d75';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Бір аяқпен тұру әрекеттері». Бала бірнеше секунд болса да, бір аяғын жерден көтеріп, тепе-теңдігін сақтауға тырысады. Бұл дененің ауырлық орталығын сезіну үшін маңызды. Онымен «Ләйлек ойынын» ойнап, кімнің ұзағырақ тұра алатынын байқап көріңіздер.') WHERE id = '5d944b43-095b-4d92-b030-b834a56949f2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сезімді білдіру». Бала енді мұңайғанын, қуанғанын немесе қорыққанын сөзбен айта алады: «Мен қорқып кеттім» немесе «Мен қуаныштымын». Сезімдерді атай білу — баланың эмоциялық интеллектісінің негізі. Ол сезімін айтқан кезде мұқият тыңдап, «Иә, мен сені түсінемін» деп, оның сезімін мойындаңыз.') WHERE id = 'cb48e516-3844-4090-848b-2afd50d005de';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Екі аяқпен алға секіру». Бала енді бір орында ғана емес, сәл алға қарай да секіре алады. Бұл аяқ бұлшықеттерінің күшін және дене қимылдарының үйлесімділігін қажет етеді. Онымен «Қояндар көгалда секіреді» ойынын ойнаңыз. Бұл әрі көңілді, әрі жалпы моториканы дамытуға арналған тамаша жаттығу.') WHERE id = '9999afba-b8a0-474d-b26c-6136ec804e12';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап диалогі». Бала енді Сізге «Әкем қайда?», «Бұл не?» сияқты қарапайым сұрақтар қоя алады. Жауап бергенде толық сөйлемдер құраңыз: «Әкең жұмысқа кетті, кешке келеді». Сіздің егжей-тегжейлі түсіндіруіңіз оның санасында оқиғалар арасындағы логикалық байланыстарды нығайтады.') WHERE id = 'e0d072d6-3ce1-4139-b80e-a94b53d2fc54';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 800 күнді артқа тастадық! Бала 2 жастан асып, күн сайын жаңа нәрсе ашып келеді. Ол қарапайым ережелерді түсінеді, эмоцияларын анық көрсетеді және Сізбен еркін қарым-қатынас жасайды. Бұл күнді онымен бірге сүйікті саябағында өткізіп, атап өтіңіз. Сіз керемет анасыз!') WHERE id = '1df3c116-f7da-4df5-8d7e-4570b51bb9eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '27-ші айдың ортасына аяқ басып келеміз. Бала енді «алдымен» және «содан кейін» деген реттілікті тереңірек түсінеді. «Киіміңді ки, содан кейін далаға шығамыз» дегенде, ол екінші әрекеттің марапат екенін ұғынады. Бұл — баланың бойындағы шыдамдылық пен жоспарлау дағдысының алғашқы негіздері. Күнделікті әдеттер барысында осы реттілікті оған жиі еске салып отырыңыз.') WHERE id = 'bf2725f4-a91c-46df-b906-cbe0eca9ab09';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Өрмелеу шеберлігі». Бала енді саябақтағы шағын баспалдақтарға немесе үйдегі қауіпсіз биіктіктерге сенімдірек көтеріледі. Бұл кезде қол мен аяқ бұлшықеттері үйлесімді жұмыс істейді. Әрдайым жанында болыңыз, бірақ оған өз күшін сынап көруге мүмкіндік беріңіз.') WHERE id = '03ce58c6-bf39-4cb2-86c0-fb921289cb85';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Логикалық байланыстар». Бала енді екі құбылысты бір сөйлемге біріктіреді: «Күн суық, күртеше ки». Бұл оның жай ғана қайталамай, ойлана да алатынын көрсетеді. Өз ойын жеткізуге деген ынтасын арттыру үшін оның осындай логикалық пайымдарын «Иә, дұрыс айтасың» деп қолдаңыз.') WHERE id = '70d20b90-08cb-4a3d-b635-39b5e961b0df';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы "Баспалдақтан түсу шеберлігі". Бала енді қолынан ұстаған кезде баспалдақтан сенімдірек, бір-бір қадамнан түсуге тырысады. Төмен түсу жоғары көтерілуден қиынырақ, өйткені тепе-теңдікті көбірек сақтауды қажет етеді. Әрдайым жанында болып, қауіпсіздігін қамтамасыз етіңіз және жетістігін мадақтаңыз.') WHERE id = '912ef746-569e-455d-af72-84d6cc3f170e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сын есімдер мен үстеулерді бірге қолдану". Бала енді жай ғана "көлік" демей, "жылдам қызыл көлік" деп айта алады. Ол айналасындағы әлемді сипаттау үшін көбірек егжей-тегжей қолданады. Онымен сөйлескенде заттардың қасиеттерін атап көрсетіңіз: "Бұл ауыр тас", "Бұл жұмсақ жастық". Бұл оның сөздік қорын сапалы түрде байытады.') WHERE id = 'c940fb90-c1d6-4fa5-8baf-334e41b324f8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Шығармашылық пен үйлесімді қимыл". Бала енді қағаз бетіне мақсатты түрде дөңгелектер немесе ретсіз болса да, анық әрі батыл сызықтар салады. Оған түрлі түсті қарындаштар мен үлкен қағаз беріп, еркін шығармашылықпен айналысуына жағдай жасаңыз. Бұл болашақта жазуға қажетті бұлшықет жадын қалыптастырады.') WHERE id = 'c40de8f9-d507-4cfb-810d-f904e8901ddd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше киінуге талпыныс". Бала енді шұлығын шешіп қана қоймай, басына бас киімін киюге немесе аяғына аяқкиімін сұғуға табандылықпен тырысады. Оған бұл әрекеттерді орындау үшін бірнеше минут қосымша уақыт беріңіз. Асықтырмай, бір нәрсені өз бетінше жасауына мүмкіндік беру оның өзіне деген сенімін және дербестік сезімін нығайтады.') WHERE id = 'c38e076c-fc5e-4ef7-ba82-49913f3b0c34';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Символдық қамқорлық". Бала ойыншық қонжығына "су ішкізіп", оны көрпемен жауып немесе жылаған кезде сипай алады. Бұл оның эмоциялық интеллектісі мен басқалардың сезімдерін түсіну қабілетінің дамып келе жатқанын көрсетеді. Оның осындай мейірімді әрекеттерін мақтауды ұмытпаңыз.') WHERE id = 'cbccdb44-553a-4ef8-8729-9f35675d89bf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Санаудың негіздері". Бала сандарды әлі ретімен санай алмаса да, "бір" мен "екінің" арасындағы сандық айырмашылықты көзбен түсіне бастайды. Оған екі алма беріп, "Біреуі сенікі, біреуі менікі" деп, бөлісу мен санауды қатар көрсетіңіз. Бұл — оның математикалық ойлауының ең алғашқы негізі.') WHERE id = '1953c2df-b74a-440f-aeda-02c40c3b1d9f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың күші: «Көрінбейтін достар мен заттар». Бала таяқты «ат» деп елестетіп, оған мініп шауып жүргендей ойнай алады. Бұл – символдық ойлаудың шыңы, яғни бір заттың басқа нәрсені бейнелейтінін түсіну. Бұл қабілет болашақта оқу мен математиканы меңгеру (таңбаларды түсіну) үшін өте маңызды.') WHERE id = '76d9591a-d7e3-4913-96a8-5d2c420ccc81';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '27-ші айдың соңғы он күндігін бастаймыз! Бала енді түстерді жай ғана танып қоймай, оларды сәйкестендіруді де шебер меңгеріп келеді. Сіз «Қызыл шұлығыңның сыңарын тап» дегенде, оны дұрыс орындаса, бұл оның көрнекі логикасының дамып жатқанын көрсетеді. Күнделікті киімдерін таңдағанда түстерді жиі атап отырыңыз.') WHERE id = '5063e9dc-6139-4c88-93fd-950678f58bde';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылында – «Баспалдақпен еркін жүру». Бала енді бір қолынан ұстап тұрғанда, баспалдақпен аяқтарын кезектестіріп басып көтерілуге талпынады. Бұл – ірі моториканың дамуындағы елеулі жетістік. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз, бірақ өз бетінше қадам басуы үшін оған сенім білдіріңіз.') WHERE id = 'd4f943d2-bf71-4b16-b7d0-f1be4b723a37';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде – «Мезгіл үстеулерінің алғашқы белгілері». Бала «қазір», «кейін», «сәлден соң» сияқты сөздердің айырмашылығын жақсырақ түсіне бастайды. Сіз «Алдымен тамақ ішеміз, содан кейін саябаққа барамыз» дегенде күте алса, бұл оның ерік-жігерінің нығайып келе жатқанын көрсетеді. Іс-әрекеттеріңіз арқылы уақыт ретін түсіндіруді жалғастырыңыз.') WHERE id = 'ad12a2ff-a0f6-446e-a287-18ac0e3ed236';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада – «Пазл құрастыру шеберлігі». Бала енді 6-9 бөліктен тұратын қарапайым пазлдарды өз бетінше құрастыра алады. Сурет бөліктерін көзбен сәйкестендіріп біріктіру оның зейінін шоғырландыру және мәселені шешу қабілеттерін дамытады. Қолынан келмей жатса, сабырлы үнмен бағыт-бағдар беріңіз.') WHERE id = 'ca532b10-de2c-4db5-9614-e001b1908ea1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше таңдау» шарықтау шегіне жетеді. Бала енді не киетіні немесе қандай ойыншықпен ойнайтыны туралы нақты пікірін білдіреді. Оған «Бүгін көк бас киіміңді киесің бе, әлде жасылын ба?» деген сияқты таңдау мүмкіндігін беру өзін жеке тұлға ретінде сезінуіне көмектеседі және қырсығу ұстамаларын барынша азайтады.') WHERE id = 'fb9fc561-26c7-41b4-bbe1-31eada18c85f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Кезек күту» дағдысы. Балаңыз саябақта әткеншекке міну үшін біраз күту керегін түсіне бастады. «Қазір оның кезегі, содан кейін сенікі» деген ойындар арқылы оны сабырмен күтуге үйретіңіз. Бұл дағды — әлеуметтік ортаға бейімделудің ең маңызды негіздерінің бірі.') WHERE id = '9df47b2e-3d86-40c8-a4bd-0d995655814b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Биіктік пен арақашықтық» түсінігі. Балаңыз баспалдақтан немесе диваннан түскенде арақашықтықты дәлірек есептей бастады. Оған үнемі абай болуды және қауіпсіз түсу тәсілдерін (артпен түсуді) еске салып отырыңыз. Бұл — дене қауіпсіздігі ережелерін меңгерудегі маңызды кезең.') WHERE id = '0f7477b8-a1ff-4761-b386-ffe1e44a9a7a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Доп тебу және нысанаға бағыттау». Балаңыз енді допты жай ғана теппей, оны белгілі бір бағытқа жіберуге тырысады. Бұл — көру зейіні мен қимыл үйлесімділігінің ұштасуы. Үйде немесе саябақта «шағын қақпа» жасап, балаңызбен допты қақпаға тебу ойынын ойнаңыз.') WHERE id = '050cfb5f-db53-4311-8b9f-fbb09f54e915';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме айтуға талпыныс». Балаңыз күні бойы көрген қызықты нәрсесін (мысалы, «Үлкен ит көрдім») Сізге айтып беруге асығады. Оның әңгімесін соңына дейін тыңдап, сұрақтар арқылы толықтырыңыз: «Иттің түсі қандай болды?». Бұл оның есте сақтау қабілетін де, ойын жеткізу дағдысын да нығайтады.') WHERE id = 'd7af8a5b-1016-4dc8-921f-52af71c3d954';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Балаңыз енді «Мен қаламаймын» деп, өз қалауын табанды түрде білдіруі мүмкін. Мұндай сәттерде қасарыспай, оған таңдау мүмкіндігін ұсынып, назарын басқаға аударыңыз. Сіздің сабырлылығыңыз бен тұрақты ережелеріңіз балада қауіпсіздік сезімін қалыптастырады. Сіз керемет жұмыс атқарып жүрсіз!') WHERE id = '80c062ac-b271-45ec-b67c-016fb884ca5b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '28-ші айға қадам басамыз! Балаңыз енді «екі кезеңді» тапсырмаларды оңай орындайды. Мысалы: «Ойыншығыңды ал да, сөреге қой». Бұл оның есте сақтау қабілеті мен тілді түсінуі жаңа деңгейге жеткенін көрсетеді. Күні бойы оған шағын әрі түсінікті «міндеттер» беріп, жауапкершілік сезімін қалыптастырыңыз.') WHERE id = 'a1060bb5-066a-438b-aafd-d9c5d706c7bc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыс үйлесімі: "Екі аяқпен алға секіру". Бала енді бір орында ғана емес, сәл алға қарай да секіре алады. Бұл аяқ бұлшықеттерінің күшін және дене қимылдарының үйлесімділігін қажет етеді. Онымен "Қояндар көгалда секіреді" ойынын ойнаңыз. Бұл әрі көңілді, әрі ірі моториканы дамытуға арналған тамаша жаттығу.') WHERE id = '3b71e4fe-1f75-478c-bb70-76e4d5347b3d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сұрақ-жауап диалогі". Бала енді Сізге: "Әке қайда?", "Бұл не?" деген қарапайым сұрақтар қоя алады. Жауап бергенде толық сөйлемдер құраңыз: "Әке жұмысқа кетті, кешке келеді". Сіздің егжей-тегжейлі түсіндірмелеріңіз оның санасында оқиғалар арасындағы логикалық байланысты нығайтады.') WHERE id = '12f65b1a-8cde-4d4d-842d-5197bc6d6352';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың күші: "Рөлдердің ауысуы". Бала Сізге еліктеп, "ана" рөлін ойнауы немесе ойыншықтарын "жұмысқа апаруы" мүмкін. Бұл оның есте сақтау қабілетін де, оқиғалар арасындағы логикалық байланысты қаншалықты терең байқап жүргенін де көрсетеді. Сіз керемет анасыз!') WHERE id = '1d0c6c5d-a275-43bf-bb3b-a961c2f6805e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді танып қана қоймай, кемінде 3-4 негізгі түсті (қызыл, көк, жасыл, сары) атай бастайды. Одан "Бұл қандай түс?" деп сұрасаңыз, дұрыс жауап беру ықтималдығы жоғары. Серуен кезінде көліктердің немесе гүлдердің түсін сұрап, бұл білімін бекітіңіз.') WHERE id = '44e5c106-bbab-44d6-a4ac-bc4a1418e1eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Бір аяқпен тепе-теңдік сақтау". Бала енді бірнеше секунд болса да, бір аяғын жерден көтеріп, тепе-теңдігін сақтауға тырысады. Бұл — дененің ауырлық орталығын басқаруды қажет ететін күрделі үйлесімді қимыл. Онымен "Ләйлек" ойынын ойнаңыз. Бұл әрі көңілді, әрі дене дамуына өте пайдалы.') WHERE id = 'fbfbb0b9-9b09-4a23-9066-c80337eab4d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Уақыт ұғымының алғашқы белгілері". Бала "кеше", "ертең" сөздерін әлі толық түсінбесе де, "қазір", "кейін", "сәлден соң" сияқты сөздердің айырмашылығын ұғынады. Оған "Алдымен қолымызды жуайық, содан кейін тамақтанайық" дегенде күте алса, бұл оның ерік-жігерінің нығайып келе жатқанын білдіреді. Уақыт ретін іс-әрекеттеріңіз арқылы түсіндіруді жалғастырыңыз.') WHERE id = 'a4ffacc2-0d5e-4231-a5d0-f90a33b4d6f5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыс дағдыларындағы "Баспалдақтан түсу шеберлігі". Бөпе қолынан ұстаған кезде баспалдақтан сенімдірек түсіп, әр басқышқа бір аяғын қоюға тырысады. Төмен түсу жоғары көтерілуден қиынырақ, өйткені ол тепе-теңдікті көбірек сақтауды талап етеді. Әрдайым жанында болып, қауіпсіздігін қамтамасыз етіңіз және әр жетістігін қошеметтеңіз.') WHERE id = '05b34d22-95f5-4000-aee3-08f747372e4d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сын есімдер мен үстеулерді бірге қолдану". Бөпе енді жай ғана "көлік" демей, "жылдам қызыл көлік" деп айта алады. Ол айналасындағы әлемді сипаттау үшін көбірек егжей-тегжей қолданады. Онымен сөйлескенде заттардың қасиеттерін атап көрсетіңіз: "Бұл ауыр тас", "Бұл жұмсақ жастық". Бұл оның сөздік қорын сапалы түрде байытады.') WHERE id = '5838f818-d4e0-42c7-ba01-7e6420078ed2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Құрастыру және құрылыс". Бөпе енді тек текшелерден мұнара тұрғызып қана қоймай, "қоршау", "пойыз" немесе "үй" сияқты белгілі бір мақсатқа сай пішіндер құрастырады. Бұл — оның көрнекі-кеңістіктік ойлауы мен қиялының үйлесуі. Оның құрастырғандары туралы сұрақтар қойыңыз: "Мұнда кім тұрады?".') WHERE id = '46a64e62-d979-410f-9a15-a2c7bbeb1ba9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше таңдау" және ерік-жігер. Бөпенің енді не киетіні немесе қай ыдыстан тамақ жейтіні туралы нақты қалауы бар. Оған "Бүгін көк жейде киесіз бе, әлде жасылын ба?" деген сияқты таңдау мүмкіндігін беру өзін жеке тұлға ретінде сезінуіне көмектеседі және қырсығу ұстамаларын барынша азайтады.') WHERE id = 'f2f6cbfc-bdac-4534-9233-ecd8a693e212';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Символдық қамқорлық". Бөпе ойыншық қонжығына "су ішкізіп", оны көрпемен жауып немесе "емдей" алады. Бұл — оның эмоциялық интеллекті мен басқалардың сезімдерін түсіну қабілетінің дамуы. Оның осындай мейірімді әрекеттерін міндетті түрде мақтаңыз.') WHERE id = '8ddc104a-ab8a-4e5a-943d-543dc807df66';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Өзгеше затты тап". Бөпе енді бір топ заттың ішінен өзгеше затты (мысалы, көліктердің арасындағы алманы) көзбен ажырата алады. Бұл оның талдау қабілетін жетілдіреді. Үйде онымен қарапайым "Қайсысы артық?" ойындарын ойнаңыз. Бұл болашақтағы логикалық тапсырмаларға тамаша дайындық болады.') WHERE id = 'a2b9980c-2bf2-401b-8655-ae5a31b2d842';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Бала енді «Мен қаламаймын» деп өз еркін ашық әрі табанды білдіруі мүмкін. Мұндай сәттерде қырсықтаспай, оған таңдау мүмкіндігін ұсынып, назарын басқаға аударыңыз. Сіздің сабырлылығыңыз бен тұрақты ережелеріңіз балаға қауіпсіздік сезімін береді. 840 күнді сәтті аяқтадық – Сіз барлық жақсылыққа лайықсыз!') WHERE id = 'f92d1e9f-889d-441d-90aa-ab2a51e762a4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '28-айдың соңғы онкүндігін бастаймыз! Бала енді екі кезеңнен тұратын тапсырмаларды оңай орындайды. Мысалы: «Ойыншықты ал да, сөреге қой». Бұл оның жұмыс жады мен тілді түсіну қабілетінің жаңа деңгейге жеткенін көрсетеді. Күні бойы оған осындай шағын «міндеттер» беру арқылы жауапкершілік сезімі мен зейінін жаттықтырыңыз.') WHERE id = '1fed649f-83be-432e-bf3b-958f939d1d57';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Баспалдақпен көтерілу шеберлігі». Бала енді бір қолынан ұстасаңыз, баспалдақпен әр басқышқа бір аяғын қойып көтерілуге талпынуы мүмкін. Бұл сан және жамбас бұлшықеттерінің нығайғанын білдіреді. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз және жетістіктеріне қол соғыңыз.') WHERE id = '2104ca19-971d-4ad2-bad2-4fb0d5fce478';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Себеп-салдар» тіркестері. Бала енді «Өйткені» деп (немесе соған ұқсас дыбыс шығарып), неліктен бір нәрсені қалайтынын түсіндіруге талпынуы мүмкін. Сіз де оған себептерін түсіндіріңіз: «Қазір балмұздақ жемейміз, өйткені күн суық». Бұл оның логикалық ойлауы мен өз ойын дәлелдеу қабілетінің негізін қалайды.') WHERE id = '9a1ea5be-b73b-4171-a8a3-6f9f06ff6d11';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Бұрау және айналдыру». Бала енді бөтелке қақпақтарын, ойыншық бұрандаларын сенімді түрде бұрап ашып-жаба алады. Бұл қимыл білек бұлшықеттерін айналмалы қозғалысқа жаттықтырудың тамаша тәсілі. Оған әртүрлі көлемдегі қауіпсіз ыдыстар беріп, механикалық әрекеттерге деген қызығушылығын қолдаңыз.') WHERE id = '326af733-89d5-4b18-a86d-69d50b560d32';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім жуынамын». Шомылған кезде бала сабынды немесе ысқышты алып, денесін ысқылап, Сізге еліктеуге тырысады. Оның гигиеналық дағдыларға деген қызығушылығын баспаңыз. Өз денесін «тазалауы» дене мүшелерін жақсырақ танып-білуіне әрі жеке гигиенаға жауапкершілікті ерте жастан меңгеруіне көмектеседі.') WHERE id = '059ef4bc-ae23-4023-aa71-ac7bfd7a180d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Шеңбер мен сызықты меңгеру". Бала қағаз бетіне бұрынғыдан мақсаттырақ шеңберлер немесе ретсіз болса да, нық түзу сызықтар сала бастайды. Оған түрлі түсті қарындаштар мен үлкен қағаз парақтарын беріп, "алғашқы суреттерін" салуына мүмкіндік жасаңыз. Бұл — болашақта жазу дағдысын қалыптастыратын ең маңызды жаттығулардың бірі.') WHERE id = 'efd8c509-5660-43d7-a555-e496a390e478';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзім киінемін" деген қырсықтық. Бала енді шұлығын шешіп қана қоймай, басына бас киімін киюге немесе оңай киілетін аяқкиімін аяғына сұғуға табандылық танытады. Бұл әрекеттерге оған бірнеше минут артық уақыт беріңіз. Асықтырмай, өздігінен бір нәрсе істей алуына мүмкіндік жасау оның өзіне деген сенімін және дербестік сезімін қалыптастырады.') WHERE id = 'ea6058fd-22cb-454f-b6df-36b6c6f564fd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Әзіл мен қалжың". Бала әдейі бір нәрсені "дұрыс емес" жасап (мысалы, бас киімін қолына киіп), Сізге қарап күлуі мүмкін. Бұл оның әзілді түсіне бастағанын және әлеуметтік ықпал ету дағдысының қалыптасып келе жатқанын көрсетеді. Оның бұл "ойынына" бар ынтаңызбен қосылыңыз. Бірге күлу араларыңыздағы эмоциялық байланысты одан әрі нығайтады.') WHERE id = '90539d1c-30bc-43ec-8cb5-e89edef1568e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Биіктік пен қашықтық". Бала енді баспалдақтан немесе диваннан түскенде қашықтықты жақсырақ бағалай алады. Оған әрдайым абай болуды және қауіпсіз түсу тәсілдерін (артқа қарай) еске салып отырыңыз. Бұл — оның дене қауіпсіздігі ережелерін меңгеруі және қауіп-қатерді көзбен бағалауы үшін маңызды кезең.') WHERE id = '00eb14eb-16c9-4d20-9af4-97c177dc49f5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: "Артқа қарай жүру". Бала енді артына қарамай, артқа қарай бірнеше қадам жасай алады. Бұл оның өз денесінің кеңістіктегі орнын сезінуі (проприоцептивтік сезім) үшін маңызды. Оған "Шаян сияқты жүрейік" деп, бұл қимылды ойынға айналдырыңыз. Бұл аяқ бұлшықеттерін өзгеше жұмыс істетеді.') WHERE id = '2b4f1496-5d34-4f25-9ad5-91b67ba2967b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Есім мен есімдіктің байланысы". Бала енді өзін атымен атаудан "Мен" деуге толықтай ауысады. Сіз одан бір нәрсе сұрағанда, "Мен" немесе "Менікі" десе, бұл оның өзін жеке тұлға ретінде сезінуі толық қалыптасқанын көрсетеді. Онымен осы тақырыпта диалог құрыңыз: "Бұл кімнің добы? Менікі!". Сіз керемет жол көрсетушісіз!') WHERE id = '61b67af6-b8e7-43c0-aeec-e2ba32964d5a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Бөлісудің қиындығы». Бұл жаста «Менікі!» деп айқайлау — қалыпты жағдай. Бала өзіне тиесілі заттарды қорғауды үйреніп жүр. Оны бөлісуге мәжбүрлемеңіз, оның орнына «Кезекпен ойнайық» қағидасын қолданыңыз. Сіздің сабырлылығыңыз оның әлеуметтік зердесінің қалыптасуына көмектеседі.') WHERE id = '89f6ed5e-1781-4f77-8a89-eea339ecb1d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Сәйкестендіру» (Matching). Бала енді бір жануардың әртүрлі суреттерін немесе түсі бірдей заттарды өзара сәйкестендіре алады. Онымен қарапайым карточкаларды пайдаланып, «Дәл сондайын тап» ойынын ойнаңыз. Бұл оның көру зейінін де, санаттар бойынша ойлау қабілетін де жылдам дамытады.') WHERE id = '1b1a5af3-541e-4a8b-826b-94504ae0251e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты алысқа лақтыру». Бала енді допты жай ғана жерге тастамай, оны иық үстінен (overhand) алға қарай лақтыруға тырысады. Бұл қимыл бүкіл дененің үйлесімді жұмысын талап етеді. Онымен саябақта «Кім допты алысырақ лақтырады?» ойынын ойнаңыз. Бұл оның қолдарын нығайтып қана қоймай, қашықтықты сезіну қабілетін де жетілдіреді.') WHERE id = '985bce91-74bc-40ac-bdc4-be9aa7dbfeab';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өтініш білдіру». Бала енді бірдеңе қалағанда саусағымен жай ғана көрсетпей, «Бер» немесе «Өтінемін» деп айта алады не соған ұқсас сөз қолданады. Оған әрдайым сыпайы сөйлеудің үлгісін көрсетіңіз. Сізден «Рақмет» немесе «Өтінемін» деген сөздерді естуі оның болашақ қарым-қатынас мәдениетінің негізін қалайды.') WHERE id = 'edefb696-9b37-48b2-bf5d-42c196545bf4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың дамуы: «Рөлдік ойындар күрделене түседі». Бала енді жай ғана тамақ пісірмейді, ойыншықтарын қонаққа шақырады, оларды «емдейді» немесе «көлікке отырғызып, жұмысқа апарады». Бұл оның жадында сақталған оқиғаларды қалай байланыстыратынын көрсетеді. Оның рөлдік ойындарына қосылыңыз — бұл оның шығармашылығын жаңа деңгейге көтереді.') WHERE id = '22acecd0-67df-4601-b0d7-23a57c3444c3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '29-шы айға қош келдіңіз! Бала енді «иә» және «жоқ» дегеннен гөрі күрделірек жауаптар бере бастайды. «Мұны неге қалайсың?» деген сұраққа «Өйткені дәмді» немесе «Өйткені қызыл» деп жауап беруі мүмкін. Бұл — оның ішкі уәжін сөзбен жеткізу қабілетінің бастамасы. Оның әрбір «өйткені» деген жауабын мұқият тыңдаңыз.') WHERE id = '0e94d08f-2dfb-49bd-b8dc-5b547bbc54de';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Бір орында секіру және айналу». Бала енді тек жоғары секіріп қана қоймай, секірген кезде денесін ауада бұруға тырысады. Бұл күрделі вестибулярлық үйлесімділікті қажет етеді. Онымен жұмсақ кілемнің үстінде «акробатика» ойындарын ойнаңыз.') WHERE id = '9536e69d-203e-4017-ae80-dbe2f9eab99b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өзін сипаттау». Бала енді Сізге «Мен үлкенмін», «Мен жүгіріп жүрмін» деп, өзінің жай-күйі туралы айта алады. Онымен бірге айна алдына тұрып, «Көзіңнің түсі қандай?», «Мұрның қайда?» деген сұрақтар қою арқылы өзін-өзі тану үдерісін қызықты етіңіз.') WHERE id = 'eca2c14e-98c5-475b-94e6-e55601d2febb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық даму: «Дербестік дағдарыстары». Бала бәрін өзі жасағысы келіп, қолынан келмегенде қатты ашулануы мүмкін. Мұндай сәттерде сабыр сақтап, оған: «Қазір ашуланып тұрсың, өйткені бұл қиын. Кел, бірге жасайық», — деп қолдау көрсетіңіз. Сіздің сабырлылығыңыз — оның эмоциялық дауылын басатын ең сенімді айлақ.') WHERE id = '9fa6b04b-2e13-4b5c-ba62-6d1e0398948e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстерді «қызыл» немесе «көк» деп қана ажыратпай, олардың бір-біріне жақын реңктерін де көзбен айыра алады. Оған жасыл түстің әртүрлі реңкіндегі жапырақтарды көрсетіп: «Қайсысы қоюырақ?» — деп сұраңыз. Бұл оның көріп талдау қабілетін жетілдіреді.') WHERE id = '1d89cf33-54f4-473a-9dbf-869b4e96ac30';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігіндегі «Бір аяқпен секіруге талпыныс». Бала енді бір аяғымен аздап секіруге тырысады. Бұл — тобықтың күшін және тепе-теңдікті қажет ететін өте күрделі қимыл. Оның осындай батыл талпыныстарын қошеметтеңіз, құлап қалса да, жігерін жоғалтпауына қолдау көрсетіңіз.') WHERE id = 'c09edac9-8b37-4347-a8dd-3e14699e7139';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өткен шақтың алғашқы белгілері». Бала енді болып өткен оқиғаларды айту үшін «бардым», «көрдім», «жедім» сияқты етістіктерді қолданады. Кешке онымен «Бүгін не істедік?» деп әңгімелесіңіз. Бұл оның есте сақтау қабілетін де, уақыт туралы түсінігін де нығайтады.') WHERE id = '5e30771f-35e9-43cb-9e6c-1bfc3d0ea335';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Мақсатты бояу». Бала енді қағаздағы үлкен пішіннің (мысалы, шеңбердің) ішін бояп, шекарасынан көп шықпауға тырысады. Бұл — қол бұлшықеттерін басқарудағы үлкен ілгерілеу. Оған жиектері қарапайым әрі анық сызылған бояу парақтарын ұсыныңыз.') WHERE id = '30b62203-ae1a-48ab-82d9-d252856f8bcb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен көмекшімін». Бала енді үйдегі шағын тазалық жұмыстарын (шаң сүрту, ойыншықтарын қорапқа жинау) ойын ретінде емес, міндет ретінде қабылдай бастайды. Оған өзінің кішкентай тазалық шүберегін беріңіз. Бұл оның отбасындағы жауапкершілік пен тиесілік сезімін айтарлықтай нығайтады.') WHERE id = '75e40c4f-895e-4725-bab2-0bb5ec9f1edc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Достықтың алғашқы белгілері». Бала енді саябақта таныс баланы көргенде қуанып, оған өз ойыншығын ұсынады. Бұл — жай ғана қатар ойнаудан бірге ойнауға (интерактивті ойынға) өту кезеңі. Оның осындай әлеуметтік қадамдарын жылы әрі жағымды сөздермен қолдаңыз.') WHERE id = '73a7095e-32dd-413f-b911-0ace0be7e88d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Биіктік пен көлем». Бала енді қай стақанға көбірек су сыятынын немесе қай мұнараның биігірек екенін көзбен салыстыра алады. Шомылу кезінде әртүрлі көлемдегі ыдыстармен су ойынын ойнаңыз. «Қай ыдыс тезірек толады?» деген сұрақ оның физикалық әлем туралы түсінігін кеңейтеді.') WHERE id = '3cf32da0-166e-4863-bf9c-f4ea80d66e98';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Жүгіріп келе жатып допты басқару». Бала енді жүгіріп жүріп, допты аяғымен алға қарай алып жүруге (дриблинг жасауға) тырысады. Бұл қимыл жылдамдығы мен аяқ дәлдігін үйлестіруді қажет етеді. Онымен таза ауада қимылды футбол ойындарын ойнап, энергиясын пайдалы арнаға бағыттаңыз.') WHERE id = 'c300bf1e-a81a-4d08-9bfb-583735c02aab';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі сұрақтар». Бала енді тек «Бұл не?» деп қана қоймай, «Құс қайда ұшып кетті?» немесе «Күн қайда кетті?» сияқты көзге көрінбейтін құбылыстар туралы сұрақтар қояды. Жауап бергенде қиялды да қосыңыз: «Күн ұйықтауға кетті». Бұл — оның қиялы мен оқиғаларды түсіну тереңдігінің көрсеткіші.') WHERE id = '5d13e772-b0dc-414e-be1a-eb306de1058d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігіндегі «Динамикалық тепе-теңдік». Бөпе енді жерге сызылған сызықтың немесе төселген арқанның үстімен «арқанның үстінде жүргендей» жүруге қызығушылық танытады. Бұл оның өз денесін сезінуін (проприоцепциясын) дамытады. Үйде түрлі түсті таспалардан жол жасап, осы дағдысын қолдаңыз.') WHERE id = '82c3b72a-274b-4062-9adf-7e5cce134bd3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Көптік жалғаулары». Бөпе енді «алма» мен «алмалар» сөздерінің айырмашылығын түсініп қана қоймай, оны сөйлеуінде қолдануға тырысады. Оған ойыншықтарын көрсетіп: «Қарашы, мұнда мәшинелер көп», — деп, көптік ұғымын бекітіңіз. Бұл оның грамматикалық құрылымдарды меңгеруінің күрделене түскенін көрсетеді.') WHERE id = '64529c1d-caa7-4ac1-a772-2e82ed067453';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Саусақ күші». Бөпе енді киім қыстырғыштарын қысып ашып-жаба алады немесе ермексазбен ойнағанда одан ұсақ бөліктерді үзіп ала алады. Бұл қимылдар саусақтардың ұсақ бұлшықеттерін нығайтып, болашақта қарындашты дұрыс ұстауға дайындайды.') WHERE id = 'e1008078-204c-4a5c-bac1-d07adf97ca32';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Символдық бөлісу». Бөпе енді басқа баланың қолындағы ойыншықты бірден тартып алмай, «бер» деп айтып, күтуге тырысады. Бұл — өзін-өзі реттеу (self-regulation) дағдысының алғашқы белгілері. Оның осындай сабырлы әрекетін көргенде: «Кезегіңді күткеніңе көп рақмет», — деп міндетті түрде мақтаңыз.') WHERE id = '7f709f10-5a18-4150-b7b4-fa822721b9c8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Мен өзім дайындаймын». Бөпе асүйде Сізге көмектескенді қатты ұнатады: қамырды илеу, көкөністерді (қауіпсіз пышақпен) кесу немесе дастарқанға қасық қою. Бұл оның қимыл-қозғалыс дағдыларын дамытып қана қоймай, тағамдарға деген қызығушылығын да арттырады.') WHERE id = '53d5b167-fe89-4403-8e4d-0684f94ae9c5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Реттілік пен есте сақтау». Бөпе енді сүйікті ертегісіндегі немесе мультфильміндегі оқиғалардың ретін біледі. Сіз оқиғаны қате айтып қалсаңыз, ол: «Жоқ, аю келді!» — деп түзетуі мүмкін. Бұл оның ұзақ мерзімді жады мен оқиға желісін түсіну қабілетінің жақсы дамығанын көрсетеді.') WHERE id = '51d45576-0732-4e17-9d1f-994a457d540c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Ережелерді түсіну». Бөпе үйдегі немесе саябақтағы белгілі бір ережелерді («тамақ ішер алдында қол жуу», «сырғанақта кезегін күту») түсінеді. Кейде бұл ережелерді бұзғысы келсе де, Сіздің бірізділігіңіз оған әлеуметтік нормаларды ішкі тәртіпке айналдыруды үйретеді.') WHERE id = '4a18c5ac-a958-4970-b854-89448eb42394';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Реттеу және салыстыру». Бөпе 3-4 затты көлеміне қарай ретімен орналастыра алады. Оған өлшемдері әртүрлі текшелерді беріп, «Ең кішісін ең үстіне қой» деңіз. Бұл көру арқылы талдау қабілетін де, бастапқы математикалық ойлау жүйесін де дамытады. Әр дұрыс қадамынан кейін «Қандай зейіндісің!» деп ынталандырыңыз.') WHERE id = '4204844b-c0b2-424d-bc6a-7ddffcbc310c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Допты алыстағы нысанаға лақтыру». Бөпе енді допты жай ғана лақтырмай, оны белгілі бір нүктеге (мысалы, себетке немесе Сізге қарай) дәлірек бағыттайды. Бұл — қол-көз үйлесімділігі мен қашықтықты қабылдау қабілетінің үйлесуі.') WHERE id = '2d64c34e-bf0d-4efe-9c0e-d67a9a461b59';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап тізбегі». Бөпе енді Сіздің сұрақтарыңызға «иә/жоқ» деп қана емес, толық сөйлемдермен жауап береді. «Бүгін не көрдің?» деген сұраққа «Үлкен ағаш көрдім» деп жауап беруі мүмкін. Онымен сөйлескенде «Оның түсі қандай болды?», «Ол қайда болды?» сияқты нақтылаушы сұрақтар қойып, сөйлеу қабілетін ынталандырыңыз.') WHERE id = 'e8d19883-dd1e-49e0-bcde-510b73e5bdc1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '880 күнді аяқтадық! Бөпе 2 жас жарымға (30 айға) жақындап қалды. Қазір ол физикалық тұрғыдан да, эмоциялық тұрғыдан да әлдеқайда мықты. Өз сезімдерін атай алады («мен көңілдімін», «мен ашуландым»). Бүгін онымен бірге өткізген әрбір сәтіңіз оның жадында өшпес жағымды із қалдырады. Сіз керемет анасыз!') WHERE id = '6218d94c-c601-40e6-8296-e74639caa069';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '30-шы айға, яғни бөпеңіздің 2 жас жарым кезеңіне қош келдіңіз! Бұл кезеңде бөпе өзін жеке тұлға ретінде толық таныта бастайды. Ол «Бұл менікі» немесе «Өзім істеймін» деп, өз шекарасын белгілейді. Оның дербестікке деген талпынысын сабырмен қабылдаңыз; бұл оның мінезінің қалыптасуы үшін өте маңызды.') WHERE id = '8c2026bd-7655-4fc6-8c90-c09af022e3d7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: Бала енді "Жоқ" деген жауапты естігенде бұрынғыдай бірден жыламай, оның себебін түсінуге тырысады. Оған ережелерді сабырлы үнмен түсіндіріңіз: "Қазір кәмпит жемейміз, өйткені кешкі ас ішетін уақыт болды". Сіздің бірізді әрі қисынды әрекетіңіз баланың өзін-өзі басқару және шыдамдылық дағдыларын қалыптастырады.') WHERE id = 'd426c7f4-84e8-442d-bd5f-c6c23fc0839f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '29-айдың соңғы онкүндігін бастаймыз! Бала енді "мен" және "сен" есімдіктерін қателеспей дерлік қолданады. Сөйлесу кезінде ол өз қалауын "Мен мұны қалаймын" деп нық білдіреді. Оның өзіндік санасын қолдап, шешімдерін құрметтейтініңізді көрсетіңіз; бұл оның өзіне деген сенімділігінің берік негізін қалайды.') WHERE id = '4a584dfd-3b1f-4ba7-b2c3-765c25e1ca50';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы "Секіру және жерге түсу". Бала енді аласа басқыштан (мысалы, тротуар жиегінен) екі аяғымен бір уақытта жерге секіруге батылы жетеді. Бұл аяқ бұлшықеттерінің күші мен кеңістікте тепе-теңдікті сақтау қабілеті үшін үлкен жетістік. Әрдайым жанында болып, қауіпсіздігін қадағалаңыз.') WHERE id = '55d65f2d-a7aa-455b-9e97-2b3375627fc7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде "Жалғаулықтарды қолдану". Бала енді "және", "бірақ", "өйткені" сияқты сөздер арқылы екі ойды байланыстырады: "Мен жүгірдім де, құлап қалдым". Бұл оның ойларының жүйелі әрі өзара байланысты бола бастағанын көрсетеді. Онымен сөйлескенде, Сіз де осы жалғаулықтарды қолданып, сөйлемдеріңізді біршама күрделендіріңіз.') WHERE id = 'a1740f48-0bf0-4597-985c-859e4a235e6b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Түйіндеуге және байлауға қызығушылық". Бала енді аяқкиім бауын тартуға, түймелерді ағытуға немесе ірі моншақтарды жіпке тізуге тырысады. Бұл әрекеттер саусақтардың үйлесімді қимылын жетілдіре түседі. Оған құрылымы әртүрлі жіптер мен тесігі бар ойыншықтар беріп, осы қызығушылығын қолдаңыз.') WHERE id = '17adcdf9-4e22-4431-92cb-4bcd0b67e350';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше киіну" шеберлігі. Бала енді шалбарын жоғары тартуды немесе қарапайым жейдесін (басынан өткізгеннен кейін) киюді жақсы меңгерген. Оны "Ал, енді шұлығыңды өзің киіп көрші" деп ынталандырыңыз. Өз бетінше жасалған осындай шағын қадамдар оның күнделікті өмірде өзін қабілетті тұлға ретінде сезінуіне көмектеседі.') WHERE id = '306f738c-086a-4ef8-9272-59796c9176d7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Физикалық дамудағы «Динамикалық тепе-теңдік». Бала енді бір аяғымен бірнеше секунд (3-5 секунд) өздігінен тұра алады. Бұл оның мишығының дамуы мен бұлшықет үйлесімділігінің көрсеткіші. Онымен «Ләйлек» ойынын ойнап, кімнің ұзағырақ тұра алатынын байқап көріңіз.') WHERE id = '59136234-e72e-461f-a081-2d86fdd6b1f1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі ұғымдар». Бала енді «махаббат», «бақыт» немесе «қорқыныш» сияқты сезімдерді атай бастайды. Оның «Мен Сізді жақсы көремін» деуі немесе «Мен қорқып кеттім» деп құшағыңызға келуі эмоциялық интеллектісінің (EQ) қарқынды дамып жатқанын көрсетеді. Оның сезімдерін әрдайым мойындап, қабылдаңыз.') WHERE id = '2c9c993e-8ed6-4bde-970b-e837e161f321';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Тік және көлденең сызықтар». Бала енді қарындашты сенімдірек ұстап, қағазға бір-бірімен қабаттасқан ретсіз сызықтардың орнына мақсатты түрде түзу сызықтар салады. Оған түрлі түсті бояулар беріп, «жолдар» немесе «баспалдақтар» салуды ұсыныңыз.') WHERE id = '2e6c20d2-ff7f-4e05-b377-0a03f81606ea';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Гигиенаны өз бетінше сақтау». Бала енді тісін тазалауға (Сіздің бақылауыңызбен), қолын сабындап, мұқият шаюға талпынады. Осы әдеттерді бұл жаста ойын түрінде бекіту оның болашақта жеке бас тазалығына жауапкершілікпен қарауына көмектеседі.') WHERE id = '9f592616-f0c7-4018-8751-de7b0540a2d9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Рөлдік ойындар». Бала енді «сценарий» құрады: ойыншықтарын қонаққа шақырады, оларға «шай береді» немесе «ұйықтатады». Осындай ойындар арқылы ол ересектер әлеміне еліктеп, әлеуметтік рөлдер мен ережелерді терең меңгереді.') WHERE id = 'b497facf-4e33-44ce-bb8d-95b34db2194a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Әртүрлі пішіндерді тану». Бала енді дөңгелек, шаршы және үшбұрыштың айырмашылығын біледі әрі оларды тиісті ойықтарға орналастырады. «Маған шаршыны берші» дегеніңізде қателеспесе, бұл оның көру-кеңістіктік ойлауының жақсы дамығанын көрсетеді.') WHERE id = 'e423f075-63ff-4c05-92b5-4ab5ac29b6be';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Артқа қарай жүру». Бала енді артына қарамай-ақ бірнеше қадам артқа жүре алады. Бұл қимыл оның өз денесінің кеңістіктегі орнын сезінуі (проприоцепция) үшін маңызды. Оған «Шаян сияқты жүрейік» деп, бұл қимылды ойынға айналдырыңыз; осылайша аяқ бұлшықеттері басқаша жұмыс істейді.') WHERE id = '4e7bdd0e-7517-4dbe-a3fb-4614d6b6754f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Көп сөзді сөйлемдер». Бала енді 4-5 сөзден тұратын күрделі сөйлемдер құрайды: «Анашым, мен саябаққа барып, ойнағым келеді». Оның сөйлемдерінде жалғаулықтар мен шақ жұрнақтары жиірек қолданыла бастайды. Онымен сөйлескенде, көбірек сөйлеуге ынталандыру үшін ашық сұрақтар қойыңыз.') WHERE id = 'd51c61a3-3310-47cc-be33-4e2fc01a2f12';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық шекаралар: Бала енді кейбір әрекеттерінің Сізге қалай әсер ететінін түсіне бастайды. Ол жүзіңізден мұңды немесе қуанышты байқайды. Оған «Сен басқалармен бөліскенде, мен қатты қуанамын» деп, эмоциялық себеп-салдар байланысын түсіндіріңіз. Бұл оның қамқор әрі сезімтал тұлға болып өсуіне көмектеседі.') WHERE id = '00079201-58ca-47e2-bd9f-428f9b22aea3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '900 күндік үлкен белеске небәрі 10 күн қалды! Бала енді тек «мен» деп ойлаудан біртіндеп арылып, басқалардың да қажеттіліктерін түсіне бастайды. Мысалы, ол Сізден «Су ішкің келе ме?» деп сұрауы мүмкін. Оның осындай қамқорлық танытқан әрекеттерін міндетті түрде мақтаңыз; бұл оның әлеуметтік зердесінің (EQ) жетіліп келе жатқанын көрсетеді.') WHERE id = '54cacacb-5f6d-4f6a-b6ea-082797db1faf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Аяқты кезектестіріп баспалдақтан түсу». Бала енді баспалдақтан аяғын кезектестіріп (әр басқышта аяғын ауыстырып) түсуге талпынады. Бұл қимыл жоғары көтерілуден қиынырақ әрі жақсы тепе-теңдікті қажет етеді. Сабырмен күтіп, оған сенетініңізді сездіріңіз.') WHERE id = 'ce4fa5fc-7dc5-4de0-b4e5-b9c6bb215fb4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Күрделі сұрақтар кезеңі». Бала енді «Бұл не?» деп қана қоймай, «Неліктен бұлай?», «Біз қайда барамыз?» деген сияқты сұрақтар қояды. Жауаптарыңыз шынайы әрі қарапайым болсын. Сіздің түсіндірмелеріңіз оның санасында әлемнің логикалық картасын қалыптастырады. Оның қызығушылығын үнемі қолдап отырыңыз: «Сеніңше, неліктен бұлай?».') WHERE id = 'b47ac63c-a31b-4cfe-b3d9-64f08edba2f8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дөңгелек пен айқыш салу». Бала енді қарындашты «ересектер сияқты» (үш саусағымен) ұстауға және қағазға дөңгелек, айқыш тәрізді пішіндерді қайталап салуға тырысады. Бұл — болашақта жазуды үйренуге қажетті ең маңызды қимыл дағдыларының бірі. Оған түрлі түсті борлар беріңіз.') WHERE id = '4c756f1e-f764-4f55-8535-6552dafc167f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тамақтану және таңдау». Бала енді дастарқан басында қанша жейтінін өзі шешкісі келеді. Оны тамақ жеуге мәжбүрлемеңіз. Өзіне-өзі қызмет көрсету дағдысы дамыған сайын, оған өз тәрелкесін (қауіпсіз болса) асүйге апаруды ұсыныңыз. Бұл оның отбасындағы жауапкершілік сезімін қалыптастырады.') WHERE id = '04c3f7db-69bb-44ed-8348-5d4d92cb8c92';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қиялдағы ойын серіктері». Бала енді ойыншықтарымен сөйлеседі, оларға тапсырма береді және тірі жандай қарым-қатынас жасайды. Бұл оның қиялының және оқиғалар арасындағы абстрактілі байланыстарды құру қабілетінің қаншалықты жақсы дамығанын көрсетеді.') WHERE id = '2c67e108-3cf8-4072-89be-1ff519eaddcc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Түс реңктерін ажырату». Бала енді жай ғана «жасыл» түсті емес, оның ашық және қою реңктерін де көзбен ажырата алады. Оған түрлі түсті реңктегі жапырақтарды немесе қарындаштарды көрсетіп, «Қайсысы қоюырақ?» ойынын ойнаңыз. Бұл оның көріп талдау қабілетін жетілдіреді.') WHERE id = 'dcddf5f8-faa5-4048-a797-208e9715f0bf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Үш дөңгелекті велосипедке қызығушылық». Бала енді педальдарды айналдыруға немесе аяғымен жерден итеріліп, алға жылжуға тырысады. Бұл қимыл аяқ бұлшықеттерін нығайтып қана қоймай, кеңістікте қозғалыс бағытын басқару қабілетін де дамытады.') WHERE id = 'a4633b77-b5aa-45ed-9da1-475ae9482abc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Өткен және келер шақ». Бала енді «Ертең барамыз» немесе «Кеше бардық» деген сияқты уақыт айырмашылықтарын (әлі толық дәл болмаса да) сөйлеу барысында қолдануға тырысады. Күннің соңында онымен «Бүгін не істедік?» және «Ертең не істейміз?» деген тақырыптарда сөйлесіңіз. Бұл оның есте сақтау және жоспарлау қабілеттерін нығайтады.') WHERE id = '3e7a62e8-608e-4fd7-88f9-177ba74dcb48';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Ынтымақтастық пен бөлісу". Бала ойыншығын бөліскенде, бұл уақытша екенін енді түсінеді. "Біраз сен ойна, содан кейін мен ойнаймын" қағидасымен танысатын кез келді. Бұл оның шыдамдылығын да, әлеуметтік эмпатиясын да қалыптастырады.') WHERE id = '79abc2a4-51b0-4f9f-8334-d1eb1d4ea6eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Көлемді қабылдау". Бала үлкен қораптың ішіне кішкентай қорап сыятынын, ал керісінше болуы мүмкін емес екенін көзбен көріп түсінеді. Оған көлемі әртүрлі ыдыстар беріп, "Мұның ішіне қайсысы сыяды?" деп сұраңыз. Бұл — болашақ математикалық және геометриялық ойлаудың негізі саналатын кеңістікті қабылдау қабілеті.') WHERE id = '615744e3-fb18-42f6-8110-3e9a2d54709c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты нысанаға лақтыру". Бала допты жай ғана лақтырмай, оны Сізге қарай немесе белгілі бір қорапқа (себетке) дәл бағыттай алады. Бұл — қол-көз үйлесімі мен тереңдікті сезінудің ұштасуы. Онымен "шағын баскетбол" ойнаңыз.') WHERE id = '8fa193ab-3d15-4b10-9608-9e3d2bd116d1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Абстрактілі ұғымдар". Бала "махаббат", "ренжу", "сағыну" сияқты сөздерді орынды қолдана бастайды. Оның "Сені сағындым" деуі — эмоциялық интеллектінің жоғары деңгейде дамып келе жатқанының белгісі. Бұл сезімдерін міндетті түрде қабылдап, өз сезімдеріңізді де атап айтыңыз: "Мен де сені көргеніме қатты қуанамын".') WHERE id = '13cc3bef-f498-4191-9d8c-212c97c4c3e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың күші: "Көрінбейтін қонақтар". Бала ойыншықтарын қонаққа шақырып, оларға қиялындағы тағамдарды ұсына бастайды. Мұндай "өтірік сияқты" ойындар — оның жадындағы әлеуметтік жағдайларды ойнап көру тәсілі. Сіз де оның осы қиял әлеміне қонақ болып қосылыңыз!') WHERE id = 'a44149c1-0e64-49a3-936a-9d1d3a595e97';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала түстерді жай ғана "қызыл" немесе "көк" деп ажыратып қоймай, олардың қою және ашық реңктерін де көзбен тани бастайды. Оған түрлі түсті қарындаштар беріп, "Маған ең қою түстісін берші" деп, көзбен талдау қабілетін тексеріңіз. Бұл оның зейінін де, эстетикалық қабылдауын да дамытады.') WHERE id = '5bd4135a-236e-4d8e-8be3-3ebc28e05d9e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Құттықтаймыз, 900 күнді еңсердік! Балаңыз қазір 2 жарым жасқа (30 айға) толды. Ол физикалық та, эмоциялық та тұрғыдан нығайып, дербес әрі шығармашыл бола түсті. Осы 900 күн бойы көрсеткен сүйіспеншілігіңіз бен жанкештілігіңіз оның бүкіл болашақ өмірінің іргетасын қалады. Сіз ғажайып іс атқардыңыз, Ана!') WHERE id = '3d5a9ac6-ec3e-4630-b503-91b84d5fef32';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '900 күндік үлкен белесті артқа тастап, жаңа кезеңді бастаймыз! Балаңыз 31-ші айға аяқ басты. Ол қазір өзінің де, отбасы мүшелерінің де есімдерін анық айта алады. Онымен бірге отбасылық альбомды қарап отырып, "Бұл кім?" ойынын ойнаңыз. Бұл оның отбасына тиесілі екенін сезінуіне және сөздік жадын нығайтуға көмектеседі.') WHERE id = '5482dfbc-7126-4e7c-8510-4a2cfbf55aee';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Бір аяқпен секіру". Балаңыз қазір бір аяғымен аздап болса да секіруге талпынып жүр. Бұл тобық пен балтыр бұлшықеттерінің айтарлықтай дамығанын көрсетеді. Саябақта онымен бірге "қоянша секіруден" жарысып, осы дағдысын қолдаңыз.') WHERE id = '2840aa13-bbb5-476f-ad1f-11685bbcd555';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Дәлелдеу". Балаңыз енді қалауын жай ғана айтып қоймай, оны түсіндіреді: "Мен мына қуыршақты қалаймын, өйткені ол әдемі". Оның "өйткені" деп келтіретін себептерін мұқият тыңдаңыз. Бұл оның логикалық ойлауы мен ойын жеткізу қабілетінің қаншалықты жетілгенін көрсетеді.') WHERE id = 'dd18fee0-7070-455b-a654-1c5450138cd5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Мақсатты бояу". Балаңыз қағаздағы ірі пішіндердің (мысалы, үлкен алманың суреті) шекарасын түсініп, бояған кезде сызықтан шықпауға тырысады. Бұл қол бұлшықеттерін басқарудағы үлкен қадам. Оған жиектері ірі етіп сызылған бояу парақтарын беріңіз.') WHERE id = '25d06f6c-6efb-491d-ac80-8bbd8fa74917';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өздігінен киіну" және Түймелер. Балаңыз енді ірі түймелерді ағытуға немесе сыдырманы (бастап бергеннен кейін) жоғары қарай тартуға қызығушылық танытады. Оған "Кәне, өзің жасап көр" деп, өздігінен орындауға мүмкіндік беріңіз. Өздігінен киіне алуы баланың "менің қолымнан келеді" деген сезімін және өзіне деген сенімін айтарлықтай арттырады.') WHERE id = 'e6e7a26c-5b45-4894-8a1d-19ed6e362c71';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Артқа қарай жүру». Бала енді тепе-теңдігін жоғалтпай, артқа қарай бірнеше қадам жасай алады. Бұл қимыл оның өз денесін сезінуін (проприоцепция) және кеңістікті бағдарлау қабілетін жетілдіреді. Онымен бірге «Шаян сияқты жүрейік» ойынын ойнаңыз.') WHERE id = '54996f87-c947-4849-9084-027fb47fcd81';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Ұйқас сөздер мен әндер». Бала енді өзі естіген әндердің соңғы сөздерін ұйқастырып аяқтағанды жақсы көреді. Бұл оның фонематикалық есту қабілетінің дамып келе жатқанын көрсетеді. Онымен бірге тақпақтар оқып, соңын өзі аяқтауы үшін кідіріңіз. Бұл оның есте сақтау қабілетін жақсартып, сөйлеу қарқынын реттейді.') WHERE id = 'acf4d772-adf5-4683-b12b-56ef67f21202';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Моншақты жіпке тізу». Бала енді тесігі үлкен моншақтарды немесе макарондарды жіпке шебер тізе алады. Бұл әрекет шыдамдылықты да, саусақтардың дәл үйлесімділігін де талап етеді. Осылайша ол болашақта жазуды үйренуге қажетті бұлшықет жадын қалыптастырады.') WHERE id = 'acfd54f8-89c0-45e8-b646-d1e1362647ed';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тазалық сақтау» дағдысының дамуы. Бала енді қолын жуғаннан кейін сүлгімен өз бетінше сүртіп, сүлгіні орнына іле алады. Осындай шағын істі «соңына дейін жеткізу» әрекеттері оның өзіне-өзі қызмет ету жауапкершілігін арттырады. Оның жинақы әрі ұқыпты әрекетін «Қандай ұқыптысың!» деп мақтаңыз.') WHERE id = 'd2072154-6990-473d-aae5-34ace20cbb48';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Өзгенің сезімін түсіну». Бала енді Сіздің жүзіңізден мұңды немесе шаршағаныңызды байқап, «Не болды?» деп сұрауы мүмкін. Бұл — жанашырлықтың ең таза көрінісі. Оған сезіміңізді қарапайым тілмен түсіндіріңіз: «Аздап шаршадым, кел, бірге демалайық». Бұл оның эмоциялық интеллектін (EQ) дамытады.') WHERE id = '146ce216-737a-480c-9a11-95c561e541a4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Реттеу және салыстыру». Бала енді 3-4 ойыншығын көлеміне қарай (кішісінен үлкеніне дейін) реттеп қоя алады. Бұл — ерте математикалық ойлаудың негізі. Оған «Ең үлкен аюды ең алдына қой» деген сияқты тапсырмалар беріңіз. Бұл әрі көрнекі талдауды, әрі зейінді шоғырландыруды үйретеді.') WHERE id = 'a0704d4b-bb47-4a9f-8d8c-90add9dfed0e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Динамикалық тепе-теңдік». Бала енді аласа керменің немесе жерге сызылған сызықтың бойымен «арқан үстінде жүргендей» жүруге қызығушылық танытады. Бұл оның вестибулярлық жүйесінің (тепе-теңдік орталығының) жетіліп келе жатқанын көрсетеді. Саябақта жиектастардың үстімен жүргенде қолынан ұстап, оның батылдығын қолдаңыз.') WHERE id = '536458a4-4f3e-423b-9a13-cba42297d147';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт ұғымы: кеше және ертең». Бала бұл сөздерді нақты уақытты білдіру үшін әлі дұрыс қолданбаса да, өткен және болашақ оқиғаларды ажыратуға тырысады. Күннің соңында онымен «Ертең қайда барамыз?» деген тақырыпта әңгімелесіңіз. Бұл оның жоспарлау қабілетін дамытып, оқиғалар арасындағы уақыт байланысын түсінуін нығайтады.') WHERE id = '6849680a-6227-4b9c-ad36-2d8926dfdf15';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: баланың бір әрекеті сәтсіз болғанда (мысалы, текшелер құлап қалса), ол бірден жыламай, қайтадан әрекет жасап көруі мүмкін. Бұл «күрескерлік рух» оның болашақта білім алуда жетістікке жетуі үшін өте маңызды. Оған «Қаншалықты тырысып жатқаныңды көріп тұрмын» деп, нәтижесін емес, еңбегін мақтаңыз.') WHERE id = '86a0403c-8de6-429b-885d-6a2141aa02c8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '31-айдың соңғы онкүндігін бастаймыз! Бала енді «мен» және «менікі» сөздерін меншіктік сезімін анық білдіре отырып қолданады. Осы кезеңде оның меншік сезіміне құрметпен қарау маңызды. Оған «Бұл сенің ойыншығың, бірақ досыңмен кезектесіп ойнап көрейік» деп, бөлісудің таңдау екенін көрсетіңіз.') WHERE id = '84330770-7540-4b55-849d-a1cc950ead4d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Екі аяқпен алға секіру шеберлігі». Бала енді бір орында ғана емес, сәл алға қарай да (шамамен 10-20 см) секіре алады. Бұл аяқ бұлшықеттерінің серпінді күшінің артқанын көрсетеді. Еденге шағын «кедергілер» (мысалы, түрлі түсті таспалар) қойып, онымен секіру ойынын ойнаңыз.') WHERE id = '5741e7d1-1ed4-44c7-a88a-391b61cdae5d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Күрделі сөйлем құрылымдары». Бала енді екі түрлі ойды жалғаулықтар арқылы біріктіреді: «Мен саябаққа барып, әткеншек тепкім келеді». Оның сөйлемдерінен мақсаты мен ниеті анық көріне бастайды. Онымен сөйлескенде «Неге?» деп сұрап, ойын кеңірек түсіндіруге ынталандырыңыз.') WHERE id = '1e35c889-6f4c-4fd3-ae21-e3389ec8548d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Ұқыпты бүктеу». Бала енді Сізге еліктеп, қағазды немесе кішкентай орамалды бүктеуге тырысады. Бұл әрекет қол мен көздің үйлесімділігін әрі көрнекі симметрияны сезіну қабілетін дамытады. Киімдерді жинағанда, оған кішкентай орамалдарын бүктеуді тапсырыңыз.') WHERE id = '3690ca7a-82f5-4004-93ab-5126e1011625';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тамақтану және дастарқан әдебі». Бала енді қасық пен шанышқыны қолданғанда тамақты төкпейді деуге болады. Ол «Ас болсын» немесе «Рақмет» сияқты дастарқан басында айтылатын сөздерді орынды қолдана бастайды. Оның мұндай әдептілігін әрдайым мақтаңыз; бұл болашақ қарым-қатынас мәдениетінің негізі.') WHERE id = '43e9a2b0-67bf-44dc-b37a-1d4a9e1b3e86';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Рөлдік ойындардың күрделенуі». Бала енді өзін мұғалім, дәрігер немесе ата-ана ретінде ұстап, Сізге «нұсқаулар» беруі мүмкін. Осы ойындар арқылы ол әлеуметтік рөлдерді меңгереді. Оның «сабақтарына» қатысыңыз, бұл баланың көшбасшылық қабілеттерін дамытады.') WHERE id = 'd218ecc4-3eae-4f6a-ba4c-e1f3fc1576d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Сан мен мөлшер арасындағы алғашқы байланыс». Бала 1-ден 5-ке дейін санауды жатқа білумен қатар, енді «екі алма» дегенде оның мөлшерін де түсіне бастайды. Оған «Маған екі қарындаш берші» деп, санды мөлшермен сәйкестендіруін сұраңыз. Бұл — математикалық ойлауды дамытудың ең маңызды кезеңдерінің бірі.') WHERE id = 'e77c9dc0-0ffc-4afa-af6f-98372ac9412c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты тебу тәсілдері». Бала енді жүгіріп келе жатып, алдындағы допты тепе-теңдігін жоғалтпай теуіп, оның бағытын өзгерте алады. Бұл динамикалық тепе-теңдік қабілетінің жетілгенін көрсетеді. Онымен далада «футбол» ойнауға таптырмас уақыт.') WHERE id = 'f27d93f9-9b8c-4331-9608-1f9403361289';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Жаңа сөздік қор: сын есімдердің көбеюі». Бала енді заттарды сипаттағанда «жұмсақ», «қатты», «ыстық», «суық», «ауыр» сияқты сөздерді қолданады. Оған құрылымы әртүрлі заттарды беріп, «Мұны ұстағанда қандай сезімде боласың?» деп сұраңыз. Сын есімдер қорының молаюы балаға қоршаған ортаны егжей-тегжейлі қабылдауға көмектеседі.') WHERE id = '2a117057-8af9-4f1a-8e6e-3d0291275ec5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тазалық сақтау» дағдысы. Бала қолын жуғанда сабындап, шаюды өз бетінше дерлік орындай алады. Бұл жаста гигиеналық дағдыларды бекіту өте маңызды. Осы үдерісті ұнатуы үшін оған бойына сай басқыш-тұғыр беріңіз.') WHERE id = '916356ea-060f-4a2e-8be7-98dcab3ad0ee';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Өзгешесін тап» тапсырмасы. Бала заттар тобының ішінен өзгеше затты (мысалы, көліктердің арасындағы алманы) көзбен ажырата алады. Бұл оның талдау қабілетін жетілдіреді. Үйде оған қарапайым «Қайсысы артық?» ойындарын ұйымдастырыңыз. Бұл болашақтағы математикалық және логикалық тапсырмаларға тамаша дайындық болады.') WHERE id = '9c6d24fc-1a56-41e1-93ca-e94c8c830e4f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Бір аяқпен тұруға талпыныс». Бала бірнеше секунд болса да, бір аяғын жерден көтеріп, тепе-теңдігін сақтауға тырысады. Бұл дененің ауырлық орталығын сезіну үшін маңызды. Онымен «Ләйлек» ойынын ойнап, кімнің бір аяқпен ұзағырақ тұра алатынын байқап көріңіздер.') WHERE id = '1769bf32-48e2-40a7-b480-c6f396b19e4b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сезімді білдіру». Бала мұңайғанын, қуанғанын немесе қорыққанын сөзбен айта алады: «Мен қорықтым» немесе «Мен қуаныштымын». Сезімдерді атай білу — баланың эмоциялық интеллектісінің негізі. Ол сезімін айтқанда, мұқият тыңдап, «Иә, мен сені түсінемін» деп, оның сезімін мойындаңыз.') WHERE id = '7f6f2c0c-ef35-4291-8d3c-3c98cbe7cfa1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қиялдың күші: «Символдық ойлау». Бала таяқты «ат» деп елестетіп, оны мініп шапқандай ойнай алады. Бұл — бір заттың басқа нәрсені білдіре алатынын түсіну қабілеті. Бұл дағды болашақта оқу мен математиканы меңгеру (таңбаларды түсіну) үшін өте маңызды. Сіз — керемет бағыт берушісіз!') WHERE id = 'b4910186-9bb2-4fc8-898b-364f4deeed97';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '32-айдың соңғы онкүндігін бастаймыз! Бала енді «біз» ұғымын түсіне бастайды. «Біз саябаққа барамыз ба?» деп, өзін отбасының ажырамас бөлігі ретінде сезінетінін білдіреді. Онымен сөйлескенде, отбасы жоспарларымен бөлісіңіз: «Бүгін біз әжеміздің үйіне барамыз». Бұл баланың отбасына тиесілі екенін сезінуіне және өзін қауіпсіз сезінуіне көмектеседі.') WHERE id = '1b278c24-eef1-4629-acd4-d211ef0e2e61';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық жетілу: бала енді кейде өзінің ашуланғанын түсініп, «Мен ашуландым» деп айта алады. Бұл — эмоциялық өзін-өзі танудағы үлкен серпіліс. Осындай сәттерде оны құшақтап: «Түсінемін, кел, бірге тынышталайық», — деңіз. 930 күндік жолды сәтті аяқтадық — Сіз керемет серік болдыңыз!') WHERE id = '9e7e7732-10aa-4ec3-9e8d-653645d590eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «алдымен» және «содан кейін» реттілігін тереңірек түсінеді. «Киіміңді ки, содан кейін далаға шығамыз» дегенде, ол екінші әрекеттің сый екенін ұғынады. Бұл — баланың бойында шыдамдылық пен жоспарлау дағдыларының қалыптасуына бастайтын алғашқы қадамдар. Күнделікті әдеттер кезінде осы реттілікті оған жиі еске салып отырыңыз.') WHERE id = '97310562-0cc9-4922-aab5-bb0de93781d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы «Өрмелеу шеберлігі». Бала енді саябақтағы баспалдақтарға немесе үйдегі қауіпсіз биік жерлерге сенімдірек көтеріледі. Бұл кезде қол мен аяқ бұлшықеттері үйлесімді жұмыс істейді. Әрдайым жанында болыңыз, бірақ оған өз күшін сынап көруге мүмкіндік беріңіз.') WHERE id = '5e669269-1aa2-4602-9a6d-be602f929f7a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Логикалық байланыстар». Бала енді екі жағдайды бір сөйлемде байланыстырады: «Күн суық, күрте ки». Бұл оның жай ғана қайталамай, ойлай да алатынын көрсетеді. Өз ойын айтуға ынтасы арта түсуі үшін оның осындай логикалық пайымдарын: «Иә, дұрыс айтасың», — деп қолдаңыз.') WHERE id = 'c578b6d7-6027-41d3-bcb5-015328604f79';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Қағазбен жұмыс істеу». Бала енді қағазды бүктеуге немесе қарапайым тәсілмен қиюға (балаларға арналған үлкен қайшымен және ересектің бақылауымен) қызығушылық танытуы мүмкін. Бұл әрекеттер саусақ бұлшықеттерін басқару қабілетін жаңа деңгейге көтереді. Оған түрлі түсті қағаздармен жұмыс істеуге жағдай жасаңыз.') WHERE id = '369aa3fa-b6a2-4869-aff0-584c7cb30be3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Рөлдік ойындардың күрделенуі». Бала енді «дәрігер», «аспаз» немесе «жүргізуші» рөліне енеді. Осындай ойындар арқылы ол айналасындағы адамдардың немен айналысатынын түсініп, жанашырлық танытуды үйренеді. Оның ойынына қосылып, Сізге берген «рөлге» сай әрекет етіңіз.') WHERE id = '71802808-c37b-439f-8b0c-227ce432a07a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Доп тебу және нысанаға бағыттау». Бала енді допты жай ғана теппей, оны белгілі бір бағытқа, мысалы, екі ойыншықтың арасынан өткізуге тырысады. Бұл — қол-көз және аяқ-көз үйлесімділігінің бір мезгілде жұмыс істеуі. Онымен үйде «шағын футбол» турнирін өткізіңіз.') WHERE id = '61ba305a-b8ae-4528-9ce2-bd394666ba9a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі сұрақтар». Бала «Бұлт қайдан келеді?», «Ай қайда кетті?» деген сияқты сұрақтар қоюы мүмкін. Жауап бергенде қиял мен нақты ақпаратты үйлестіріңіз: «Бұлттар алыстан келіп, бізге жаңбыр әкеледі». Мұндай әңгімелер оның дүниетанымын кеңейтіп, білімге деген құштарлығын керемет арттырады.') WHERE id = 'a8a1120b-b774-4f04-89b0-c124a8cbf647';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: Бала енді сәтсіздікке төзімдірек қарайды. Текшелері құлап қалғанда бірден жыламай, «Қайтадан құрастырамын» деп айта алады. Оның табандылығын қолдаңыз. 950 күндік жолды артта қалдырдық, 1000 күнге аз ғана қалды! Сіз бұл жолда әрі ұстаз, әрі ең жақын доссыз!') WHERE id = 'c5fe4618-aa8a-4004-b14e-8472a1232fc2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды түріне ғана емес, түс реңктеріне қарай да топтастыра алады. Оған жасыл түстің әртүрлі реңкіндегі ойыншықтарды беріп, «Ашық түстен қою түске қарай орналастырайық» деп, көру арқылы талдау қабілетін дамытыңыз. Бұл оның эстетикалық қабылдауын жақсартып, зейінін шыңдайды.') WHERE id = '4cccdb9f-0090-4953-be45-4aac0e3ecdc0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Бір аяқпен секіру». Бала енді бір аяғымен сәл ғана секіруге талпынады. Бұл тобық күшінің және вестибулярлық жүйенің (тепе-теңдік) жақсы дамығанын көрсетеді. Онымен «Көжек» ойынын ойнаңыз. Құлап қалудан қорықпай, еркін қимылдауы үшін әрдайым жанында болыңыз.') WHERE id = '611c7f89-d565-4c80-b60a-401386c94dd3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қарама-қарсы мағыналы сөздер». Бала енді «үлкен-кіші», «ыстық-суық», «ауыр-жеңіл» сияқты қарама-қарсылықтарды толық түсініп, сөйлеу кезінде қолданады. Оған «Мына тас ауыр, ал мына мақта қандай?» деген сияқты сұрақтар қойыңыз. Бұл оның сөздік қорын сапалы түрде байытып, салыстыра ойлау қабілетін нығайтады.') WHERE id = '8c5fde41-64b4-4f6a-8c4b-9b0a4470f2ce';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен еркін жүру». Бала енді баспалдақпен әр басқышқа кезек-кезек бір аяғын басып, бір қолынан ғана ұстаған кезде сенімді көтеріледі. Бұл оның жалпы моторикасының толық жетілгенін көрсетеді. Сіз тек жанында болып, оған рухани қолдау көрсетіңіз.') WHERE id = '275df927-814f-46e6-87b1-244d3e43ae78';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме құрастыру». Бала енді суреттерге қарап, қарапайым оқиғалар ойлап табады. «Мысық келді, сүт ішті, ұйықтады» деген сияқты бірізді сөйлемдер — оның жады мен қиялының үйлесімі. Оған қызықты суреттері бар кітаптар беріп, «Мұнда не болып жатыр?» деп сұраңыз. Бұл оның шығармашылық ойлауын дамытады.') WHERE id = '904512e9-992f-4497-b856-79751b10de80';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәл орналастыру». Бала енді кішкентай ойыншық мүсіндерді орналастыруды немесе моншақтарды жіпке тізуді бұрынғыдан аз қателесіп орындайды. Бұл кезеңде саусақ ұштарының сезімталдығы артады. Оған құрылымы әртүрлі ұсақ заттармен ересектердің бақылауымен ойнайтын ойындар ұсыныңыз.') WHERE id = 'd9171a51-69d8-4d0a-829c-7db5c26a601f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше киінуге» деген табандылық. Бала енді түймесіз жейделерін немесе шалбарын өзі киюге талаптанады. «Өзім!» деген сәттерде оған уақыт беріңіз. Бұл дербестікке ұмтылу — болашақтағы өзіне деген сенімділік пен жеке жауапкершіліктің берік негізі. Оның кішкентай жетістіктерін «Қарашы, өзің-ақ істей алдың!» деп атап өтіңіз.') WHERE id = 'b1c5306b-77bb-4136-8d44-3c944e44a9e3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әдептілік ережелері». Бала енді «Өтінемін», «Көп рақмет», «Мархабат» сияқты сөздерді жай ғана қайталамай, орынды қолданады. Сіздің сыпайы мінез-құлқыңыз — ол үшін ең жақсы үлгі. Осындай әрекеттерін мақтап, қарым-қатынас мәдениетін нығайтыңыз.') WHERE id = '9e1b06c8-d4a2-4b28-b3bc-ad2c39ab7cb0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мезгіл үстеулері». Бала «кейін», «біраздан соң», «қазір» сөздерін орынды қолдана бастайды. «Біраздан соң келемін» дегеніңізде, ол уақыттың өтетінін түсінеді. Бұл баланың күте білу және өзін-өзі реттеу қабілетін арттырады. Күнделікті әдеттеріңізде осы сөздерді жиі қолданыңыз.') WHERE id = '6f964b8f-02b2-4bed-adce-f35ba0656a6a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Күрделірек құрылымдар". Бала енді тек текшелерден мұнара тұрғызып қана қоймай, "баспалдақ", "қоршау" немесе "қақпа" сияқты арасы ашық пішіндер де құрастырады. Бұл — оның кеңістіктік ойлауы мен инженерлік түйсігінің алғашқы нақты белгілері.') WHERE id = '8323ecc8-fdd4-4a47-acab-de738c3b3b74';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше таңдау: Ауа райы және киім". Бала далада күн суық болса, жылы киіну керектігін енді түсінеді. Оған "Бүгін дала суық, қай күртеңді кигің келеді?" деп, екі нұсқа ұсыныңыз. Өз таңдауы бойынша киіну баланың жауапкершілік сезімі мен шешім қабылдау қабілетін дамытады.') WHERE id = 'b6331bb4-9640-46b8-a4de-673e4569b48f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Символдық бөлісу". Бала енді өзі үшін аса құнды емес ойыншығын досына өз еркімен бере алады. Бұл — эгоцентрлік кезеңнен (бәрі менікі) шығудың және әлеуметтік ынтымақтастықтың басталуы. Оның бұл жомарттығын міндетті түрде "Қандай қамқорсың!" деп мақтаңыз.') WHERE id = '7a5cc16d-c4e3-465c-94b4-27327272c867';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Реттеу және санау". Бала 1-ден 10-ға дейін жатқа санаумен қатар, заттарды саусағымен көрсетіп, "бір, екі, үш" деп санын анықтай бастайды. Оған "Мұнда неше көлік бар?" деген сұрақ қойыңыз. Бұл — абстрактілі сандардың шынайы әлеммен алғаш рет нақты байланысатын кезеңі.') WHERE id = '27d58f54-7d91-4fc1-9abe-0e7741238b0e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Артқа қарай жүру және жүгіру". Бала енді артына қарамай-ақ артқа қарай сенімді жүріп, тіпті бірнеше қадам жүгіре алады. Бұл қимыл оның дене үйлесімділігінің қаншалықты дамығанын көрсетеді. Онымен "Шаяндар жарысы" ойынын ойнап, бірге көңіл көтеріңіз әрі бұлшықеттерін өзгеше қимылдатыңыз.') WHERE id = '5835a9f7-31b7-47bc-af3b-fbaf1eae167a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Жалғаулықтарды қолдану". Бала "және", "бірақ", "өйткені" сөздерін сөйлемге қосып, ойын толығырақ жеткізеді: "Менің қарным ашты, бірақ тамақ жегім келмейді". Оның сөйлемдерін тыңдап, Сіз де ұқсас күрделі сөйлемдермен жауап беріңіз. Бұл оның грамматиканы түсіну қабілетін толық жетілдіреді.') WHERE id = 'e679f00c-7a2a-4673-af5d-88a6f4d8128e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: баланың қолынан бір іс келмей қалса, ол енді Сізден бірден көмек сұрамай, бірнеше рет өзі жасап көреді. Оның бұл табандылығын жақсы жағынан қолдаңыз. «Қатты тырысып жатқаныңды көріп тұрмын» деу оған нәтижеден гөрі үдерісті жақсы көруге көмектеседі. 1000 күнге небәрі 40 күн қалды!') WHERE id = '73811b23-1334-47b6-aa32-fe16ca9f7dfe';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «мен», «сен» және «біз» есімдіктерін орынды қолданады. «Біз қазір тамақ ішеміз бе?» деп, өзін отбасының белсенді мүшесі ретінде сезінеді. Онымен сөйлескенде, оны да жоспарларыңызға қосыңыз: «Кел, дастарқанды бірге жасайық». Бұл оның отбасына тиесілі екенін сезінуіне және жауапкершілігінің артуына ықпал етеді.') WHERE id = '0088ee7c-73a0-42ed-a073-c3d4d5a577af';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен еркін жүру». Бала енді баспалдақпен аяғын кезектестіріп басып, бір қолынан ғана ұстап тұрғанда сенімді көтеріледі. Бұл оның ірі моторикасының толық жетілгенін көрсетеді. Сіз тек жанында болып, оған рухани қолдау көрсетіңіз.') WHERE id = 'bf415e92-93fc-4c0c-8e41-d0e69018f7ba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме құрастыру». Бала енді суреттерге қарап, қарапайым әңгімелер ойлап табады. «Мысық келді, сүт ішті, ұйықтады» деген сияқты бірізді сөйлемдер оның жады мен қиялының үйлесімін көрсетеді. Оған қызықты суреттері бар кітаптар беріп, «Мұнда не болып жатыр?» деп сұраңыз. Бұл оның шығармашылық ойлауын дамытады.') WHERE id = 'e900e935-8ccc-4908-bf87-10603eb74cda';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәл орналастыру». Бала енді кішкентай ойыншық мүсіндерді орналастыруды немесе моншақтарды жіпке тізуді азырақ қателесіп орындайды. Бұл кезеңде саусақ ұштарының сезімталдығы артады. Оған құрылымы әртүрлі ұсақ заттармен бақылауыңызда ойнайтын ойындар ұсыныңыз.') WHERE id = '6c732ec0-7e78-45c4-a464-029d46e20701';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше киінуге» деген табандылық. Бала енді түймесіз жейдесін немесе шалбарын өзі киюге тырысады. «Өзім!» деген сәттерде оған уақыт беріңіз. Өз бетінше әрекет етуге деген бұл талпыныстар — болашақтағы өзіне деген сенімділік пен жеке жауапкершіліктің берік іргетасы. Кішкентай жетістіктерін «Міне, өзің-ақ істей алдың!» деп атап өтіңіз.') WHERE id = '3fe4a18c-cebd-45f6-88ed-6acbe7109fd0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әдептілік ережелері». Бөпе енді «Өтінемін», «Көп рақмет», «Мархабат» сияқты сөздерді жай қайталамай, орынды қолданады. Сіздің әдепті мінез-құлқыңыз — ол үшін ең жақсы үлгі. Осындай әрекеттерін мақтап, қарым-қатынас мәдениетін нығайтыңыз.') WHERE id = 'e6b8bd35-5e9c-4328-a121-a6fecf7c7d62';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мезгіл үстеулері». Бөпе «кейін», «сәлден соң», «қазір» сөздерін орынды қолдана бастайды. Сіз «Сәлден соң келемін» дегенде, ол біраз уақыт өтуі керектігін түсінеді. Бұл бөпенің күте білу және өзін-өзі реттеу дағдыларын дамытады. Күнделікті әдеттеріңізде осы сөздерді жиі қолданыңыз.') WHERE id = 'eac1461c-042b-436c-8d00-465739e12f49';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты тебу және нысана». Бөпе енді допты жай ғана теппей, оны белгілі бір бағытқа, мысалы, екі ойыншықтың арасынан өткізуге тырысады. Бұл — қол мен көз, сондай-ақ аяқ пен көз үйлесімінің бір мезгілде жұмыс істеуі. Үйде онымен бірге «шағын футбол» турнирін өткізіңіз.') WHERE id = '3ddf5bfb-d5a6-4b94-8ee2-f4ce76892d43';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі сұрақтар». Бөпе «Бұлт қайдан келеді?», «Ай қайда кетті?» сияқты сұрақтар қоюы мүмкін. Жауап бергенде қиял мен нақты ақпаратты үйлестіріңіз: «Бұлттар алыстан келіп, бізге жаңбыр әкеледі». Мұндай әңгімелер оның дүниетанымын кеңейтіп, білімге деген құштарлығын айтарлықтай арттырады.') WHERE id = '1a341992-7717-4fca-abe1-d703ab6a7a2f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: Бөпе енді сәтсіздікке төзімдірек қарайды. Текшелері құлап қалса, бірден жыламай, «Қайтадан құрастырамын» деп айта алады. Оның табандылығын қолдаңыз. 970 күндік жолды еңсердік, 1000 күнге небәрі 30 күн қалды! Сіз бұл жолда әрі ұстаз, әрі ең жақын доссыз!') WHERE id = 'e1da111f-ccec-436b-a492-b6e924de37bf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпе енді түстерді жай ғана «қызыл» немесе «көк» деп ажыратып қоймай, олардың қою және ашық реңктерін де көзбен ажырата бастайды. Оған түрлі түсті қарындаштар беріп, «Ең қою түстісін маған берші» деп, көру арқылы талдау қабілетін тексеріңіз. Бұл оның зейінін де, эстетикалық қабылдауын да дамытады.') WHERE id = '1fa9d3d6-a970-457d-af04-c009e72b5e1b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Динамикалық тепе-теңдік». Бала енді аласа керілген арқанның немесе жерге сызылған сызықтың үстімен «арқанның үстінде жүргендей» жүруге қызығушылық танытады. Бұл оның вестибулярлық жүйесінің жетіліп келе жатқанын көрсетеді. Саябақта жиектастың үстімен жүргенде қолынан ұстап, оның батылдығын қолдаңыз.') WHERE id = '7d0f18e8-75ea-46a5-ae28-0011a1c178d0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт ұғымы: кеше және ертең». Бала бұл сөздерді нақты уақытты білдіру үшін әлі дұрыс қолданбаса да, өткен және болашақ оқиғаларды ажыратуға тырысады. Күннің соңында онымен «Ертең қайда барамыз?» деп әңгімелесіңіз. Бұл оның жоспарлау қабілетін дамытып, оқиғалар арасындағы уақыт байланысын түсінуіне көмектеседі.') WHERE id = 'a8b25b83-9fde-45e1-b976-1cd3459165f2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: Бала бір істі орындай алмаған кезде (мысалы, текшелер құлап қалғанда) бірден жыламай, қайтадан жасап көруге кірісуі мүмкін. Бұл «күрескерлік рух» оның алдағы оқу жетістіктері үшін өте маңызды. Оған «Қаншалықты тырысып жатқаныңды көріп тұрмын» деп, нәтижесін емес, еңбегін мақтаңыз.') WHERE id = '0db561dc-233c-4544-804a-8f5b95ba51b9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «Біз» ұғымын түсіне бастайды. «Біз қазір саябаққа барамыз ба?» деп, өзін отбасының ажырамас мүшесі ретінде сезінетінін көрсетеді. Онымен сөйлескенде отбасы жоспарларымен бөлісіңіз: «Бүгін біз әжеміздің үйіне барамыз». Бұл баланың өз отбасына тиесілі екенін сезінуіне және қауіпсіздік сезімінің нығаюына көмектеседі.') WHERE id = 'cb75068e-4a47-4582-8cce-0e1abcdf18e0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Баспалдақпен өздігінен көтерілу». Бала енді баспалдақпен аяқтарын кезектестіріп, әр басқышқа бір қадам басып және тек бір қолынан ұстағанда сенімді көтеріледі. Бұл оның жалпы моторикасының толық жетілгенін көрсетеді. Сіз тек жанында болып, оған рухани қолдау көрсетіңіз.') WHERE id = 'c4f997be-e1af-4807-8fcf-d6afc3087197';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әңгіме құрастыру». Бала енді суреттерге қарап, қарапайым әңгімелер ойлап табады. «Мысық келді, сүт ішті, ұйықтады» деген сияқты бірізді сөйлемдер оның жады мен қиялының үйлесімін көрсетеді. Оған қызықты суреттері бар кітаптар беріп, «Мұнда не болып жатыр?» деп сұраңыз. Бұл оның шығармашылық ойлауын дамытады.') WHERE id = '8a750939-d6ea-4327-ae01-fe2febf3e561';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Артқа қарай жүру» дағдысы. Бала енді тепе-теңдігін жоғалтпай, артқа қарай бірнеше қадам жасай алады. Бұл қимыл оның өз денесін сезінуін және кеңістікте бағдарлау қабілетін жетілдіреді. Онымен бірге «Шаян сияқты жүрейік» ойынын ойнаңыз.') WHERE id = '21db9a7e-7c35-47c7-9f2e-7e03f72a88a3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Ұйқас сөздер мен әндер» дағдысы. Бала енді естіген әндерінің соңғы сөздерін ұйқастырып аяқтағанды өте жақсы көреді. Бұл оның фонематикалық есту қабілетінің дамып келе жатқанын көрсетеді. Онымен бірге өлең оқып, соңғы сөзін өзі аяқтауы үшін кідіріңіз. Бұл оның есте сақтау қабілетін де, сөйлеу қарқынын да реттейді.') WHERE id = '6ee138fb-22b9-41f6-a232-d405003097d3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Моншақты жіпке тізу» дағдысы. Бала енді тесігі үлкен моншақтарды немесе макарондарды жіпке шебер тізе алады. Бұл әрекет шыдамдылықты да, саусақтардың дәл үйлесімділігін де қажет етеді. Осылайша ол болашақта жазу дағдысына қажет бұлшықет жадын қалыптастырады.') WHERE id = 'e27670af-3f91-498b-a727-68765b4a34c6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше тазалық сақтау» дағдысындағы ілгерілеу. Бала енді қолын жуғаннан кейін сүлгімен өз бетінше сүртіп, оны орнына іле алады. Осындай шағын істі «соңына дейін жеткізу» әрекеттері оның өзіне-өзі қызмет ету жауапкершілігін арттырады. Оның жинақы әрекетін «Қандай ұқыптысың!» деп мақтаңыз.') WHERE id = '41467e61-a2ce-4e56-9659-81bc3b54b05e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Басқаның сезімін түсіну» дағдысы. Бала енді жүзіңізден мұңды немесе шаршағаныңызды байқап, «Не болды?» деп сұрауы мүмкін. Бұл — эмпатияның ең таза көрінісі. Оған сезіміңізді қарапайым тілмен түсіндіріңіз: «Аздап шаршадым, кел, бірге демалайық». Бұл оның эмоциялық интеллектісін дамытады.') WHERE id = '639f97f3-6003-448b-9622-c5dde4b5cec4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Реттеу және салыстыру» дағдысы. Бала енді 3-4 ойыншығын көлеміне қарай (кішісінен үлкеніне дейін) ретімен орналастыра алады. Бұл — ерте математикалық логиканың негізі. Оған «Ең үлкен қонжықты ең алдына қой» деген сияқты тапсырмалар беріңіз. Бұл көру арқылы талдауды да, зейінді шоғырландыруды да үйретеді.') WHERE id = '370bff62-25e0-4406-b269-39b56f69516b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Сан мен таңбаны сәйкестендіру». Бала енді цифрлардың таңбаларын (1, 2, 3) көзбен танып, оларды тиісті мөлшермен сәйкестендіре алады. Оған «Мұнда 3 алма бар, маған ''3'' цифрын көрсетші» деген сияқты шағын тапсырмалар беріңіз. Бұл — мектепке дейінгі дайындықтың ең қызықты әрі маңызды кезеңдерінің бірі.') WHERE id = '277f876e-8768-4106-82f9-f67a9aa287de';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Дербестіктің шыңы». Баланың енді велосипед тебуге, әткеншекте өздігінен тербелуге немесе биік сырғанақтан сырғанауға батылы жетеді. Оның қауіпсіздігін қамтамасыз етіңіз, бірақ кедергі жасамаңыз. Өз күшіне сенуі оның мінезін шыңдайды.') WHERE id = '27b9a0e5-6b83-4460-8a15-0df9cab1dff0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт тереңдігі». Бала енді «Мен бөпе болғанда...» немесе «Мен өскенде...» деген сияқты сөйлемдер құрап, уақыт желісіндегі өз орнын түсіне бастайды. Оған бөпе кезіндегі суреттерін көрсетіп, осы уақытқа дейін қаншалықты өскенін айтып беріңіз. Бұл баланың жеке өмір тарихы мен өзіндік санасының (self-identity) толық қалыптасуына көмектеседі.') WHERE id = '3439184d-c674-4353-b4d8-24d477730a8a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Үлкен мәреге 1 күн қалды! Бүгін өткен жолыңызға көз жүгіртіп, өзіңізді мақтан тұтыңыз. Балаңыздың ми дамуының 80%-і осы алғашқы 1000 күнде аяқталды. Сіз оған сөйлеуді, жақсы көруді, сенуді және әлемді танып-білуді үйреттіңіз. Ертең балаңыздың өмірінде жаңа әрі жарқын бет ашылады. Сіз керемет АНАСЫЗ!') WHERE id = '6f7bcab0-f835-4b32-baa1-c34bfb4bf5a9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'ҚҰТТЫҚТАЙМЫЗ! Алғашқы 1000 күнді сәтті аяқтадыңыздар! 🌟 Бұл — адам өміріндегі ең маңызды даму кезеңі. Бала енді бөбектік шақтан өтіп, әлемді бағындыруға дайын кішкентай қаһарманға айналды. Anacan отбасы ретінде әр қадамда жаныңыздан табылып, бұл жетістікті Сізбен бірге атап өтудеміз. Бүгін — үлкен мереке, балаңыз бен Сіздің жеңіс мерекеңіз!') WHERE id = 'df76a0b6-eddc-484e-b6f0-24845f214e66';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1000 күндік үлкен марафоннан кейінгі алғашқы күніміз! Бала енді өмірінің 4-ші жылына қадам басып келеді. Бұл кезеңде «Неге?» деген сұрақтар жаңа сипатқа ие болады. Ол жай ғана ақпаратты емес, оқиғалар арасындағы логикалық байланысты іздейді. Сабырмен жауап беріңіз, өйткені бұл сұрақтар оның зияткерлік негізін қалайды.') WHERE id = '458401f2-485d-418a-8b89-143f552eb250';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәл орналастыру». Бала енді кішкентай ойыншық мүсіндерін орналастыруды немесе моншақты жіпке тізуді азырақ қателесіп орындай алады. Бұл кезеңде саусақ ұштарының сезімталдығы артады. Оған түрлі текстурасы бар ұсақ заттармен бақылауыңызда ойнауды ұсыныңыз.') WHERE id = 'b81dacf6-43a1-47b5-b976-b04cc72c15b8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзім киінемін» деген табандылық. Бала енді түймесіз жейдесін немесе шалбарын өзі киюге талпынады. «Мен өзім!» деген сәттерде оған уақыт беріңіз. Бұл дербестікке ұмтылу — болашақтағы өзіне деген сенімділік пен жеке жауапкершіліктің ең берік негізі. Кішкентай жетістіктерін «Қарашы, өзің істей алдың!» деп атап өтіңіз.') WHERE id = '5b370f66-ddd3-45df-8b72-80322e3b54c6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әдептілік ережелері». Бала енді «Өтінемін», «Рақмет», «Рұқсат болса» сияқты сөздерді жай ғана қайталамай, орынды қолданады. Сіздің сыпайы қарым-қатынасыңыз — ол үшін ең жақсы үлгі. Мұндай әрекеттерін мақтап, қарым-қатынас мәдениетін нығайтыңыз.') WHERE id = 'fb257145-0061-4b1c-8bd6-415874362912';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мезгіл үстеулері». Бала «кейін», «біраздан соң», «қазір» сөздерін орынды қолдана бастайды. Сіз «Біраздан соң келемін» дегенде, ол уақыттың өтетінін түсінеді. Бұл баланың күте білу және өзін-өзі реттеу дағдыларын дамытады. Күнделікті әдеттеріңізде осы сөздерді жиі қолданыңыз.') WHERE id = '2d2fd92a-c54e-421a-b575-674a4add6e64';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты тебу және нысанаға бағыттау». Бала енді допты жай ғана теппей, оны белгілі бір бағытқа, мысалы, екі ойыншықтың арасынан өткізуге тырысады. Бұл — көз-қол және көз-аяқ үйлесімінің бір мезгілде жұмыс істеуі. Онымен үйде «шағын футбол» турнирін өткізіңіз.') WHERE id = '4639b4f7-f878-413c-9ed9-f5c72fb301e3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі сұрақтар». Бала «Бұлт қайдан келеді?», «Ай қайда кетті?» деген сияқты сұрақтар қоюы мүмкін. Жауап бергенде қиял мен нақты ақпаратты үйлестіріңіз: «Бұлттар алыстан келіп, бізге жаңбыр әкеледі». Осындай әңгімелер оның дүниетанымы мен білімге құштарлығын айтарлықтай кеңейтеді.') WHERE id = 'bc37e242-95d7-44a8-8a20-2eacd0325914';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы "Динамикалық маневрлер". Бала енді жүгіріп келе жатып күрт бұрыла немесе кедергілерді жылдам айналып өте алады. Бұл оның өз денесін басқару қабілетінің жоғары деңгейде екенін көрсетеді. Оған аулада шағын кедергілер сайысын ұйымдастырыңыз.') WHERE id = '1242feeb-5e2f-4d55-aa93-952aedfbe568';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Күрделі шақтар". Бала енді "мен істеп қойған едім", "мен істейтін боламын" сияқты күрделі шақ формаларын сөзінде қолдана бастайды. Онымен өткен оқиғаларды талқылаңыз: "Кеше әжеңнің үйіне барғанда не болды?". Бұл оның есте сақтау қабілетін де, сөйлеуінің грамматикалық дәлдігін де жетілдіреді.') WHERE id = '5e199122-f8a1-4104-82fd-2c91af60c12f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Симметрия жасау талпыныстары". Бала қағазды дәл ортасынан бүктеуге немесе салған суретіндегі бөлшектерді (мысалы, адамның екі көзін, екі қолын) дәлірек орналастыруға тырысады. Оның көріп қабылдау зейінін "Қарашы, екі қолын да салыпсың!" деп атап өтіңіз.') WHERE id = '9dfe80c5-1c6a-4ec4-852c-1433440d5b52';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Ережелерді ішкі қабылдау". Бала енді Сіз айтпай-ақ кейбір ережелерді есіне түсіреді: "Тамақтанар алдында қолымды жуайын ба?". Бұл сыртқы тәртіптің ішкі тәртіпке айналуының бастамасы. Оның өз бетінше жауапкершілік танытуын міндетті түрде мақтаңыз; бұл — мінезінің қалыптасуындағы үлкен қадам.') WHERE id = '5760ce33-81a1-4f8c-a7a0-f30c320a688a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Мен және досым". Бала енді басқа балалармен жай ғана қатар ойнамай, ортақ сюжет бойынша ойнай бастайды (мысалы, "Сен ана бол, мен бала боламын"). Бұл — әлеуметтік ынтымақтастық пен рөлдерді бөлудің алғашқы маңызды тәжірибесі.') WHERE id = 'e6c24a0b-d760-47b5-90b8-f6d05b42625b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Жіктеу шеберлігі". Бала заттарды бір уақытта екі белгісі бойынша топтастыра алады: "әрі қызыл, әрі кішкентай заттар". Оған аралас ойыншықтар беріп, "Барлық кішкентай мәшинелерді осында жина" деңіз. Бұл оның миындағы логикалық сүзгілеу жүйесін дамытады.') WHERE id = '083c5f31-3fe0-44d9-b65b-c4b92bb36ae4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: бала енді сәтсіздікке төзімдірек қарайды. Текшелері құлап қалғанда бірден жыламай, «Қайтадан құрастырамын» деп айта алады. Оның осы қайсарлығын қолдаңыз. 1000 күнге небәрі 10 күн қалды! Сіз осынау ғажайып жолды балаңызбен қол ұстасып бірге жүріп өттіңіз. Жарайсыз!') WHERE id = 'a124273d-b639-4f61-aa7d-a589a92dd962';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1000 күндік үлкен марафонның соңғы онкүндігіне қош келдіңіз! Бала енді өзін толық танып, «Мен өстім» деген сезіммен әрекет етеді. Онымен бірге өткізген 991 күнді ой елегінен өткізіңіз: алғашқы қадамы, алғашқы сөзі... Қазір ол физикалық жағынан да, ақыл-ойы жағынан да дербес тұлға. Сіздің махаббатыңыз — осы тұлғаның ең берік іргетасы.') WHERE id = 'b5b8d286-f3be-458e-9da0-f739ba54a527';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Физикалық дамудағы «Күрделі қимылдар». Бала енді жүгіріп келе жатып кенет тоқтай алады, бағытын өзгерте алады немесе кедергіден секіріп өте алады. Бұл оның жүйке жүйесі мен бұлшықет үйлесімділігінің жетілгенін көрсетеді. Онымен бірге таза ауада қимылды ойындар ойнауды жалғастырыңыз.') WHERE id = '40ef129f-5b1b-4e7a-8bf0-78a6953a2417';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Логикалық диалог». Бала енді Сізбен пікір таластыра алады: «Менің ұйықтағым келмейді, өйткені ойынымды аяқтаған жоқпын». Бұл жай ғана қырсықтық емес, өз ойын дәлелдей білу қабілеті. Оған «Дұрыс айтасың, бірақ сәлден соң қараңғы түседі» деген сияқты қисынды түсініктемелер беріп, өзара сыйластықты үйретіңіз.') WHERE id = 'b9aae384-2df5-41c3-b46c-488d1b02a6ae';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Шығармашылық суреттер». Бала енді жай сызықтар ғана емес, «адамды» (әдетте дөңгелек пен сызықтардан тұратын таяқша адам), «үйді» немесе «күнді» салуға тырысады. Бұл суреттер — оның санасындағы бейнелердің қағазға түсуі. Осы «өнер туындыларын» міндетті түрде сақтап қойыңыз.') WHERE id = '28f47857-a1db-40ef-a9e2-553a55c8a841';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қамқорлық». Бала енді Сіздің шаршағаныңызды немесе досының жылап отырғанын көрсе, жанына барып, жұбатуға тырысады. Бұл — эмоциялық интеллектінің (EQ) ең жоғары көрінісі. Оның кіршіксіз жүрегі — Сіз сыйлаған мейірімнің айнасы.') WHERE id = 'ad204761-7be7-4b3d-9813-46b7f3ddfbf5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Мекен үстеулері". Бала "жанында", "артында", "астында", "үстінде" ұғымдарын толық әрі дәл түсініп, қолдана алады. Егер ол "Доп диванның астында" десе, демек оның кеңістікті бағдарлау қабілеті толық қалыптасқан. Онымен "Жасырынбақ" ойынын ойнап, осы ұғымдарды одан әрі бекітіңіз.') WHERE id = '64ca65c7-1a28-48d4-beca-77b3f217471c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: "Шыдамдылық сынағы". Бала енді қалаған нәрсесін алу үшін бірнеше минут күту қажет екенін түсінеді және бірден жылай бастамайды. Осындай сәттерде оған: "Күткенің үшін көп рақмет, бұл — есейгендіктің белгісі", — деңіз. Сіз керемет жолсеріксіз!') WHERE id = 'd29729c2-dd1d-4552-9d6e-3a6745ad9680';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді түстер мен пішіндерді байланыстыра отырып, айналасындағы әлемді сипаттайды. Егер ол "Маған ана сары шаршы текшені берші" десе, бұл оның миы бір уақытта бірнеше белгіні өңдей алатынын көрсетеді. Бұл қабілетін күнделікті өмірде шағын тапсырмалар беру арқылы (мысалы, "көк шұлығыңды тап") қолдаңыз.') WHERE id = '6e9a3917-235a-4638-821e-7544b6f6fd44';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене дамуындағы "Динамикалық тепе-теңдік". Бала енді бір аяғымен 5 секундқа дейін тұра алады. Бұл вестибулярлық жүйенің (тепе-теңдік орталығының) және аяқ бұлшықеттерінің нығайғанын көрсетеді. Онымен "Ләйлек" ойынын ойнап, кімнің ұзағырақ тұра алатынын байқап көріңіз.') WHERE id = 'bf8d8f80-94a0-4e9e-beaa-a9027d0e8ae4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Себеп-салдар байланыстары". Бала енді "Егер... онда..." түріндегі сөйлемдерді түсіне бастайды. "Егер ойыншықтарыңды жинасаң, мультфильм көре аламыз" дегенде, ол шартты түсінеді. Бұл логикалық ойлаудың да, ішкі тәртіптің де (өзін-өзі тәртіпке үйретудің) қалыптасуындағы маңызды қадам.') WHERE id = 'b1f57847-eeec-4119-b2fc-2905b91fb26b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Қайшымен алғашқы тәжірибелер". Бала енді қағазды (қауіпсіз қайшымен) түзу сызық бойымен қиюға қызығушылық танытады. Бұл әрекет қол-көз үйлесімін де, саусақтардың ұсақ моторикасын да жақсы дамытады. Оны қараусыз қалдырмаңыз, бірақ дербестігіне кедергі жасамаңыз.') WHERE id = 'bc3bff7e-368e-485f-8abd-ee144e6a6477';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігіндегі «Баспалдақпен еркін жүру». Бала енді баспалдақпен әр басқышқа бір аяғын кезек-кезек қойып, тек бір қолынан ұстағанда (немесе мүлде ұстамай-ақ) сенімді түрде түседі. Бұл оның жалпы моторикасы толық жетілгенін көрсетеді. Сіз тек жанында болып, оған рухани қолдау көрсетіңіз.') WHERE id = 'e1ab27cc-4713-481c-b52f-32935f62d3d2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақ-жауап тізбегі». Бала енді Сіздің сұрақтарыңызға жай ғана «иә/жоқ» деп емес, толық сөйлемдермен жауап береді. «Бүгін саябақта кіммен ойнадың?» деген сұраққа егжей-тегжейлі жауап бере алады. Онымен сөйлескенде «Ол қандай түсті еді?», «Не істедіңдер?» сияқты қосымша сұрақтар қойып, сөйлеу қабілетін ынталандырыңыз.') WHERE id = '7d186d1a-0812-440c-b07e-ee9ed0da127d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Дәлірек бояу». Бала енді кішкентай пішіндердің де шекарасын сезіп, бояған кезде сызықтан көп шықпауға тырысады. Бұл қол бұлшықеттерін басқарудағы үлкен ілгерілеу. Оған қалыңдығы әртүрлі қарындаштар беріп, тәжірибе жасауына мүмкіндік беріңіз.') WHERE id = 'a7b0a891-2fdb-4521-b60b-98a992dcf545';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өз бетінше киіну: сыдырма мен түйме». Бала енді үлкен түймелерді ағытып, сыдырманы (ілгегін салып бергеннен кейін) жоғары қарай тарта алады. Оған «Кәне, өзің жасап көр» деп, сабырмен күтіңіз. Өз бетінше киіне алуы баланың «менің қолымнан келеді» деген сезімі мен өзіне деген сенімін айтарлықтай арттырады.') WHERE id = '9893a146-5d99-48e6-ae6a-1f46520795f5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Жалпы және жалқы». Бала енді алма, алмұрт пен бананның барлығы «жеміс» екенін түсінеді. Оған әртүрлі заттарды көрсетіп, «Бұлардың барлығын бір сөзбен қалай атаймыз?» деп сұраңыз. Санаттар бойынша ойлау оның миындағы ақпаратты сақтау жүйесін ретке келтіреді.') WHERE id = 'f440da85-66a5-444d-9191-5dceb0b51d20';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты иықтан асыра лақтыру». Бала енді допты жай ғана жерге тастамай, оны иықтан асыра алға қарай, белгілі бір нысанаға дәлдеп лақтыра алады. Бұл бүкіл дене қимылдарының үйлесімділігін талап етеді. Онымен саябақта «нысанаға дәл тигізу» ойындарын ойнаңыз.') WHERE id = '5a9ea9e5-b06c-4aa9-b965-a6664f7442e8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Қиялдағы ойын серіктері". Бала енді жалғыз ойнағанда да дауыстап сөйлеп, ойыншықтарына рөлдер береді. Бұл — "Эгоцентрлік сөйлеу", ол балаға өз әрекеттерін сөз арқылы реттеуге көмектеседі. Оның осы "монологтарын" тыңдау арқылы ішкі әлемінде не болып жатқанын түсіне аласыз.') WHERE id = '9f4b387f-964e-4bb9-856d-1ac035b357f4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өз бетінше таңдау: Шешім қабылдау". Бала енді не жегісі келетінін немесе қандай ойын ойнағысы келетінін нақты біледі. Оған күн сайын екі нұсқа ұсыныңыз: "Алма қалайсың ба, әлде банан ба?". Бұл оған өз өмірін басқара алатынын сезінуге көмектесіп, өзіне деген сенімділігін арттырады.') WHERE id = '7022c99f-3026-41d3-8d24-5d2da8ff257d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Көлем мен мөлшердің сақталуы". Бала әзірге жіңішке әрі биік ыдыстағы су кең ыдыстағы судан көп деп ойлауы мүмкін. Бұл — "Piaget" кезеңіне сай қалыпты жағдай. Онымен су ойындарын ойнап, суды әртүрлі ыдыстарға құйыңыз. Бұл тәжірибе арқылы логикалық түсінігінің қалыптасуын жеделдетеді.') WHERE id = '63894550-7c88-4d80-827d-abe697cce597';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Екі аяқпен алға секіру". Бала енді кедергілерден (мысалы, жердегі жіптен) екі аяғымен бір мезгілде секіріп өте алады. Бұл бүкіл дене қимылының үйлесімділігін және жарылғыш күшті қажет етеді. Оған қауіпсіз жерлерде шағын кедергілер жолағын жасап беріңіз.') WHERE id = 'cab49b1b-46a8-46fe-9575-6cef46f13add';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Абстрактілі уақыт ұғымы". Бала енді "Таң", "Түс" және "Кеш" арасындағы айырмашылықтарды күнделікті дағдылар арқылы түсінеді. "Кешке әкең келгенде..." дегенде, ол тәуліктің сол уақытын ойша елестетеді. Күн тәртібін тұрақты ұстануыңыз оның уақыт туралы түсінігін қауіпсіздік сезімімен байланыстырады.') WHERE id = '50a38f0a-e830-42a7-9b23-0d529496ee7f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді суреттерге қарап, қарапайым оқиғалар ойлап табады. "Аю орманға барды, қарны ашып, бал жеді" деген сияқты бірізді сөйлемдер оның логикалық реттілікті түсінетінін көрсетеді. Оған қызықты суреттері бар кітаптар беріп, "Сеніңше, бұдан кейін не болады?" деп сұраңыз. Бұл оның шығармашылық қиялын барынша дамытады.') WHERE id = '5b5539ed-db72-44da-bf5f-8b147bfb9b43';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Нәтижеге бағытталған ынтымақтастық». Бала енді досымен бірге үлкен мұнара тұрғызу үшін «тастарды» бөлісе алады. Бұл — жай ғана қатар ойнау емес, ортақ мақсатқа жету үшін бірлесіп ойнау (cooperative play). Оның бойындағы осы тіл табыса білу қабілетін «Керемет команда болдыңдар!» деп мақтап қойыңыз.') WHERE id = '12a2b82c-6975-4312-a2f7-fbbdcf5d9909';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мөлшердің сақталуын түсіну сынағы». Бала әлі де жалпайтылған ермексаз домалақ ермексаздан үлкен деп ойлауы мүмкін. Онымен осындай тәжірибелер жасап көріңіз: домалақ ермексазды жайыңыз, содан кейін қайтадан домалақтаңыз. Бұл оған физикалық әлемнің өзгермейтін заңдылықтарын түсінуге көмектеседі.') WHERE id = 'ae824ed0-4f75-4515-b7bf-83483a6c043d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты аяқпен алып жүру». Бала енді допты жай ғана теппей, оны аяғымен аздап алға итеріп, қозғалып жүруге (dribbling) тырысады. Бұл динамикалық тепе-теңдік пен аяқ-көз үйлесімділігін қажет етеді. Саябақта оған арнап шағын «футбол жолын» жасап, допты нысанаға қарай алып жүруін сұраңыз.') WHERE id = '6f891729-8e3d-4c9f-bdb3-588b6de557c3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әдептілік пен әдеп нормалары». Бала енді «кешіріңіз», «өтінемін» деген сөздерді жаттанды түрде емес, орынды қолданады. Сіздің өзгелермен сөйлескенде қолданатын дауыс ырғағыңыз — ол үшін ең маңызды үлгі. Ол әдептілік танытқанда, бұл әрекеттің айналасындағыларға жағымды әсер ететінін сезінуіне көмектесіңіз.') WHERE id = '8553307b-a429-4fdd-a8d5-b4776f0fb3d5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1300 күндік ғажайып жол! Бала бөпелік әдеттерін толығымен артта қалдырып, мектепке дейінгі кезеңнің ең белсенді сатысына қадам басты. Ол енді өзін жеке «мен» ретінде танып, әлемді өзгертуге дайын. Осы 1300 күн бойы Сіз оның ең сенімді жол көрсетушісі болдыңыз. Махаббатыңыз бен сабырыңыз үшін өзіңізге алғыс айтыңыз!') WHERE id = '7883dc4b-dac2-42dc-8a35-51e8d5b489b1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '44-ші айға қош келдіңіз! Бала енді «мен өстім» деген сезімді терең сезінеді. Осы кезеңде оған киімін өзі таңдау немесе дастарқан жаю сияқты шағын міндеттер беріңіз. Бұл оның дербестікке деген ұмтылысын дұрыс бағытқа бұрып, өзіне деген сенімін арттырады.') WHERE id = 'aad2ad75-5a11-4a2d-9c7c-2bc5d48aa312';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Кеңістік пен бағыт". Бала "оң" және "сол" ұғымдарын әлі толық ажырата алмаса да, "алға", "артқа", "жоғары" және "төмен" командаларын дәл орындайды. Онымен "Робот ойынын" ойнаңыз: "Екі қадам алға, бір қадам артқа!". Бұл әрі көңілді, әрі кеңістікті бағдарлау қабілетін нығайтады.') WHERE id = '6ef1e101-45d4-451a-8710-b32b9878cd2e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала "егер... онда..." логикасын толық меңгере бастады. "Егер ойыншықты сындырып алсам, ол енді жұмыс істемейді". Бұл — болашақтағы жағдайды болжай білу қабілетінің бастауы. Оған өз әрекеттерінің салдарын алдын ала ойлауды ұсыныңыз: "Қалай ойлайсың, стақанды шетке қойсақ, не болады?". Бұл жауапкершілік сезімін қалыптастырады.') WHERE id = '98264d01-8080-47ff-9743-5076f3c1e9fb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Статикалық тепе-теңдік шыңы". Бала енді бір аяғымен еш жерге сүйенбей 5-10 секунд тұра алады. Бұл ішкі құлақтағы тепе-теңдік орталығының, сондай-ақ бел мен аяқ бұлшықеттерінің нығайғанын көрсетеді. Онымен "қатып қалдық" ойынын ойнап, бұл дағдыны қызықты әрекетке айналдырыңыз.') WHERE id = 'e5ea1656-41df-45ea-937c-07b3a21bce4f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Күрделі оқиға құрастыру". Ол енді суретті кітапты қарағанда заттарды жай ғана атап қоймай, оқиғалар арасындағы байланысты түсіндіреді: "Қоян қашып барады, өйткені түлкі келе жатыр". Оның қиялын ынталандыру үшін "Қалай ойлайсың, түлкі не айтады?" деген сияқты сұрақтар қойыңыз. Бұл оның когнитивтік икемділігін арттырады.') WHERE id = '991395b5-cce5-4484-973b-52ea93850c86';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Саусақтардың дербес қимылы". Бала енді саусақтарын бір-біріне тигізу немесе саусақ ұштарымен ұсақ моншақтарды жіпке тізу сияқты күрделі әрекеттерді орындайды. Бұл мидың екі жарты шарының үйлесімді жұмысын қажет етеді. Оған түйме тағу немесе ілгек ағыту ойындарын ұсыныңыз.') WHERE id = '7718afa5-181a-4995-b727-92bfdea228d9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Қиялдан туындайтын қорқыныштарды басқару". Бұл жаста балалар кейде қараңғылықтан немесе "құбыжықтардан" қорқуы мүмкін. Оның қорқынышын жоққа шығармаңыз, керісінше "құбыжықты қуатын сиқырлы шам" сияқты ойындар ойлап табыңыз. Сіздің эмоциялық қолдауыңыз оған бұл қорқыныштардың уақытша екенін түсінуге көмектеседі.') WHERE id = '5da5688a-9254-4a8e-94a4-a6cdb8624f11';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Епті маневр». Бала енді бар жылдамдығымен жүгіріп келе жатып, алдындағы кедергіні байқап, құламай айналып өте алады. Бұл — мидағы «қимылды жоспарлау» қабілетінің ең жоғары деңгейі. Саябақта оған шағын кедергілер жолағын жасап беріңіз. Бұл денесін басқару қабілетін де, ептілігін де арттырады.') WHERE id = '5ff72db7-e0be-4353-a758-f27d398fc0b7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сұрақтардың сапасы». Енді ол «бұл не?» деп қана қоймай, «неге бұлай?» деп сұрайды. Ол оқиғалардың ішкі қисынын түсінуге тырысады. Жауап бергенде оның қиялын да іске қосыңыз: «Сеніңше, жаңбыр неге жауады?». Бұл оның шығармашылық және ғылыми ойлауын ынталандырады.') WHERE id = '104d37cc-f454-4cee-bc62-45a7dd638317';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Суретті көшіру: шаршы мен үшбұрыш». Бала енді бұрыштары бар пішіндерді салуға талпынады. Бұл шеңбер салудан қиынырақ, өйткені қарындашты белгілі бір нүктеде тоқтатып, бағытын өзгертуді талап етеді. Оған бұрышты пішіндерді біріктіріп, «үй» немесе «көлік» салуды көрсетіңіз.') WHERE id = '72c3574b-2a9a-4755-8727-8d01b439e56e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Әділдік пен ережелер». Бала енді ойын кезінде ережелердің бұзылуына бірден қарсылық білдіреді: «Ол кезекті бұзды!». Бұл — әлеуметтік санасы мен этикалық түсінігінің дамуы. Оған ережелердің барлығына бірдей екенін түсіндіру арқылы ішкі әділдік сезімі мен әлеуметтік тәртібін нығайтасыз.') WHERE id = '6e14d59c-92a1-4b52-9746-19ec45e3a240';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Дипломатиялық талпыныстар». Бала жанжалдарды «Сен маған мынаны бер, мен де саған ананы беремін» деген сияқты ұсыныстармен шешуге тырысады. Бұл — әлеуметтік зерденің ең айқын көрсеткіштерінің бірі. Оның осы «келіссөз жүргізуші» қырын мақтап, әділ шешімдерді қолдаңыз.') WHERE id = '1bc59678-d965-4c53-ad57-e91ac3a6bece';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Санды бірден тану (субитизация)». Бала енді 3 немесе 4 затты санамай-ақ, бір қарағанда олардың нешеу екенін түсіне алады. Оған нүктелер саны әртүрлі карточкаларды көрсетіп, қанша нүкте бар екенін бірден айтуды сұраңыз. Бұл — болашақта математикалық есептеулерді жылдам орындау қабілетінің негізі.') WHERE id = '9268aa12-9e8f-498d-a13c-fd38e4e68957';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: «Допты иықтан асыра лақтыру». Бала енді допты жай ғана жерге тастамай, оны иық деңгейінен алысқа әрі белгілі бір нысанаға қарай лақтыра алады. Бұл бүкіл дене қимылын үйлестіруді және күшін реттеуді талап етеді. Онымен саябақта нысанаға доп лақтыру ойындарын ойнаңыз.') WHERE id = 'dbdc7993-c5ce-4ff8-a2f5-69daf1b98fea';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әзіл мен қалжыңның тереңдеуі». Бала енді сөздердің мағынасын өзгертіп, әзілдей алады. Мысалы, Сізді «Ата» деп атап, күлуі мүмкін. Бұл оның тілдік нормаларды жақсы білетінін және әзіл тудыру үшін оларды әдейі бұзатынын көрсетеді. Онымен бірге көңіл көтеріңіз.') WHERE id = '8c83e3c0-4591-49c2-a059-525f584c28d3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Шыдамдылық сынағы». Бала енді қалаған нәрсесін алу үшін бірнеше минут бойы (мысалы, Сіз телефонмен сөйлесіп жатқанда) үнсіз күте алады. Бұл оның өзін-өзі басқару дағдысының нығайып келе жатқанын көрсетеді. Күткеннен кейін оған міндетті түрде «Мені күткенің үшін көп рақмет» деп алғыс айтыңыз.') WHERE id = '75df2db1-9a5a-4048-99dc-80b484b6d396';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді айналасындағы логотиптер мен жазуларды тани алады. Мысалы, сүйікті балмұздақ брендін немесе дүкеннің логотипін көргенде, оның атауын айтады. Бұл — символдық ойлаудың дамуы. Оған әртүрлі жол белгілерін немесе қарапайым пиктограммаларды көрсетіп, олардың мағынасын сұраңыз. Бұл — болашақта оқу дағдысын меңгерудің көрнекі негізі.') WHERE id = 'bb1f5dc6-7300-4f63-9d44-40f2e54dfb71';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Артқа қарай секіру». Бала енді артқа қарай аздап секіре алады. Бұл тепе-теңдікті сақтаудың да, кеңістікте денесін басқару қабілетінің де жаңа деңгейі. Онымен «Шаян мен бақа» жарысын ойнап, белсенділігін ынталандырыңыз.') WHERE id = '2c74b1f3-a8fd-4086-88da-377857855b8c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қарама-қарсы қасиеттерді салыстыру». Бала енді «ең үлкен», «кішірек», «өте ауыр» сияқты салыстыру дәрежелерін сөйлемде орынды қолданады. Оған өлшемдері әртүрлі 3 ойыншық беріп, «Ең үлкені қайсы?» деп сұраңыз. Бұл оның сөздік қорының сандық және сапалық тұрғыдан байып келе жатқанын көрсетеді.') WHERE id = 'f9bd7f70-01bc-46e8-8391-e80ede82d1cc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада — «Адам бейнесіндегі пропорция». Бала енді адам суретін салғанда дене мүшелерін қисындырақ орналастырады: көздерін беттің ортасына, қолдарын дененің екі жағына салады. Бұл суреттер оның өз денесін қабылдауының (дене бейнесінің) дамып келе жатқанын көрсетеді.') WHERE id = 'b857a3b6-e216-49cf-a9c0-e7adabf3fdba';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін сипаттау». Бала енді өзін сипаттай алады: «Менің шашым сары», «Мен жылдам жүгіремін». Бұл — жеке тұлғалық болмысының нығаюы. Оған «Сен тағы нені ұнатасың?» деген сияқты сұрақтар қойып, өзін танып-білуіне көмектесіңіз. Өз-өзі туралы жақсы пікірде болуы — болашақтағы өзіне деген сенімінің негізі.') WHERE id = '9ca9132e-1f05-4086-b977-373ac1739718';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта — «Дипломатия және келіссөз». Бала енді бір нәрсеге қол жеткізу үшін: «Егер сен маған мұны берсең, мен де саған мынаны беремін», — деген сияқты ұсыныстар айтады. Бұл — әлеуметтік зерде мен мәселені шешу қабілетінің жоғары деңгейде дамуының белгісі. Оның осындай әділ «саудаласу» әрекеттерін қолдап, оң қабылдаңыз.') WHERE id = '68e14866-1913-4e48-a5b0-15a89d136783';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамуда — «Уақытты күн тәртібімен байланыстыру». Бала «Таңертең оянғанда», «Кешке ұйықтағанда» деген сияқты тіркестер арқылы тәулік бөліктерін бір-бірінен ажыратады. Онымен ертеңгі жоспарларды «алдымен, содан кейін, соңында» ретімен талқылаңыз. Бұл балада қауіпсіздік пен тәртіп сезімін қалыптастырады.') WHERE id = 'fc45f60c-b22c-4712-b519-43e1ec159d0a';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Допты аяқпен алып жүру». Бала енді допты жай ғана теппей, оны аяғымен аздап алға итеріп, алып жүруге (дриблинг жасауға) тырысады. Бұл динамикалық тепе-теңдік пен зейінді қажет етеді. Саябақта оған арнап шағын «футбол жолын» жасап, допты нысанаға қарай алып жүруін сұраңыз.') WHERE id = '27b3b770-0010-4e27-a15b-7e39df48e572';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде — «Әдептілік және әлеуметтік этика». Бала енді «кешіріңіз», «рұқсат па?» деген сияқты сөз тіркестерін жағдайға сай қолданады. Сіздің басқалармен сөйлесу мәнеріңіз — ол үшін ең басты үлгі. Бала әдептілік танытқанда, бұл әрекетінің өзгелерге жағымды әсер қалдырғанын сездіріңіз: «Сен осындай әдепті болғандықтан, бәрі саған күлімсіреп қарайды».') WHERE id = 'eddeff81-68cf-4451-8b49-9db4335c7821';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Қиялдан туған оқиғалар». Енді ойындар күрделене түсті: «Мен сатушымын, сен менен нан сатып алуға кел». Мұндай ойындарда бөпе қоғамдағы түрлі рөлдерді байқап көреді. Оның ойдан құрған оқиғаларына ілесіп, шығармашылық үдерісін ынталандырыңыз.') WHERE id = 'c35d44af-1b5b-4a3a-b44c-143278463e37';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Заттардың қызметі». Бала енді заттарды тек сыртқы көрінісіне қарай емес, атқаратын қызметіне қарай да топтастырады. «Бұлар — кесетін құралдар», «Ал бұлар — жазуға арналған құралдар». Бұл оның миындағы ақпарат қорының жүйеленіп, қызметіне қарай реттеле бастағанын көрсетеді.') WHERE id = '52b43fec-3fc9-4135-bc89-1ca56d2c89c9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыс үйлесіміндегі «Нәзік қимылдар». Бала енді сұйықтық құйылған стақанды көп төкпей алып жүре немесе тар соқпақпен жүре алады. Бұл оның көру-қимыл үйлесімінің қаншалықты жетілгенін көрсетеді. Үйде оған «кішкентай көмекші» рөлін беріп, зейінін одан әрі дамытыңыз.') WHERE id = 'b2a95188-79e5-4c80-963a-2302704140ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу қабілетіндегі «Сезімдер сөздігі». Бала енді жай ғана «жаманмын» немесе «жақсымын» демейді. Ол «ашуландым», «сағындым», «қуаныштымын» сияқты сөздерді орынды қолданады. Оның сезімдерін қабылдап, растаңыз: «Сағынғандықтан жылауың — қалыпты жағдай». Бұл — оның эмоциялық саулығының ең сенімді кепілі.') WHERE id = '8d118e2f-9e48-4f84-bdd9-4688744f285c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1330 күндік белес! Бала енді ресми түрде «ерте балалық шақтың» ең белсенді әрі зерек кезеңінде. Қазір ол физикалық жағынан да, эмоциялық жағынан да толыққанды жеке тұлға. Сіз бұл жолды білім мен сүйіспеншілікке сүйеніп жүріп өттіңіз. «Anacan» әрдайым Сіздің жаныңызда!') WHERE id = 'ee7d4f4f-acca-4792-810c-9ebdc339da81';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '45-ші айға қош келдіңіз! Бала енді айналасындағы жазулардан таныс әріптерді іздей бастайды. Әсіресе өз есімінің алғашқы әрпін кез келген жерден тани алады. Бұл — оқу дағдысының бастапқы кезеңі. Оған әріптерді күштеп үйретпеңіз, тек көрген әріптің атауы мен дыбысын ойын арқылы айтып беріңіз.') WHERE id = 'c1854d46-26a3-452c-9eb7-697ec5a92d6c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігінде — «Үш дөңгелекті велосипедті толық басқару». Бала енді педальды тоқтатпай айналдырып, рульді бұру арқылы тар бұрылыстардан өте алады. Бұл дененің төменгі бөлігінің күші мен көру-кеңістіктік үйлесімнің жоғары деңгейде дамығанын көрсетеді.') WHERE id = 'ee3c0b22-95f2-4059-93bc-287ff0eb00cf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде — «Болжау қабілеті». Ертегі оқыған кезде бала енді «Қалай ойлайсың, әрі қарай не болады?» деген сұраққа қисынды жауап бере алады. Бұл оның оқиғалар арасындағы жасырын байланыстарды (inference) түсіне бастағанын көрсетеді. «Сен оның орнында болсаң, не істер едің?» деп сұрап, қиялын дамытыңыз.') WHERE id = '8651dfdb-b093-4f7c-b25e-9846200e12c4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада — «Қағаз қию: Пішінді қиып алу». Бала енді қауіпсіз қайшымен қарапайым дөңгелекті немесе шаршыны шетін бойлай қиып алуға тырысады. Бұл қолдың ұсақ бұлшықеттерін жоғары деңгейде басқаруды қажет етеді.') WHERE id = '9727b126-febe-431d-a82a-db6a6416efff';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Әділдік пен тәртіп сақшысы». Бала енді ережені өзі ғана емес, басқалар бұзған кезде де оған назар аударады: «Әке, сен кезекті бұздың!». Бұл ішкі ар-ұждан мен әлеуметтік әділдік сезімінің қалыптасып келе жатқанын көрсетеді. Оған ережелердің неліктен барлығына бірдей екенін түсіндіріңіз.') WHERE id = 'a0bdfa22-2c16-417c-bc41-62353716c069';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта — «Дипломатиялық шешімдер». Келіспеушілік кезінде бала енді «Кел, кезекпен ойнайық» деген сияқты ұсыныстар айта алады. Бұл — әлеуметтік зияттың ең айқын көрсеткіштерінің бірі. Оның осындай татуластырғыш көзқарасын міндетті түрде «Өте жақсы шешім таптың» деп мақтаңыз.') WHERE id = '1c1d5af4-d669-4eee-8938-97dcf06fd2d8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамуда — «Мөлшердің сақталуын зерттеу тәжірибелері». Онымен құм немесе су ойынын ойнаңыз. Бірдей мөлшердегі суды пішіні әртүрлі ыдыстарға құйыңыз. Ол әлі де биік ыдыста су көбірек деп ойлауы мүмкін. Мұндай тәжірибелер оның миын физикалық шындықты түсінуге дайындайды.') WHERE id = '32e16fdb-1a45-43a1-8bb5-fea77db311d2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сәтсіздікті қабылдау». Бала бір нәрсені істей алмаған кезде (мысалы, пазлды құрастыра алмаса) бірден ашуланбай, қайтадан байқап көреді немесе көмек сұрайды. Оның нәтижесін емес, күш-жігерін мақтаңыз: «Сен көп тырыстың және берілмедің, жарайсың!».') WHERE id = '3c009bb9-dfc9-4682-a20a-9afa3ba74f26';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды түсі мен материалына қарай бір уақытта топтастыра алады: «Бұл әрі көк, әрі жұмсақ». Бұл — когнитивтік икемділіктің маңызды көрсеткіші. Оған құрылымы әртүрлі заттардан (ағаш, мата, пластик) тұратын ойындар ұсыныңыз.') WHERE id = 'b98d1c0b-fdd1-4aeb-a1f1-d636c58ba6b7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Динамикалық секіру». Бала енді жүгіріп келе жатып, алдынан кездескен шағын кедергіден жылдамдығын бәсеңдетпей секіріп өте алады. Бұл мида қимылды алдын ала жоспарлау (моторлық жоспарлау) қабілетінің дамып келе жатқанын көрсетеді. Саябақта оған шағын кедергілер жасап бере аласыз.') WHERE id = '60d3fdb2-caa2-4bc5-bc84-452616921b80';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыт рәсімдері». Бала «кеше», «бүгін» және «ертең» ұғымдарын әлі толық ажырата алмаса да, күнделікті әрекеттер ретін біледі. «Тамақтан кейін — саябақ» немесе «Ұйықтар алдында — ертегі». Осындай реттілік оның санасында уақыт желісін қалыптастырады.') WHERE id = '95122e91-e077-4e38-a3b4-27a4e9e756f1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Симметрияға ұмтылу». Бала қағазды бүктеуге немесе салған суретіндегі бөлшектерді (мысалы, адамның екі көзі мен екі қолын) симметриялырақ орналастыруға тырысады. Бұл оның көру-кеңістіктік қабылдауының қаншалықты жетілгенін көрсетеді.') WHERE id = '27b05f17-57a4-4b79-9091-f702b81309dd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Саяси» келіссөздер. Бала енді Сізбен «саудаласады»: «Егер мен көкөніс жесем, содан кейін саябақта ұзағырақ қала аламыз ба?». Бұл оның әлеуметтік ықпал ету тәсілдерін үйреніп жатқанын көрсетеді. Мұндай «келіссөздерде» шынайы әрі дәйекті болыңыз; осылайша ол шекараларды түсінуді үйренеді.') WHERE id = '0875811d-7343-4ba3-a29e-c235cba78b04';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты иықтан асыра лақтыру». Бала допты нысанаға қарай бұрынғыдан да күшті әрі дәл лақтыра алады. Бұл қол мен иық бұлшықеттерінің үйлесімді жұмыс істейтінін көрсетеді. Онымен саябақта «себетке доп лақтыру» сияқты шағын ойындар ойнаңыз. Бұл әрі көңілді, әрі денені басқару қабілетін нығайтады.') WHERE id = '5eff2db7-b37a-4ebb-9335-292fea3a6331';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Абстрактілі ұғымдар: Оң және сол». Бала «оң қол» және «сол аяқ» ұғымдарын үйренуге қызығушылық танытады. Әзірге оларды шатастыруы мүмкін, бұл қалыпты жағдай. Оған шұлық кигізгенде: «Енді оң аяғыңды соз», — деп, осы ұғымдарды күнделікті өмірде қолданыңыз.') WHERE id = 'dcd74d19-3308-4446-89b6-05aecfc53aed';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Өзін-өзі реттеу (Self-regulation)». Баланың бір нәрсе қолынан келмей қалса, бірден ашуланбай, Сізге қарап: «Қайтадан байқап көрейін бе?» — деп айта алуы мүмкін. Бұл — эмоциялық жетілудің ең маңызды кезеңдерінің бірі. Оның нәтижесін емес, танытқан шыдамдылығы мен күш-жігерін мақтаңыз. Сіз керемет анасыз!') WHERE id = 'b36ad394-fd9c-40bc-963f-954848c1c743';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала «алдымен, қазір, кейін» реттілігін күрделі әрекеттерде де қолдана алады. «Алдымен ойыншықтарымды жинаймын, кейін қолымды жуып, тамақ ішемін». Бұл — мидағы стратегиялық жоспарлау (атқарушы функция) қабілетінің дамуы. Оған күн жоспарын құруға белсенді қатысуға мүмкіндік беріңіз; бұл оның ішкі тәртібін нығайтады.') WHERE id = 'a41e3209-8dbf-44ce-98bb-5a5b64b4268c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Статикалық және динамикалық тепе-теңдік». Бала бір аяғымен 5-10 секунд тұра алады немесе жіңішке жиектастың үстімен тепе-теңдігін жоғалтпай жүре алады. Бұл вестибулярлық жүйенің толық жетілгенін көрсетеді. Онымен «Арқанның үстімен жүруші» ойынын ойнайтын кез келді.') WHERE id = '696cb686-c625-440d-93fe-4e04eee0ca77';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Себеп-салдар тізбегі». Ол енді Сіздің тыйымдарыңыздың қисынды түсіндірмесін іздейді: «Неге қазір тәтті жеуге болмайды?». Жауап бергенде «Өйткені мен солай айттым» деудің орнына: «Өйткені қазір тәтті жесең, қарның тойып қалып, пайдалы түскі асыңды іше алмайсың», — деп түсіндіріңіз. Бұл оның логикалық ойлау қабілетін жетілдіреді.') WHERE id = '1bdc4f44-d5e0-42ee-9d67-dc1beca39c22';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Адам бейнесіндегі бөлшектер". Бала енді адамның суретін салғанда саусақтар, кірпіктер, түймелер немесе баскиім сияқты ұсақ бөлшектерді қосады. Мұндай суреттер оның айналасындағы әлемді қаншалықты мұқият бақылайтынын және қол-көз үйлесімінің дамығанын көрсетеді.') WHERE id = 'dd86234a-f54a-432f-bcb2-f0fc25c1a9f2';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Қиялдағы қорқыныштар мен батылдық". Бұл жаста баланың қиялы соншалықты күшті болғандықтан, ол қараңғыда "құбыжықтарды" көруі мүмкін. Оның қорқынышын жоққа шығармай, бірге "қорқынышты қуатын" рәсімдер (мысалы, сиқырлы жастық немесе қолшам) ойлап табыңыз. Бұл оның эмоциялық қауіпсіздік сезімін нығайтады.') WHERE id = '30d373fa-79f5-41e2-b2ee-ce7f265298c1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Көшбасшылық және ынтымақтастық". Бала енді ойынның желісін өзі құрып, достарына рөлдер бөледі: "Сен мысық бол, ал мен сенің иең боламын". Бұл оның әлеуметтік иерархия мен рөлдерді түсіне бастағанын көрсетеді. Кейде оның сценарийіне қосылып, шығармашылық көшбасшылыққа деген талпынысын қолдаңыз.') WHERE id = 'ec5ff997-3ed4-4645-be9c-2d361314cc2f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Мөлшер және сан таңбасы". Бала енді "4" цифры 4 алманы, ал "1" цифры бір ғана затты білдіретінін толық түсінеді. Оған "Маған 5 қарындаш берші" сияқты тапсырмалар беріп, дерексіз сандар мен нақты мөлшер арасындағы байланысты нығайтыңыз.') WHERE id = 'c8eb9b80-1c81-4e02-86f3-e8fdf448ffb9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты екі қолмен қағып алу". Бала енді өзіне қарай баяу лақтырылған допты қолдарын бүгіп, кеуде тұсында біріктіру арқылы (кейде бірден алақандарымен) қағып ала бастайды. Бұл реакция жылдамдығы мен көзбен қадағалау дағдысының дамуын көрсетеді. Онымен жақын қашықтықтан жұмсақ доппен жаттығыңыз.') WHERE id = 'e3704303-d02a-47ea-9a47-f1164a3046e0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Уақыт ұғымдары". Бала "кеше", "бүгін" және "ертең" ұғымдарын орындырақ қолдана бастайды. "Ертең мен әжемнің үйіне барамын" дегенде, ол уақыт ретін ойша елестетеді. Күннің соңында онымен ертеңгі жоспарларды "ертегі" сияқты әңгімелеп, ұйқыға жатыңыз. Бұл оның келер шақ туралы түсінігін де қалыптастырады.') WHERE id = '58a4bd7b-b429-45cf-92c2-f503f4e7d474';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1350 күнге созылған үлкен даму жолы! Балаңыз енді ресми түрде «сәбилік» жағалауынан алыстап, «ерте балалық шақ» мұхитында еркін жүзіп жүр. Оның даралығы, әзіл-қалжыңы мен мінезі қазір Сіз үшін ең үлкен қызығушылық көзіне айналды. Осы 1350 күн ішінде Сіз оның әлеміндегі ең сенімді айлақ болдыңыз. Жарайсыз, Ана!') WHERE id = '647eb338-5057-4cf4-a29d-e4970189abc1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Балаңыз әлеуметтік ойындарда «мен» мен «біздің» арасындағы айырмашылықты қолдана бастады. Егер ол: «Кел, бірге үй салайық, сен кірпіштерді әкел, мен қалаймын», — деп міндеттерді бөліссе, бұл оның бірлесіп әрекет ету қабілетінің жоғары деңгейде екенін көрсетеді. Оған топтық жұмыстарда көшбасшы немесе көмекші рөлін байқап көруге мүмкіндік беріңіз. Бұл оның болашақта командамен жұмыс істеу дағдыларын қалыптастырады.') WHERE id = '56b16411-749d-48ab-a1c9-aec6ee4d3f2b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «Жылдам жүгіру және шұғыл бұрылу». Балаңыз енді жүгіріп келе жатып тепе-теңдігін жоғалтпай, шұғыл бұрыла алады. Бұл оның өз денесін сезінуі (проприоцепция) мен бұлшықеттерін басқару қабілетінің қаншалықты жетілгенін көрсетеді. Саябақтағы «Ирек жүгіру» ойыны ол үшін тамаша жаттығу болады.') WHERE id = '3acf9991-6e18-469c-8243-5255e3b47e73';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Неге?» сұрақтарының логикалық тізбегі. Ол енді Сіздің жауабыңызды қанағат тұтпай, «Ал ол неге сондай?» деп бірінен соң бірі сұрақ қояды. Жауап бергенде оны да ойлануға ынталандырыңыз: «Қалай ойлайсың, күн қайда кетеді?». Бұл оның қиялын ғылыми қызығушылықпен ұштастырады. Оның таным әлемін балаларға арналған шағын энциклопедиялармен кеңейтіңіз.') WHERE id = '09e33fb1-46b4-4ad6-a2f6-bb3ee2d41636';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Қағаз бүктеу (оригами негіздері)». Балаңыз енді қағазды дәл ортасынан бүктеуге және бұрыштарын беттестіруге тырысады. Бұл әрекет қол бұлшықеттерін нығайтып қана қоймай, геометриялық симметрия ұғымын да санасына орнықтырады. Оған түрлі түсті қағаздан қарапайым пішіндер жасауды үйретіңіз.') WHERE id = 'b9689a6f-2bcb-421e-acea-f03b1095905f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару және сезімді білдіру». Балаңыз ашуланғанда жай ғана айқайламай, «Мен қазір қатты ашулымын!» деп сезімін сөзбен жеткізе алады. Оның сезімдерін қабылдап, растаңыз: «Сені түсінемін, ашулануың қалыпты жағдай». Бұл оның эмоциялық тұрғыдан жетілуіне көмектеседі.') WHERE id = '7a0c1e64-9ecb-47f6-83f4-aa32390210cd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Статикалық тепе-теңдік шыңы". Бала енді бір аяғымен еш жерге сүйенбей 5-10 секунд тұра алады. Бұл ішкі құлақтағы тепе-теңдік орталығының, сондай-ақ белі мен аяқ бұлшықеттерінің нығайғанын көрсетеді. Онымен "қатып қал" ойынын ойнап, бұл дағдыны қызықты ермекке айналдырыңыз.') WHERE id = '2f039b11-24db-4020-90d7-1c5f7a16c171';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Себеп-салдар тізбегі". Ол енді Сіздің тыйымдарыңыздың қисынды себебін іздейді: "Неге қазір тәтті жеуге болмайды?". Жауап бергенде "Өйткені мен солай айттым" деудің орнына, "Өйткені қазір тәтті жесең, қарның тойып қалып, пайдалы түскі асыңды іше алмайсың" деп түсіндіріңіз. Бұл оның логикалық ойлау қабілетін жетілдіреді.') WHERE id = 'c914eb21-6b42-48f0-8ec0-5b93a47ae392';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Адам бейнесінің бөлшектері". Бала енді адамның суретін салғанда саусақ, кірпік, түйме немесе баскиім сияқты ұсақ бөлшектерді қосады. Бұл суреттер оның қоршаған ортаны қаншалықты мұқият бақылайтынын және қол-көз үйлесімінің дамығанын көрсетеді.') WHERE id = 'fdd8b340-0697-4aeb-8d02-8988eb7da642';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Қиялдан туған қорқыныштарды басқару". Бұл жаста балалар кейде қараңғылықтан немесе "құбыжықтардан" қорқуы мүмкін. Оның қорқынышын жоққа шығармаңыз, керісінше, "құбыжықты қуатын сиқырлы шам" сияқты ойындар ойлап табыңыз. Сіздің эмоциялық қолдауыңыз оған бұл қорқыныштардың уақытша екенін түсінуге көмектеседі.') WHERE id = 'd0348641-27c7-4875-b24e-5d2722f25676';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы "Нәтижеге бағытталған ынтымақтастық". Бала енді досымен бірге үлкен мұнара тұрғызу үшін "тастарды" бөлісе алады. Бұл — жай ғана қатар ойнау емес, ортақ мақсат үшін бірлесіп ойнау (cooperative play). Оның әлеуметтік тіл табысу қабілетін "Қандай керемет команда болдыңдар!" деп мадақтаңыз.') WHERE id = 'bd3e5f00-1925-4d9d-bea8-7fc43abbb171';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы "Мөлшердің сақталуын түсіну сынағы". Бала әлі де жалпайтылған ермексаз домалақ кесектен үлкен деп ойлауы мүмкін. Онымен осындай тәжірибелер жасаңыз: кесекті жайыңыз, содан кейін қайтадан домалақтаңыз. Бұл оған физикалық әлемнің өзгермейтін заңдылықтарын түсінуге көмектеседі.') WHERE id = '34ed2954-3007-40b2-9228-8e5bbced6cd6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Дипломатиялық келіссөздер». Бала бір нәрсеге қол жеткізу үшін: «Егер сен маған мына мәшинені берсең, мен де саған шоколад беремін», – деп «саудаласуы» мүмкін. Бұл – әлеуметтік ықпал ету және дипломатиялық дағдылардың бастамасы. Онымен әділ «саудаласу» ережелерін ойын түрінде қолданып көріңіз.') WHERE id = '2dd70517-4599-4775-b1e7-2b11f39244da';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Мөлшердің сақталуы (көлем)». Онымен асүйде тәжірибе жасап көріңіз: бірдей мөлшердегі суды бір жалпақ ыдыс пен бір биік, жіңішке ыдысқа құйыңыз. Ол әлі де биік ыдыста су көбірек деп айтуы мүмкін. Мұндай тәжірибелер оның көру арқылы қабылдауы мен логикалық ойлауы арасындағы қайшылықты шешу қабілетін дамытады.') WHERE id = 'eb9fac33-252a-4cde-bb98-95be1aaf831f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты аяқпен алып жүру». Бала енді допты жай ғана теппей, аяғымен сәл алға итеріп, алып жүруге (дриблинг) тырысады. Бұл динамикалық тепе-теңдік пен зейінді қажет етеді. Онымен бірге саябақта шағын «футбол жолын» жасап, допты нысанаға қарай алып жүруін сұраңыз.') WHERE id = 'f40621db-c962-42bd-85b1-429800b2b4ef';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Әдептілік және әлеуметтік нормалар». Бала енді «кешіріңіз», «рұқсат па?» сияқты сөз тіркестерін жай жаттап алып қана қоймай, жағдайға сай әрі орынды қолданады. Сіздің өзгелермен сөйлесу мәнеріңіз – ол үшін ең басты үлгі. Ол әдептілік танытқанда, бұл әрекетінің айналасындағыларға жағымды әсер қалдырғанын міндетті түрде сездіріңіз.') WHERE id = '3804d992-5f37-4fb4-bfb6-18ad143039e9';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1360 күндік үлкен сапар! Бала 45 айды артта қалдырды. Ол енді өз ойлары, қалжыңдары мен армандары бар толыққанды жеке тұлға – кішкентай адам. Осы 1360 күн ішінде Сіз оның әлемінің сәулетшісі болдыңыз. Оның өзіне сенімді жанарында Сіздің махаббатыңыздың ізі бар. Сіз керемет анасыз!') WHERE id = '333176ec-4bc6-4177-b76d-921996ec28d4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды сыртқы көрінісіне ғана емес, қандай материалдан жасалғанына қарай да ажыратады: «Мынау пластиктен, ал мынау темірден жасалған». Оған фактурасы әртүрлі заттарды беріп, олардың айырмашылықтарын сұраңыз. Бұл оның қоршаған ортаны егжей-тегжейлі талдауына және физикалық әлем туралы білімін жүйелеуіне көмектеседі.') WHERE id = '657efc38-ed5e-4e3a-9572-7dbdb9184154';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада — "Суретті көшіру: шаршы". Шеңберден айырмашылығы, шаршы салу үшін қарындашты бұрыштарға келгенде тоқтатып, бағытын өзгерту қажет. Бұл жазуға көшудегі маңызды дене дайындығы. Оған әртүрлі геометриялық пішіндерді біріктіріп, үй немесе көлік салуды көрсетіңіз.') WHERE id = '90518b08-497d-4de6-998e-df3fea30a1f5';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзін-өзі басқару және шыдамдылық". Бала енді кезегін күтудің немесе қалауының бірден орындалмауының "ақырзаман" емес екенін түсінеді. Сіздің "5 минут күте тұр" дегеніңізді сабырлырақ қабылдайды. Күтіп болғаннан кейін оған міндетті түрде "Шыдамдылық танытқаның үшін рақмет" деп айтып, осы жағымды мінез-құлқын нығайтыңыз.') WHERE id = '24183c71-3661-48ff-a107-410bfbd38523';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта — "Ережесі бар командалық ойындар". Бала енді басқа балалармен бірге ережесі бар ойындарды (мысалы, "Жасырынбақ") ойнауға қызығушылық танытады. Бұл — әлеуметтік бейімделудің маңызды кезеңі. Ережелерді сақтағанда, оны "Әділ ойнағаның үшін жарайсың" деп мақтаңыз.') WHERE id = '04f3027e-9e30-43e8-bafb-f6c237c97831';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамуда — "Санды бірден тану (субитизация)". Бала енді 4-5 затты санамай-ақ, бір қарағанда олардың нешеу екенін түсіне алады. Оған нүктелер саны әртүрлі карточкаларды көрсетіп, "Мұнда нешеу?" деп сұраңыз. Бұл болашақта жылдам математикалық есептеулер жүргізудің негізін қалайды.') WHERE id = '494bf11b-00d7-4571-8a96-04e2a73dc57c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Бір аяқпен секіру". Бала енді бір аяғымен қатарынан бірнеше рет секіруге талпынады. Бұл күшті де, жоғары деңгейдегі тепе-теңдікті де қажет етеді. Онымен үйде "Іздермен секіру" ойынын ойнап, аяқ бұлшықеттері мен тепе-теңдігін нығайтыңыз.') WHERE id = 'e519a6cc-28f9-4dbb-80e3-d4aaf6533df1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеу дамуында — "Уақытты көрнекі түрде елестету". Бала енді тәулік бөліктері мен олардың ретін жақсы біледі. "Таңертең оянғанда күн шығады, ал кешке ай көрінеді". Онымен ертеңгі жоспарларды "алдымен, содан кейін, соңында" ретімен талқылау балада қауіпсіздік сезімін де қалыптастырады.') WHERE id = '22058766-30d2-4299-8138-dbe3e33f7a99';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты аяқпен басқару". Бала енді допты жай ғана теппей, оны аяғымен сәл алға итеріп, алып жүруге (дриблинг) тырысады. Бұл динамикалық тепе-теңдік пен аяқ-көз үйлесімін қажет етеді. Саябақта оған шағын "футбол жолын" жасап, допты нысанаға қарай алып жүруін сұраңыз.') WHERE id = 'f67ac937-be10-4065-8ce0-71169b977a25';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Әдептілік пен этика". Бала енді "кешіріңіз", "өтінемін" деген сөздерді жаттанды түрде емес, орынды қолданады. Сіздің өзгелермен сөйлескенде қолданатын дауыс ырғағыңыз — ол үшін ең маңызды үлгі. Ол әдептілік танытқанда, бұл әрекетінің айналасындағыларға қалай жағымды әсер ететінін сезінуіне көмектесіңіз.') WHERE id = '81b527f9-bc6c-4fa6-a384-bfac0dbe1b99';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1370 күндік ғажайып жол! Бала бөбектік шақтағы әдеттерін толығымен артқа тастап, мектепке дейінгі кезеңнің ең белсенді сатысына қадам басты. Ол енді өзін жеке "мен" ретінде танып, әлемді өзгертуге дайын. Сіз осы 1370 күн бойы оның ең сенімді жол көрсетушісі болдыңыз. Сүйіспеншілігіңіз бен төзіміңіз үшін өзіңізге алғыс айтыңыз!') WHERE id = '7f1e62d7-6f8c-466a-917b-3acd9000a197';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала айналасындағы жазулардан таныс әріптерді (әсіресе өз есімінің бірінші әрпін) іздей бастайды. Бұл — "көзбен шолып оқу" кезеңі. Оған әріптерді күштеп үйретпеңіз, тек көрген таңбаларының қандай дыбысты білдіретінін қызықты жаңалық ретінде көрсетіңіз.') WHERE id = '395ee563-1ee4-4a29-8a28-f145933f9a6e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Динамикалық маневр". Бала енді жүгіріп келе жатып, алдындағы кедергіні оңай айналып өте алады немесе бағытын кенет өзгерте алады. Бұл мидағы қимылды жоспарлау қабілетінің жетілгенін көрсетеді. Саябақта онымен "Ирек жол жарысын" ойнап, ептілігін арттырыңыз.') WHERE id = 'cad61f20-8263-4b3a-bfc8-ed14fb447f18';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Болжау және логика". Оған ертегі оқығанда, "Қалай ойлайсың, әрі қарай не болады?" деп сұраңыз. Бала енді оқиғалардың өрбуіне сай қисынды болжамдар жасай алады. Бұл оның қиялын да, себеп-салдар байланыстарын түсіну қабілетін де жетілдіреді.') WHERE id = '9337ce82-dd36-4b6f-a92e-336053ee8590';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: "Дипломатия және шешу жолдары". Келіспеушілік кезінде бала енді жай ғана жыламай, "Ойыншықты бөлісіп ойнайық" немесе "Маған мынаны бер, мен де саған мынаны берейін" деген сияқты ұсыныстар айтады. Бұл — әлеуметтік зерденің ең жоғары көрінісі. Оның осындай бейбіт жолды таңдауын әрдайым қолдаңыз. Сіз керемет тұлға тәрбиелеп келесіз!') WHERE id = '29c7e41f-162a-440d-ad79-c662956e2e8e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды түсі мен өлшеміне қарай бір уақытта топтастыра алады: "Барлық кішкентай жасыл текшелерді осында жинайық". Бұл — когнитивтік икемділіктің маңызды көрсеткіші. Оған бірнеше белгі бойынша іздеуді қажет ететін "Ізде де, тап" ойындарын ұсынып, зейінін шыңдаңыз.') WHERE id = '428720ac-8db6-44a9-825f-ab25eee4d54f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Дәл көздеу". Бала енді допты немесе кішкентай дорбашаны белгілі бір нысанаға (мысалы, себетке) дәлірек лақтыра алады. Бұл — кеңістіктегі қашықтықты бағалау (spatial estimation) және күшін реттеу қабілетінің дамуы. Үйде онымен бірге "Нысанаға тигіз" сайысын ұйымдастырыңыз; бұл қол мен көз үйлесімін де жақсартады.') WHERE id = '5a34a884-0d1a-4ecc-8aaf-0538071d5d58';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде "Неліктен?" сұрағынан "Қалай?" сұрағына көшу. Енді ол оқиғалардың себебін ғана емес, қалай жүзеге асатынын да сұрайды: "Көлік қалай жүреді?", "Жаңбыр қалай жауады?". Жауап бергенде қарапайым физикалық заңдылықтарды (мысалы, "дөңгелектер айналады") түсіндіру арқылы оның ғылымға деген қызығушылығын арттырыңыз.') WHERE id = '43f973d1-c670-48fb-b082-c963d974b2cb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы "Композиция құрастыру". Бала сурет салғанда енді бір-бірімен байланысты бірнеше нысанды бір параққа орналастырады: "Бұл — үй, ал мынау — оның жанындағы ағаш". Бұл оның айналасындағы әлемді біртұтас әрі жүйелі түрде түсіне бастағанын көрсетеді.') WHERE id = '4fc62a39-6aec-4659-8e0d-de5a572b7f58';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '"Өзін-өзі реттеу (Self-regulation)". Бала енді ашуланғанда "Мен ашуландым!" деп, физикалық әрекетті (мысалы, ұруды) сөзбен алмастыруға тырысады. Бұл — эмоциялық зерденің дамуындағы ең үлкен серпілістердің бірі. Ол сезімін білдіргенде, мұқият тыңдап, "Сезіміңді сөзбен жеткізгенің үшін сені мақтан тұтамын" деп қолдаңыз.') WHERE id = '2e78bbc8-d3e0-46e9-b6f4-fd06f0ff0e92';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Рөлдік ойындардағы диалог». Енді бөпе ойын барысында ұзақ диалогтер құрады: «Сен дүкенге келдің, менен нан сұрайсың...». Осындай ойындар арқылы ол әлеуметтік нормалар мен қарым-қатынас әдебін байқап көреді. Оның сценарийіне ілесіп, осы шығармашылық үдеріске қатысыңыз.') WHERE id = 'c878d5a6-c839-4863-9ea6-c1e45caf4ee6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Қарама-қарсы ұғымдарды ажырату». Бөпе енді «ыстық-суық», «биік-аласа», «ауыр-жеңіл» ұғымдарын толық ажыратады. Онымен «Керісінше айт» ойынын ойнаңыз: Сіз «үлкен» деңіз, ал ол «кішкентай» десін. Бұл оның сөздік қорын да, абстрактілі салыстырмалы ойлауын да дамытады.') WHERE id = '96a1b8b4-4a53-4821-8a70-36e9af7db4b1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Баспалдақпен қозғалу». Бөпе енді баспалдақпен сенімді түрде көтеріліп-түседі және кейде қолында ойыншығы болса да, тепе-теңдігін сақтай алады. Бұл — қозғалыс кезіндегі тепе-теңдіктің жоғары деңгейі. Әрдайым жанында болыңыз, бірақ оған өз бетінше қимылдауға сенім беріңіз.') WHERE id = 'e31518b3-755f-43f6-a042-c5c881774776';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қиял мен әңгіме». Бөпе Сізге өзі ойдан шығарған шағын ертегілерін айтып беруі мүмкін. Бұл ертегілерде шындық пен қиял араласып жатады. Оның әңгімелерін «Шынымен бе?» немесе «Содан кейін не болды?» деген қызығушылық танытатын сұрақтармен қолдаңыз. Бұл болашақта оның еркін әрі мәнерлі сөйлеуіне көмектеседі.') WHERE id = '1285abea-7296-4d22-a83f-6877ea839c11';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Жеңіс пен жеңіліс». Бөпе енді ойындарда жеңіліп қалуды бұрынғыдан сабырлырақ қабылдайды (әрдайым болмаса да). Оның «Тағы бір рет ойнайықшы» деп қайтадан талпынуы — ерік-жігерінің белгісі. «Ең бастысы — ойынға қатысу» деп, өмірде қажет осы маңызды дағдыны әрдайым атап өтіңіз.') WHERE id = 'ab47da7b-7dd4-423e-bf69-3500dd83cc2f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бөпе енді «егер... онда...» логикасын күрделі әлеуметтік жағдайларда қолданады: «Егер мен оған ойыншығымды берсем, ол да маған өз ойыншығын береді». Бұл — өзара қарым-қатынастың негізі. Онымен «Нәтижесі қандай болады?» ойынын ойнаңыз (мысалы, «Гүлге су құймасақ, не болады?»). Бұл оның алдағыны болжай білу қабілетін дамытады.') WHERE id = 'd6bf3a90-b7f5-4d81-9101-4bd23f1bc25d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Биіктіктен секіру». Бала енді белгілі бір биіктіктен (мысалы, аласа басқыштан) тепе-теңдігін жоғалтпай, екі аяғымен секіріп түсе алады. Бұл тізе және тобық буындарының нығайғанын көрсетеді. Оған тізесін сәл бүгіп, «жұмсақ қонуды» үйретіңіз.') WHERE id = '2795a26f-4a85-42cd-9860-03afd8411f60';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Уақыттың абстрактілі ұғымдары». Ол енді «демалыс күндері», «мерекеде», «туған күнде» сияқты ауқымды уақыт аралықтарын түсінеді. Онымен жақында болатын маңызды оқиға (мысалы, серуен) туралы сөйлескенде, «3 күннен кейін» деген сияқты тіркестерді қолданып, уақыт туралы түсінігін тереңдетіңіз.') WHERE id = '4dbdf376-fb0e-469f-bb2e-b3be32d8d1c8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Әріптерді көшіру». Бала енді кейбір қарапайым әріптерді (мысалы, A, O, T) көргеніндей көшіріп жазуға тырысады. Бұл таңбалардың көру және қимыл жадына қатар сақталуының белгісі. Оған құм салынған науаға немесе саусақ бояуымен әріптерді «жазуды» ұсыныңыз.') WHERE id = '83f43947-4f06-425b-801a-dd053a64d6b1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару: қалауын кейінге қалдыру». Бала енді бір сый үшін біраз күту керек екенін (мысалы, «тамақтан кейін тәтті жейсің») қабылдай алады. Бұл ерік-жігер мен өзін-өзі басқарудың (delayed gratification) дамуы. Оның шыдамдылығын міндетті түрде атап өтіп, мақтаңыз; бұл болашақтағы табысты оқу өмірінің негізі.') WHERE id = '51891c5d-a6e3-40d4-8ba5-38112ce2f223';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Топтық жанашырлық». Бала енді досы жылағанда оған жай ғана қарап тұрмай, «Не болды?» деп сұрайды немесе Сізге хабарлайды. Бұл — эмпатияның белсенді кезеңі. Оның қамқорлығын «Сен өте мейірімді доссың» деп қолдаңыз.') WHERE id = '9932ed27-e891-4fec-aac9-e64c5a418a49';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Қосудың негіздері». Бала енді 2 ойыншықтың жанына тағы 1 ойыншық қойғанда, барлығы 3 болғанын санамай-ақ (немесе жылдам санап) түсіне алады. Күнделікті істер кезінде «Сенде 2 алма бар еді, мен тағы 1 алма бердім, енді нешеу болды?» деген сияқты шағын математикалық жұмбақтар құрастырыңыз.') WHERE id = '5f9e5aa3-02e0-4bd3-85bf-ad954730aed0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық тұрақтылық: «Өзін-өзі жұбату». Бала енді сәл сүрініп құлағанда немесе бір ісі сәтсіз болғанда бірден жыламай, өзіне «Ештеңе болған жоқ» деп, орнынан тұра алады. Бұл — эмоциялық төзімділіктің маңызды белгісі. Сіз оның батылдығын әрдайым «Сен өте мықтысың!» деп қолдап жүріңіз.') WHERE id = 'c0cb0b02-4a51-4012-b51b-53868aad0bf0';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді «сағат» ұғымына қызығушылық таныта бастайды. Ол «Сағат неше болды?» деп сұрауы мүмкін. Оған уақытты минуттармен емес, оқиғалар арқылы түсіндіріңіз: «Үлкен тіл мына жерге келгенде, біз серуендеуге шығамыз». Бұл оған уақыттың өлшенетін ұғым екенін түсінуге көмектеседі.') WHERE id = '3a58737c-1dc5-47f3-86ee-31c959892712';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы «айқаспалы үйлесімділік». Бала енді бір орында адымдап тұрып, оң қолын сол тізесіне (және керісінше) тигізе алады. Бұл қимыл мидың екі жартышарының бір мезгілде жұмыс істеуін талап етеді және болашақта оқу мен жазуды меңгеруді жеңілдетеді.') WHERE id = '86960e2f-7035-4c14-a9a6-baeb23c3ea3d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «өткен оқиғаның егжей-тегжейі». Бала бірнеше күн бұрын болған оқиғаны ретімен айтып бере алады. «Әжемнің үйіне барғанда, біз сол жерде мысық көрдік, ол ағашқа шығып кеткен еді». Оның осы «эпизодтық жадын» нығайту үшін күннің соңында «Бүгінгі ең қызықты оқиға не болды?» деп сұраңыз.') WHERE id = '6caf0def-6055-4b83-9a80-442193cfb9e1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Қағаз қию: күрделі пішіндер». Бала енді қайшымен тек түзу сызық бойымен ғана емес, ирек сызықтарды немесе үлкен шеңберді де қиып алуға тырысады. Бұл қол мен көз үйлесімділігінің өте жоғары деңгейде дамығанын көрсетеді.') WHERE id = '64c3b0ce-8c21-4147-b606-f32ae65475bf';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Оң және сол ұғымы». Бала енді оң және сол қолын (әзірге толық дәл болмаса да) ажырата алады. Оған «Қасықты оң қолыңмен ұста» немесе «Шұлығыңды сол аяғыңа ки» деп айтып, кеңістікті бағдарлау қабілетін нығайтыңыз. Бұл дағды болашақта әріптердің бағытын шатастырмау үшін маңызды.') WHERE id = '51c70f08-e08e-4a17-97ca-6373b3c435eb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене үйлесімділігі: "Бір аяқпен секіру (Hop-stop)". Бала енді бір аяқпен қатарынан 2-3 рет секіре алады. Бұл тепе-теңдікті жақсы сақтауды әрі аяқ бұлшықеттерінің күшін қажет етеді. Онымен үйде "Классики" ойынын ойнап, қимыл үйлесімділігін одан әрі жетілдіріңіз.') WHERE id = '5d319604-f8fa-4e75-83e3-e78cf306cb47';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Сипаттап әңгімелеу". Бала салған суреті немесе көрген оқиғасы туралы бірізді сөйлемдермен айтып береді. "Мұнда бір ит болды, ол жүгірді, содан кейін ағашқа шықты...". Оның оқиғаны ретімен баяндауына назар аударыңыз. Бұл оның миында оқиғалардың логикалық ретін қалай құратынын көрсетеді.') WHERE id = '5e32473e-0836-4d23-8816-7e98014c394b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1400 күндік үлкен жеңіс! Балаңыз 46 айға толды. Ол енді өзін түсінетін, өзгелердің сезіміне ортақтаса алатын және әлемді логика арқылы зерттейтін кішкентай "ғалым". Осы 1400 күн бойы Сіз балаңыз үшін ең сенімді айлақ әрі ең жақсы ұстаз болдыңыз. Сіз керемет анасыз!') WHERE id = 'af7c9867-8fc8-42cc-b62a-1044c801bdef';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '47-ші айға қош келдіңіз! Бала енді "жауапкершілік" ұғымын жақсырақ түсінеді. Оған үйде шағын "міндеттер" беріңіз (мысалы, өсімдіктерді суару немесе дастарқанға майлық қою). Бұл оның өзін отбасының маңызды әрі пайдалы мүшесі ретінде сезінуіне көмектеседі. Оның бұл талпынысын міндетті түрде атап өтіп, алғыс айтыңыз.') WHERE id = '13b68bb4-0e80-4802-bd12-f626258d3f54';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Кезектескен қадамдармен жүгіру". Бала енді жүгіріп келе жатып, баспалдақтардан немесе кедергілерден әр қадам сайын аяғын кезектестіріп, ырғақты түрде өте алады. Бұл дененің төменгі бөлігінің күші мен көру-қимыл жоспарлауының қаншалықты жетілгенін көрсетеді.') WHERE id = '8fba68a9-4860-41c9-9d6a-0aabd4a4dc7d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Фонетика және әріптер". Бала енді сөздердің қандай дыбыстан басталатынын ажырата алады: "Алма ''А'' әрпінен басталады". Онымен "Дыбыс аулау" ойынын ойнаңыз; бөлмеден белгілі бір дыбыстан басталатын заттарды табуын сұраңыз. Бұл болашақта оқу мен жазу дағдыларын меңгерудің ең маңызды негізі.') WHERE id = '4c5fdac9-9874-4896-80d4-6960b6675b1b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада «Қарындашты дұрыс ұстау (Tripod)». Бала енді қарындашты бас бармақ, сұқ саусақ және ортаңғы саусақпен («үштаған» әдісімен) сенімдірек ұстайды. Бұл оған егжей-тегжейлі суреттер салуға және әріптерді көшіріп жазуға мүмкіндік береді. Саусақ бұлшықеттерін жаттықтыру үшін оған жуандығы әртүрлі қарындаштар беріңіз.') WHERE id = '01cf8b7d-9668-4ab1-a360-d6968cb99749';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару: Ережелердің мәні». Бала енді ережелерді Сіз айтқандықтан ғана емес, олардың мәнін түсінгендіктен орындауға тырысады. «Жолда жүргенде қолыңнан ұстаймын, өйткені көліктер бар». Оған ережелердің қауіпсіздік пен тәртіп үшін маңызды екенін түсіндіре беріңіз; бұл — ішкі тәртіптің негізі.') WHERE id = 'd91c45ef-c67b-4312-9a1e-572e86ed0a0e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Әділ бөлісу». Бала енді ойыншықтарды немесе тәттілерді достарына тең бөліп беруге қызығушылық танытады: «Біреуі саған, біреуі маған». Бұл — әлеуметтік эмпатия мен бастапқы математикалық түсініктердің (бөлу ұғымының) үйлесуі.') WHERE id = '2a9fd489-5479-4444-9ad0-d9ca9e6d37c8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Заттарды жіктеу». Бала енді заттарды түріне де, қолданылатын орнына да қарай топтастырады: «Мыналар асүйге арналған, ал мыналар жатын бөлмеге арналған». Бұл оның миындағы ақпарат қорының жүйелі әрі иерархиялық түрде қалыптасып жатқанын көрсетеді.') WHERE id = 'b49a3e45-1e44-429c-b3ab-7432f30a4a37';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Допты ұстау және лақтыру (Интеграция)». Бала енді допты ұстап алғаннан кейін оны бірден нысанаға лақтыра алады. Бұл — бірізді қимылдардың өзара жалғасуы. Онымен саябақта «Лақтыр да ұста» ойынын ойнап, реакция жылдамдығы мен ептілігін арттырыңыз.') WHERE id = 'b2cee277-0949-412e-af09-df96b2fd9cfd';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Күрделі сөйлем құрылымы». Бала енді «егер», «өйткені», «алайда» сияқты жалғаулықтарды қолданып, ұзақ әрі логикалық сөйлемдер құрайды. Оның сөзін бөлмей тыңдаңыз және «Демек, сен осылай ойлайсың...» деп, ойын кеңейтуге көмектесіңіз. Бұл оның өз ойын жеткізу қабілетін дамытып, сөздік қорын белсенді қолдануына ықпал етеді.') WHERE id = 'eaf98320-82a4-46ba-81fe-43fd023e6b82';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Топтағы көшбасшылық». Ойын кезінде бала басқа балаларға «Сен мұнда тұр, ал сен мынаны істе» деп рөлдерді бөліп бере бастайды. Осылайша ол әлеуметтік иерархияны түсінуі мен ұйымдастырушылық қабілетін сынап көреді. Оның көшбасшылық жасауға талпынысын бақылап, әділ болуына көмектесіңіз.') WHERE id = 'ed221959-c928-4692-880d-29170d62352e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Санның тұрақтылығын түсіну». Бірдей мөлшердегі тастарды бір жағына бір-біріне жақын, ал екінші жағына араларын алшақ етіп қойсаңыз, бала екі жақтағы тастар санының бірдей екенін түсіне бастайды. Бұл — көзбен көргенге алданып қалудан логикалық қорытынды жасауға өту кезеңі.') WHERE id = '55c3f5e4-d3a4-465e-b035-b83e41b450d4';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Бір аяқпен секіру». Бала бір аяғымен алға қарай бірнеше рет секіре алады. Бұл тепе-теңдікті сақтауды да, аяқтың серпінді күшін де қажет етеді. Онымен үйде «Классик» ойынын ойнауға таптырмас уақыт.') WHERE id = 'ddfca79d-8eb7-4cbd-84fd-61e54d7153db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сөз құрамындағы дыбыстар». Бала сөздің соңындағы дыбыстарды да ажырата бастайды (мысалы, «алма» сөзінің «а» дыбысымен аяқталатынын айта алады). Бұл — фонематикалық есту қабілетінің жоғары деңгейі. Онымен «Соңғы әріптен сөз тап» (сөз тізбегі) ойынын ойнап, сөздік қорын және есту зейінін дамытыңыз.') WHERE id = '3863c552-322d-4dc8-a917-02d61270f313';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сәтсіздік және стратегия». Баланың бір ісі ойдағыдай болмағанда, ол бірден жыламай, «Басқаша жасап көрсем ше?» деп ойланады. Бұл — «дамуға бағытталған ойлау жүйесінің» (growth mindset) негізі. Оны нәтижесі үшін емес, жаңа жол іздегені үшін міндетті түрде мақтаңыз.') WHERE id = 'da0d4f8a-08c6-45ad-9022-933f9025eb01';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала заттарды енді тек сыртқы көрінісіне ғана емес, жасалған материалына қарай да ажыратады: «Мынау пластиктен, ал мынау темірден жасалған». Оған текстурасы әртүрлі заттарды беріп, олардың айырмашылықтарын сұраңыз. Бұл қоршаған ортаны егжей-тегжейлі талдауына және физикалық әлем туралы білімін жүйелеуіне көмектеседі.') WHERE id = 'ec9b72ac-4600-4d72-8d5e-3a0bc232d29c';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Дәл секіру». Бала енді белгілі бір нысанаға қарай (мысалы, жердегі шеңбердің ішіне) секіре алады. Бұл оның тепе-теңдікті сақтай алатынын әрі кеңістіктегі арақашықтықты есептей білетінін көрсетеді. Саябақтағы «тастан тасқа секіру» ойыны ол үшін тамаша жаттығу болады.') WHERE id = 'f6611b06-b8bc-42ff-84b4-2e17ea2e10d6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қарама-қарсы ұғымдарды ажырату». Бала енді «ыстық-суық», «биік-аласа», «ауыр-жеңіл» ұғымдарын толық ажырата алады. Онымен «Керісінше айт» ойынын ойнаңыз: Сіз «үлкен» деңіз, ал ол «кіші» деп жауап берсін. Бұл оның сөздік қорын да, абстрактілі салыстырмалы ойлау қабілетін де дамытады.') WHERE id = '00735398-0d89-4428-a943-f4a27fc19021';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пішінді көшіріп салу: үшбұрыш пен айқыш». Бала енді түзу сызықтарды қиылыстырып, айқыш (+) сала алады және үшбұрышқа ұқсас пішіндер салуға тырысады. Бұл — жазу дағдысының бастапқы негізі. Оған түрлі түсті қарындаштар мен таза қағаз беріп, осы «геометриялық жаңалықтарын» қолдаңыз.') WHERE id = '1b117df4-43a4-4780-a2e3-365c2acc3518';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару: қалауын кейінге қалдыру». Бала енді сыйлыққа қол жеткізу үшін біраз күту керектігін (мысалы, «тамақтан кейін тәтті жейміз») қабылдай алады. Бұл — ерік-жігері мен өзін-өзі басқару қабілетінің (қалауын кейінге қалдыра білудің) дамуы. Оның осындай шыдамдылығын міндетті түрде атап өтіңіз: бұл болашақтағы оқу жетістіктерінің кілті.') WHERE id = '93c7b1b4-9941-4328-bd03-c48ffc7f605f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Топтық жанашырлық». Бала енді досы жыласа, оған жай ғана қарап тұрмай, «Не болды?» деп сұрайды немесе Сізге хабарлайды. Бұл — эмпатияның белсенді кезеңі. Оның осы қамқор мінезін «Сен өте мейірімді доссың» деп қолдаңыз.') WHERE id = 'e9a7f349-2186-4929-ba3f-64f7d951af57';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Қосудың негіздері». Бала енді 2 ойыншықтың жанына тағы 1 ойыншық қойғанда, барлығы 3 болғанын санамай-ақ (немесе тез санап) түсіне алады. Күнделікті істер кезінде «Сенде 2 алма болды, мен саған тағы 1 алма бердім, енді нешеу болды?» деген сияқты шағын математикалық жұмбақтар құрастырыңыз.') WHERE id = '6d1eeaa2-0164-4cca-94b4-9c14e8d79d60';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Топтық ынтымақтастық». Бала енді досы жылап қалса, оған жай ғана қарап тұрмай, «Не болды?» деп сұрайды немесе Сізге хабарлайды. Бұл — эмпатияның белсенді кезеңі. Оның қамқорлығын «Сен өте мейірімді доссың» деп қолдаңыз.') WHERE id = 'ed4539aa-f1cf-4dd1-97f9-a5cf3f6b499d';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Қосу негіздері». Бала енді 2 ойыншықтың жанына тағы 1 ойыншық қойғанда, барлығы 3 болғанын санамай-ақ немесе жылдам санау арқылы түсіне алады. Күнделікті істер кезінде «Сенде 2 алма бар еді, мен тағы 1 алма бердім, енді нешеу болды?» деген сияқты шағын математикалық жұмбақтар құрастырыңыз.') WHERE id = '321e201a-5cd6-485a-a700-1c1f11885a2b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: «Баспалдақпен қозғалу». Бала енді баспалдақпен сенімді көтеріліп-түседі және кейде қолында ойыншық болса да, тепе-теңдігін сақтай алады. Бұл — динамикалық тепе-теңдіктің жоғары деңгейі. Әрдайым жанында болыңыз, бірақ оған өздігінен еркін қозғалуға сенім беріңіз.') WHERE id = '26b9ae52-0022-4e15-934b-ad179ba90589';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қиял мен әңгіме». Бала Сізге өзі ойдан шығарған шағын ертегілерін айтып бере алады. Бұл ертегілерде шынайы өмір мен қиял араласып жатады. Оның әңгімелерін «Рас па?» немесе «Содан кейін не болды?» деген сияқты қызығушылық танытатын сұрақтармен қолдаңыз. Бұл болашақта оның еркін әрі мәнерлі сөйлеуіне көмектеседі.') WHERE id = 'e96b1dc7-ba0c-47d3-b15a-cb6918e2bc9b';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '4 жасқа толуына небәрі 30 күн қалды! Бала қазір мектепке дейінгі кезеңнің ең жемісті шағында. Ол енді өз талғамы, қорқыныштары мен сансыз сұрақтары бар дербес тұлғаға айналды. Сіз бұл жолдан білім мен сүйіспеншілікке сүйеніп өттіңіз. Anacan әрдайым Сіздің жаныңызда!') WHERE id = '34fd4a41-2c8b-49b5-b2b0-6911f5bb04ab';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды тек сыртқы көрінісіне қарай емес, қандай топқа жататынына қарай да жіктейді. «Бұлар — теңіз жануарлары, ал бұлар — орман жануарлары». Бұл оның санасындағы ақпараттың ғылыми санаттарға бөліне бастағанын көрсетеді. Онымен «Кім қайда мекендейді?» ойынын ойнаңыз.') WHERE id = 'bacec645-5384-4fc1-94d1-94b2914a27a1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикада «Қағаз қию: күрделі пішіндер». Бала енді қайшымен күрделі пішіндерді (мысалы, жұлдызды немесе кішкентай жануардың сұлбасын) жиегімен қиып алуға тырысады. Бұл қол мен көз үйлесімінің қаншалықты жетілгенін көрсетеді. Оған түрлі түсті қағаздар беріңіз.') WHERE id = '619d1623-d881-46f6-a718-4a537172efc7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару: эмоциялық дипломатия». Бала қалағаны болмаған кезде енді айқайлаудың орнына Сізге өз уәжін айта алады: «Бірақ мен мұны қатты қаладым, өйткені...». Оның диалог құруға деген талпынысын бағалаңыз. Сезімін түсініп, қабылдайтыныңызды білдіріңіз, бірақ ережелердің неліктен өзгермейтінін де сабырмен түсіндіріңіз.') WHERE id = 'd8f54a1a-d4b0-4c91-b361-1e6376bfa2db';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықта «Ережелерді сақтау». Бала енді үстел ойындарын (мысалы, доминоны немесе қарапайым сандық ойындарды) ережені бұзбай ойнауға ерекше мән береді. Бұл — әлеуметтік бейімделудің маңызды кезеңі. Ережелерді сақтаған кезде оны: «Өте адал әрі сабырлы ойнадың», — деп жігерлендіріңіз.') WHERE id = '111e7db0-d36d-44a0-97d8-10b28cd566ca';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамуда «Мөлшердің сақталуы: көлем сынағы». Бірдей мөлшердегі ермексаздың бірін домалақтап, екіншісін ұзын «жылан» пішініне келтірсеңіз, бала олардың мөлшері бірдей болып қалғанын түсіне бастайды. Бұл — көзбен көргенге алданып қалудан логикалық қорытынды жасауға өтетін кезең. Осындай тәжірибелерді бірге жасап көріңіздер.') WHERE id = '0655a03a-60b9-48e1-b285-1d3c83082836';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылдарын үйлестіру: «Бір аяқпен секіру». Бала енді бір аяғымен алға қарай бірнеше рет секіре алады. Бұл тепе-теңдікті де, аяқтың серпінді күшін де қажет етеді. Онымен үйде «Классик» ойынын ойнауға таптырмас уақыт; бұл кеңістікті бағдарлау қабілетін де дамытады.') WHERE id = 'c5a0358e-6841-4ba2-8c21-cb976413e324';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеуде «Қиял мен логиканы ұштастыру». Бала Сізге өзі ойлап тапқан, бірақ оқиғалары логикалық ретпен өрбитін ертегілерді айтып бере алады. «Бір күні бір робот болыпты, оның қуаты таусылып, тоқтап қалыпты...». Оның әңгімелерін «Содан кейін не болды?» деген сияқты сұрақтармен қолдаңыз. Бұл болашақта оның еркін әрі мәнерлі сөйлеуіне көмектеседі.') WHERE id = '5fe788e8-9a0a-4448-9455-65cf7a8679b1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Баспалдақпен еркін қозғалу". Бала баспалдақпен сенімді көтеріліп-түседі және кейде қолында ойыншық болса да, тепе-теңдігін сақтай алады. Бұл — қозғалыс кезіндегі тепе-теңдіктің жоғары деңгейі. Әрдайым жанында болыңыз, бірақ оған еркін қозғалуға мүмкіндік беріп, сенім білдіріңіз.') WHERE id = '28cfd5f7-ecbc-4133-9e9d-cc5c82140054';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Қиял мен әңгіме". Бала Сізге өзі ойлап тапқан шағын ертегілерін айтып беруі мүмкін. Бұл ертегілерде шындық пен қиял араласып жатады. Оның әңгімелерін "Рас па?" немесе "Содан кейін не болды?" деген қызығушылық білдіретін сұрақтармен қолдаңыз. Бұл болашақта оның анық әрі мәнерлі сөйлеуіне көмектеседі.') WHERE id = 'c414dc79-8944-48c3-a5d5-e50145e600bc';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '1430 күндік жеңіс! Бала 47 айға толды. Ол енді өзін танып-білетін, өзгелердің сезіміне ортақтаса алатын және әлемді логика арқылы зерттейтін кішкентай "ғалым". Осы 1430 күн бойы Сіз балаңыз үшін ең сенімді қорған әрі ең жақсы ұстаз болдыңыз. Сіз керемет анасыз!') WHERE id = '8f2e9299-bb7b-4d28-9fbc-c07c7ba2a262';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '48-айға (4 жасқа) дейінгі кері санақ басталды! Бала әлеуметтік ойындарда "мен" мен "біздің" арасындағы айырмашылықты толық түсініп, қолдана бастады. Егер ол "Кел, бірге кеме жасайық, сен желкенді ұста, ал мен рульді ұстаймын" деп міндеттерді бөліссе, бұл — ынтымақтастық қабілетінің ең жоғары деңгейі. Оның командалық рухын қолдаңыз; бұл болашақ мектеп өмірі үшін маңызды.') WHERE id = 'b940be7d-ee82-4c09-8760-e2ce9294193f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылындағы "Дәл бұрылыстар". Бала бар жылдамдығымен жүгіріп келе жатып, кенет тоқтай немесе тепе-теңдігін жоғалтпай шұғыл бұрыла алады. Бұл — вестибулярлық жүйе мен бұлшықеттерді басқарудың толық үйлесімді жұмысы. Саябақта оған арнап шағын "кедергілер жолағын" құрыңыз.') WHERE id = 'ce453995-5119-4943-ace6-1439bc5d5820';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Дыбыстарды талдау". Ол енді сөздердің басындағы ғана емес, соңындағы дыбыстарды да ажырата бастайды: "Алма ''А'' дыбысымен аяқталады". Бұл — фонематикалық есту қабілетінің дамуы. Онымен "Соңғы дыбыстан басталатын жаңа сөз тап" ойынын ойнап, тілдік түйсігін жетілдіріңіз.') WHERE id = 'e258838d-b844-4e68-840e-2eb0ef520682';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Эмоциялық төзімділік: «Сәтсіздікке қарсы жаңа стратегия». Баланың бір ісі (мысалы, пазл құрастыру) ойдағыдай шықпаса, ол бірден ашуланбай, «Мүмкін, мұны былай қойып көрсем ше?» деп жаңа жолдар іздейді. Бұл — «дамуға бағытталған ойлау жүйесінің» (growth mindset) негізі. Оның нәтижесін емес, жаңа жол табуға деген талпынысын міндетті түрде мақтаңыз.') WHERE id = '19cb7d19-f480-4e1f-805a-267dba1df2a8';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Бала енді заттарды тек сыртқы көрінісіне ғана емес, жасалған материалына қарай да ажыратады: «Бұл пластик, ал мынау темір». Оған текстурасы әртүрлі заттарды беріп, олардың айырмашылықтарын сұраңыз. Бұл қоршаған ортаны егжей-тегжейлі талдап, физикалық әлем туралы білімін жүйелеуге көмектеседі.') WHERE id = '0ec14802-bab2-45c4-8cbf-788bdfa85e13';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Қимыл-қозғалыстағы «Дәл секіру». Бала енді белгілі бір нысанаға қарай (мысалы, жердегі шеңбердің ішіне) секіре алады. Бұл оның тепе-теңдік сақтау және кеңістіктегі қашықтықты есептеу қабілетін көрсетеді. Саябақтағы «тастан тасқа секіру» ойыны ол үшін тамаша жаттығу болады.') WHERE id = '0ddedeb7-e832-48ca-923d-05838885cdc1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Қарама-қарсы ұғымдарды жіктеу». Бала енді «ыстық-суық», «биік-аласа», «ауыр-жеңіл» ұғымдарын толық ажыратады. Онымен «Керісінше сөзді тап» ойынын ойнаңыз: Сіз «үлкен» десеңіз, ол «кіші» десін. Бұл оның сөздік қорын да, абстрактілі салыстырмалы ойлау қабілетін де дамытады.') WHERE id = '3810cfc8-49ab-40fa-b90d-2edf9dc84fae';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Пішінді көшіру: Үшбұрыш пен Айқыш». Бала енді түзу сызықтарды қиылыстырып, айқыш (+) сала алады және үшбұрышқа ұқсас пішіндер салуға тырысады. Бұл — жазу дағдысының бастапқы негізі. Оған түрлі түсті қарындаштар мен таза қағаз беріп, осы «геометриялық жаңалықтарын» қолдаңыз.') WHERE id = 'dfeb7b05-cea8-4a6f-b41b-005f3d3c488e';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару: Қалауын кейінге қалдыру». Бала енді сыйақы алу үшін сәл ұзағырақ күту керек екенін (мысалы, «тамақтан кейін тәтті жеуге болады») қабылдайды. Бұл — ерік-жігер мен өзін-өзі басқару қабілетінің (delayed gratification) дамуы. Оның бұл сабырын міндетті түрде атап өтіңіз; бұл болашақтағы табысты оқу өмірінің кілті.') WHERE id = '988ae101-5f2f-4a86-a365-28a27e843965';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене белсенділігіндегі «Жылдам жүгіру және үйлесімді тоқтау». Бала енді бар жылдамдығымен жүгіріп келе жатып, Сіздің «Тоқта!» деген нұсқауыңыз бойынша құламай әрі алға сүрінбей бірден тоқтай алады. Бұл — бұлшықеттерді басқару мен есту-қимыл реакциясының ең жоғары деңгейі. Саябақта осы ойынды үнемі қайталап ойнаңыздар.') WHERE id = 'ea737131-3977-4085-b4c4-94dd4ae125f1';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі «Сыпайы пікірлесу». Бала енді қалағанын алу үшін «Өтінемін, бола ма?» деп қана қоймай, себебін де түсіндіреді: «Өйткені мен оны қатты жақсы көремін». Сіздің сыпайы жауабыңыз оның әлеуметтік қарым-қатынас тілін қалыптастырады. Оның әрбір сыпайы өтінішін «Ойыңды осылай әдемі жеткізгенің үшін саған жауап беру маған жағымды» деп бағалаңыз.') WHERE id = '0bfff590-18d1-438c-bef2-c5dac59fc7e3';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Ұсақ моторикадағы «Әріптер мен сандарды көріп көшіру». Бала енді өз есімінің әріптерін немесе «1, 2, 3» сияқты сандарды қағазға жазуға тырысады. Бұл — қимыл мен көру жадының үйлесуі. Оған түрлі түсті қарындаштар беріп, «жазғандарын» үйдің көрінетін жеріне іліп қойыңыз.') WHERE id = '65fb665a-a079-4bde-be1e-8536275e5fd6';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '«Өзін-өзі басқару: эмоциялық дербестік». Бала енді кішкентай қиындыққа тап болғанда (мысалы, ойыншығы шашылып қалса), бірден Сізге жүгірмей, алдымен өзі жөндеуге тырысады. Бұл — «менің қолымнан келеді» деген сенімнің нығаюы. Оның өз бетінше жасаған осындай әрекеттерін бақылап, тек көмек қажет болғанда ғана араласыңыз.') WHERE id = '5a2e55ce-3f97-41a9-965d-b857b33a020f';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Әлеуметтік мінез-құлықтағы «Ережелерді түсіндіру». Ол енді кішкентай балаларға немесе ойыншықтарына ойын ережелерін түсіндіреді: «Алдымен мен, содан кейін сен». Бұл — ішкі тәртіп пен көшбасшылық қабілеттің белгісі. Оның осы «ұстаздық» қырын қолдаңыз.') WHERE id = '1e4b1da3-fa3d-4b83-9554-7fdd901b9dfb';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Танымдық дамудағы «Уақыт күнтізбесі». Бала енді «3 күн қалды» немесе «Демалыс күндері барамыз» сияқты тіркестерді түсінеді. Туған күні жақындағанда «кері санау күнтізбесін» жасаңыздар. Әр өткен күнді белгілеп отыру оған уақыттың өтуін нақтырақ түсінуге көмектеседі.') WHERE id = 'e9a169de-bc44-43dd-b6f0-9adaff7e3796';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Дене қимылын үйлестіру: "Допты аяқпен нысанаға тигізу". Бала енді допты жай ғана теппей, оны белгілі бір нысанаға (мысалы, екі тастың арасына) бағыттауға тырысады. Бұл кеңістіктегі қашықтықты есептеуді және аяқ бұлшықеттерінің дәл жұмыс істеуін талап етеді.') WHERE id = '1c5a132d-9357-46a5-b5fe-17d6baae9cac';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, 'Сөйлеудегі "Күрделі әңгіме құрастыру". Бала енді өзі ойлап тапқан ертегілерінде "өйткені", "алайда", "сондықтан" сияқты жалғаулықтарды қолданып, оқиға желісін құрады. Оның әңгімелерін мұқият тыңдап, "Сеніңше, кейіпкер одан кейін не істеді?" деген сияқты сұрақтар арқылы жаңа мәліметтер қосуға ынталандырыңыз.') WHERE id = '24dad4d0-2c9d-4d1c-bb0a-41d9b402e0e7';
UPDATE public.mommy_daily_messages SET message_kk = COALESCE(message_kk, '4 жасқа толуына небәрі 20 күн қалды! Бала сәбилік әдеттерінен толық арылып, өзіндік мінезі бар кішкентай тұлғаға айналды. Осы 1460 күн бойы Сіз оның даму жолындағы ең үлкен жарық болдыңыз. Оның жетістіктері — Сіздің сүйіспеншілігіңіздің жемісі. Сіз кереметсіз!') WHERE id = 'd76fe554-fd7b-4db0-9296-a5ba3be690d0';

