UPDATE public.nutrition_tips SET title_kk = COALESCE(title_kk, 'Жұмыртқа'), content_kk = COALESCE(content_kk, 'Сапалы ақуызға және мидың дамуы үшін маңызды холинге бай. Бөпенің жүйке жүйесінің қалыптасуына көмектеседі.') WHERE id = 'a551c688-076a-470a-9862-b199c56afee1';
UPDATE public.nutrition_tips SET title_kk = COALESCE(title_kk, 'Фолатқа бай тағамдар'), content_kk = COALESCE(content_kk, 'Жүктіліктің алғашқы триместрінде фолат өте маңызды. Қою жасыл жапырақты көкөністер, цитрус жемістері мен бұршақ тұқымдастар — оның жақсы көздері.') WHERE id = '3cd9d02f-2306-400b-bf13-48f59e00d6e0';
UPDATE public.nutrition_tips SET title_kk = COALESCE(title_kk, 'Темірді тұтыну'), content_kk = COALESCE(content_kk, 'Жүктілік кезінде темірге деген қажеттілік артады. Қызыл ет, саумалдық пен жасымық — темірдің жақсы көздері.') WHERE id = 'c72c92e6-079c-4154-b75a-f4bc2185c69d';
UPDATE public.nutrition_tips SET title_kk = COALESCE(title_kk, 'Кальцийдің маңызы'), content_kk = COALESCE(content_kk, 'Кальций бөпенің сүйектерінің дамуы үшін маңызды. Сүт өнімдері, брокколи мен бадам — кальцийдің жақсы көздері.') WHERE id = 'a6924eca-1ccc-46fd-aec6-27df0057d25d';

