UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Сылдырмақты қадағалау'), description_kk = COALESCE(description_kk, 'Сылдырмақты көзбен және есту арқылы қадағалау'), instructions_kk = COALESCE(instructions_kk, '1. Бөпенің назарын аудару үшін сылдырмақты сілкіңіз\n2. Оны әр бағытқа баяу жылжытыңыз\n3. Бөпеге оны ұстап көруге мүмкіндік беріңіз') WHERE id = 'ea96ae3c-ed32-4118-b146-ecbb3a3bb763';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Телефонмен сөйлесу ойыны'), description_kk = COALESCE(description_kk, 'Телефонмен рөлдік ойын ойнау'), instructions_kk = COALESCE(instructions_kk, '1. Бөпеге ойыншық телефон беріңіз\n2. Бөпеге қоңырау шалғандай болыңыз\n3. Бөпені "сөйлесуге" ынталандырыңыз\n4. Кезектесіп сөйлеңіз') WHERE id = 'e08ba272-48b6-4a5f-b44b-0ba7da5cb808';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ақырын ән айту'), description_kk = COALESCE(description_kk, 'Бөпеңізге ақырын ән айтып беріңіз'), instructions_kk = COALESCE(instructions_kk, 'Бөпені бауырыңызға басып, нәзік бесік жырын немесе қарапайым әндер айтып беріңіз. Бөпенің даусыңызға қалай жауап беретініне назар аударыңыз.') WHERE id = 'a3c29297-6e01-48c7-9b34-d7d9d3af361a';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ойыншықтармен етпетінен жату'), description_kk = COALESCE(description_kk, 'Етпетінен жатқанда алдына түрлі түсті ойыншықтар қойыңыз'), instructions_kk = COALESCE(instructions_kk, 'Бөпені етпетінен жатқызыңыз. Қолын созып, басын көтеруге ынталандыру үшін түрлі түсті ойыншықтарды қолы сәл жетпейтін жерге қойыңыз.') WHERE id = 'e0e77763-f782-46a8-bcfe-1cf276ba2cce';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Сумен шолпылдатып ойнау'), description_kk = COALESCE(description_kk, 'Бөпеге суды қолымен шолпылдатуға мүмкіндік беріңіз'), instructions_kk = COALESCE(instructions_kk, 'Таяз ыдысқа жылы су құйыңыз. Бөпеге суды ұстап көріп, шолпылдатып ойнауға мүмкіндік беріңіз. Үнемі мұқият бақылаңыз.') WHERE id = '5cea30c3-38d1-4326-b521-b5428eba62a1';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ұшақ-бөпе'), description_kk = COALESCE(description_kk, 'Бөпені ақырын жоғары көтеріңіз'), instructions_kk = COALESCE(instructions_kk, 'Шалқаңыздан жатып, бөпені нық ұстап, ұшып бара жатқандай ақырын жоғары көтеріңіз. Бұл араларыңыздағы байланысты нығайтуға көмектеседі.') WHERE id = 'eb368346-4c28-48f4-acc2-82c3747e66bf';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Айна алдында етпетінен жату'), description_kk = COALESCE(description_kk, 'Бөпенің айнадан өзін көруі оның дамуын ынталандырады'), instructions_kk = COALESCE(instructions_kk, 'Бөпені жастықтың үстіне етпетінен жатқызыңыз. Алдына айна қойыңыз. Оған айнадағы бейнесін көрсетіңіз.') WHERE id = '20e1c63e-791f-43a8-bb33-84ebfe166368';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Асүй оркестрі'), description_kk = COALESCE(description_kk, 'Кәстрөлдер мен табалар арқылы ырғақ сезімін дамыту'), instructions_kk = COALESCE(instructions_kk, 'Ағаш қасық пен кәстрөлдерді бөпенің алдына қойыңыз. Оларды қалай соғу керектігін көрсетіңіз. Бірге ырғақ құрыңыз.') WHERE id = '5a6d5c7d-3489-4b3d-8210-fbeed43d3536';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қораптан жасалған туннель'), description_kk = COALESCE(description_kk, 'Еңбектеу және зерттеу дағдыларын дамыту'), instructions_kk = COALESCE(instructions_kk, 'Үлкен картон қораптың екі жағын да ашыңыз. Бөпені бір жағынан еңбектеп өтуге ынталандырыңыз. Екінші жағынан оны шақырыңыз.') WHERE id = '8266c528-ae95-47fa-b7f4-28400410ebc2';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Шұлықтан жасалған қуыршақтар'), description_kk = COALESCE(description_kk, 'Қарым-қатынас пен шығармашылық қабілетті дамыту'), instructions_kk = COALESCE(instructions_kk, 'Ескі шұлықтан қуыршақ жасаңыз. Бөпемен қуыршақ арқылы "сөйлесіңіз". Әртүрлі дыбыстар шығарыңыз.') WHERE id = 'fc6ee2c8-0599-4677-994a-dc1385d83024';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Түрлі текстуралар жолы'), description_kk = COALESCE(description_kk, 'Әртүрлі текстуралар арқылы сезім мүшелерін дамыту'), instructions_kk = COALESCE(instructions_kk, 'Текстуралары әртүрлі материалдарды (көрпе, шарф, қағаз) еденге жайыңыз. Бөпеге олардың үстімен еңбектеуге мүмкіндік беріңіз.') WHERE id = '3b19cf38-0d12-4b49-81d4-69a60f7b3cc2';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Контрастылығы жоғары карточкалар'), description_kk = COALESCE(description_kk, 'Көру қабілетін дамытуға арналған ақ-қара өрнекті карточкалар'), instructions_kk = COALESCE(instructions_kk, '1. Карточканы бөпенің бетінен 20-30cm қашықтықта ұстаңыз\n2. Оны солдан оңға қарай баяу жылжытыңыз\n3. Бөпенің карточканы көзімен қадағалауын бақылаңыз') WHERE id = '16373dad-486f-490c-bc14-144cfd354f5f';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Айнамен ішпен жату жаттығуы'), description_kk = COALESCE(description_kk, 'Бөпенің қызығушылығын ояту үшін айнамен ішпен жату жаттығуы'), instructions_kk = COALESCE(instructions_kk, '1. Бөпені жұмсақ жерге ішімен жатқызыңыз\n2. Бөпенің алдына айна қойыңыз\n3. Онымен сөйлесіп, басын көтеріп қарауға ынталандырыңыз') WHERE id = 'c1e1e351-1af5-4816-8f2c-de374135c16b';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жұмсақ массаж уақыты'), description_kk = COALESCE(description_kk, 'Бөпемен жақын қарым-қатынас орнатуға және оның дамуына арналған массаж'), instructions_kk = COALESCE(instructions_kk, '1. Бөпелерге қауіпсіз майды қолданыңыз\n2. Қолдарын, аяқтарын және ішін ақырын уқалаңыз\n3. Массаж кезінде ән айтып немесе сөйлесіп отырыңыз') WHERE id = 'ea46fd4e-7a05-4463-bf0d-2b9e8add8866';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Сабын көпіршіктерін бақылау'), description_kk = COALESCE(description_kk, 'Көру арқылы қадағалау қабілетін дамыту үшін сабын көпіршіктерін бақылау'), instructions_kk = COALESCE(instructions_kk, '1. Бөпенің жанында сабын көпіршіктерін үрлеңіз\n2. Көпіршіктерді көрсетіп, оларды сипаттаңыз\n3. Көпіршіктердің бөпенің терісінде ақырын жарылуына мүмкіндік беріңіз') WHERE id = '449a2aa8-5640-4e79-b7fa-0c92027bb12c';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Түрлі текстураларды зерттеу'), description_kk = COALESCE(description_kk, 'Әртүрлі текстураларды танып-білу'), instructions_kk = COALESCE(instructions_kk, '1. Текстуралары әртүрлі заттарды жинаңыз\n2. Бөпеге әр затты ұстап көруге мүмкіндік беріңіз\n3. Текстураларды сипаттаңыз: жұмсақ, кедір-бұдыр, тегіс') WHERE id = 'e257be70-2380-44c1-91be-9e079d4879b7';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ыдыспен ойнау'), description_kk = COALESCE(description_kk, 'Заттарды ыдысқа салу және одан шығару'), instructions_kk = COALESCE(instructions_kk, '1. Қауіпсіз ыдыс пен жұмсақ ойыншықтарды пайдаланыңыз\n2. Бөпеге заттарды ыдысқа қалай салу керектігін көрсетіңіз\n3. Бөпені заттарды ыдыстан шығаруға ынталандырыңыз\n4. Қол шапалақтап, жетістігін атап өтіңіз') WHERE id = '4d841e68-97b6-4186-be6e-26bef3df65df';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Допты домалату'), description_kk = COALESCE(description_kk, 'Допты бір-біріңізге кезекпен домалату'), instructions_kk = COALESCE(instructions_kk, '1. Бөпеге қарама-қарсы отырыңыз\n2. Жұмсақ допты бөпеге қарай домалатыңыз\n3. Бөпені допты кері итеруге ынталандырыңыз\n4. Бөпе ойынға қатысқанда, оны мақтап, қолпаштаңыз') WHERE id = '073a2084-da2c-4ef3-8a93-22136a2c77a5';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Шүберекпен «Ку-ку» ойыны'), description_kk = COALESCE(description_kk, 'Классикалық «Ку-ку» ойыны'), instructions_kk = COALESCE(instructions_kk, '1. Бетіңізді шүберекпен жабыңыз\n2. "Мен қайдамын?" деп сұраңыз\n3. Шүберекті алып, "Ку-ку!" деңіз\n4. Бөпенің бетін шүберекпен ақырын жауып, қайталаңыз') WHERE id = '58d3e4f3-7256-4eaa-901e-ce192a8aca44';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ақ-қара аспалы ойыншық'), description_kk = COALESCE(description_kk, 'Бөпенің үстіне контрастылығы жоғары суреттерді іліңіз'), instructions_kk = COALESCE(instructions_kk, 'Қағаздан қарапайым пішіндерді қиып алып, бөпеден 20-30cm биіктікке іліңіз. Бөпеге олардың қозғалысын көзімен бақылауға мүмкіндік беріңіз.') WHERE id = '8c2f484b-326a-4dac-b7a4-7eb528aff395';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Стақандарды жинау'), description_kk = COALESCE(description_kk, 'Стақандардан мұнара құрау'), instructions_kk = COALESCE(instructions_kk, '1. Бөпеге стақандарды бірінің үстіне бірін қоюды көрсетіңіз\n2. Бөпеге мұнараны құлатуға мүмкіндік беріңіз\n3. Қайта құрып, қайталаңыз\n4. Стақандарды жинаған кезде түстерін атаңыз') WHERE id = '6145784f-e184-4ae7-8691-ff33671cc7d0';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Суретті кітап оқу'), description_kk = COALESCE(description_kk, 'Суретті кітаптарды бірге қызықты етіп оқу'), instructions_kk = COALESCE(instructions_kk, '1. Ашық түсті суреттері бар кітаптарды таңдаңыз\n2. Суреттерді көрсетіп, оларды атаңыз\n3. Бөпеге парақтарды аударуға мүмкіндік беріңіз\n4. Жануарлардың дауыстарына еліктеңіз') WHERE id = '68d82e2b-fe11-4b41-af57-aa141f8eb6cc';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Пішіндерді сұрыптағыш'), description_kk = COALESCE(description_kk, 'Пішіндерді сәйкес тесіктерге салу'), instructions_kk = COALESCE(instructions_kk, '1. Пішіндердің тесіктерге қалай салынатынын көрсетіңіз\n2. Алдымен бөпенің қолын бағыттаңыз\n3. Әр жетістігіне қуаныңыз\n4. Ойын кезінде пішіндерді атаңыз') WHERE id = '60e5d3d1-5587-48f5-99df-4e806c62490a';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Би кеші'), description_kk = COALESCE(description_kk, 'Музыкаға бірге билеу'), instructions_kk = COALESCE(instructions_kk, '1. Көңілді музыка қосыңыз\n2. Бөпені қолыңызға алып билеңіз\n3. Бөпені жерге түсіріп, бірге билеңіз\n4. Қол шапалақтап, айналыңыз') WHERE id = '52245d35-3235-4e80-b73d-af4fe323ed93';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Губканы сығу'), description_kk = COALESCE(description_kk, 'Сулы губкаларды ыдыстарға сығу'), instructions_kk = COALESCE(instructions_kk, 'Губкаларды сулап, бөпеге суды ыдысқа қалай сығу керектігін көрсетіңіз. Бұл қол бұлшықеттерін нығайтуға өте пайдалы.') WHERE id = 'df24840d-33ce-4c49-b093-3e0206c89ed5';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қауырсынды үрлеу'), description_kk = COALESCE(description_kk, 'Қауырсындарды үрлеп, олардың қалықтауын бақылау'), instructions_kk = COALESCE(instructions_kk, 'Қауырсындарды тегіс жерге қойыңыз. Ақырын үрлеңіз де, бөпеге оларды ұстап көруге немесе өзі де үрлеуге мүмкіндік беріңіз.') WHERE id = 'efd51de1-efff-48a2-a2e9-f6a4a3d7a2ee';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Құммен ойнау'), description_kk = COALESCE(description_kk, 'Құмды қазу және ыдыстан ыдысқа төгу'), instructions_kk = COALESCE(instructions_kk, 'Табаққа құм толтырыңыз. Кеселер мен қасықтар беріңіз. Бөпеге құмды қазуға, төгуге және оның құрылымын қолмен сезуге мүмкіндік беріңіз.') WHERE id = '53ef4599-988b-4a29-8f82-c3c78d48283b';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ермексазды илеу'), description_kk = COALESCE(description_kk, 'Ермексазды илеу, домалату және пішіндеу'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге ермексаз беріңіз. Оны қалай илеу, домалату және саусақпен басу керектігін көрсетіңіз. Түрлі пішіндер жасау үшін қалыптарды қолданыңыз.') WHERE id = '9a13c43a-a835-47cf-99fe-bd97a0f1562c';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Текшелерден мұнара құрау'), description_kk = COALESCE(description_kk, 'Текшелерді мүмкіндігінше биік етіп жинау'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге текшелерді бірінің үстіне бірін қалай жинау керектігін көрсетіңіз. Әр текшені санаңыз. Мұнара құлағанда бірге қуаныңыз! Оны бірге қайта құрастырыңыз.') WHERE id = '5c63d4c6-a28a-488e-84cb-86ad690cd854';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Орамалдарды суырып алу'), description_kk = COALESCE(description_kk, 'Орамалдарды қораптан суырып алу'), instructions_kk = COALESCE(instructions_kk, 'Орамалдарды тесігі бар қорапқа салыңыз. Бөпеге оларды бір-бірден суырып алуға мүмкіндік беріңіз. Әрқайсысының түсін атаңыз.') WHERE id = '00ca6e21-d67f-4f0a-a874-ef5c64e2e91a';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қазына себеті'), description_kk = COALESCE(description_kk, 'Себетті қауіпсіз тұрмыстық заттармен толтырыңыз'), instructions_kk = COALESCE(instructions_kk, 'Текстурасы мен пішіні әртүрлі 5-10 қауіпсіз зат жинаңыз. Бөпеге оларды еркін зерттеуге мүмкіндік беріп, әр заттың атауын айтып отырыңыз.') WHERE id = 'ebc79f1e-7d23-4c5a-b28e-dda90e096b3a';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қол шапалақтау әні'), description_kk = COALESCE(description_kk, 'Бірге ән айтып, қол шапалақтаңыздар'), instructions_kk = COALESCE(instructions_kk, 'Қол шапалақтайтын қарапайым әндер айтыңыз. Бөпеге екі алақанын соғып, шапалақтауға көмектесіңіз. Бұл ырғақ сезімі мен қимыл үйлесімділігін дамытуға өте пайдалы.') WHERE id = 'a4aa194b-9d64-4f72-8ba4-90ae6e12f0c5';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қасық салу ойыны'), description_kk = COALESCE(description_kk, 'Қасықтарды кәстрөлге салыңыз'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге ағаш қасықтарды кәстрөлге қалай салу керектігін көрсетіңіз. Шыққан дыбысты тыңдап, әрекетті қайталауына мүмкіндік беріңіз.') WHERE id = 'b99f62da-0ba0-4a8c-a136-3eae65f486ee';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Мақта шариктерін ауыстырып салу'), description_kk = COALESCE(description_kk, 'Мақта шариктерін бір ыдыстан екіншісіне ауыстырыңыз'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге екі тостаған мен мақта шариктерін беріңіз. Оларды қалай алып, бір тостағаннан екіншісіне салу керектігін көрсетіңіз. Бұл ұсақ моториканы дамытуға өте пайдалы.') WHERE id = 'bf6bdf5d-9977-460c-978a-4df325af6d86';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қағаз жырту'), description_kk = COALESCE(description_kk, 'Қағазды бөліктерге жыртыңыз'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге жырту үшін жұмсақ қағаз беріңіз. Оның дыбысы мен қолға сезілуі сенсорлық қабылдау мен қол күшін дамытады.') WHERE id = 'c80230e8-6d2c-459b-9557-6ff0795bbec7';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Картон түтіктен жасалған туннель'), description_kk = COALESCE(description_kk, 'Допты картон түтіктің ішінен домалатыңыз'), instructions_kk = COALESCE(instructions_kk, 'Картон түтікті ұстап тұрып, бөпеге кішкентай допты оның ішінен қалай домалату керектігін көрсетіңіз. Доптың артынан бірге қуыңыздар.') WHERE id = '977ee460-5cf3-4eaa-878a-9d316320f9a5';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Су құю'), description_kk = COALESCE(description_kk, 'Суды бір стақаннан екіншісіне құю'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге екі стақан мен су беріңіз. Суды бір стақаннан екіншісіне қалай құю керегін көрсетіңіз. Бұл қимыл үйлесімділігін дамытуға өте пайдалы.') WHERE id = '94152e25-5d19-43e0-9c7f-26f0205d234e';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жасырынбақ ойыншығы'), description_kk = COALESCE(description_kk, 'Ойыншықты стақандардың астына жасырып, тауып алу'), instructions_kk = COALESCE(instructions_kk, '2-3 стақанды төңкеріп қойыңыз. Біреуінің астына кішкентай ойыншықты жасырыңыз. Бөпеден оны табуын сұраңыз.') WHERE id = '18e16dc8-b896-4c03-8b0c-c7052e294b98';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Түстер бойынша сұрыптау'), description_kk = COALESCE(description_kk, 'Заттарды түсіне қарай ыдыстарға бөлу'), instructions_kk = COALESCE(instructions_kk, 'Түсі әртүрлі заттарды (текшелер, доптар, қақпақтар) пайдаланыңыз. Ыдыстарды қойып, баладан заттарды түсіне қарай сұрыптауын сұраңыз.') WHERE id = 'a9054a6e-ef97-45fa-aea0-e0e0cc640bc3';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Дене мүшелері ойыны'), description_kk = COALESCE(description_kk, 'Дене мүшелерін көрсетіп, атау'), instructions_kk = COALESCE(instructions_kk, 'Мұрныңызды, құлағыңызды, көзіңізді ұстап, олардың атауын айтыңыз. Баладан Сізден қайталауын сұраңыз. Бас, иық және тізе туралы ән айтыңыз.') WHERE id = '07108cc6-ef41-4d92-ad52-d3d9ab5b5c1a';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жетекшінің соңынан қайтала'), description_kk = COALESCE(description_kk, 'Қимылдарды бірге қайталау'), instructions_kk = COALESCE(instructions_kk, 'Қарапайым қимылдар жасаңыз: секіріңіз, қол шапалақтаңыз, айналыңыз, аяғыңызды тарсылдатыңыз. Баладан Сізден қайталауын сұраңыз. Содан кейін жетекші болуға оған мүмкіндік беріңіз.') WHERE id = '61ed8f13-2ee8-4bf5-b395-427c971b2b93';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Пазл құрастыратын уақыт'), description_kk = COALESCE(description_kk, 'Пішіндерден тұратын қарапайым пазлдар'), instructions_kk = COALESCE(instructions_kk, 'Балаға 3-5 бөліктен тұратын қарапайым пазл беріңіз. Пішіндерді сәйкестендіруіне көмектесіңіз. Әр бөлікті дұрыс орналастырған сайын мақтап қойыңыз.') WHERE id = '407aee71-093f-47d5-be98-f518ebc93883';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жапсырмалармен ойын'), description_kk = COALESCE(description_kk, 'Жапсырмаларды қағазға жапсыру'), instructions_kk = COALESCE(instructions_kk, 'Балаға жапсырмалар мен қағаз беріңіз. Жапсырмаларды ажыратып алу ұсақ моториканы дамытады. Бірге сурет құрастырыңыздар.') WHERE id = 'ab3c62c3-5d7c-4ac6-ad8b-ac7d714a3ea7';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Табиғат аясындағы серуен'), description_kk = COALESCE(description_kk, 'Жапырақтар мен тастарды жинау'), instructions_kk = COALESCE(instructions_kk, 'Қысқа серуенге шығыңыздар. Жапырақтар, тастар мен гүлдер жинаңыздар. Олардың түстері, пішіндері және құрылымы туралы сөйлесіңіздер.') WHERE id = '62e05487-3056-4592-b1ea-0b4cac9e8f41';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Дабылдар шеңбері'), description_kk = COALESCE(description_kk, 'Кәстрөлдер мен қасықтардың көмегімен ырғақ шығару'), instructions_kk = COALESCE(instructions_kk, 'Кәстрөлдерді төңкеріп, дабыл ретінде пайдаланыңыз. Ағаш қасықтарды дабыл таяқшасы ретінде қолданыңыз. Бірге түрлі ырғақтар шығарыңыздар.') WHERE id = '55dd9c21-79eb-44fa-92b7-7a1329f2835d';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Күріш салынған сенсорлық ыдыс'), description_kk = COALESCE(description_kk, 'Күрішті қолмен және түрлі құралдармен зерттеу'), instructions_kk = COALESCE(instructions_kk, 'Ыдысты күрішпен толтырыңыз. Оған стақандар, қасықтар және кішкентай ойыншықтар салыңыз. Балаға күрішті көсіп алуға, бір ыдыстан екіншісіне құюға және ішінен ойыншықтарды іздеуге мүмкіндік беріңіз.') WHERE id = '1edc1365-0580-41a0-86fb-6e413cd251cc';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Көрпемен тербету'), description_kk = COALESCE(description_kk, 'Бөпені көрпеге салып, ақырын тербету'), instructions_kk = COALESCE(instructions_kk, 'Екі ересек адам ішінде бөпе жатқан көрпенің бұрыштарынан ұстасын. Ән айтып тұрып, оны бір жағынан екінші жағына қарай ақырын тербетіңіздер.') WHERE id = '8055a758-49ff-45d1-880c-15da141896b2';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Музыкалық аспаптар'), description_kk = COALESCE(description_kk, 'Қарапайым аспаптармен музыка ойнау'), instructions_kk = COALESCE(instructions_kk, '1. Бөпеге сылдырмақ сияқты қауіпсіз аспаптар беріңіз\n2. Музыка қосып, ырғағына сай сілкілеңіз\n3. Бірге ән айтыңыздар\n4. Бөпеге әртүрлі дыбыстарды зерттеуге мүмкіндік беріңіз') WHERE id = '23d036b7-20b9-4a05-a223-49a6d472d380';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Кір жууға көмектесу'), description_kk = COALESCE(description_kk, 'Шұлықтарды түсіне қарай сұрыптау'), instructions_kk = COALESCE(instructions_kk, 'Түсі әртүрлі шұлықтарды араластырыңыз. Бөпеңізден түсі бірдей шұлықтарды жұптастырып табуын сұраңыз.') WHERE id = 'c6f840ec-4a7f-4cab-a710-22e0769b14e1';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Көлеңкелер ойыны'), description_kk = COALESCE(description_kk, 'Қабырғада көлеңке бейнелерін жасау'), instructions_kk = COALESCE(instructions_kk, 'Қараңғы бөлмеде қолшамның көмегімен қабырғаға қолдың көлеңкесін түсіріңіз. Жануарлар мен заттардың бейнелерін жасаңыз.') WHERE id = '236f386f-6b5f-4108-a856-812efa52e5d0';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Ойыншықтарды жуу'), description_kk = COALESCE(description_kk, 'Ойыншықтарды сабынды сумен жуу'), instructions_kk = COALESCE(instructions_kk, 'Ыдысқа жылы сабынды су құйыңыз. Бөпеңізге ойыншықтарды жуу үшін ысқыш беріңіз. Жуу кезінде әр ойыншықтың атауын айтыңыз.') WHERE id = '3bde9afc-8036-426d-ae82-c76b546162fc';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Санау ойыны'), description_kk = COALESCE(description_kk, 'Заттарды бірге санау'), instructions_kk = COALESCE(instructions_kk, 'Текшелер сияқты ұсақ заттарды жинаңыз. Оларды бір-бірден бірге санаңыз. 2, 3, 4 заттан топтар құрыңыз.') WHERE id = '97af70f2-c634-4bfa-bd72-86e31f80ae2a';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жануарлардың дауыстары'), description_kk = COALESCE(description_kk, 'Жануарлардың дауыстарына бірге еліктеу'), instructions_kk = COALESCE(instructions_kk, 'Кітаптағы жануарлардың суреттерін көрсетіңіз. Әр жануардың дауысын салыңыз. Бөпеңізді қайталауға ынталандырыңыз.') WHERE id = 'ff72da83-28a7-4824-919d-7d40add23a69';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жастықтар тауы'), description_kk = COALESCE(description_kk, 'Жастықтардан жасалған кедергілерден өту'), instructions_kk = COALESCE(instructions_kk, 'Жастықтарды кедергілер жолағы түрінде орналастырыңыз. Бөпеңізді олардың үстімен және арасымен өтуге ынталандырыңыз.') WHERE id = '7a752652-ca03-444b-9521-72269d1948b7';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Картон үйшік'), description_kk = COALESCE(description_kk, 'Үлкен қораптан ойын үйшігін жасаңыз'), instructions_kk = COALESCE(instructions_kk, 'Үлкен қораптан терезелер мен есік ойып кесіңіз. Оны балаңызбен бірге безендіріңіз. Балаға үйшіктің ішінде ойнауға мүмкіндік беріңіз.') WHERE id = '25a4322e-633e-4a3e-9979-250fedcd62b2';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Туннельмен еңбектеу'), description_kk = COALESCE(description_kk, 'Көрпеден жасалған туннельмен еңбектеп өтіңіз'), instructions_kk = COALESCE(instructions_kk, 'Туннель жасау үшін орындықтардың үстіне көрпе жабыңыз. Баланы туннельмен еңбектеп өтуге ынталандырыңыз. Туннельдің соңына ойыншықтар қойыңыз.') WHERE id = 'ae4fecd1-f9d4-4188-aac6-c77af614920c';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Макароннан жасалған алқа'), description_kk = COALESCE(description_kk, 'Макарондарды жіпке тізіңіз'), instructions_kk = COALESCE(instructions_kk, 'Ірі түтікше макарондарды пайдаланыңыз. Балаға оларды жіпке немесе аяқкиім бауына қалай тізу керегін көрсетіңіз. Бұл ұсақ моториканы дамытуға өте пайдалы.') WHERE id = '64c0f7f0-7997-4646-84a7-28213e200807';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Саусақпен сурет салу'), description_kk = COALESCE(description_kk, 'Қағазға саусақпен сурет салыңыз'), instructions_kk = COALESCE(instructions_kk, 'Қағазға қауіпсіз бояу жағыңыз. Балаға саусақтары мен алақандарын қолданып сурет салуға мүмкіндік беріңіз. Түстер туралы әңгімелесіңіз.') WHERE id = '48b54a1e-5f01-444e-ac3a-7700916922cc';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Сенсорлық бөтелке'), description_kk = COALESCE(description_kk, 'Түрлі түсті сұйықтық құйылған бөтелке бөпенің назарын аударады'), instructions_kk = COALESCE(instructions_kk, 'Пластик бөтелкеге түрлі түсті су немесе жылтыр материалдар салыңыз. Қақпағын мықтап жабыңыз. Бөпеге көрсетіп, домалатып ойнауына мүмкіндік беріңіз.') WHERE id = '75be8860-ac3f-4a9e-87c7-5122de70d0a6';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Қолмен ұстау және қармау'), description_kk = COALESCE(description_kk, 'Бөпеге саусақтарыңызды қармап ұстауға жаттығуға мүмкіндік беріңіз'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге қармап ұстауы үшін саусақтарыңызды ұсыныңыз. Ұстау күшін дамыту үшін қолын ақырын тартыңыз.') WHERE id = 'f5161cf6-25f1-4eda-b672-91e0dc7075f4';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Маталарды сезіну'), description_kk = COALESCE(description_kk, 'Бөпеге әртүрлі маталарды ұстап көруге мүмкіндік беріңіз'), instructions_kk = COALESCE(instructions_kk, 'Жұмсақ, кедір-бұдыр, тегіс және үлпілдек маталарды жинаңыз. Бөпеге әрқайсысын ұстап, сезінуіне мүмкіндік беріп, матаның сипатын атап отырыңыз.') WHERE id = 'd62cf27d-4570-4976-85c1-ea88d0004a93';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Сылдырмақты сілкілеу'), description_kk = COALESCE(description_kk, 'Бөпе дыбыс шығару үшін сылдырмақты сілкілейді'), instructions_kk = COALESCE(instructions_kk, 'Бөпеге сылдырмақ беріп, оны қалай сілкілеу керегін көрсетіңіз. Бөпе Сізді қайталағанда, мақтап қойыңыз. Әртүрлі ырғақтарды байқап көріңіз.') WHERE id = 'b0958c0b-1439-4e5e-8443-a1ae673d0845';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Мұз текшелерімен сурет салу'), description_kk = COALESCE(description_kk, 'Қағазға түрлі түсті мұз текшелерімен сурет салыңыз'), instructions_kk = COALESCE(instructions_kk, 'Тағамдық бояу қосылған суды мұздатыңыз. Бөпеге мұзды қағаз бетімен сырғытып, түрлі түсті өрнектер жасауға мүмкіндік беріңіз.') WHERE id = '2fb728ab-9f62-4c72-8288-051a6eb7e14e';
UPDATE public.play_activities SET title_kk = COALESCE(title_kk, 'Жұмыртқа науасына сұрыптау'), description_kk = COALESCE(description_kk, 'Ұсақ заттарды жұмыртқа науасының ұяшықтарына сұрыптаңыз'), instructions_kk = COALESCE(instructions_kk, 'Қауіпсіз ұсақ заттарды жанына қойыңыз. Бөпеге әр затты жұмыртқа науасының жеке ұяшығына қалай салу керегін көрсетіңіз. Салған сайын бірге санаңыз.') WHERE id = '4b4383db-2e14-4720-b060-17d8ff1704ee';

