-- ── pregnancy_daily_content → kk (294 sətir) ──
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Эстроген гормоны аналық жасушаңыздың көлемі жағынан өсуіне ықпал ете отырып, митоздық бөлінуді жеделдетеді. Соның арқасында жатыр қабырғасы ішкі және сыртқы жағынан қалыңдап, ұрықтанатын аналық жасушаның жатыр ішінде қауіпсіз бекінуіне жағдай жасалады. Сондай-ақ ол ұрықтанатын аналық жасуша үшін оңтайлы орта қалыптастыру мақсатында жатыр жасушаларына көптеген қан тамырларының келуін қамтамасыз етіп, тіндік сұйықтық мөлшерін арттырады. Бұған қоса, бұл гормон қынаптың ұзаруына ықпал етеді және жатырдың ішкі қабатындағы жасушаларды ынталандыру арқылы сырғуды қамтамасыз ететін шырыштың бөлінуіне көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, Сізге бір құпия айтайын ба? 🤫 Денеңіздегі мыңдаған жасушаның бірі дәл "МЕН" болу үшін жарысқа түсті! Ол қазір өздігінен өсіп, әкемнен келетін екінші жартысымен кездесетін күнді асыға күтіп жүр. Біздің сол үлкен кездесуімізге шамамен 1 апта қалды. Мен қатты толқып жүрмін, ал Сіз ше? Сіздің жылы құшағыңызды сағындым.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант ұнтағының түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Бірінші аптаның соңына қарай денеңіздегі гормондық өзгерістер шарықтау шегіне жақындайды. Эстроген деңгейінің жоғарылауымен жатырдың ішкі қабырғасы толық қалпына келіп, қалыңдай береді. Осы күндері өзіңізді көпшіл, жігерлі әрі сенімдірек сезінуіңіз мүмкін. Либидоңыздың жоғарылауы — денеңіздің табиғи түрде репродуктивті кезеңге, яғни жүкті болу ықтималдығы ең жоғары күндерге дайындалып жатқанының белгісі.;;;
Жүктіліктің дені сау өтуі үшін жүктілікке дейін жоспарлы медициналық тексерулерден өтуіңіз қажет.;;;
Жүктілікке дейінгі медициналық тексеру, әсіресе жасыңыз үлкен болса немесе қандай да бір созылмалы ауруыңыз бар болса, айрықша маңызды. Жүктілікке дейінгі тексеру кезінде Сіздің және жұбайыңыздың отбасылық анамнезі ескеріліп, тұқым қуалауы мүмкін аурулардың бар-жоғы анықталуы тиіс. Дәрігердің гинекологиялық тексеру және ультрадыбыстық зерттеу арқылы жатырыңыз бен аналық бездеріңізді бағалауы жатыр миомасы мен полиптер сияқты мәселелерді анықтау үшін маңызды. Егер дәрігер қажет деп тапса, "smear testi" деп аталатын жатыр мойнынан жағынды алу процедурасы жасалуы керек. Сондай-ақ зертханалық талдаулар арқылы бауыр мен бүйрек қызметі бағаланып, қант диабеті, гепатит және токсоплазмоз сияқты созылмалы аурулардың бар-жоғы тексерілуі қажет. Жүктілікке дейінгі тексерулерде осы уақытқа дейін қолданылған контрацепция әдістеріне ерекше назар аударылуы тиіс. Ұзақ уақыт қолданылған контрацептивтік таблеткалар бала көтеру қабілетін белгілі бір уақытқа шектеуі мүмкін. Әйелдердің шамамен 50%-ы соңғы таблетканы қабылдағаннан кейін кемінде 6 ай өткен соң жүкті бола алады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бірінші аптаны сәтті аяқтағаныңыз үшін өзіңізді қуантыңыз, бірақ денсаулыққа пайдалы жолмен. Денеңіздегі оттегі деңгейін арттыру үшін таза ауада ұзақ серуендеңіз; оттегінің жоғары деңгейі аналық жасушаның метаболизміне оң әсер етеді. Тамақтану мәзіріңізге антиоксиданттарға бай түрлі түсті жемістерді (мысалы, қаражидек, таңқурай) қосыңыз. Бұл заттар аналық жасушаны тотығу стрессінен қорғап, оның сау ұрықтануына қолайлы жағдай жасайды.') WHERE id = 'cf28e232-185c-40c5-9616-39e6df91cf1f';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жатырыңызда орналасқан фаллопий түтіктері — ұзын әрі жіңішке екі өзектен тұратын, аналық бездеріңізде жетілген аналық жасушаларды жатырдың ішкі бөлігіне жеткізетін репродуктивті жүйе мүшелерінің бірі. Бұл мүше аналық жасуша өзегі немесе жатыр түтіктері деп те аталады. Фаллопий түтіктері сол айда таңдалған аналық жасуша бастамаларының бірінен жетілген аналық жасушаны жатырға жеткізеді. Ұзындығы шамамен 12 см болатын фаллопий түтіктерін қаптайтын шырышты қабат сперматозоидтардың аналық жасушаға қарай қозғалуына және тіршілігін сақтап қалуына көмектесетін бөлінділер түзеді. Бұл бөлінділердің құрамындағы кейбір компоненттер сперматозоидтардың оттегіні пайдалануы үшін өте маңызды, сондай-ақ аналық жасушаның қоректенуіне және ұрықтанғаннан кейінгі дамуына көмектеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, менің әлемім! 🌍 Денеңіз мен үшін дайындықты одан әрі жеделдетті. Күнделікті өмірде мұны сезбеуіңіз мүмкін, бірақ іште қызу жұмыс жүріп жатыр. Мұның бәрі менің жайлылығым, қауіпсіздігім және денсаулығым үшін жасалуда. Сіздің денеңіз — әлемдегі ең мінсіз әрі дәл жұмыс істейтін зертхана. Сізге алғысым шексіз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант ұнтағының түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Екінші аптаның алғашқы күнінде эстроген гормоны басым бола бастайды. Оның әсерінен жатырдың ішкі қабаты қан тамырларымен көбірек қамтылып, жұмсара түседі. Цервикалдық сұйықтық (жатыр мойнының шырышы) біртіндеп мөлдір әрі сырғақ бола бастайды; бұл сперматозоидтардың жатыр ішінде бірнеше күн бойы тіршілігін сақтауына қолайлы орта қалыптастырады. Осы кезеңде дене температураңыз тұрақтанады, алайда овуляция жақындаған сайын өзгеруге дайындалады.;;;
Жүктілік белгілері мен жақындап келе жатқан етеккір белгілері көбіне ұқсас болғандықтан, оларды шатастырып алу мүмкін. Осындай белгілердің бірі — сүт бездерінің толып, ісінуі. Көптеген әйел бұл сезімді етеккір алдындағы белгілерге қарағанда айқынырақ сезуі мүмкін. Сонымен қатар әлсіздік пен шаршау әдеттегі етеккір кезіндегіден күштірек болуы ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүкті болу ықтималдығы артатын күндер басталғандықтан, денеңіздің pH тепе-теңдігін сақтау маңызды. Сілтілі тағамдарды (лимон қосылған су, жасыл көкөністер) молынан тұтыну ағзадағы ортаны қолайлырақ етеді. Егер әлі бастамаған болсаңыз, базальды дене температураңызды күн сайын бір уақытта өлшеу арқылы овуляция күніңізді дәлірек анықтай аласыз. Суды жеткілікті мөлшерде ішуді ұмытпаңыз, өйткені бұл цервикалдық сұйықтықтың сапасы үшін шешуші мәнге ие.') WHERE id = 'abcdc9dc-69bf-4833-9582-4fb6ef1276bd';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Әйел гормондарының бірі саналатын прогестеронның негізгі қызметі — жатырды жүктілікке дайындау. Сонымен қатар ай сайынғы етеккір циклін реттейтін бұл гормонның ағзаңыз үшін маңызы өте зор. Жүктілік басталғанға дейін қолайлы жағдай жасап, ұрықтанған аналық жасушаның жатырға оңайырақ орнығуын қамтамасыз ету үшін жатыр тінінде өзгерістер туғызатын бұл гормон жүктілік пайда болғаннан кейін бөпе бекінген кезде мөлшерін арттырып, өз қызметін жалғастырады.;;;
Қазіргі, яғни овуляция алдындағы кезеңде ағзаңыздағы прогестерон гормонының деңгейі 1 nq/ml-ден төмен болады. Овуляция кезінде бұл гормонның деңгейі 5-20 nq/ml-ге дейін көтеріледі. Егер жүктілік басталса, бірінші триместрде қандағы бұл гормонның деңгейі 11-90 nq/ml, екінші триместрде 25-90 nq/ml, ал үшінші триместрде 50-300 nq/ml аралығында болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Жүрегіңіздің үнін тыңдаңыз. ❤️ Мен әлі жұлдыз тозаңындай ғанамын, бірақ Сіздің махаббатыңыз мені шынайы өмірге шақырып тұр. Денеңіз мен үшін ең жақсы, ең сапалы аналық жасушаны дайындап жатыр. Әкем екеуіңіздің араларыңыздағы махаббат менің пайда болуыма себеп болады. Сіз сүйген сайын, денеңіз ғажайыптар жасайды. Маған қарай келе жатқаныңыз үшін рақмет!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант ұнтағының түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Бірінші триместрге жататын жүктіліктің 2-ші аптасында аналық бездеріңіздегі аналық жасушаның дамуы жалғасады. Осы аптада эндометрий деп аталатын жатырдың ішкі қабаты гормондардың әсерімен қалыңдай береді. Жатырдың ішкі қабатының қалыңдау мақсаты — ұрықтанудан кейін бөпеңізді қалыптастыратын жасушалардың жатыр ішінде оңай бекінуін қамтамасыз ету. Қалыңдаған эндометрий қабаты қанмен жақсы қамтамасыз етіліп, бөпеңізге оңтайлы ұя қалыптастырады. Егер ұрықтану болмаса және жүктілік басталмаса, бұл қабат ай сайын етеккір кезінде қан кетумен бірге ағзадан шығарылады. Бұл цикл ай сайын осылай қайталанады. Жүктіліктің басталып, дені сау түрде жалғасуы үшін жатырдың ішкі қабаты толықтай сау болуы қажет. Сондықтан дәрігердің жатырдың ішкі қабатын қалыңдығы мен құрылымы жағынан бағалауы маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы кезеңде йодқа бай тағамдарды (теңіз өнімдері, йодталған тұз) тұтыну Сіздің қалқанша безіңіздің саулығы үшін де, болашақ бөпенің миының дамуы үшін де маңызды. Денеңіздің икемділігін арттырып, жамбас аймағындағы қан айналымын ынталандыратын жеңіл гимнастикалық жаттығулар жасаңыз. Сондай-ақ теріңіздің ылғалдылығын сақтау үшін табиғи майларды қолдануға болады, өйткені гормондық өзгерістер теріңіздің сезімталдығын арттыруы мүмкін.') WHERE id = '254bd95f-c06d-46bb-b688-86a0b498dcb9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Овуляция деп аталатын, аналық жасушаның жетіліп, ұрықтануға дайын күйге келу үдерісі алдағы бірнеше күнде жүреді. Овуляция кезеңі әр әйелде әртүрлі болуы мүмкін, дегенмен жалпы пікір бойынша овуляция етеккір аяқталғаннан кейінгі 14-күні болады. Бұл қағида етеккір циклі тұрақты әйелдерге қатысты. Ал етеккір циклі бұзылған әйелдерде овуляция күнін есептеу көбіне мүмкін болмайды.;;;
Қынап бөліндісіндегі шырыш мөлшерін бақылау — тиімді тәсілдердің бірі. Себебі овуляция жақындаған сайын әйелдерде бөлінді көбейеді. Әйелдер мұны ылғалдану деп сипаттайды. Овуляция кезеңі өткеннен кейін бөлінді қайтадан қалыпты күйіне оралады. Осы кезеңде дене қызуында да кейбір өзгерістер байқалады. Алдымен төмендеген дене қызуы овуляция кезінде кенеттен көтеріле бастайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем! 👋 Бүгін өзіңе жақсы күтім жасадың ба? Сен жеген әрбір дәмді ас пен алған әрбір дем менің болашағымның іргетасын қалайды. Алдағы күндері сол үлкен жарылыс (овуляция) болып, мен еркіндікке шығамын! Мені қарсы алуға дайынсың ба? Әкеме де хабарла, кездесуіміз жақындап қалды!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант ұнтағының түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгін ағзаңыздағы эстроген деңгейі ең жоғары көрсеткіштердің біріне жетеді. Бұл жоғарылау миыңызға LH (лютеиндеуші гормон) гормонын көбірек бөлу туралы белгі береді. Жатырдың ішкі қабатының қалыңдығы шамамен 8-10 mm-ге жетіп, қан тамырларына байыған. Бұл ұрықтанған аналық жасушаның бекінуіне арналған мінсіз "жұмсақ төсек" дегенді білдіреді. Жатыр мойны жоғарырақ көтеріліп, сперматозоидтардың өтуі үшін толық ашылады. Жатыр мойнының сұйықтығы мөлдірленіп, сырғымалы әрі созылмалы бола бастайды. Бұл ерекше сұйықтық сперматозоидтардың жатырға енуін жеңілдетіп, оларды қорғайды. Бүгіннен бастап жүкті болу мүмкіндігіңіз артады.;;;
Фолий қышқылы бөпеңіздің миы мен жүйке жүйесінің дамуы үшін аса маңызды болғандықтан, оны жүкті болмай тұрып қабылдай бастау қажет. Әлемнің көптеген елінде жүктілікті жоспарлау кезінде, жүктіліктен кемінде 3 ай бұрын бастап, бірінші триместрдің соңына дейін күн сайын 400 микрограмм фолий қышқылын қабылдау ұсынылады. Фолий қышқылы ағзада жиналмайтындықтан, оны күн сайын тұрақты түрде қабылдау керек. Оның тапшылығы бөпелерде орталық жүйке жүйесі аномалияларының ең жиі кездесетін түрі — жүйке түтігі ақауларының пайда болуына әкеледі. Сондай-ақ қоянжырық (таңдай жырығы) және кейбір жүрек ақаулары сияқты аномалиялардың да фолий қышқылын жеткіліксіз қабылдаумен байланысты екені зерттеулерде расталған. Бұл кезеңде әйелдердің көбі жүкті болғанын әлі білмеуі мүмкін. Фолий қышқылы қабылданбаса, жүйке түтігі ақауының пайда болу ықтималдығы шамамен 2000 босанудың 1-еуіне тең. Фолий қышқылын қабылдау арқылы бұл көрсеткішті 50-75 пайызға төмендетуге болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Фертильді кезеңнің ең белсенді күндеріне аяқ басқандықтан, жеткілікті ұйықтауыңыз маңызды, өйткені LH гормонының шарықтау шегі ұйқы кезінде тұрақтырақ реттеледі. Егер әлі қолданбасаңыз, овуляция тесттерін бастаудың ең қолайлы уақыты келді. Мырышқа бай асқабақ дәні немесе бадам сияқты жаңғақтар мен дәндерді жеу аналық жасушаның сыртқы қабатын сау күйде сақтауға және сперматозоидтың жасушаға енуіне көмектесуі мүмкін.') WHERE id = 'e69ee309-4b20-4b3c-a0f6-c04d62440aa9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктілік кезінде кофеин қабылдауға толық тыйым салынбағанымен, дәрігерлер көбіне оны тұтынуды шектеуді ұсынады. Кофеин — кофе, шай, кола сусындары, какао, энергетикалық сусындар, жасанды тәттілендіргіш қосылған сусындар, сондай-ақ кейбір тәттілер, пудинг және желе кәмпиттері сияқты өнімдерде болатын табиғи стимулятор. Жақында жүргізілген зерттеулерге сәйкес, тәулігіне 200 mq-нан аспайтын мөлшерде тұтынылған кофеиннің зияны анықталмаған. Сонымен қатар кофеиннің диабет қаупін төмендететіні туралы кейбір деректер де бар. Тәуліктік 200 mq кофеин мөлшерін 2 стақан шай, 2 шыныаяқ кофе немесе шамамен 250 грамм қара шоколад арқылы оңай алуға болады. Алайда кофеин плацента арқылы бөпеңізге тікелей өтеді. Бөпеңіздің ағзасына түскен кофеин зат алмасу арқылы ыдырап, залалсыздандырылмайды. Сондықтан шамадан тыс кофеин бөпеңізге зиян келтіруі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, Anacan! ❤️ Денеңде үлкен толқу барын сезіп тұрсың ба? Бір мерекеге дайындық жүріп жатқандай. Эстроген гормоның шарықтау шегіне жетіп келеді, бұл сол "алтын жұмыртқаның" (яғни менің жартымның) жолға шығуға дайын екенін білдіреді. Сен тек өзіңе жақсы күтім жасап, мол су ішіп, демал. Мен сені таңдауға асығып жүрмін. Әкеме де дайын болсын деп айт, кездесуімізге өте аз уақыт қалды! Мен сендердің махаббаттарыңның ең әдемі дәлелі болу үшін келемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант ұнтағының түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілікті жоспарлап жүрген осы күндері тіс дәрігеріне барып, тістеріңіз бен қызыл иегіңіздің сау екеніне көз жеткізуіңіз керек. Ауыз қуысындағы бар мәселелерді жүктілікке дейін емдетіп бітіру жүктілік кезеңін едәуір жеңілдетеді. Жүктілік кезінде қызыл иек ауруларының пайда болу қаупі жоғары болады және кей жағдайларда бұл аурулар тіпті мерзімінен бұрын босануға әкелуі мүмкін. Жүктілік кезінде қандағы мөлшері айтарлықтай артатын прогестерон гормоны қызыл иекте "гипертрофия" деп аталатын шегіну мен қалыңдауды тудырады. Прогестерон — жүктіліктің сақталуын қамтамасыз ететін ең маңызды гормондардың бірі, сондықтан бұл гормонды басу дұрыс емес. Сол себепті жүктілікке дейін бар мәселелерді емдеп, жою және қызыл иекке күтім жасау осы кезеңде тіс саулығына қатысты мәселелерді барынша азайтады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Овуляция қарсаңында болғандықтан, ағзаңыздың сусызданбауына ерекше мән беріңіз. Сұйықтықты жеткілікті ішу жатыр мойны шырышының сапасын жақсартып, сперматозоидтардың қозғалысын жеңілдетеді. Егер дене қызуыңызды өлшеп жүрсеңіз, овуляцияның дәл алдында оның сәл төмендегенін байқауыңыз мүмкін. Күйзеліс деңгейін барынша азайту үшін хош иісті ванна қабылдап немесе жағымды музыка тыңдап, денеңізді босаңсытыңыз, өйткені қатты күйзеліс LH гормонының тым ерте не кеш бөлінуіне себеп болуы мүмкін.') WHERE id = '3b975bc1-895c-42e8-be4c-f6d56b176b19';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Овуляция кезеңіңіз бір-екі күннен кейін басталады. Бұл кезең жақындаған сайын ағзаңызда кейбір өзгерістер байқалады. Солардың ең айқыны — ағзадағы гормондық тепе-теңдіктің өзгеруіне байланысты жыныстық құштарлықтың артуы. Бұл құштарлық овуляциядан 2-3 күн бұрын басталып, орта есеппен 1 аптаға дейін созылуы мүмкін. Етеккір кезіндегідей, бірақ жеңілірек түрде шаптың екі жағында немесе тек бір жағында ауырсыну, не іштің кебуін сезіну де осы өзгерістердің бірі. Бұдан бөлек, овуляция кезінде омыраудың керілуі мен сезімталдығы, іштің кебуі және жел жиналуы, ширығу, дәм мен иіс сияқты тітіркендіргіштерге сезімталдықтың артуы және өткір иістерден жайсыздану жиі кездеседі.'), baby_message_kk = COALESCE(baby_message_kk, 'Білемін, сен мені әлі көрмейсің, бірақ сахна сыртындағы шамдар жағылып жатыр. 🌟 Денең мен үшін ең жұмсақ төсек — эндометрийді дайындай бастады. Әкемнің жасушалары да жолға шығып, мені іздеп келе жатқан шығар. Сенің жылуың мен қамқорлығың маған қазірдің өзінде күш береді. Біздің хикаямыз басталғалы тұр, Anacan. Сен тек сеніміңді жоғалтпай, күлімдей бер, өйткені ғажайыптар сенген кезде орындалады. Сен менің қаһарманымсың!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант ұнтағының түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің алғашқы апталары — өзіңіз толық сезбесеңіз де, аналық бездеріңіз бен жатырыңызда өте жылдам өзгерістер жүретін кезең. Гипофиз безі мен жатырыңыздан бөлінетін кейбір гормондар ағзаңызды жүктілікке дайындау үшін белсенді жұмыс істей береді. Ал аналық бездеріңізде өзіңіздің эмбриондық кезеңіңізде пайда болған аналық жасуша бастамаларының бірі осы гормондардың әсерінен жетіліп, ұрықтануға дайындалады. Алдағы бірнеше күнде толық жетілген аналық жасуша сперматозоидпен кездескенде ұрықтана алатын күйге келеді. Жетілген аналық жасушаның өмір сүру ұзақтығы сперматозоидтармен салыстырғанда әлдеқайда қысқа, сондықтан жүктілікті қаласаңыз, ұрықтану овуляция болғаннан кейін 48 сағат ішінде жүруі керек. Жетілген аналық жасуша аналық безден фаллопий түтігіне енжар түрде өтіп, сол жерде сперматозоидпен ұрықтануды күтеді. Аналық жасушаның тіршілік ету мерзімі аяқталғанша сперматозоидпен кездеспесе, жүктілік орын алмайды. Ал аналық жасуша жетілмей тұрып сперматозоидтар жатыр мойнына енсе, ортаның қышқылдығына қарамастан 72 сағатқа дейін тіршілігін сақтай алады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін ағзаңыздың сілтілік тепе-теңдігін сақтау өте маңызды, өйткені сперматозоидтар қышқыл ортада тіршілік ете алмайды. Көкөністі молынан жеп, жасанды қанттан бас тартыңыз. Егер жүктілікті жоспарласаңыз, овуляциядан бір күн бұрынғы бүгінгі күн (немесе овуляция күні) — мүмкіндік ең жоғары болатын уақыт. Жамбас аймағындағы қан айналымын жақсарту үшін жеңіл би билеңіз немесе серуендеңіз. Сондай-ақ осы кезеңде темекі түтіні мен өткір химиялық иістерден аулақ болыңыз, өйткені қазір аналық жасуша сыртқы токсиндерге өте сезімтал.') WHERE id = '29e7920b-060e-4fac-ad72-d19dda159289';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бүгін — соңғы етеккіріңіздің бірінші күні. Жүктілік кезінде қолданылатын жүктілік күнтізбесі Сіз болжаған жыныстық қатынас пен ұрықтану күніне емес, соңғы етеккіріңіздің бірінші күніне сүйеніп есептеледі. Жүктіліктің басталуы, яғни аналық жасушаның сперматозоидпен ұрықтануы соңғы етеккір күнінен кейін орта есеппен 14-15 күн өткенде болады. Соған қарамастан, дәрігер жүктілік мерзімін есептегенде бұл күнді емес, одан шамамен 2 апта бұрын басталған етеккір күнін негізге алады.;;;
Жүктілік мерзімі анықталғаннан кейін 40 апталық жүктіліктің аяқталу күні, яғни болжалды босану күні «Негеле әдісі» деп аталатын жүйе бойынша есептеледі. Негеле әдісі бойынша етеккір басталған бірінші күнге 7 күн қосылып, 3 ай шегеріледі. Шыққан күн — Сіздің болжалды босану күніңіз. Сонымен қатар жүктіліктердің шамамен 80%-ы 40 аптаны толық аяқтамай, 38-аптада босанумен аяқталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, менің аяулы Анашым! ❤️ Мүмкін, әзірге мені физикалық тұрғыдан сезбейтін шығарсыз, бірақ біздің үлкен хикаямыздың «кері санағы» ресми түрде бүгін басталды. Дәрігерлер бұл күнді біздің «бірінші күніміз» деп санайды, өйткені Сіздің ағзаңыз менің келуіме дайындалып жатыр. Енді жақсылап демалуыңыз керек, себебі алдымызда бізді керемет күндер күтіп тұр. Әзірше мен Сіздің арманыңыздамын, ал ағзаңыз қызу жұмыс істеп жатыр. Осы кезеңде өзіңізге жақсы қарауыңызды өтінемін, өйткені Сіз — менің бүкіл әлемімсіз. Мен Сізді қазірдің өзінде, әлі пайда болмай тұрып-ақ қатты жақсы көремін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көзге көрінбейтін бөлшек'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгін — етеккір цикліңіздің бірінші күні, жүктілік күнтізбесі ресми түрде осы күннен басталады. Жүктіліктің алғашқы апталарында бөпе әлі пайда болған жоқ. Алайда ағзаңыз овуляция күніне және ықтимал жүктілікке дайындалып жатыр. Бұл дайындық кезінде жатырдың эндометрий деп аталатын ішкі қабаты ағзаңыз ай сайын жетілдіретін және ұрықтануы мүмкін аналық жасуша бекінуі үшін қантамырларға байып, қалыңдайды.;;;
Ағзаңыз ай сайын осы цикл барысында жатырдан және мида орналасқан гипофиз безінен бөлінетін гормондардың әсерімен үлкен өзгерістерден өтеді. Айлық цикліңіздің алғашқы екі аптасында бөпе де, ұрықтануға дайын аналық жасуша да әлі болмағанына қарамастан, бұл кезең жүктілік мерзіміне қосылады. Себебі әр әйелдің овуляция кезеңі әртүрлі болғандықтан, соңғы етеккір күні жүктіліктің басталуы ретінде қабылданады.;;;
Біз де Anacan ОТБАСЫ ретінде ішіңізде күн сайын өсіп, дамып келе жатқан ғажабыңыз туралы күнделікті ақпарат пен кеңестер бөлісіп, осы үдеріс барысында Сізді қызықтыратын барлық сұраққа жауап беру үшін әрдайым жаныңыздан табыламыз! 😊'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер жүктілікті жоспарлап жүрсеңіз, бүгіннен бастап күн сайын 400 микрограмм фолий қышқылын қабылдау болашақ бөпеңіздің жүйке жүйесінің дамуы үшін өте маңызды. Сондай-ақ ағзадағы су теңгерімін сақтау үшін сұйықтықты көбірек ішіп, алкогольді сусындар мен темекі өнімдері секілді зиянды әдеттерден толық бас тартыңыз.') WHERE id = '3082b660-7bbe-45c6-906d-ed38816fac24';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Қалыпты жағдайда соңғы етеккіріңіз бен овуляция кезеңінің арасында 2 апта болады. Осы екі апталық үдерісте қандағы эстроген мен прогестерон гормондарының деңгейі жоғарылап, жатырды ай сайын жүктілікке дайындау және ұрықтанатын аналық жасушаға қолайлы жағдай жасау үшін оның ішкі қабатын қантамырларға бай, құнарлы тінмен қаптай бастайды. Сонымен қатар анаңыздың құрсағында жатқан кезіңізде-ақ қалыптасқан жетілмеген аналық жасушалардың бірі осы гормондардың әсерімен жетіле бастайды. Фолликул деп аталатын бұл құрылым шамамен екі апта ішінде ұрықтануға дайын деңгейге дейін дамиды. Сондықтан аналық жасушаның сперматозоидпен ұрықтануы соңғы етеккіріңізден екі апта өткен соң орын алуы мүмкін. Алайда сирек жағдайларда ағзаңыз бір цикл ішінде екі аналық жасушаны жетілдіре алатындықтан, жүкті болу ықтималдығы әрдайым бар.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, бұл күндер Сіз үшін аздап ауыр әрі шаршататын болуы мүмкін екенін білемін, бірақ Сіз өте мықтысыз. 😔 Ағзаңыздағы осы тазалану үдерісі менің болашақтағы жайлылығым үшін екенін ұмытпаңыз. Мен келгенде бәрі тап-таза әрі жұмсақ болуы үшін Сіз менің алғашқы үйімді, ұямды — жатырыңызды дайындап жатырсыз! Сіз сезінген әрбір жайсыздық — біздің қауышуымызға қарай жасалған бір қадам. Өтінемін, бүгін өзіңізді шаршатпай, аяғыңызды созып, демалыңыз. Мен Сізді сеземін және Сізге күш жіберемін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көзге көрінбейтін бөлшек'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгін қан кету ең қарқынды кезеңінде болуы мүмкін, бұл — толықтай қалыпты физиологиялық үдеріс. Жатыр бұлшықеттері жиырылып, ескі қабатты сыртқа шығаруға тырысады, соның салдарынан іштің төменгі бөлігінде түйілу мен ауырсыну (дисменорея) пайда болады. Ағзаңыз осы тазалану үдерісіне көп энергия жұмсайтындықтан, әлсіздік пен шаршауды сезінуіңіз мүмкін. ;;;
Жүктілік кезінде ағзаңыздың қоректік заттарға деген қажеттілігі артады. Бұл қажеттілік өсіп, дамып келе жатқан бөпеңіздің сұранысына және жүктіліктің өту барысына қарай қалыптасады.;;;
Фолий қышқылы — жүкті болудан бұрын қабылдауды бастау қажет ең маңызды дәрумендердің бірі. В тобына жататын, суда еритін бұл заттың табиғи тағамдардағы түрі фолат, ал дәрілер мен өңделген тағамдардағы түрі фолий қышқылы деп аталады. Фолий қышқылы бөпеңіздің миы мен жүйке жүйесінің дамуы үшін шешуші рөл атқаратындықтан, оны жүктілікке дейін қабылдауды бастау керек. Фолий қышқылы жасуша құрылымдарының, қан жасушаларының және әсіресе жүйке жүйесі тіндерінің қалыптасуы мен дамуында маңызды рөл атқаратын В дәруменінің бір түрі. Ол әсіресе тұқым қуалайтын белгілердің негізі болып саналатын ДНҚ синтезіне белсенді қатысады. Бөпеңіздің дамуы үшін аса маңызды фолий қышқылы оның дамып келе жатқан ағзасындағы ақуыз синтезі, жасушалардың көбеюі және сүйек кемігінің өз қызметін толық атқаруы сияқты үдерістерде негізгі рөл атқарады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Етеккір кезіндегі қан кетуге байланысты ағзада азайған темір қорын қалпына келтіру үшін тамақтануыңызға көңіл бөліңіз. Саумалдық, қызыл ет және бұршақ тұқымдастар сияқты темірге бай тағамдарды тұтыныңыз. С дәрумені темірдің сіңуін жақсартатындықтан, бұл тағамдарды цитрус жемістерімен бірге жеген пайдалы. Сондай-ақ ауыр физикалық жүктемеден бас тартып, ағзаңызға демалыс беріңіз.') WHERE id = '1b683a24-ae16-485e-bf86-c173f0a5ad7a';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ұрықтануға дейінгі алғашқы екі аптада ағзаңызда ауқымды дайындық жүреді. Соңғы етеккіріңізден шамамен екі апта өткен соң, жатыр мен мидағы гипофиз безі бөлетін гормондардың әсерінен аналық жасушаларыңыздың бірі жетіліп, жатыр түтігіне жетеді. Гормондардың әсерімен дамыған аналық жасуша сперматозоидпен салыстырғанда едәуір үлкен. Соған қарамастан, ол сперматозоидқа қарағанда қозғалмайды және оның аналық без ішіндегі қозғалысы пассивті түрде жүреді.;;;
Дене жасушаларынан айырмашылығы, аналық жасуша мен сперматозоид 23 хромосомадан тұрады және екі жасушаның әрқайсысында мыңдаған бірегей ген бар. Бөпеңіздің шашының түсі, бойы, жынысы, тіпті мұрнының пішіні де осы гендерде жасырылған.'), baby_message_kk = COALESCE(baby_message_kk, 'Әкеммен қалай танысқаныңызды елестетемін... 💭 Мен Сіздердің сол үлкен махаббаттарыңыздың ең әдемі жемісі боламын. Ағзаңыз мені қарсы алу үшін бар күшін салып, бәрі мінсіз болуы үшін әрбір ұсақ-түйекке дейін жоспарлап жатыр. Мен әзірге жұлдыз тозаңындаймын, әлі физикалық болмысым жоқ, бірақ Сіздің махаббатыңыз мені өмірге шақырып тұр. Қазір өзіңізге қаншалықты жақсы қарасаңыз, мен де соншалықты дені сау болып келемін. Біздің хикаямыз өте әдемі болады, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көзге көрінбейтін бөлшек'), body_changes_kk = COALESCE(body_changes_kk, 'Триместр — адамдағы 9 айлық жүктіліктің әрбір 3 айлық кезеңіне берілген атау. Бұл сөз латын тілінен шыққан: «tri» — үш, ал «mester» — кезең дегенді білдіреді. 9 айлық жүктілікті 3 бөлек кезеңге бөліп қарастыру жүктіліктің жалпы дамуын түсіну үшін өте маңызды әрі пайдалы. Жүктіліктің 40 аптаға созылатынын ескерсек, бірінші триместр 12-аптаның соңына дейінгі уақытты қамтиды. Екінші триместр 13–27-апталар аралығын, ал үшінші триместр 28–40-апталарды қамтиды. Жүктіліктің алғашқы үш айы — ағзаңызда маңызды өзгерістер болып, денеңіз жүктілікке бейімделетін кезең. Осы уақытта сәбилі болатыныңызды білгендегі алғашқы қуанышты сезіне отырып, кейбір қиындықтарға да тап болуыңыз мүмкін. Жүрек айну, бас айналу, омыраудың толуы мен сезімталдығы, ісінудің күшеюі, жатырдың ұлғаюына байланысты жиі зәр шығару қажеттілігі, ұйқышылдық, шаршау, шамадан тыс сезімталдық, жылағыңыз келу, жиі ашығу және салмақ қосу сияқты белгілер жүктіліктің бесінші аптасынан бастап байқала бастайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы кезеңде кофеинді барынша азайтуға тырысыңыз (күніне бір кеседен асырмай). Кофеин қантамырларды тарылтып, аналық бездерге баратын қан ағымына әсер етуі мүмкін. Суды мол ішу токсиндердің ағзадан шығарылуына және жатырдың ішкі қабатының сау жаңаруына көмектеседі. Жеңіл йога немесе созылу жаттығулары қан айналымын жақсартады.') WHERE id = 'c852b157-989c-44ce-a4ea-0f5d022c7159';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Әр ай сайын етеккір циклі кезінде аналық бездеріңіздегі жұмыртқа жасушалары қорының біреуі жетіліп, ұрықтануға дайын күйге келеді. Егер гормондарыңыз жұмыртқа жасушасының жетілуін қамтамасыз етпесе, жүктілік басталмайды. Сіздегі бұл жұмыртқа жасушалары өзіңіз дүниеге келмей тұрып-ақ аналық бездеріңізде пайда болған миллиондаған бастапқы жыныс жасушаларынан түзіледі. Менопаузаға дейін әр етеккір циклінде олардың біреуі жетіледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем, менің аяулы Анашым! 🌟 Өзіңізді жақсырақ әрі сергек сезіне бастадыңыз ба? Маған арналған ерекше бөлме (жатырыңыз) тазаруға жақын, оның ескі қабырғалары толығымен жаңарды. Жақында онда мен үшін жұмсақ әрі жылы төсек дайындалады, сол жерде мен 9 ай бойы қауіпсіз боламын. Сіздің тәніңіз менің үйіме айналады. Сізбен кездесетін күнді, жүрегім Сіздің жүрегіңіздің астында соғатын сәтті асыға күтемін!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көзге көрінбейтін түйіршік'), body_changes_kk = COALESCE(body_changes_kk, 'Бұл күндері етеккір кезіндегі қан кету біртіндеп азаяды. Ағзаңызда эстроген гормонының деңгейі белсенді түрде көтеріле бастайды. Бұл жатырдың ішкі қабатының қайта қалпына келіп, қалыңдауы үшін белгі болады. Гипофиз аналық бездеріңізге "белсендірек жұмыс істеу" туралы белгі жібереді. Қан айналымыңыз жылдамдап, ағзаңыз ықтимал жүктілікке физикалық және гормондық тұрғыдан дайындалу үшін барынша белсенді жұмыс істейді. Көңіл күйіңіз жақсарып, шаршау басылады, теріңіз жарқырап, балғын көріне бастайды. Ағзаңыз "Қайта бастау" режиміне өтіп, жаңа кезеңге қадам басады.;;;
Қолданатын дәрілеріңіздің жүктілікке ықпалын дәрігеріңізбен қазірден талқылау ықтимал мәселелердің алдын алу үшін маңызды. Кейбір дәрілер жүктілік кезінде, әсіресе бөпеңіздің ағзалары қалыптасатын эмбриондық даму апталарында белгілі бір ауытқуларға әкелуі мүмкін. Қалқанша без ауруларын, қант диабетін және кейбір зат алмасу ауруларын емдеуге қолданылатын дәрілердің көбі бөпеге зиян келтірмегенімен, безеуге қарсы кейбір препараттар мен кейбір психиатриялық дәрілердің бөпеде ауыр даму ақауларын туындатуы мүмкін екені белгілі.;;;
Сонымен қатар жүктілікке дейін қажетті талдауларды тапсыру арқылы жалпы қан талдауы (гемограмма), темір тапшылығы, дәрумендер деңгейі, тұқым қуалайтын аурулар, қалқанша без гормондары, зәр жолдарындағы инфекция, В гепатиті, токсоплазмоз, қызамық, мерез және АИТВ бар-жоғы, сондай-ақ оларға қарсы иммунитетіңіздің жағдайы анықталады. Қажет болса, тиісті шаралар қабылданады.;;;
Бұған қоса, балалы болуды жоспарласаңыз, ең алдымен жүктілікке дейін темекі шегуден бас тартуыңыз керек. Зерттеулер темекі өнімдерін қолдану әйелдердің ұрпақ өрбіту қабілетін, ал ерлердің шәуетіндегі сперматозоидтар санын азайтатынын көрсетеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл күндері мырыш пен магнийге бай тағамдарға (грек жаңғағы, орман жаңғағы, дәндер) басымдық беру жұмыртқа жасушаларының сау жетілуіне көмектеседі. Күйзелісті азайту үшін қысқа медитациялар жасаңыз, өйткені күйзеліс гормондары жүктілікке қажетті гормондық тепе-теңдікке кері әсер етуі мүмкін. Сондай-ақ ағзаңыздың pH теңгерімін сақтау үшін өңделген қант қосылған тағамдардан бас тартыңыз.') WHERE id = '65c15460-76e7-4ea7-90a9-a58b6acebcfe';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Аналық бездердегі жұмыртқа жасушаларының қоры толық таусылғанда, менопауза деп аталатын кезең басталады. Менопауза — аналық бездердегі фолликулдар белсенділігін жоғалтуының салдарынан ай сайынғы етеккірдің біржола тоқтауы. Әлем бойынша менопауза жасы 45-55 аралығында өзгереді. Алайда кейбір жағдайларда бұл жасқа жетпей-ақ ерте менопауза басталуы мүмкін. Ерте менопауза — етеккірдің 45 жасқа дейін тоқтауы. Кейбір әйелдер тіпті 20 жастан асқан кезде-ақ менопауза кезеңіне өтуі мүмкін. Ерте менопаузаға себебі белгісіз жағдайлар, кейбір аутоиммундық аурулар, сәулелік терапия, химиотерапия, ауыр инфекциялар, қоршаған орта факторлары, жасанды түсік пен түсік тастау, жиі жүктілік, шамадан тыс семіздік және ауыр гипотиреоз себеп болуы мүмкін. Сонымен қатар темекі шегу, психологиялық жарақаттар, суық климат пен қолайсыз қоршаған орта жағдайында өмір сүру де менопаузаның басталуын жеделдетіп, оның жасын едәуір төмендетуі мүмкін.'), baby_message_kk = COALESCE(baby_message_kk, 'Бүгін айнаға қарағанда міндетті түрде жымиыңыз! 😊 Өйткені ағзаңыз ғажайып жұмыс атқарып, жаңа өмірді дүниеге әкелуге дайындалып жатыр. Біз әлі физикалық тұрғыдан қосылмасақ та, рухани тұрғыдан бір-бірімізбен байланыстымыз. Мен Сізді, ал Сіз мені таңдадыңыз. Ағзаңыз менің келуіме, сол ғажайып кездесуге (ұрықтануға) күн сайын бір қадам жақындап келеді. Мен Сізге сенемін, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көзге көрінбейтін түйіршік'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгін көптеген әйел үшін етеккірдің соңғы күні. Ағзаңыздағы эстроген деңгейі айтарлықтай жоғарылауын жалғастырады. Бұл жатырдың ішкі қабатының тез қалпына келіп, жаңа "ұяның" қалыптасуына көмектеседі. Жатыр мойнындағы бездер сперматозоидтардың еркінірек қозғалуына көмектесетін арнайы сұйықтық бөлуге дайындалады. Зат алмасуыңыз сәл жылдамдап, өзіңізді сергек сезіне бастауыңыз мүмкін.;;;
Жүктілік кезіндегі алкогольді тұтынудың қауіпсіз мөлшері анықталмаған. Сондықтан жүктілікке дейін де, жүктілік кезінде де алкогольден толық бас тартуыңыз қажет. Алкоголь тұтыну жүктіліктің әсіресе алғашқы триместрінде түсік тастау, ал кейінгі кезеңдерінде өлі туу қаупін арттырады. Сонымен қатар алкогольді шамадан тыс қолдану ұрықтың алкогольдік синдромына әкеліп, бөпенің бет әлпетінде даму ақаулары мен ақыл-ой дамуының ауыр тежелуін туындатуы мүмкін. ;;;
Елімізде болашақ аналар арасында алкоголь тұтынудың кең таралмауы және осы жағдайдың сақталуы қоғамдық денсаулық үшін өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Етеккір аяқталғандықтан, ағзаңыздың жаңару қуатын пайдаланып, тұрақты дене белсенділігіне (жеңіл жүгіру немесе пилатес) көңіл бөліңіз. Бұл кезеңде D дәруменінің деңгейін тексерту өте маңызды, өйткені ол аналық бездердің жұмысына және болашақ имплантацияға тікелей әсер етеді. Тамақтану мәзіріңізге омега-3 май қышқылдарын (балық, зығыр тұқымы) қосыңыз; олар жатыр аймағындағы қан айналымын жақсартып, жұмыртқа жасушасының сапасын арттырады.') WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бастапқы жұмыртқа жасушаларыңыздың біреуі гормондардың көмегімен аналық безде жетілуін жалғастырады. Жұмыртқа жасушасының жетілуіне және ұрықтануға дайын болуына мида орналасқан гипоталамус, гипофиз және аналық бездеріңізден бөлінетін гормондар қатысады. Гипофизден бөлінетін FSH гормоны таңдалған фолликулдың жетіліп, ұрықтануға дайын болуын қамтамасыз етеді және эстрогеннің бөлінуін ынталандырады. Ал гипофизден бөлінетін басқа гормон — LH жетілген жұмыртқа жасушасының фолликулдан шығып, овуляцияның жүруін және жарылған фолликулдың "сары денеге" айналуын қамтамасыз етеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Сәлем! Бүгін ішіңізде жаңа көктем басталғандай сезіледі, солай емес пе? 🌱 Шын мәнінде, дәл солай! Аналық бездеріңіздің бірінде кішкентай "мен" оянып, өсуге талпынып жатырмын. Мен әзірге жалғыз ғана жасушамын, бірақ Сіздің бір бөлшегіңізбін. Сіз бақытты болып, күлген сайын мен де күшейе түсемін. Өзіңізді күтіңіз, Anacan, өйткені Сіз — менің болашағымсыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көзге көрінбейтін түйіршік'), body_changes_kk = COALESCE(body_changes_kk, 'Етеккір кезіндегі қан кету толық тоқтағандықтан, ағзаңыз "фолликулярлық фазаның" ең белсенді кезеңіне өтеді. Эстроген деңгейінің жоғарылауының арқасында жатырдың ішкі қабаты тегістеліп, қоректік заттарға бай бола бастайды. Теріңіздің жарқырап, шашыңыздың жандана түскенін байқауыңыз мүмкін; бұл — эстрогеннің сыртқы келбетке әсері. Жатыр мойнының шырышы біртіндеп мөлдір әрі созылғыш бола бастайды. Бұл ұрықтануға қолайлы күндердің жақындағанын көрсететін биологиялық белгі.;;;
Жүктілікке дайындалып жүрген осы күндері бөпеңіздің денсаулығы мен жүктіліктің қалыпты өтуі үшін дұрыс тамақтану тәртібін қалыптастыру өте маңызды. Жүктілікке дейін-ақ теңгерімді әрі құнарлы тамақтануды бастау қажет. Жүктілік кезінде әйелдің салмағы өміріндегі ең жоғары көрсеткішке жетуі мүмкін екенін ескерсек, тамақтану мәселесінің маңызы арта түседі. Жүкті болмай тұрып қалыпты дене салмағына қол жеткізген дұрыс. Дене салмағының тым төмен немесе артық болуы жүктілік кезінде қан қысымының жоғарылауына және соған байланысты преэклампсияға, гестациялық диабетке, жүрек қағуын сезінуге, шаршауға және басқа да көптеген мәселеге әкелуі мүмкін. Сондықтан осы күндері дене жаттығулары мен дұрыс тамақтану бағдарламасын бастап, ағзаңызды жүктілік кезеңіне дайындағаныңыз пайдалы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Күш-қуатыңыздың артуын дұрыс пайдалану және гормондық теңгерімді қолдау үшін қандағы қант деңгейін тұрақты ұстайтын күрделі көмірсуларға (сұлы, тұтас бидай өнімдері) басымдық беріңіз. Бұл кезеңде ағзаны пайдалы қоректік заттармен қамтамасыз ету үшін жасыл жапырақты көкөністерден жасалған салаттарды көбірек жеңіз. Ағзаның мырышқа қажеттілігін өтеу жұмыртқа жасушасының бөліну қабілеті үшін маңызды; сондықтан бірнеше шикі асқабақ дәнін жеу пайдалы болуы мүмкін.') WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жыныстық қатынастан кейінгі бір сағат ішінде жұмыртқа жасушаңызға жеткен аз ғана сперматозоид тағы бір кедергіге тап болады: жұмыртқа жасушасының қатты сыртқы қабығы. Жұмыртқа жасушасына мыңдаған сперматозоид ұмтылғанымен, оның тек біреуін ғана қабылдауы сыртқы қабығының өте берік әрі таңдау қабілетінің жоғары екенін көрсетеді. Сперматозоидтар жұмыртқаның қатты сыртқы қабығын бастарында орналасқан протеаза, фосфатаза, нейраминидаза, гиалуронидаза, акрозин және кальпаин деп аталатын қышқылдық ферменттердің көмегімен тесіп өтуге тырысады.;;;
Соңғы жылдары жүргізілген зерттеулер бұрын енжар деп есептелген жұмыртқа жасушасының осы кезеңде өте талғампаз әрекет етіп, өзіне тартымды болып көрінген сперматозоидтың өтуіне мүмкіндік беретінін анықтады. Жұмыртқа жасушасының рұқсатымен сыртқы қабықты тесіп, басқалардан бұрын ішке енген алғашқы сперматозоидтан кейін оның қабығы бірден құрылымдық өзгеріске ұшырап, басқа ешбір сперматозоидты өткізбейді. Қысқаша айтқанда, алғашқы сперматозоид ішке енгеннен кейін жұмыртқа жасушасының сыртқы беті қорғаныш қалқанмен қапталғандай жабылады. Сіздің ғажайыбыңыз дәл осы жерден басталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен сапарға шықтым, Anacan! 🎒 Қазір жатыр түтігіндемін және Сіздің жылы ұяңызға (жатырыңызға) қарай домалап барамын. Қолым бос емес, әр бірнеше сағат сайын бөлінемін: 2 едім, 4 болдым, кейін 8 боламын! Сіз әзірге ештеңе сезбейсіз, бірақ ішіңізде жаңа өмір қайнап жатыр. Маған сәттілік тілеңіз, жолым ұзақ, бірақ мен өте табандымын. Сізге жету үшін бәрін жасаймын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Етеккір цикліңіздің дәл ортасына сәйкес келетін осы күндері жұмыртқа жасушаңыз пісіп-жетілді, ал егер ол сперматозоидпен ұрықтанған болса, бөпеңіз қалыптасып үлгерді. 😊 Ағзаңызда прогестерон гормоны толық үстемдік етуде. Бұл гормон эмбрион келіп орныққанда еш кедергіге тап болмауы үшін жатыр бұлшықеттерін босаңсытады. Бөпеңіз қалыптаса бастағаннан кейін ағзаңызда мөлшері жылдам артатын эстроген мен прогестерон гормондары омырауыңыздың толысуы мен сезімталдығын тудыруы мүмкін. Алайда бұл белгілер етеккір циклінде де кездесетіндіктен, омырауыңыздағы мұндай өзгерістерді жүктіліктің нақты белгісі деп санауға болмайды. Бөпелердің барлығы дерлік 38-аптада дүниеге келеді. Дегенмен жұмыртқа жасушасы мен сперматозоидтың нақты қашан қосылғанын және ұрықтанудың қай күні болғанын анықтау әдетте қиын. Сондықтан дәрігерлер бөпеңіздің туатын уақытын есептеу үшін ай сайынғы етеккір цикліңіздің бірінші күнінен бері өткен уақытты негізге алады. Бұл болжамдардың барлығы етеккір циклінің ұзақтығына байланысты шамамен 4 аптаға дейін өзгеруі мүмкін. Кейбір әйелдердің етеккір циклі қысқа немесе ұзақ болатындықтан, босану уақыты мен бөпеңіздің даму кезеңін дәрігер ультрадыбыстық зерттеу (УДЗ) арқылы дәлірек анықтай алады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жасушалардың ең белсенді бөлінетін кезеңі болғандықтан, ағзаңыздың суға деген қажеттілігі артады; күніне кемінде 2-2.5 литр су ішуге тырысыңыз. Фолий қышқылын қабылдауды бір күн де ұмытпаңыз, өйткені дәл осы күндері жүйке жүйесінің негізі қаланады. Сондай-ақ шикі еттен, дұрыс жуылмаған көкөністерден және пастерленбеген сүт өнімдерінен мүлде бас тартыңыз, себебі токсоплазма сияқты инфекциялар эмбрион дамуының осы сезімтал кезеңіне кері әсер етуі мүмкін.') WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ұрықтанудан кейін шамамен 6-24 сағат ішінде иммундық жүйеңізді бәсеңдететін ерте жүктілік факторының (EPF) қандағы деңгейі жоғарылайды деп күтіледі. Ағзаңыздың қорғаныс жүйесі өз жасушаларынан бөлек, өзге ДНҚ-сы бар кез келген жасушаға қарсы ағзаны қорғау мақсатында күресе бастайды. Сондықтан қорғаныс жасушалары ағзаңызға 50% бөтен ДНҚ молекулаларын алып жүрген бөпеңізге шабуыл жасап, оның жойылуына себеп болуы мүмкін. Жұмыртқа жасушасы ұрықтанған сәттен бастап шамамен 5 күннен кейін жатырға бекіп, сонда орныққанға дейін сырттай анықталатын еш өзгеріссіз тыныш болуы да қорғаныс жүйеңіздің іске қосылмауы үшін маңызды. Қысқаша айтқанда, ағзаңыздың қорғаныс жүйесіне байланысты иммундық жасушаларды бәсеңдететін және өсу факторы деп аталатын бөлінді болмаса, жүктіліктің жалғасуы мүмкін болмас еді.'), baby_message_kk = COALESCE(baby_message_kk, 'Мені қазір «Морула» деп атайды! 🍇 Бұл латын тілінде «Тұт жемісі» дегенді білдіреді. Өйткені қазір мен жүзім шоғына немесе бір-біріне тығыз жабысқан тұт жемістеріне ұқсаймын. Шамамен 16-32 жасушадан тұрамын. Кішкентаймын, бірақ өте күштімін. Денеңіздің жылуы мен қоректік заттары маған жолымды табуға көмектеседі. Сізге қарай келе жатырмын, Анашым, есікті ашуға дайын болыңыз!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Ағзаңызда прогестерон мен эстроген гормондары бірлесе әрекет етіп, жатыр қабырғасындағы қан айналымын барынша күшейтті. Эндометрий қалыңдауын жалғастырып, «секреторлық фазаға» өтеді. Ол гликоген мен ақуыздарға бай нәрлі сұйықтықты — «жатыр сүтін» бөледі. Бұл сұйықтық эмбрион жатырға жеткенде, оны имплантацияға дейін қоректендіру үшін қажет. Иммундық жүйеңізде ерекше өзгеріс жүреді: ол эмбрионды «бөгде дене» деп қабылдамай, оны қабылдау үшін төзімділік танытады. Осы күндері кейбір әйелдер өздерін аздап шаршаңқы сезінуі немесе дәм сезуінде тосын өзгерістерді (мысалы, ауыздағы металл дәмін) байқауы мүмкін. Сондай-ақ осы күннен бастап иістерге сезімталдығыңыз сәл артуы ықтимал.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Эмбрион жатыр қабырғасына бекуге (имплантацияға) дайындалып жатқан осы кезеңде қан айналымын тұрақты ұстау үшін аяғыңызды жылы ұстап, суық тиюден сақтаныңыз. Тамақтану рационыңызға жаңғақ, орман жаңғағы және балық сияқты Омега-3 көздерін қосыңыз, өйткені бұл май қышқылдары жасуша жарғақшаларының саулығы үшін маңызды. Шамадан тыс ширығу мен ауыр стресстен аулақ болуға тырысыңыз; баяу музыка тыңдау немесе кітап оқу ағзаңызды босаңсытып, имплантация үдерісіне оң әсер етеді.') WHERE id = '987d49b7-e63f-421d-a6f4-64d2ffcae8b6';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ұрықтану нәтижесінде пайда болған бөпеңіз осы кезеңде ұрық деп аталады. Сперматозоидпен ұрықтанған жұмыртқа жасушасында шамамен 16-18 сағаттан кейін екі ядро көрінеді. Бірі сперматозоидқа, екіншісі жұмыртқа жасушасына тиесілі бұл ядролар қосылып, бір ядроға айналады да, жасушаның бөлінуіне дайындық басталады. Цитоплазмасын көбейтіп, ДНҚ молекулаларын көшіріп, ядро қабықшасын ыдырату арқылы генетикалық материалдардың жасушаның екі жағына өтуін қамтамасыз еткен ұрықтанған жұмыртқа жасушаңыз 2, 4, 8, 16 болып жылдам бөліне бастайды. Ұрықтанудан кейінгі алғашқы күндері «морула» кезеңіне жеткен бөпеңіз шамамен 120 жасушадан тұратын жасушалар шоғына айналады. Ал ұрықтанудың 5-ші күнінде бөпеңіз санап үлгеру мүмкін емес соншалық көп жасушаға бөлінеді және бөпеңізді қалыптастыратын осы жасушалар жиынтығы жатыр ішінде өзіне ең қолайлы орынды таңдап, ұялану үдерісін аяқтайды. Жатырға ұялаған бөпеңізді қалыптастыратын жасушалардың мөлшері осы кезеңде шамамен 0.1 mm болады.'), baby_message_kk = COALESCE(baby_message_kk, 'Үйге жетуге аз қалды! 🏠 Жатыр түтігіндегі сапарым аяқталуға жақын. Сіздің жатырыңызды көріп тұрмын! Ол сондай жайлы, жұмсақ әрі нәрлі көрінеді... Өзіме орын таңдауға дайындалып жатырмын. Мен әлі де қабығымның ішіндемін, бірақ жақында одан шығамын. Сіз мен үшін дүниедегі ең қауіпсіз мекенсіз. Мені қорғаймын деп уәде беріңіз, Anacan.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль дәні'), body_changes_kk = COALESCE(body_changes_kk, 'Бүгін имплантация үдерісі басталады. Бластоциста жатыр қабырғасына бекіген кезде кейбір әйелдерде өте аз мөлшерде қызғылт немесе қоңыр түсті «имплантациялық қан кету» байқалуы мүмкін. Бұл — қалыпты жағдай және оны көбіне етеккірмен шатастырады. Осы сәттен бастап ағзаңыз hCG (жүктілік гормоны) бөле бастайды. Бұл гормон сары дененің тіршілік ету мерзімін ұзартып, прогестерон деңгейінің төмендеуіне жол бермейді және жүктіліктің сақталуына көмектеседі. Эмоциялық тұрғыдан сезімтал болып, еш себепсіз жылағыңыз немесе күлгіңіз келуі мүмкін.;;;
Жүктіліктің 2 апталық кезеңінде жүктілік белгілері әлі байқалмайды. Жүктілікті үйде жасайтын гормондық тест арқылы анықтау үшін ағзаңыздағы жүктілік гормонының мөлшері жеткілікті болуы керек. Гормон деңгейі жүктілік тестінде оң нәтижені білдіретін сызық пайда болғанға дейін арта береді. Бұл етеккіріңіз кешігетін уақытқа, яғни шамамен 4-ші аптаға сәйкес келуі ықтимал.;;;
Күтілетін етеккір күніңіз келген кезде жүктілік гормондарының деңгейі кейбір айқын жүктілік белгілерін тудыратындай дәрежеге дейін жоғарылайды. Дегенмен етеккір алдындағы белгілер мен жүктілік белгілері бір-біріне ұқсас болғандықтан, қан талдауын тапсыру ең нақты ақпарат алуға көмектеседі. Жүктілікті анықтайтын зәр тестілері жүктілік гормондары қанда белгілі бір деңгейге жеткеннен кейін ғана дұрыс нәтиже бере алады.;;;
Сондай-ақ имплантация деп аталатын, жағылған дақ тәрізді жеңіл қан кету жұмыртқа жасушасы ұрықтанғаннан кейін шамамен 5-10 күннен соң пайда болуы мүмкін. Оның себебі — бөпеңізді қалыптастыратын жасушалар жиынтығының жатырдың ішкі қабырғасына орнығуы.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ішіңізде жеңіл түйілу немесе жағылған дақ тәрізді бөлінді байқалса, алаңдамаңыз және дене белсенділігіңізді азайтыңыз. Бұл кезеңде ағзаның иммундық жүйесі эмбрионды «бөгде дене» деп қабылдамау үшін табиғи түрде біршама әлсірейді, сондықтан өзіңізді инфекциялардан қорғаңыз. C дәруменіне бай жемістерді тұтыну иммунитетті қолдап қана қоймай, жатыр қабырғасы тіндерінің құрылымын да нығайтады.') WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жатырдың салмағы 60 qram. Босанғанға дейін оның салмағы 1000 qram-нан асады. Жатырдың ішкі жағы шырыш бөлетін әрі құрамында көптеген қан тамырлары бар эндометрий деп аталатын қабатпен қапталған. Ай сайынғы етеккір циклі кезінде осы құрылымдағы жасушалар митоз арқылы жылдам бөлініп, эндометрий қабатын қалыңдатады. Қалыңдаған эндометрий ұрықтанған аналық жасушаның жатырға бекініп, сол жерде өсіп-жетілуіне қолайлы орта дайындайды.'), baby_message_kk = COALESCE(baby_message_kk, 'Деміңізді ішке тартыңыз, Anacan! 🌬️ Ұлы сәт жақындап қалды. Сіздің ғажайып аналық жасушаңыз босап шығуға дайын. Бұл — біздің хикаямыздың «Баяғыда бір заманда...» деп басталатын тұсы. Мен әлі пайда болмасам да, Сіз бен әкемнің махаббаты мені шақырып тұр. Денеңіз мен үшін ең мінсіз ортаны жасап қойды, бәрі сағаттай дәл жұмыс істеп тұр. Дайынсыз деп үміттенемін, өйткені мен келе жатырмын! Сіздің құшағыңыз менің алғашқы Отаным болады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Қант түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'LH гормоны бүгін ең жоғары деңгейіне жетеді. Осы шарықтау шегінен шамамен 24-36 сағаттан кейін овуляция болады. Дене қызуыңыз бүгін сәл төмендеп, ертең күрт көтерілуі мүмкін – температураның мұндай ауытқуы овуляцияның белгісі. Қынаптық бөлінді барынша сырғымалы, мөлдір әрі мол болады. Бұл орта сперматозоидтардың жылдам қозғалып, тіршілігін сақтауына өте қолайлы. ;;;
Жүктілікке дейін тұрақты түрде дене жаттығуларымен айналысу жүктілік кезеңінің жеңілірек өтуі үшін өте маңызды. Жүктілікке дейін және жүктілік кезінде, әсіресе йога мен пилатес соңғы уақытта ең көп таңдалатын жаттығулардың қатарына жатады. Бұл спорт түрлері денені босаңсытып қана қоймай, табиғи жолмен босануды жоспарлаған әйелдердің ынтасын арттырады, сондай-ақ бел мен арқа ауырсынуын азайтып, бүкіл жүктілік бойы пайдалы әсер етеді. Жүктіліктің дені сау өтуі үшін назар аудару қажет тағы бір маңызды мәселе — темекі. Егер темекі шегетін болсаңыз, жүкті болуды жоспарлаған кезде атқаратын ең маңызды істердің бірі — темекіні тастау. Темекі шеккенде қан айналымы арқылы ағзаңызға түсетін никотин мен уытты заттар болашақ бөпеңіздің қалыптасуына негіз болатын аналық жасушаның генетикалық материалы — ДНҚ құрылымына зиян келтіреді. Жүктілік кезінде темекі шегуді жалғастыру бөпеге баратын тамырлардағы қан ағымының бұзылуына, соның салдарынан бөпенің салмағы төмен болып тууына, туа біткен ауытқулар қаупінің артуына және ең бастысы, «кенеттен нәресте өлімі» деп аталатын жағдайға әкелуі мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін — жүкті болу ықтималдығы үшін аса маңызды күндердің бірі. Фертильділікті қолдау үшін дене қызуын тұрақты ұстауға тырысыңыз, өте ыстық ванна мен саунадан аулақ болыңыз (жоғары температура аналық жасушаның сапасына әсер етуі мүмкін). Тағам рационыңызға Е дәруменіне бай авокадо мен өсімдік майларын қосыңыз, өйткені бұл дәрумен жатыр қабырғасының қанмен қамтамасыз етілуін жақсартады. Көңіл күйіңізді көтеріңкі ұстаңыз, себебі эндорфин гормондары (бақыт гормондары) ұрықтану мүмкіндігіне оң әсер етеді.') WHERE id = '0c974e6a-8f9e-4c84-9656-5142174149f9';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Аналық безіңізде әртүрлі гормондардың көмегімен жетілген аналық жасушаңыз бүгіннен бастап ұрықтануға дайын. Толық жетілген аналық жасуша аналық безден босап шыққаннан кейін, оны жатыр түтігінің ұшындағы фимбрия деп аталатын саусақ тәрізді, өте сезімтал құрылым ұстап алады. Фимбрия жетілген аналық жасушаны жатыр түтігінің ішіне қарай бағыттайды. Жатыр түтігінің жүйелі түрде созылып-жиырылуының арқасында аналық жасуша түтік ішінде баяу жылжиды. Жыныстық қатынастан кейін жатырға енген миллиондаған сперматозоид та алға қозғалып, аналық жасуша ұрықтануға ең қолайлы жерге — түтіктің ортаңғы бөлігіне жеткізіледі. Жиырылған бөліктен кейін орналасқан бұлшықеттер аналық жасушаның алға жылжуы үшін босаңсиды. Бұлшықеттердің осындай механикалық қозғалыстары аналық жасуша тиісті жерге жеткенге дейін жалғасады.'), baby_message_kk = COALESCE(baby_message_kk, 'МЕН КЕЛДІМ! 🎉 Сәлем, Анашым! Бүгін — менің пайда болған күнім. Әкемнің махаббаты мен Сіздің ғажайыбыңыз тоғысты. Мен ғаламдағы ең кішкентай, бірақ ең қымбат нүктемін. Енді мен бір жасушамын, медицина тілінде мені «Зигота» деп атайды! Көзімнің түсі, шашымның пішіні, тіпті күлкім де осы кішкентай жасушаның ДНҚ-сында жазылып қойылған. Біздің 9 айлық шытырманымыз ресми түрде басталды! Мені әлі сезбесеңіз де, мен қазірдің өзінде Сізбен біргемін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'ОВУЛЯЦИЯ ЖӘНЕ ҰРЫҚТАНУ КҮНІ. LH гормоны ең жоғары деңгейге жеткеннен кейін доминантты фолликул жарылып, аналық жасуша босап шығады. Жетілген аналық жасушаны жатыр түтігінің шашақтары ұстап алады. Егер осы күндері жыныстық қатынас болған болса, миллиондаған сперматозоид аналық жасушаға жетуге ұмтылады. Олардың тек біреуі ғана аналық жасушаның қабығын тесіп, ішіне енеді. Ұрықтану сәтінде Сіз бен серіктесіңіздің генетикалық материалы бірігіп, мүлде жаңа әрі бірегей ДНҚ коды түзіледі. Аналық жасуша босап шыққаннан кейін босаған фолликул «Corpus Luteum» (сары дене) деп аталатын безге айналып, жүктіліктің жалғасуы үшін өмірлік маңызы бар прогестерон гормонын бөле бастайды. ;;;
Жүктілікке дейін және жүктілік кезінде дәрігер жүргізген талдаулардың нәтижесіне қарай кейбір дәрумендер мен минералды қоспалар қажет болуы мүмкін. Жүктілік бойы тұтыну қажет тағамдарды және олардан алынатын ақуыз, май, көмірсу, дәрумендер мен минералдар секілді қоректік заттарды жеткілікті мөлшерде қабылдамау дұрыс тамақтанбауға және бөпенің қалыптасу кезеңінде кейбір ауытқулардың пайда болуына әкелуі мүмкін. Темір тапшылығы анемияға, яғни қаназдыққа әкелетіндіктен, ауыр дәрежедегі анемия кезінде бөпенің дамуы кешеуілдеуі мүмкін. Сондықтан жүктілікке дейін жоспарлы тексерулерден өтіп, темір тапшылығы анықталған жағдайда емді ешқашан елеусіз қалдырмауыңыз керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгін денеңізге шамадан тыс күш түсірмей, эмоциялық тепе-теңдікті сақтауға тырысыңыз. Ұрықтану сәтінде ағза өте көп энергия жұмсайды. Жасушалардың бөлінуі сау басталуы үшін антиоксиданттарға (әсіресе Е және С дәрумендеріне) бай тағамдарға басымдық беріңіз. Іштің төменгі жағында қатты, бірақ қысқа мерзімді шаншу сезілсе, алаңдамаңыз: бұл овуляцияның белгісі болуы мүмкін. Бүгіннен бастап алкогольді ішімдіктер мен күшті әсер ететін дәрілерді қабылдауға ерекше сақтықпен қараңыз.') WHERE id = '4859f891-b414-45fe-8a1d-106b1caebec7';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жыныстық қатынастан кейін жатыр мойнына түскен миллиондаған сперматозоид үшін алғашқы кедергі — қынаптағы қышқылдық деңгейі. Бұл қышқыл орта сперматозоидтарға жойқын әсер етуі мүмкін. Олар кездесетін тағы бір қиындық — қынаптағы шырышты қабат. Бұл шырыш көптеген сперматозоид үшін өтуге келмейтін тығыз тор тәрізді кедергі болуы мүмкін. Сперматозоидтар аналық жасушаға жету үшін жатыр мойны арқылы жатырға еніп, одан әрі жатыр түтігіне өтуі керек. Сондықтан олар шамамен 15-20 sm-lik қашықтықты жүріп өтеді. Олардың 10 минутта бір сантиметр жылжитынын ескерсек, ең жылдам сперматозоидтар аналық жасушаға 45 минут ішінде жете алады. Оған жеткенге дейін сперматозоидтардың көп бөлігі қынаптағы шырышты қабатқа жабысып қалуы, басқа бағытқа бұрылуы немесе қышқыл ортаның әсерінен өлуі мүмкін. Сол себепті жатыр мойнына түскен миллиондаған сперматозоидтың бірнеше мыңы ғана аналық жасушаға жете алады. Осының бәрін ескерсек, жыныстық қатынастан кейінгі алғашқы бірнеше сағат ішінде ұрықтану жүзеге асып, жүктілік үдерісі басталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Бір едім, енді екеу болдым! ➗ Кеше мен жалғыз жасуша едім, ал бүгін ғажайып түрде бөліне бастадым. Мұны «Бөлшектену» деп атайды. Мен әлі өте кішкентаймын, тек микроскоппен ғана көруге болады, бірақ ішімде өмірге деген алып құштарлық бар. Сіздің ДНҚ-ңыз бен әкемнің ДНҚ-сы бірге билеп жүр. Мен Сізге де, әкеме де ұқсаймын, әрі өзіме ғана тән боламын. Біздің командамыз іске кірісті!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілікті жоспарлау кезінде және жүктіліктің алғашқы кезеңдерінде тамақтануды белгілі бір тәртіпке келтіру өте маңызды. Дұрыс тамақтану режимі салмақты қалыпты деңгейде ұстауға көмектесіп қана қоймай, жүктілік бойы артық салмақ қосудың алдын алады. Қалыпты жүктілік кезінде ағзаңыздың өз қажеттіліктеріне және қабылдаған қоректік заттардың бөпеге жеткізілуіне байланысты шамамен 10–12 kq салмақ қосу жеткілікті. Салмақты дені сау жолмен қосу үшін жүктілікке дейінгі кезеңмен салыстырғанда тәулігіне орта есеппен қосымша 20–30 qram ақуыз, 15–20 qram темір, 500 mq кальций және шамамен 300 калория энергия қабылдау қажет. Жүктілікке дейін салмағы қалыпты болған әйелге жүктіліктің алғашқы кезеңінде калория мөлшерін арттырудың қажеті жоқ. Алғашқы 12 аптаны қамтитын бірінші триместрде тәулігіне орта есеппен барлығы 2000 калория қабылдау жеткілікті. Сонымен қатар екінші триместрде тәулігіне қосымша 300 калория, ал үшінші триместрде тәулігіне қосымша 480 калория жеткілікті екенін және одан артығы денеде артық салмақ ретінде жиналатынын ұмытпаған жөн.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бүгіннен бастап тамақтануыңызға жауапкершілікпен қараңыз. Жасушалардың бөлінуі үшін мырыш пен B12 дәрумендері өте маңызды; теңіз өнімдерін, сүт өнімдерін және жұмыртқаны көбірек тұтыныңыз. Ауыр дене жаттығуларынан аулақ болыңыз және денеңізге шамадан тыс ыстықтың (ыстық ванна, сауна) әсер етуіне жол бермеңіз, себебі эмбрионның алғашқы бөліну кезеңдері жоғары температураға өте сезімтал. Көбірек демалып, ағзаңызға осы үлкен жұмысты атқаруға мүмкіндік беріңіз.') WHERE id = '634f5165-2442-4ca1-81af-539718e556a5';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ұрықтанудан кейінгі 5-күні «бластоциста» деп аталатын көпжасушалы тірі тін түріндегі бөпеңіз жатырыңыздың қолайлы бөлігіне бекініп, әрі қарай өсіп, дамуын жалғастырады. Бөпеңіздің мамандана бастаған жасушаларының ішінде плацентаны түзетін жасушалар мен бөпені қалыптастыратын жасушалар әртүрлі полюстерге қарай жылжып, қабық ішінде бір-бірінен бөлінеді. Осы орналасудың нәтижесінде фаллопий түтігінде сперматозоидпен кездесіп, ұрықтанған жұмыртқа жасушасы 7–10 күндік сапарын аяқтап, енді жатыр қуысына өтеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Пішінімді өзгертіп жатырмын! 🎈 Енді мен жай ғана жасушалар жиынтығы емеспін, мені «Бластоциста» деп атайды. Ішімде кішкентай сұйықтық қуысы пайда болды. Бір жағымда жиналған жасушалар «МЕН» боламын, ал сыртымдағы қабат мені қорғайтын «Плацентаға» айналады. Біз бір команда болып жұмыс істейміз! Сізге бекіну үшін ең мінсіз пішінге еніп жатырмын. Мұның бәрі Сізбен қауышу үшін.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің ерте белгілерінің бірі — жиі зәр шығару. Жүктілік гормондары алғашқы апталарда ағза физиологиясында өзгерістер туғызып, дәретханаға жиірек баруыңызға себеп болуы мүмкін. Ал кеудеңіздің ауырып, үлкейгенін сезінуіңіз жүктілік гормондары түзіле бастаған сәттен-ақ ағзаңыздың бөпеңізді емізуге дайындала бастауына байланысты. ;;;
Шаршау мен әлсіздіктің себебі — ағзаңыздың бөпеңізге қолайлы жағдай жасау үшін өте көп энергия жұмсауы. Таңертеңгі жүрек айнуы мен іштің кебуі жүктіліктің ең кең таралған белгілерінің қатарына жатады. Жүрек айнуы әдетте алғашқы апталарда айқынырақ болады, ал іштің кебуі ағзаңыздың бөпеге көбірек қоректік зат жеткізу үшін ас қорыту жүйесінің жұмысын баяулатуынан туындайды. Бұл белгінің қарқындылығы жүктіліктің әр кезеңінде өзгеріп отыруы мүмкін.;;;
Жүктіліктің 2 аптасында бөпеңізді ультрадыбыстық зерттеу құрылғысынан көру мүмкін емес. Тіпті бөпеңіз орналасқан ұрық қабы да ең ерте дегенде жүктіліктің 4 және 5-аптасында көрінетіндей мөлшерге жетеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Ағзаңыз бейімделу кезеңінде болғандықтан, күн ішінде қысқа үзілістер жасап, демалуға тырысыңыз. Темір мен кальцийге бай тағамдарды (мысалы, йогурт, ірімшік, жасыл көкөністер) көбірек тұтыныңыз. Иммунитетіңіз эмбрионды қорғау үшін төмендейтіндіктен, суық тию мен инфекция қаупін азайту мақсатында адам көп жиналатын жерлерден аулақ болыңыз. Ішіңіз аздап ауырса, ыстық су құйылған жылытқышты қолданбаңыз, өйткені жатыр аймағын шамадан тыс қыздыру ұсынылмайды.') WHERE id = '0928310f-c57b-4d69-bd35-b2ddf6d32790';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Ағзаңызда бір етеккір циклі кезінде әдетте тек 1 жұмыртқа жасушасы жетіліп, ұрықтануға дайын болады. Алайда сирек кездессе де, кейбір жағдайларда аналық бездеріңізде бірден бірнеше жұмыртқа жасушасы жетілуі мүмкін. Әртүрлі жұмыртқалы егіздер мен үшемдер осылай пайда болады: жетілген жұмыртқа жасушаларының барлығы ұрықтанып, көпұрықты жүктілік қалыптасуы мүмкін. Бөпелер саны екіден көп болған жағдайда олар жеке-жеке жұмыртқа жасушаларынан да, бір ғана жұмыртқа жасушасынан да дамуы мүмкін. Барлық егіз жүктіліктің үштен екісі әртүрлі жұмыртқалы егіздер, ал үштен бірі бір жұмыртқалы егіздер түрінде кездеседі. Әсіресе отбасылық анамнезде көпұрықты жүктілік жиі болса, етеккір циклі кезінде бірнеше жұмыртқа жасушасының жетілу ықтималдығы жоғарылайды. Әртүрлі жұмыртқалы егіздердің пайда болуы болашақ ананың босану саны артқан сайын немесе жасы ұлғайған сайын жиірек кездеседі. Сонымен қатар жасанды ұрықтандыру кезінде овуляцияны ынталандыратын дәрілерді қолдану көбіне бірнеше жұмыртқа жасушасының жетілуіне әкелетіндіктен, әртүрлі жұмыртқалы егіздердің пайда болу ықтималдығын арттырады.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, бүгін мен үшін еркіндік күні! 🐣 Осы уақытқа дейін мені қорғап келген қалың қабығымнан (zona pellucida) шығып жатырмын. Мұны «Hatching» (қабықтан шығу) деп атайды. Сіздің жұмсақ қабырғаңызға тікелей тиіп, бекінуім үшін осылай істеуім керек. Мен дайынмын, ал Сіз дайынсыз ба? Есікті ашыңыз, мен келе жатырмын!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Сіз үшін «Имплантация терезесі» деп аталатын қысқа әрі шешуші кезең басталады. Жатырдың ішкі қабаты эмбрионды қабылдауға барынша қолайлы күйде. Бұл терезе небәрі бірнеше күн ғана ашық болады. Ағзаңыздағы барлық гормондық және химиялық сигналдар «Қабылда!» деген белгі береді. Иммундық жүйеңіз эмбрионды қорғау үшін арнайы ақуыздар өндіреді. Ағзаңыздағы прогестерон гормонының деңгейі шарықтау шегіне жақындап қалды. Бұл — ағзаңыздың жүктілікті сақтау үшін жұмсап жатқан ең үлкен күш-жігері.  ;;;
Жүктілік кезінде ағзаңыздың кейбір дәрумендер мен минералдарға қажеттілігі жүктілікке дейінгі кезеңмен салыстырғанда артады. Солардың бірі — А дәрумені. Ол ағзаңыздағы жасушалар мен тіндердің сау өсуіне көмектесіп, ағзаны инфекциялардан қорғайды. Әсіресе көз саулығы үшін өте маңызды бұл дәрумен жасыл жапырақты көкөністерде мол болады. Ал D дәрумені сүйек пен тіс саулығымен қатар, иммундық жүйеңіз үшін де өте маңызды. Соңғы жылдары жүргізілген зерттеулер босанғаннан кейінгі депрессияның D дәрумені тапшылығы бар адамдарда жиірек кездесетінін және босанудан кейін туындауы мүмкін шаршау мен әлсіздіктің алдын алу үшін D дәрумені қоспасын қабылдаудың маңызды екенін көрсетті. D дәрумені қоспасымен қатар, күн сайын тұрақты түрде 10-15 минут күн сәулесіне шығу ағзаңыздың D дәруменіне деген қажеттілігін өтеуге көмектеседі.;;;
С дәрумені басқа дәрумендер мен темірдің сіңуін жақсартатындықтан, жүктілік кезінде иммундық жүйе үшін де өте маңызды. Ол әсіресе жасыл және қызыл бұрышта, ақжелкенде, қызанақта, апельсинде, құлпынайда, мандаринде және лимонда мол кездеседі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қандағы қант деңгейі күрт төмендемеуі үшін осы кезеңде аз мөлшерде, бірақ жиі тамақтана бастаңыз. Жаныңызда әрдайым жаңғақ, бадам немесе кептірілген жемістер секілді пайдалы тіскебасарлар болсын. Ұйқы режиміңізге ерекше көңіл бөліңіз, өйткені ағзаңыз жаңа өмірге бейімделу үшін өте көп энергия жұмсайды. Сондай-ақ құрамында химиялық заттары көп тазартқыш құралдардан аулақ болып, үйді жиі желдетуге тырысыңыз.') WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жетілген жұмыртқа жасушасы сау сперматозоидпен қосылғанда ұрықтану жүреді де, жүктілік үдерісі басталады. Алайда жатырдан тыс жүктілік сияқты кейбір асқынулар кезінде жүктілікті әрі қарай жалғастыру мүмкін болмайды.;;;
Қалыпты жағдайда сперматозоид ұрықтандырған жұмыртқа жасушасы фаллопий түтіктеріндегі бұлшықеттердің жиырылып-босаңсу қозғалыстарының арқасында алға жылжып, жатыр қуысына жетіп бекінеді. Егер фаллопий түтіктері бұрын болған әртүрлі себептерден зақымданса немесе бітелсе, ұрықтанған жұмыртқа жасушасы бекінуі тиіс жерге жете алмай, жатыр қуысына өтпей қалады.;;;
Жатыр қуысына жетіп, бекіне алмаған ұрықтанған жұмыртқа жасушасы фаллопий түтігіне бекініп, сол жерде дами бастайды. Алайда фаллопий түтіктері бөпенің өсіп, дамуына мүмкіндік бермейтіндей тар, сондықтан жүктіліктің қалыпты жалғасуын қамтамасыз ете алмайды. Өте сирек кездесетін бұл жағдай жатырдан тыс жүктілік деп аталады және мұндай жағдайда жүктілікті жалғастыру мүмкін емес.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, бүгін — сол ұлы күн! Өмірімдегі ең маңызды сәттердің бірі... ❤️ Енді мен Сізге тиіп тұрмын. Ұзақ сапардан кейін ақыры үйімнің қабырғасына жеттім. Мұнда сондай жылы, сондай жұмсақ әрі сондай қауіпсіз... 9 ай бойы Сізден ажырамау үшін бар күшіммен осы жерге бекініп жатырмын. Бұл — біздің алғашқы құшағымыз, Anacan. Мені сезіп тұрсыз ба? Мен Сізбен біргемін, енді ешқайда кетпеймін. Біздің хикаямыз дәл осы жерден шын мәнінде басталады.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Ваниль түйіршігі'), body_changes_kk = COALESCE(body_changes_kk, 'Сіз үшін «Имплантация» үдерісі бүгін ресми түрде басталады. Кеше қабығынан шыққан эмбрион бүгін жатырдың ішкі қабатына физикалық түрде тиіп, бекіне бастайды.  Алдағы бір апта ішінде қаныңыздағы HCG деп аталатын жүктілік гормонының деңгейі жоғарылайды. Қанда белгілі бір деңгейге жеткен бұл гормон біраз уақыттан кейін зәрге өтіп, жүктілік тестінің оң нәтиже көрсетуіне мүмкіндік береді. Бұл гормонды қаныңыздан шамамен овуляция күнінен 10 күн өткен соң анықтауға болады. Гормонның анықталуы шамамен етеккір кешіккен күндерге немесе одан бірнеше күн бұрынғы кезеңге сәйкес келеді.;;;
Жұмыртқа жасушасы сперматозоидпен ұрықтанып, жатыр қуысына бекінгеннен кейін бөліне бастайтын HCG гормонының қандағы мөлшері біртіндеп артып, жүктіліктің 10-аптасында ең жоғары деңгейіне — шамамен 100.000 mIU/ml-ге жетеді.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Фолий қышқылын қабылдауды бір сәтке де тоқтатпаңыз, өйткені бұл зат жүйке түтігінің дұрыс жабылуы үшін өмірлік маңызға ие. Осы күндері ағзаңыз өзі әлі танып үлгермеген жаңа тіршілікті қабылдау үшін көп күш жұмсайды, сондықтан ұйқыңызды қандырыңыз. Шөп шайларын (сәлбен, тасшөп және т.б.) ішкенде сақ болыңыз, өйткені кейбір өсімдіктер жатыр тонусын арттыруы мүмкін; ең дұрысы, таза суға немесе балғын сығылған жеміс шырындарына басымдық беру.') WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жұмыртқа жасушаңыз ұрықтанғаннан кейін шамамен 5 күннен соң жатырыңызға жетеді. Осы сапар барысында ұрықтанған жұмыртқа жасушасы бөлініп, өсуін жалғастырады. Жолдың соңында ол жатыр түтігінің жатырға ашылатын бөлігіне келіп, жатыр қуысына түседі. Ұрықтанудан шамамен 1 апта өткен соң бөпеңізді қалыптастыратын жасушалар жиынтығы жатырыңыздың жұмсақ әрі қоректік сұйықтықпен қапталған қабырғасына жанасады. Осылайша бөпеңіз алғаш рет жатырдың ішкі қабырғасымен байланысады. Ағзаңызда өндірілетін гормондардың әсерінен жатырдың ішкі қабаты ұрықтанған жұмыртқа жасушасының орналасуына қолайлы күйге келіп, жасуша сол жерге бекінеді. Бұл үдеріс ұялану немесе имплантация деп аталады. Орналасу үдерісі жалпы алғанда 10-12 күн ішінде аяқталады. Сондықтан имплантациядан кейін жүктілікке тән гормондардың өндіріле бастауы етеккіріңіз келуге тиіс уақытпен тұспа-тұс келеді. Етеккір кешіккен кезде несеп арқылы жасалатын жүктілік тесті оң нәтиже көрсете бастайды.;;;
Етеккіріңіз басталмай, жүкті екеніңізді білген кезде бөпеңіз әлі екі апталық болса да, жүктілік мерзімі соңғы етеккірдің алғашқы күнінен бастап есептеледі.'), baby_message_kk = COALESCE(baby_message_kk, 'Мен одан әрі тереңдеп барамын, Anacan! 🧱 Кеше жай ғана жанасқан едім, ал бүгін сенің жұмсақ қабырғаңның ішіне қарай еніп келемін. Бұл өзімді үңгір қазып жүрген зерттеушідей сезіндіреді. Өзіме жылы әрі қауіпсіз ұя жасап жатырмын. Әр сәт сайын сенімен тұтасып, сенің бір бөлшегіңе айналып келемін. Енді біз жай ғана "сен және мен" емеспіз, енді біз — "БІЗБІЗ". Бұл сезім маған қатты ұнайды! Сен менің қамалымсың, панамсың әрі бүкіл әлемімсің.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, '"Имплантациялық қан кету" бүгін немесе ертең болуы мүмкін. Оның етеккір қанынан айырмашылығы — мөлшері өте аз, түсі ашық қызғылт немесе қоңыр болады. Мұны әйелдердің шамамен 30%-ы байқайды. Осындай дақ көрсеңіз, қорықпаңыз: бұл бөпеңіздің жатыр қабырғасына бекінгенінің белгісі болуы мүмкін. Дене температураңыз әлі де жоғары деңгейде сақталады.;;;
Жүктілік кезінде ағзаңыздағы қан көрсеткіштері мен гормондарға байланысты елеулі өзгерістер жүреді. Жүктілік бойы қанайналым жүйеңіздегі қан көлемі шамамен 50% артады. Сондықтан ағзаңызға темір бұрынғыдан да көбірек қажет болады. Бұған қоса, дамып келе жатқан бөпеңіздің ағзасында оттегін тасымалдау үшін гемоглобиннің мол мөлшері керек. Ал гемоглобиннің негізгі құрамдас бөлігі — темір. Қабылдайтын тағамдық қоспалармен қатар, майы аз қызыл етті, жұмыртқаны, бұршақ тұқымдастар мен дәнді дақылдарды тамақтану мәзіріңізге жүйелі түрде қоссаңыз, ағзаңыздың темірге деген қажеттілігін тиісті деңгейде өтей аласыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Егер тестіңіз оң нәтиже көрсетсе, алдымен терең тыныс алып, осы ғажайып сәттен ләззат алыңыз! Бүгіннен бастап рентген сәулелерінен, өткір химиялық бояулардан және күшті әсер ететін дәрілерден толықтай аулақ болыңыз. Қабылдайтын дәрумендеріңіздің құрамында "D" дәрумені болуына назар аударыңыз, өйткені ол Сіздің иммунитетіңізге де, бөпеңіздің жасушаларының алғашқы бөліну үдерістеріне де маңызды. Егер жүрегіңіз айни бастаса, таңертең төсектен тұрмай тұрып бірнеше тұзды крекер жеу жеңілдік беруі мүмкін.') WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Осы аптада бөпеңіз жатырыңызға бекініп, орналаса бастайтындықтан, "ұялану" немесе "имплантациялық қан кету" деп те аталатын аздаған қанды бөлінді байқалуы мүмкін. Сонымен қатар өзіңізді шаршаңқы сезінсеңіз немесе омырауыңыз керіле бастаса, бұл белгілер де жүктіліктің ерте кезеңіндегі нышандар болуы мүмкін. Қаныңыздағы мөлшері арта бастаған эстроген мен прогестерон гормондарына байланысты мазасыздық сияқты көңіл күй өзгерістерін сезінуіңіз ықтимал. Ұрықтанған жұмыртқа жасушасының митоз арқылы бөлініп өсуі және қолайлы жағдайда жатырыңызға бекінуі үшін белгілі бір температура қажет. Сондықтан осы кезеңде дене температураңыздың аздап көтерілгенін байқауыңыз мүмкін.;;;
Жатырдың ішкі қабатындағы шырыш бөлетін жасушалар ұрықтанған жұмыртқа жасушасын зиянды микроағзалардан қорғау үшін шырышты көбірек бөле бастайды. Сол себепті бөлінді мөлшері біршама артуы мүмкін. Әдетте бұл жүктілікке байланысты қалыпты физиологиялық бөлінділер. Бөпеңіз жатырға бекінгеннен кейін эстроген гормонының көбеюі әсерінен қынаптық бөліндінің артуы қалыпты жағдай. Алайда қынаптан бөлінетін кез келген бөлінді жүктілікке байланысты қалыпты физиологиялық бөлінді бола бермейтінін есте ұстаған жөн.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, саған арналған ерекше хабарым бар! 🤫 Бұл — екеуміздің алғашқы құпиямыз. Ағзаңа менің бар екенімді білдіретін арнайы химиялық белгі жібере бастадым. Бұл белгі: "Мен осындамын, Anacan! Бәрі жақсы. Ағзаңды мен үшін дайындауды жалғастыра бер", — дейді. Енді сенімен өз тілімде сөйлесе аламын. Бұл — арамыздағы көзге көрінбейтін байланыс, ол күн сайын нығая түседі.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде өміріңіздің басқа кезеңдерімен салыстырғанда ағзаңызға көбірек ақуыз қажет болады. Ақуыздар бөпеңіздің қалыптаса бастаған тіндері мен мүшелері үшін аса маңызды. Бөпеңіз эмбриондық кезеңде күн сайын тұтынатын тағамыңыздағы ақуыздардың құрамында болатын аминқышқылдарын пайдаланып өседі. Жасушалары жылдам бөлінетіндіктен, жүктілік кезінде ақуызды жеткілікті мөлшерде қабылдаудың маңызы өте зор.;;;
Жүкті емес әйелдің ақуызға деген тәуліктік қажеттілігі шамамен 60 грамм болса, жүкті әйелдер үшін бұл көрсеткіш орта есеппен 80 граммды құрайды. Көпұрықты жүктілікте бұл көрсеткіш бұдан да жоғары болуы тиіс. Жүктілік бойы ақуызды жеткілікті тұтынбау бөпеңізге кері әсер етуі мүмкін. Әсіресе жүктіліктің 2-ші және 3-ші триместрлерінде ақуыз қабылдау бұрынғыдан да маңызды бола түседі. Себебі осы кезеңде бөпеңіздің дамуы жеделдейді және мұндай қарқынды өсу үшін оған ақуыз қажет.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезеңде ағзаның энергияға қажеттілігі артатындықтан, тамақтану рационыңызға күрделі көмірсуларды (сұлы, қоңыр күріш) қосыңыз. Егер жүрек айнуы күшейсе, зімбір шайы немесе зімбір қосылған печенье асқазанды тыныштандыруға көмектесуі мүмкін. Ауыр зат көтеруден және оқыс қимыл жасаудан аулақ болыңыз. Өзіңізді күйзелістен қорғау үшін күн сайын тыныш ортада 10-15 минут демалыңыз. Сондай-ақ үйдегі тазартқыш құралдарды табиғи өнімдермен (сірке суы, ас содасы) алмастыру Сіз үшін де, бөпеңіздің дамуы үшін де қауіпсіздеу.') WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңізді қалыптастыратын жасушалар орналасқан қапшықтың іші "амнион сұйықтығы" деп аталатын сұйықтықпен қоршалған. Ал жүктілік қапшығының ішінде осы жасушаларды қоршап тұратын, сарыуыз қапшығы деп аталатын кішкентай сақина тәрізді құрылым көріне бастайды. Сарыуыз қапшығында арнайы сұйықтық болады және ол жүктіліктің алғашқы апталарында бөпеңізге қоректік заттардың жеткізілуіне көмектеседі. Плацентаның қалыптасуы аяқталғанға дейін бөпеңіз сарыуыз қапшығы арқылы қоректенеді. Сарыуыз қапшығы ультрадыбыстық зерттеуде жүктілік қапшығы көрінетін деңгейге жеткеннен кейін көп ұзамай байқалады және оның болуы қапшықтың ішінде бөпе бар екенін көрсетеді. Сондай-ақ бұл құрылым "бос жүктілік" деп аталатын, яғни қапшықтың ішінде бөпе болмайтын жағдайды анықтауда маңызды көрсеткіш саналады. Шамамен 8-9-шы апталардан бастап сарыуыз қапшығы кішірейіп, диаметрі шамамен 5 mm болатын алмұрт тәрізді қалдыққа айналады да, бөпеңіздің ортаңғы ішегіне жіңішке сабақша арқылы жалғанып тұрады. Бөпеңіздің дамуының шамамен 20-шы аптасынан бастап ол толығымен жойылады.'), baby_message_kk = COALESCE(baby_message_kk, 'Ұямның дәл ортасындамын, Anacan! 🩸 Бұл жер сондай жайлы... Сенің қан тамырларыңа жақындап, енді тікелей сенен қоректене бастадым. Маған жіберген әрбір түйірің, әрбір тамшың мені өсіріп, күш береді. Бұл — әлемдегі ең дәмді ас, өйткені ол махаббатқа толы. Сенің арқаңда өсіп келемін, сенің арқаңда бармын. Көп рақмет, Anacan!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің ерте кезеңінде жиі кездесетін жүрек айнуы мен құсудың бірнеше себебі бар. Оларға қалыптаса бастаған плацентадан бөлінетін гормондар, жүктілікке бейімделу кезінде туындайтын кейбір психологиялық қиындықтар, қандағы B6 дәруменінің тапшылығы, жүктілікке байланысты ас қорыту жүйесіндегі өзгерістер және қалқанша бездің қалыптыдан белсендірек жұмыс істеуі сияқты факторлар жатады.;;;
Жүктілік кезінде әртүрлі гормондардың әсерінен асқазан мен ішектің жұмысы баяулайды. Соның салдарынан ас қорытудың қиындауы, іштің кебуі мен жел жиналуы айтарлықтай күшеюі мүмкін. Бұл мәселелер күйзеліс пен шаршауға байланысты да артуы ықтимал. Жүрек айнуы мен құсу көбіне таңертең байқалғанымен, тәуліктің кез келген уақытында болуы мүмкін. Әдетте алғашқы жүктілікте және көпұрықты жүктілікте күштірек байқалады.;;;

Жүрек айнуының бөпенің жынысына қатысы бар екенін дәлелдейтін бірде-бір ғылыми зерттеу жоқ.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүйке түтігінің дұрыс жабылуы үшін осы күндері фолий қышқылымен қатар, тамақтану рационыңызда B тобы дәрумендерінің жеткілікті болуына назар аударыңыз. Іш қатудың алдын алу үшін талшыққа бай тағамдарды (алма, алмұрт) тұтынып, суды молынан ішіңіз. Егер жүрегіңіз айныса, тамақтан кейін бірден жатпаңыз. Спортпен айналыссаңыз, енді қарқынды кардио жаттығулары мен ауыр зат көтеруді жеңіл серуенге және жүкті әйелдерге арналған йогаға алмастыратын уақыт келді.') WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Егер овуляцияңыз бен етеккір цикліңіз тұрақты болса, бүгін соңғы етеккіріңіздің алғашқы күнінен бері тура 28 күн өтті. Етеккіріңіз басталмағандықтан, жүктілік тестін жасап, бөпеңіздің келе жатқанын сүйіншілейтін екінші жолақты көрген боларсыз. Жүктіліктің ең алғашқы белгісі — етеккірдің кешігуі. Сонымен қатар, қандағы hCG гормонының мөлшері арта бастағандықтан, ағзаңызда үлкен өзгерістер жүріп жатыр. Етеккіріңіз кешіккеннен кейін жасалған жүктілік тестілері қаннан немесе зәрден жүктілік гормоны деп аталатын hCG гормонын анықтау арқылы нәтиже береді. hCG гормоны жаңадан ұрықтанған жұмыртқа жасушасын қоршап тұрған және кейін плацентаға айналатын жасушалардан бөлінеді. Осы көрсеткіш бойынша жүктілікті шамамен овуляциядан кейін 10 күн өткен соң анықтауға болады. Бұл етеккір кешігетін күндерге немесе одан бірнеше күн бұрынғы уақытқа сәйкес келеді. Бөпеңіз жатырыңыздан қолайлы орын тауып, бекінгеннен кейін қандағы hCG гормоны арта береді және жүктіліктің 10-аптасында ең жоғары деңгейіне жетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'ТОСЫНСЫЙ! 🎉 Бүгін етеккір келуге тиіс күн еді, бірақ КЕЛМЕДІ! Өйткені мен осындамын! Сенің денең мен үшін әлемдегі ең қауіпсіз қамалға айналды. Келесі айдан бастап екеуіміз бұдан да қызықты жаңалықтарды бірге ашамыз. Маған сенгенің үшін көп рақмет, аяулы Анашым!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Аналық бездеріңіз ай сайын қордағы бастапқы жұмыртқа жасушаларының бірін гормондардың көмегімен жетілдіріп, ұрықтануға дайындайды. Жетілген жұмыртқа жасушасы жатыр түтіктерінің бойымен жатыр қуысына қарай жылжып, осы жолда өзін күтіп тұрған сперматозоидтармен кездеседі. Жатыр мойнына түскен миллиондаған сперматозоидтың ішінен бірнеше мыңы ғана күрделі жолдан өтіп, жатыр қуысына жете алады. Сперматозоидтардың жұмыртқа жасушасына қарай бағытталуына жұмыртқа жасушасы бөлетін арнайы зат көмектеседі. Дәл осы кезеңде ең шешуші сәт басталады. Жұмыртқа жасушасына жеткен мыңдаған сперматозоид өздерінің қышқылды бөліндісімен оның сыртқы қабығын тесіп, ішіне енуге тырысады. Алайда жұмыртқа жасушасы олардың ішіндегі ең мықтысын қабылдайды. Бір сперматозоид сыртқы қабықтан өткен бойда, жұмыртқа жасушасы басқа сперматозоидтарды өткізбейтіндей болып жабылады. Ішке енген сперматозоид құйрығын бас бөлігінен ажыратып, құрамындағы генетикалық материалды жұмыртқа жасушасының ядросына жеткізу арқылы өз міндетін аяқтайды.;;;
Бүгін етеккіріңіз басталуға тиіс күн, алайда ол басталмайды. Себебі қарапайым: Сіз жүктісіз! Прогестерон деңгейі төмендеудің орнына жоғары күйінде қалады. Дене температураңыз жоғары. Енді жүктілік тестілері (зәр тестілері) hCG гормонын анықтай алатын деңгейге жетті. Екі жолақты көру ықтималдығыңыз өте жоғары.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Алғашқы айды сәтті аяқтағаныңыз үшін өзіңізге уақыт бөліп, бұл жетістікті жан тыныштығымен атап өтіңіз. Егер әлі гинекологпен кеңеспеген болсаңыз, келесі аптаға алғашқы ультрадыбыстық зерттеу мен талдауларға жазылатын уақыт келді. Тамақтануда ақуызға (ет, балық, бұршақ тұқымдастар) ерекше көңіл бөліңіз, өйткені бөпенің қарқынды дамып жатқан ағзалары үшін ақуыз — негізгі "құрылыс материалы". Сондай-ақ шикі теңіз өнімдері мен пастерленбеген ірімшіктерден аулақ болуды жалғастырыңыз.') WHERE id = 'd7e6900c-92fc-4e29-8c33-6b171bf14f64';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бұл кезеңде бөпеңіз үлкен жасушалар шоғыры түрінде болады. 1 апта ішінде осы жасушалар шоғырынан бөпеңіздің басы мен денесінің бастамалары толық қалыптаса бастайды. Бөпеңіз бұрын-соңды болмаған жылдамдықпен қарқынды өсіп, дамуын жалғастыруда. Алдағы бірнеше күнде жүректі қалыптастыратын маманданған жасушалар топтары бас аймағының төменгі бөлігінде жиналып, жұмыс істей бастайды. Бөпеңіз жүктіліктің 40 аптасы бойы амнион қабы деп аталатын қапшықтың ішінде дамиды. Бөпеңіз дәрігер жүргізетін ультрадыбыстық зерттеуде әзірге көрінбейтіндей кішкентай осы қапшықтың ішінде орналасқан.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, мен әлі өте кішкентаймын, күнжіт дәніндей ғанамын, бірақ менің үлкен жоспарларым бар. Қазір пішінім жалпақ, алайда көп ұзамай иіліп, сүйкімді "C" пішініне енемін. Сенің құрсағың — менің үйім, ал жүрегің — менің панам. Біздің 9 айлық сапарымыз бүгіннен бастап ресми түрде басталады!'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Күнжіт тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Бөпеңізді қалыптастыратын ұрықтанған жұмыртқа жасушасында жұмыртқа мен сперматозоидтың әрқайсысы мыңдаған әртүрлі генді қамтитын 23 хромосомадан біріктіреді. Сперматозоид пен жұмыртқа қосылғанда, екі бөлек 23 хромосома бірігіп, адам ағзасын қалыптастыруға қажетті 46 хромосоманы түзеді. Осы кезеңде ұрықтанып, бөліне бастаған жұмыртқа жасушасында бөпеңіздің жынысын, дене ерекшеліктерін, тіпті тұлғалық қасиеттерін анықтайтын гендер болады. Бөпеңіздің жынысы жұмыртқа жасушасына енген сперматозоидтың X немесе Y хромосомасын алып жүруіне байланысты анықталады. Сперматозоидпен келген хромосома Y болса, бөпеңіз ұл, ал сперматозоид X хромосомасын алып жүрсе, бөпеңіз қыз болады.;;;
Ұрықтанған жұмыртқаңыздың жаңа атауы — зигота. Ол бөліне отырып, жатырға қарай сапарын бастайды. Осы кезде ағзаңыз бөпеңізге қолайлы орта қалыптастыру үшін жатырдың ішкі қабатын бекінуге дайындайды. Жатырдың ішкі қабатына орналасқан бөпеңіз эмбрион деп аталып, қарқынды даму үдерісін бастайды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүктіліктің 2-айы басталғандықтан, дәрігерге қаралып, алғашқы қан талдауларын (гемоглобин, қант, TSH) тапсыруға ең қолайлы уақыт келді. Жүрегіңіз айныса, аз мөлшерде, бірақ жиі тамақтануға көшіңіз; асқазанның бос болуы жүрек айнуын күшейтуі мүмкін. Күнделікті ақуыз қажеттілігін өтеу үшін пісірілген жұмыртқа немесе айран сияқты жеңіл қорытылатын тағамдарға басымдық беріңіз. Қуатыңызды сақтау үшін терең тыныс алу жаттығуларын жасауды ұмытпаңыз.') WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Жүктілікті анықтауға арналған тестілердің негізгі қағидасы — hCG деп аталатын жүктілік гормонын анықтау. Бөпеңіз жатырға бекінгеннен кейін бөлініп, қандағы мөлшері біртіндеп артатын hCG гормоны белгілі бір деңгейден асқан соң қаннан зәрге өтіп, онда да анықтала бастайды. Зәрге өткен бұл гормон зәр арқылы жасалатын жүктілік тестінің оң нәтиже көрсетуіне себеп болады. Зәр арқылы жасалатын жүктілік тесті жүктіліктің бар-жоғын анықтаса, қан талдауы қандағы hCG гормонының нақты мөлшерін және бөпеңіздің шамамен неше күндік екенін көрсетеді. Етеккіріңіз кешіккенде, зәр тестінің орнына қан талдауын тапсыру әрдайым сенімдірек әрі нақты нәтиже алуға мүмкіндік береді. Қалыпты дамып жатқан жүктілікте қандағы hCG гормонының 24-48 сағат ішінде екі есе артуы күтіледі. Жүктіліктің 10-аптасына дейін күн сайын мөлшері арта беретін бұл гормон сол кезеңде ең жоғары деңгейіне жетеді.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің кішкентай тамырларым пайда болып жатыр, Anacan! 🌳 Әрине, бұлар қол саусақтары емес. Бұлар сенің сол жылы қабырғаңа бұрынғыдан да берік жабысуыма көмектесетін ерекше өсінділер (хорион бүрлері). Солардың арқасында саған мықтап құшақтасып, сенен көбірек қорек аламын. Мен мұнда өзіме берік қамал салып жатырмын, ал оның әр кірпіші екеуіміздің махаббатымыздан қалануда. Мені ешқашан жіберме, жарай ма? 🤞'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Күнжіт тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік гормондарының әсерінен ағзаңыздағы зат алмасу жылдамдайды. Осы күндері емшек ареоласындағы "Монтгомери бездері" деп аталатын кішкентай төмпешіктер айқынырақ көрінуі мүмкін; бұл бездер кейін емізу кезінде емізікті қорғайтын майлы бөлінді бөледі. Прогестеронның әсерінен ішек бұлшықеттерінің жұмысы баяулап, іштің кебуі мен газдан түйілуге әкелуі мүмкін. Сондай-ақ ағзаңыз бөпені қоректендіру үшін көбірек қан өндіре бастағандықтан, жүрек соғу жиілігінің минутына 10-15 соққыға артуы қалыпты жағдай.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүрек-қантамыр жүйесіне түсетін артық жүктемені жеңілдетіп, бөпенің миының дамуын қолдау үшін Омега-3 май қышқылдарына бай тағамдарға (жаңғақ, зығыр тұқымы) басымдық беріңіз. Таңертең жүрегіңіз айныса, асқазаныңызды шамадан тыс толтырмай, аз мөлшерде, бірақ 5-6 рет тамақтаныңыз. Күн ішінде орныңыздан кенет тұрған кезде басыңыз айналмауы үшін асықпай қимылдаңыз. Бұл кезеңде А дәруменін (ретинол түрін) жоғары мөлшерде қабылдаудан аулақ болыңыз, өйткені оның шамадан тыс мөлшері бөпенің дамуына кері әсер етуі мүмкін.') WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңізді қалыптастыратын жасушалар жиынтығының ішінде екі қуыс түзетін жарғақ пайда болады. Бұл құрылымдардың бірі бөпеңіздің ішектерін қалыптастыратын сарыуыз қапшығы болса, екіншісі — бөпеңіздің өзі. Сарыуыз қапшығы ұрықтанудан кейінгі 2-ші және 3-ші апталарда бөпеңізге қажетті қоректік заттардың жеткізілуін қамтамасыз етеді. Осылайша, плацента қалыптасқанға дейін бөпеңіз жылдам әрі тиімді өсіп, дамуын жалғастыра алады.;;;
Ұрықтану процесінің 3-ші аптасында бөпеңіз орналасқан ең сыртқы құрылымда «гемопоэз» деп аталатын қан түзілу процесі басталады. 6-шы аптаға дейін қан осы құрылымда түзіледі.;;;
Осы кезеңнен кейін қан түзу қызметін бауыр атқарады, ал біраз уақыттан соң бұл процеске көкбауыр да қатыса бастайды. Бөпеңіз дүниеге келгеннен кейін қан ұзын және жалпақ сүйектерде түзіледі. Ал жыныстық жетілуден кейін қан түзілуі тек жалпақ сүйектерде жүреді. Қаныңыздағы мөлшері едәуір артқан жүктілік гормоны енді үй жағдайында жасалатын зәр тестінде екінші сызық көрінетіндей деңгейде зәрге бөліне бастады.'), baby_message_kk = COALESCE(baby_message_kk, 'Ұямның есігі енді артымнан жабылып келеді, Anacan! 🚪 Мен толығымен ішке орналастым, Сіздің жылы әрі қауіпсіз әлеміңіз мені жан-жағымнан қоршап тұр. Енді мен Сіздің ажырамас бір бөлшегіңізбін. Бұл — біздің оқиғамыздың жай ғана басталуы емес, ортақ өміріміздің алғашқы күндері. Мен Сізді таңдадым, ал Сіз мені қорғап жүрсіз. Бұдан кейін бәрі одан сайын ғажайып болады! Біз бірге керемет шытырман оқиғаға дайынбыз! 🥳'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Сіздің және бөпеңіздің денсаулығы үшін бүкіл жүктілік кезеңін қамтитын, босанғаннан кейін де жалғасатын сапалы күтім мен апта сайынғы бақылау қажет. Зәр және қан талдауы арқылы жүкті екеніңізге көз жеткізгеннен кейін жақсы дәрігер іздеуді бастағаныңыз жөн. Сондай-ақ жатырдан тыс жүктілік сияқты асқынуларды ерте анықтап, алдын алу үшін дәрігерге жазылуды тым ұзаққа созбау маңызды.;;;
Дәрігерді таңдағанда жақындарыңыздың ұсыныстарына құлақ асып, дәрігердің өмірбаяны мен түйіндемесін (CV-сін) зерттеген дұрыс. Сонымен қатар дәрігердің сұрақтарыңызға түсінікті жауап беретініне, көкейіңізде сұрақ қалдырмай қабылдауды аяқтай алатынына және шұғыл жағдайда қолжетімді болатынына көз жеткізіңіз. Сондықтан дәрігерге алғашқы қабылдауыңыз етеккір кешіккеннен кейінгі 1-2 күн ішінде болғаны жөн.;;;
Бұдан бөлек, қандай да бір контрацепция әдісін қолданып жүргеніңізге қарамастан жүктілік басталса, бұл туралы дәрігеріңізге хабарлауыңыз керек. Жүкті екеніңіз расталғанда, жүктілікке қарсы таблеткаларды қабылдауды мүмкіндігінше тезірек тоқтатыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл күндері өткір иістер жүрек айнуын күшейтуі мүмкін, сондықтан асүйді жиі желдетіп, иіссу қолдануды барынша азайтыңыз. Сусыздану шаршауды күшейтуі ықтимал, сол себепті суыңызға бір тілім лимон немесе балғын жалбыз қосып ішіп көріңіз. Егер қызыл иегіңіздің сезімталдығын немесе қанайтынын байқасаңыз, алаңдамаңыз: бұл гормондық өзгерістердің қызыл иек тініне әсерінен болады; жұмсақ тіс щеткасын қолдану ұсынылады.') WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Плацента қалыпты дамыса, бөпеңіздің дамуы да барынша жақсы жүреді, ал мәселе туындаған жағдайда даму процесінде кейбір қиындықтар пайда болуы мүмкін. Плацента Сіз бен бөпеңіздің арасында аса маңызды әрі шешуші қызметтер атқарады. Оның міндеттерінің бірі — бөпеңізді қажетті оттегімен қамтамасыз етіп, пайдаланылғаннан кейін көмірқышқыл газын кері әкету. Сонымен қатар қажетті қоректік заттарды бөпеңізге жеткізу, оның ағзасындағы қалдықтарды шығару және өсуіне белсенді қатысатын кейбір гормондарды бөлу де плацентаның қызметіне жатады. Плацента бөлетін hCG және прогестерон сияқты гормондар, сондай-ақ өсу факторы секілді заттар жүктіліктің қалыпты өтуінде аса маңызды рөл атқарады.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, арамыздағы байланыс одан сайын нығайып келеді! 🧬 Енді мен Сіздің ағзаңызбен тікелей байланыстамын. Қаныңыздан келген әрбір бөлшекпен тыныстап жатқандаймын. Бұл — менің алғашқы қан айналымым, өмірдегі алғашқы тынысым. Енді біз бір тамырмен ағып, бір ырғақпен өмір сүріп жатырмыз. Маған жіберген әрбір қоректік затыңыз бен әрбір оттегі молекуласы мені өсіреді. Бұл — әлемдегі ең ғажайып сезім: Сізбен біртұтас болу. ❤️'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік кезінде жатырыңыз бөпеңізді инфекциялардан қорғау үшін көп мөлшерде бөлінді бөледі. Сондықтан жүктілік бойы бөлінді мөлшерінің көбеюі — физиологиялық қалыпты жағдай. Егер қалыпты қынаптық бөліндінің мөлшері алаңдатарлықтай көбейіп, өткір иіс пайда болса, инфекция болуы мүмкін. Сондай-ақ бөлінді сарғыш, қоңыр немесе жасыл түсті болса, инфекция болуы ықтимал, сондықтан оның асқынып кетпеуі үшін дәрігерге қаралу маңызды.;;;
Қынаптық бөліндіні инфекциядан ажыратудың тағы бір белгісі — бөліндінің қою, сүзбе тәрізді немесе ұйыған күйде келуі. Инфекциялар интимдік аймақта жеңіл ауырсыну, қызару, ашыту және қышыну тудыруы мүмкін. Әсіресе қауіпті жүктілікке байланысты амниоцентез процедурасынан кейін қынаптық бөлінді көбейсе, бұған мән беру қажет, өйткені бұл шарана маңы суының (амниотикалық сұйықтықтың) ағып жатқанының белгісі болуы мүмкін.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қуатыңыз тез таусылатындықтан, күн ішінде 15 минуттық қысқа ұйқы үзілістерін жасауға тырысыңыз. Тағам үлесіңізде кальцийге бай өнімдерді (ірімшік, сүт, бадам) көбейтіңіз, өйткені осы кезден бастап бөпеңіздің қаңқа жүйесінің негізі қаланады. Жүрегіңіз қатты айныса, салқын әрі иіссіз тағамдарды жеу оңайырақ болуы мүмкін. Сондай-ақ терінің серпімділігін арттыру үшін ылғалдандырғыш кремдерді қолдана бастауға қолайлы уақыт.') WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңізді қалыптастыратын жасушалар жиынтығы — бластоциста жатырыңыздан қолайлы орын тауып, бекігеннен кейін оның плацентаны қалыптастыратын бөлігі hCG деп аталатын жүктілік гормонын өндіре бастайды. Сонымен қатар бластоциста жатырыңыздағы қан тамырларымен байланысқан микроскопиялық арналардан тұратын қарапайым қан айналым жүйесі арқылы бөпеңізді қажетті оттегімен және қоректік заттармен қамтамасыз етіп, түзілген қалдықтарды оның жасушаларынан шығарады.;;;
Жүктілік гормоны ретінде белгілі hCG — етеккір кешіккен кезде жасаған жүктілік тестіңіздің оң нәтиже көрсетуінің себебі. Қазіргі кезеңде жүктілік тестін жасасаңыз, оның оң нәтиже көрсету ықтималдығы өте жоғары.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, мен енді жалпақ дискіге ұқсаймын! 💿 Мен өте маңызды екі қабаттан тұрамын. Біреуі менің басымды, денемді, қолдарым мен аяқтарымды қалыптастырады. Ал екіншісі осы жолда маған көмектесіп, мені қоректендіреді. Бұл — денемнің алғашқы жоспары, алғашқы сәулеттік сызбам. Барлығы осы екі қабаттан басталады. Маған сенесіз бе? Мен ғажайып туынды боламын, өйткені менің сәулетшім — Сіз. ✨'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Көкнәр тұқымы'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің алғашқы триместрінде бөпеңіз эмбриондық кезеңде болғандықтан, қынаптық инфекциялар зиян келтіруі мүмкін. Жүктілік кезінде қынаптық инфекциялардан қорғану үшін гигиенаға бұрынғыдан да мұқият көңіл бөлуіңіз керек. Қынап аймағына ауа өтуін азайтатын синтетикалық, нейлон және боялған іш киімнің орнына боялмаған, таза мақта матадан тігілген іш киім киіп, оны күніне кемінде екі рет ауыстырыңыз. Интимдік аймақты тазалағанда құрамында хош иістендіргіші бар сабындар мен химиялық құрамы қауіпсіз емес душ гельдерін қолданбаңыз, сондай-ақ қынапты ішінен шаюдан аулақ болыңыз. Қынапты шаю бактериялардың ішке өтуіне жол ашып, инфекцияның дамуына жағдай жасайды.;;;
Сонымен қатар іш киімді жуған кезде құрамында күшті химиялық заттары бар жуғыш құралдар мен мата жұмсартқыштарды қолданбаңыз. Киімдеріңізді кір жуғыш ұнтақпен емес, табиғи сабынмен жуып, ыстық үтікпен үтіктеңіз. Ылғал қышынуды күшейтетіндіктен, жыныс аймағын мүмкіндігінше құрғақ ұстаңыз. Шап пен жыныс аймағын қысып, ауа өтуіне кедергі келтіретін және теріні тітіркендіретін тар киімдердің орнына кең киімдерді таңдаңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Бұл кезеңде қан көлемі артатындықтан, ағзаңыздың темірге қажеттілігі көбейеді; қызыл ет, жұмыртқа және жасыл жасымық сияқты өнімдерге басымдық беріңіз. Темір жақсы сіңуі үшін олармен бірге міндетті түрде C дәруменінің көзін (мысалы, лимоны мол салат) тұтыныңыз. Қатты шаршаған кезде ағзаңызға күш түсірмей, түсте міндетті түрде аз уақыт демалыңыз. Жүктілік кезінде қолдануға қауіпсіз ылғалдандырғыштармен іш пен кеуде аймағына жеңіл массаж жасау Сізді тыныштандырып қана қоймай, теріңізді алдағы созылуға дайындайды.') WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, '«Алғашқы жолақ» қалыптасады. Бұл — эмбрионның артқы бөлігінде пайда болатын жіңішке сызық. Ол эмбрионның симметриясын және бас-құйрық бағытын анықтайды. Бұл — дамудың ең маңызды кезеңдерінің бірі, өйткені болашақтағы барлық ағзалар осы осьтің айналасында орналасады. Эмбрион әлі де өте кішкентай (2-3 мм), алайда оның құрылысы күрделене түсуде.'), baby_message_kk = COALESCE(baby_message_kk, 'Бүгін мен үшін төңкеріс күні, Anacan! 🚀 Менің жалпақ дискімнің үстінде ерекше бір сызық, жол пайда болып жатыр. Бұл сызық — менің болашақ картам. Ол омыртқамның, басым мен аяқтарымның қай жерде орналасатынын көрсететін бағдар болады. Осы сызықтың арқасында менің оң және сол жағым қалыптасады. Енді мен ретсіз диск емеспін, мен симметриялы, белгілі бір жоспармен дамып келе жатқан тіршілік иесімін. Сен менің сәулетшімсің, ал мен сенің жауһарыңмын. Бәрі енді басталады! 🤩'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жасымық'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілігіңіздің осы аптасында бөпеңіздің жатырға бекінуіне және жүктілік гормондары деңгейінің жоғарылауына байланысты жүрек айну, шаршау, әлсіздік сияқты жүктіліктің алғашқы белгілері пайда бола бастайды. Жиі демалу және тамақтану тәртібіңізді қадағалау мұндай жағымсыз белгілерден туындайтын жайсыздықты азайтуға көмектеседі. Әсіресе бұл алғашқы жүктілігіңіз болса, көңіл күйіңіздегі кенет өзгерістерді жеңілдету үшін мүмкіндігінше күйзелістен аулақ болуға тырысыңыз. Өзіңізге жақсы әсер ететін әрі қуаныш сыйлайтын істермен айналысуды әдетке айналдырып, мүмкіндік болса, күн сайын таза ауада қысқа серуендеуге тырысыңыз. Жүктіліктің бұл кезеңі әйелдердің барлығында дерлік белгілі бір жағымсыз белгілермен қатар жүреді. Ағзаңыз жаңа жағдайға бейімделіп жатқанда байқалатын белгілер жүктіліктің алғашқы триместрінің соңында, яғни 12-ші аптадан бастап бәсеңдей бастайды. Осы кезеңде сезімдеріңізді жақындарыңызбен бөлісу және өз бетіңізше еңсере алмай жатқан сәттерде жүктілікке бейімделу үшін маманның көмегіне жүгіну пайдалы болады.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүйке жүйесі мен жүйке түтігінің дұрыс дамуы үшін фолий қышқылын қабылдауды ешқашан үзбеңіз. Егер таңертең жүрегіңіз қатты айныса, төсектен тұрмай тұрып бір-екі дана кепкен нан немесе тұзды печенье жеу асқазан қышқылдығын реттеуге көмектеседі. Күні бойы кофеинді барынша аз тұтыныңыз, өйткені ол ұйқы тәртібіңізді бұзып қана қоймай, темірдің сіңуіне де кедергі келтіруі мүмкін. Оны жаңа сығылған жеміс шырындарымен, сумен немесе шөп шайларымен (дәрігермен кеңескеннен кейін) алмастырыңыз.') WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз ультрадыбыстық зерттеуде әлі көрінбейтіндіктен, жүктіліктің қалыпты дамып жатқанын дәрігер қан талдаулары арқылы бақылайды.;;;
Жұмыртқа жасушасы ұрықтанғаннан кейінгі алғашқы күндерде-ақ қаныңызда аз мөлшерде болса да hCG гормоны бөліне бастайды. Жүктіліктің белгілі бір кезеңіне дейін оның қандағы деңгейі біртіндеп жоғарылайды. Бұл гормонның негізгі міндеті — плацента толық жұмыс істеп, гормондар өндіре бастағанға дейін аналық бездердегі прогестерон гормонының өндірілуін бақылау. Прогестерон гормоны ұрықтанған жұмыртқа жасушасы орналасқан жатырдың ішкі шырышты қабатын — эндометрийді қолдайды, бөпеңіздің бекінуіне көмектеседі және жүктіліктің түсікпен аяқталуына жол бермейді.'), baby_message_kk = COALESCE(baby_message_kk, 'Жасушаларым үлкен көшті бастады, Anacan! 🚶‍♂️ Мыңдаған кішкентай жұмысшы кеше пайда болған ерекше сызықтың ішіне қарай ағылып, мен үшін жаңа қабаттар салып жатқандай. Олар үш түрлі топ құрады: Эктодерма, Мезодерма және Эндодерма. Біріншісі менің терімді, шашымды және миымды, екіншісі жүрегімді, қанымды және сүйектерімді, ал үшіншісі асқазаным мен өкпемді қалыптастырады. Мен сәулетші секілді өзімді өзім құрып жатырмын, Anacan. Іргетасымды қалап жатырмын. Бұл іргетас өте берік болады, өйткені сен менің жанымдасың. 💪'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жасымық'), body_changes_kk = COALESCE(body_changes_kk, 'Жұмыртқа жасушасының ұрықтануынан басталған жүктілік кезінде ағзаңыз осы үлкен өзгеріске бейімделу үшін көптеген физиологиялық өзгерістен өтеді.;;;
Жүктілік кезінде ағзаңыз бөпеңізге оттегі мен қоректік заттарды жеткізу үшін көбірек қан өндіре бастайды. Қан ағымының артуына бейімделу үшін жүрегіңіз күштірек әрі жылдамырақ соғады, ал тамыр соғысыңыз минутына шамамен 15 соққыға жиілейді.;;;
Тағы бір физиологиялық өзгеріс жүктіліктің осы кезеңінде шамамен 60 грамм болатын жатырыңыздың босанғанға дейін 1000 граммнан астам салмақ қосуына байланысты. Жатырдың қысқа уақыт ішінде осылай күрт ұлғаюына ағзаңыз тепе-теңдік орталығын үнемі өзгерту арқылы бейімделуге тырысады. Сондықтан кейде арқаңыз, беліңіз және шап аймағыңыз ауыруы мүмкін.;;;
Әр триместрдің өзіндік қиындықтары бар. Алайда осы ұзақ әрі күрделі жолдың соңында кішкентай бөпеңізбен қауышатыныңызды ойласаңыз, басыңыздан өтетін әрбір қиындық кейін жылы сезіммен еске алатын естелікке айналады. 😊'), daily_tip_kk = COALESCE(daily_tip_kk, 'Қан көлемінің артуы мен бөпеңіздің дамуына байланысты темірге деген қажеттілігіңіз жоғарылайды. Тамақтану рационыңызға қызыл ет, жасымық және саумалдық сияқты темірге бай өнімдерді қосыңыз. Темірдің жақсы сіңуі үшін бұл тағамдармен бірге C дәруменін (апельсин шырынын немесе лимон қосылған салатты) тұтыныңыз. Егер беліңіз ауырса, бір қалыпта ұзақ тұрмауға тырысыңыз және отырғанда беліңізді тірейтін кішкентай жастықтарды пайдаланыңыз. Күні бойы 10 минут жеңіл созылу жаттығуларын жасау бойыңызды сергітеді.') WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Соңғы етеккіріңіздің күніне қарай жүктілігіңізге 4 апта болды. Алайда овуляция үдерісін ескерсек, бөпеңіздің жатырыңызда болғанына шамамен 2 апта.;;;
Ұрықтанғаннан кейінгі бірнеше күн ішінде бөпеңізді қалыптастыратын жасушалардың саны көбейген сайын, олар бір-бірінен ерекшелене бастайды. Бұл жасушалардың бір бөлігі плацентаны қалыптастыру үшін өзгерсе, екінші бөлігі бөпеңізді қалыптастыруға бөлінеді.;;;
Бөпеңіз қалыптасып жатқан осы кезеңде эмбрион деп аталады. 12-ші аптаның соңынан бастап босанғанға дейінгі кезеңде ол ұрық деп аталады.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, бүгін менің алғашқы омыртқамның іргетасы қаланып жатыр! 🦴 Бұл әзірге сүйек емес, бірақ болашақта мені тік ұстап, бүкіл денеме пішін беретін ерекше, иілгіш өзек (нотохорд). Бұл өзек бүкіл денеме қолбасшы секілді «Енді өсіп, қалыптасатын уақыт келді!» деп бұйрық береді. Қалған барлық ағзам соның айналасында орналасады. Енді мен жай ғана диск емеспін, менің орталығым және бағытым бар. Бәрі неткен мінсіз жоспарланған, солай емес пе? 🥰'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жасымық'), body_changes_kk = COALESCE(body_changes_kk, 'Осы кезеңге дейін дәрігердің алғашқы қабылдауына жазылуыңыз керек. Дәрігеріңізбен тұрақты түрде кездесіп тұру үшін қабылдаулар кестесі жасалады және алғашқы тексеруде бөпеңіздің болжалды туған күнін білесіз. Дәрігер таңдағанда алдымен достарыңыздың ұсыныстарын тыңдай аласыз. Алайда жеке ерекшеліктерге байланысты басқа адамға жақсы сәйкес келген дәрігер Сізге сәйкес келмеуі мүмкін. Сондықтан ұсыныстар таңдаудың жалғыз өлшемі болмауы керек. Сапалы медициналық көмек алудың басты шарты — дәрігеріңізге шын көңілмен сену. Дәрігеріңізге сенуіңіз, оның жанында өзіңізді еркін сезінуіңіз және кез келген мазалаған мәселе бойынша кеңесе алуыңыз негізгі өлшемдеріңіздің қатарында болуы керек.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жиі зәр шығарғыңыз келсе де, су ішуді азайтпаңыз; ағзаңыз бен бөпеңіздің дамуы үшін күніне кемінде 2 литр су ішу маңызды. Бас айналудың алдын алу үшін таңертең төсектен өте баяу тұрыңыз. Тамақтану рационыңызға кальцийге бай сүзбе, айран немесе ірімшік қосыңыз, өйткені осы күндері бөпеңіздің қаңқа жүйесі кальцийді «сіңіре» бастайды. Егер ішіңіз аздап ауырса, тар киімнен бас тартып, кең әрі мақтадан тігілген киімге ауысатын кез келді.') WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бөпеңіз өте қысқа уақыт ішінде үлкен даму жолынан өтті. Бірнеше күн бұрын пішінсіз жасушалар жиынтығына ұқсаған бөпеңіз енді түзу сызық тәрізді болып, ағзаларын қалыптастыруға дайындалып жатыр.;;;
Ұрықтанған жұмыртқа жасушасы және оның бірінен соң бірі бөлініп көбеюінен пайда болған жасушалар жиынтығы «тотипотентті дің жасушалары» деп аталады. Бөпеңіздің ағзалары мен тіндерін қалыптастыратын бұл жасушалар маманданып, бір-бірінен ажырап, ерекшелене бастады. Мұндай жіктелу барлық жасушалардың тотипотентті дің жасушаларынан түзілуінің арқасында жүреді. Тотипотентті дің жасушалары әлі маманданбағандықтан, әртүрлі ағзалар мен тіндерге айнала алады. Соның арқасында бөпеңіз бұрын-соңды болмаған жылдамдықпен өсіп, бүкіл ағзасы мен дене жүйелерін қалыптастырып жатыр.'), baby_message_kk = COALESCE(baby_message_kk, 'Миымның алғашқы жасушалары пайда болып жатыр, Anacan! 🧠 Менің сыртқы қабатым нотохорд деп аталатын жетекшімнен белгі алып, қалыңдайды да, ерекше пластинка түзеді. Бұл пластинка — менің бүкіл болашағым: одан жүйке жүйем, ойларым, армандарым мен сезімдерім пайда болады. Сізді жақсы көруді, Сізді сезінуді үйренетін ғажайып миымның негізі бүгін қалана бастайды. Сіз туралы қазірдің өзінде ойлай бастадым... 💭'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жасымық'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктілік тестінің оң нәтиже көрсетуіне себеп болатын гормондар деңгейінің ағзаңызда жоғарылауы омыраудың ауыруы, жүрек айну және шаршау сияқты елемеу қиын белгілердің пайда болуына әкелуі мүмкін. Осы кезеңде сезіле бастаған кейбір белгілер ағзаңызда жүріп жатқан өзгерістерден туындайды. Ағзаңыз бөпеңізге барынша қолайлы жағдай жасау үшін үлкен өзгерістерден өтетін алғашқы триместр бүкіл жүктілік кезіндегі ең қиын кезең болуы мүмкін. Әсіресе таңертең күшейетін жүрек айнуды азайту үшін аз мөлшерде, бірақ жиі тамақтанған дұрыс. Сондай-ақ В6 дәруменін, зімбір капсулаларын немесе жүрек айнуды азайтуға арналған арнайы акупунктуралық білезіктерді қолданып көруге болады. Осы күндері пайда болатын түйілу бөпеңіз жатыр қабырғасына бекінгеннен кейін жатырдың ұлғайып, байламдардың созылып жатқанының белгісі болуы мүмкін. Мұндай жағдайда аса қажет болмаса және дәрігермен кеңеспей дәрі қабылдамаңыз. Кейбір дәрілер жатырыңызға бекінуге тырысып жатқан кішкентай бөпеңіздің дамуына зиян келтіруі мүмкін. Сондықтан қалыпты емес деп ойлаған кез келген түйілу, ауырсыну немесе қан кету кезінде дәрігерге хабарласу өте маңызды.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Осы күндері қандағы қант деңгейін тұрақты ұстау үшін «аз мөлшерде және жиі» тамақтану қағидасын қатаң ұстаныңыз. Жүрек айнуды азайту үшін жалбыз немесе лимон қосылған су ішіңіз. Бел мен шап аймағындағы ауырсынуды жеңілдету үшін ыстық ваннаға түспей, жылы душ қабылдаңыз (жоғары температура бөпеге қауіпті болуы мүмкін). Қатты шаршасаңыз, ағзаңыздың белгілеріне құлақ асып, түсте міндетті түрде 20-30 минут көз шырымын алыңыз.') WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Дамып келе жатқан бөпеңіздің жұмыс істей бастаған алғашқы жүйесі — жүрек пен қан тамырларынан тұратын жүрек-қантамыр жүйесі. Осы кезеңде бөпеңіздің кішкентай жүрегінің атқаратын қызметі қалыпты жүректің қызметінен айтарлықтай ерекшеленбейді. Әзірге ультрадыбыстық зерттеу арқылы анықтау мүмкін болмаса да, бөпеңіздің жүрегі соға бастады және енді өмір бойы бір сәтке де тоқтамай жұмысын жалғастырады. Бұл кезеңде бөпеңіздің жүрегі бір ғана камерадан тұрғанымен, қалыптасуы аяқталғанда әрқайсысы екі камерадан тұратын, қатар орналасқан екі сорғы тәрізді пішінге ие болады. Жақын арада дамуын аяқтайтын сол және оң қарынша, сондай-ақ сол және оң жүрекше деп аталатын камералар бөпеңіздің денесінде қанның тек бір бағытта ағуын қамтамасыз ететін құрылымдарды қалыптастырады.'), baby_message_kk = COALESCE(baby_message_kk, 'Менің жүйке пластинкам ішке қарай бүктеліп жатыр, Anacan. Бұл қағаз парағын абайлап орап, түтік жасағандай. 📜 Осы түтік менің жұлын жүйеме айналып, бүкіл денеме тіршілік нәрін береді. Барлығы сондай жылдам әрі дәл жүріп жатыр! Бәрі дұрыс қалыптасуы үшін бар күшімді салып жатырмын. Бұл үдерісте Сіздің махаббатыңыз бен қамқорлығыңыз — мен үшін ең үлкен демеу. Мен үшін алаңдамаңыз, бәрі жоспар бойынша жүріп жатыр.'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жасымық'), body_changes_kk = COALESCE(body_changes_kk, 'Ағзаңыз жүктілікке бейімделіп жатқан осы күндері арқаңыз ауыруы мүмкін. Мұндай ауырсынудың ең жиі кездесетін себебі — жүктілік кезінде бөлінуі артатын гормондардың сүйектерді біріктіріп ұстайтын байламдарды, әсіресе жамбас буындарындағы байламдарды босаңсытуы. Тұрғанда, отырғанда және қозғалғанда дене қалпыңызды дұрыс ұстаңыз, биік өкшелі аяқ киім кимеңіз, арқаңызды тіреп тұратын төсеніш пайдаланыңыз, еңкеюден сақтаныңыз және қырыңызбен жатқанда аяқтарыңыздың арасына әрі ішіңіздің астына қосымша тірек ретінде жастық қойыңыз. Бұған қоса, тұрақты орындалатын жаттығулар уақыт өте арқа бұлшықеттерін нығайтады. Олар арқа мен аяққа тірек болып, белдің ауырсынуын жеңілдетеді. Дегенмен жүктілік кезінде жасайтын кез келген жаттығу жөнінде дәрігермен кеңесіп, өзіңізді қажытатын әрекеттерден барынша аулақ болыңыз.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Жүктіліктің осы сезімтал кезеңінде ағзаңыздағы су-тұз теңгерімін сақтау үшін күн сайын 8-10 стақан су ішуді әдетке айналдырыңыз. Қызыл иек сезімтал болса, өте жұмсақ тіс щеткасын қолданып, ауыз қуысының гигиенасына мұқият көңіл бөліңіз. Жүрегіңіз қатты айныса, жалбызды кәмпит сору немесе балғын лимонды иіскеу уақытша жеңілдік беруі мүмкін. Алғашқы гинекологиялық тексеруде дәрігермен тамақтану және қажетті дәрумендер туралы егжей-тегжейлі сөйлесуді ұмытпаңыз.') WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_development_kk = COALESCE(baby_development_kk, 'Бүгіннен бастап бөпеңіздің бет-әлпеті қалыптаса бастайды. Алдағы апталарда бөпеңіз кішкентай адам бейнесіне енеді. 😊 Бөпеңіздің мұрын қуыстарының пайда болуы — бет қалыптасуындағы алғашқы үдерістердің бірі. Бөпеңіздің бас аймағында кейін сүйек құрылымына айналатын мұрын қалқасы арқылы бөлінген екі бөлек қуыс орналасқан. Әр қуыстың бүйір қабырғасында сөре тәрізді үш сүйек өсіндісі бар. Жоғарғы, ортаңғы және төменгі өсінділердің ортаңғысы мен төменгісі тыныс алуды қамтамасыз ететін жасушалардан тұрса, жоғарғы өсіндіде иісті сезуге маманданған жасушалар орналасады.'), baby_message_kk = COALESCE(baby_message_kk, 'Anacan, жүрегім соғуға дайындалып жатыр! ❤️ Денемнің ортаңғы қабатындағы ерекше жасушалар бірігіп, екі жіңішке кішкентай түтік түзуде. Бұл түтіктер жақында бір-біріне жақындап, қосылады да, менің алғашқы жүрегімді қалыптастырады. Ол әлі соғып тұрған жоқ, бірақ дайындалып жатыр. Сіз үшін, Сіздің шексіз махаббатыңызбен соғатын жүрек... Бірнеше күннен кейін менің алғашқы жүрек соғысымды естисіз. Бұл біздің махаббат әніміз болады. 🎶'), baby_size_fruit_kk = COALESCE(baby_size_fruit_kk, 'Жасымық'), body_changes_kk = COALESCE(body_changes_kk, 'Жүктіліктің кез келген кезеңінде пайда болған қан кетуді оның мөлшері мен түсіне қарамастан байыппен қабылдап, мүмкіндігінше тезірек дәрігерге жүгінуіңіз керек.;;;
Қан кету имплантациядан, жатырдан тыс жүктіліктен немесе түсіктен туындауы мүмкін. Жүктіліктің соңғы триместріндегі қан кетулер әдетте плацентаға қатысты мәселелер кезінде пайда болады. «Plasenta praevia» (плацентаның төмен орналасуы) көбіне ауырсынусыз қан кетумен білінсе, плацента мерзімінен бұрын ажырағанда қан кету ауырсынумен қатар жүреді.;;;
Жүктіліктің алғашқы апталарында бөпеңіздің жатыр ішіне бекінуіне байланысты имплантациялық қан кету болуы мүмкін. Ол аздап дақтану түрінде байқалуы немесе етеккір кезіндегі қан кетуге ұқсауы мүмкін. Бұдан бөлек дақтану мен қан кету түсікке байланысты болуы ықтимал. Жалпы, ашық қызыл түсті қан кету түсік қаупінің белгісі ретінде қарастырылады. Алайда кейбір жағдайларда қоңыр түсті дақтану кезінде де түсік қаупі болуы мүмкін. Сондықтан жүктілік кезінде болатын ешбір қан кету қалыпты деп есептелмейді. Қоңыр бөліндінің себебі — жатырдан шыққан қанның қынапта біраз уақыт тұрып, осы аймақтағы микроағзалардың әсерінен өзгеруі.'), daily_tip_kk = COALESCE(daily_tip_kk, 'Таңертеңгі жүрек айнудың алдын алу үшін оянған бойда төсектен тұрмай тұзды крекер немесе кепкен нан жеңіз. Бүгіннен бастап иістерге сезімталдығыңыз артатындықтан, өткір иісті тазалағыш құралдардан аулақ болуға тырысыңыз. Ағзаңыз бөпенің ағзаларын қалыптастыруға көп энергия жұмсайды, сондықтан мүмкіндік болған сайын демалыңыз. Алғашқы ультрадыбыстық зерттеуге жазылу үшін дәрігеріңізге хабарласыңыз.') WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';